class EquipmentInstance:
    def __init__(self, card_instance: CardInstance, owner: int):
        self.card_instance = card_instance
        self.owner = owner
        self.effect_target: int = owner
        self.turns_equipped: int = 0
        self.uses_this_turn: int = 0
        self.corruption_active: bool = False
        self.armor: int = 0
        self.custom_vars: Dict[str, int] = {}

    @property
    def def_id(self) -> str:
        return self.card_instance.def_id

    @property
    def card_def(self) -> CardDef:
        return self.card_instance.card_def

    def to_dict(self) -> dict:
        return {
            'card_instance': self.card_instance.to_dict(),
            'owner': self.owner,
            'effect_target': self.effect_target,
            'turns_equipped': self.turns_equipped,
            'uses_this_turn': self.uses_this_turn,
            'corruption_active': self.corruption_active,
            'armor': self.armor,
            'custom_vars': dict(self.custom_vars),
        }

    @staticmethod
    def from_dict(d: dict) -> 'EquipmentInstance':
        ei = EquipmentInstance(
            CardInstance.from_dict(d['card_instance']),
            d['owner']
        )
        ei.turns_equipped = d.get('turns_equipped', 0)
        ei.uses_this_turn = d.get('uses_this_turn', 0)
        ei.effect_target = d.get('effect_target', ei.owner)
        ei.corruption_active = d.get('corruption_active', False)
        ei.armor = max(0, int(d.get('armor', 0) or 0))
        ei.custom_vars = dict(d.get('custom_vars', {}) or {})
        return ei


def clear_spikeball_play_flags(card: CardInstance):
    flags = getattr(card, 'instance_flags', set())
    was_legacy_boost = (
        SPIKEBALL_BOOSTED_FLAG in flags
        and SPIKEBALL_ADDED_PRECISION_FLAG not in flags
        and SPIKEBALL_ADDED_WIDE_STRIKE_FLAG not in flags
    )
    if SPIKEBALL_ADDED_PRECISION_FLAG in flags or was_legacy_boost:
        flags.discard('precision')
    if SPIKEBALL_ADDED_WIDE_STRIKE_FLAG in flags or was_legacy_boost:
        flags.discard('wide_strike')
    flags.discard(SPIKEBALL_BOOSTED_FLAG)
    flags.discard(SPIKEBALL_ADDED_PRECISION_FLAG)
    flags.discard(SPIKEBALL_ADDED_WIDE_STRIKE_FLAG)


def reset_card_after_play(card: CardInstance):
    preserve_fission = 'preserve_fission' in normalize_card_flags(getattr(card, 'instance_flags', set()) or set()) or 'preserve_fission' in normalize_card_flags(getattr(card.card_def, 'flags', set()) or set())
    preserved_fission_level = clamp_card_layer(getattr(card, 'fission_level', 1)) if preserve_fission else 1
    card.cost_e_override = None
    card.cost_m_override = None
    card.mimic_discount = 0
    preserve_power = 'amplify' in normalize_card_flags(getattr(card, 'instance_flags', set()) or set()) or 'amplify' in normalize_card_flags(getattr(card.card_def, 'flags', set()) or set())
    if not preserve_power:
        card.power_value = 0
    card.temp_swift_value = 0
    card.temp_heavy_value = 0
    card.temp_magic_heavy_value = 0
    card.hand_blind_turns = 0
    if not preserve_power:
        card.instance_flags.discard('power')
    card.instance_flags.discard('temp_swift')
    card.instance_flags.discard('temp_heavy')
    card.instance_flags.discard('temp_magic_heavy')
    clear_spikeball_play_flags(card)
    card.instance_flags.discard('wide_strike')
    card.setup_modifiers.discard('desert_citron_precision_play')
    card.setup_modifiers.discard('desert_citron_stealth_play')
    for attr in (
        '_desert_marble_bounce_cursor',
        '_desert_marble_previous_target',
        '_arctic_ricochet_cursor',
        '_arctic_ricochet_previous_target',
    ):
        if hasattr(card, attr):
            delattr(card, attr)
    for countered_attr in ('_play_was_countered_this_play', '_sewers_was_countered_this_play'):
        if hasattr(card, countered_attr):
            delattr(card, countered_attr)
    if isinstance(getattr(card, 'custom_vars', None), dict):
        card.custom_vars.pop('sewers_toilet_paper_power', None)
        card.custom_vars.pop('_ocean_charge_resolved_this_play', None)
        card.custom_vars.pop('_once_per_play', None)
    if card.card_type == 'thorn':
        card.fission_level = preserved_fission_level if preserve_fission else 1
        card.fusion_level = 1
        card.fission_count = max(0, card.fission_level - 1)
        card.fusion_multiplier = 1.0
        card.fission_hit = 0
        # Round 10: the properties zeroed on leaving play come from the card data
        # (``reset_properties``); the built-in fallback in engine_runtime_support
        # covers card definitions that never load a data resource (unit tests,
        # legacy saves).  See docs §13.1.
        from engine_runtime_support import card_reset_properties
        for reset_prop in card_reset_properties(card):
            if hasattr(card, reset_prop):
                setattr(card, reset_prop, 0)
    if getattr(card, '_mimic_copy', False):
        try:
            delattr(card, '_mimic_copy')
        except Exception:
            pass


