    def _refresh_equipment_derived_player_flags(self, player_id: int = -1):
        for ps in self.players:
            ps.sponge_active = False
        for owner_id, owner_state in enumerate(self.players):
            for eq in list(getattr(owner_state, 'equipment', []) or []):
                if not self._card_has_flag(getattr(eq, 'card_instance', None), 'sponge_active_projection'):
                    continue
                if not self._non_stack_equipment_is_active(eq):
                    continue
                target_id = self._equipment_effect_target_id(eq, owner_id)
                if self._status_application_blocked(target_id, 'sponge_active'):
                    continue
                self.players[target_id].sponge_active = True

        self._refresh_jurassic_magic_soil_bonuses()
        self._refresh_desert_topaz_bonuses()
        self._refresh_garden_magic_disc_bonuses()
        self._garden_refresh_coal_cards()

        # Pill applies status immunity through its card event to the chosen effect target.
        # Equipment itself stays in the user's equipment area, so deriving the status from
        # the equipment owner would incorrectly make both players immune.
        for pid in range(len(self.players)):
            self._hel_sync_crit_multiplier_display(pid)

    def _apply_jurassic_magic_soil_bonus(self, eq: EquipmentInstance, target_id: int) -> None:
        if eq is None or not self._valid_player_id(target_id):
            return
        custom = getattr(eq, 'custom_vars', {}) or {}
        try:
            applied_target = int(custom.get('jurassic_magic_soil_applied_target', -1))
        except Exception:
            applied_target = -1
        if applied_target == target_id:
            return
        target = self.players[target_id]
        target.max_health += 40
        target.base_max_health += 40
        target.max_magic += 10
        custom['jurassic_magic_soil_applied_target'] = target_id
        eq.custom_vars = custom

    def _remove_jurassic_magic_soil_bonus(self, eq: EquipmentInstance) -> None:
        if eq is None:
            return
        custom = getattr(eq, 'custom_vars', {}) or {}
        try:
            target_id = int(custom.get('jurassic_magic_soil_applied_target', -1))
        except Exception:
            target_id = -1
        if not self._valid_player_id(target_id):
            custom.pop('jurassic_magic_soil_applied_target', None)
            eq.custom_vars = custom
            return
        target = self.players[target_id]
        target.max_health = max(1, int(target.max_health) - 40)
        target.base_max_health = max(1, int(target.base_max_health) - 40)
        target.max_magic = max(0, int(target.max_magic) - 10)
        target.health = min(int(target.health), int(target.base_max_health))
        target.magic = min(int(target.magic), int(target.max_magic))
        custom.pop('jurassic_magic_soil_applied_target', None)
        eq.custom_vars = custom

    def _refresh_jurassic_magic_soil_bonuses(self) -> None:
        for owner_id, owner_state in enumerate(getattr(self, 'players', []) or []):
            for eq in getattr(owner_state, 'equipment', []) or []:
                if not self._card_has_flag(getattr(eq, 'card_instance', None), 'tracked_max_health_projection'):
                    continue
                target_id = self._equipment_effect_target_id(eq, owner_id)
                try:
                    applied = int((getattr(eq, 'custom_vars', {}) or {}).get('jurassic_magic_soil_applied_target', -1))
                except Exception:
                    applied = -1
                if not self._equipment_runtime_active(eq):
                    if applied >= 0:
                        self._remove_jurassic_magic_soil_bonus(eq)
                    continue
                if applied >= 0 and applied != target_id:
                    self._remove_jurassic_magic_soil_bonus(eq)
                self._apply_jurassic_magic_soil_bonus(eq, target_id)

    def _jurassic_lowest_selectable_enemy(self, player_id: int) -> int:
        if not self._valid_player_id(player_id):
            return -1
        if hasattr(self, 'get_enemies'):
            try:
                enemy_ids = list(self.get_enemies(player_id))
            except Exception:
                enemy_ids = []
        else:
            enemy_ids = [pid for pid in range(len(self.players)) if pid != player_id]
        candidates = [
            pid for pid in enemy_ids
            if self._target_can_be_selected(player_id, pid, allow_self=False)
        ]
        if not candidates:
            return -1
        lowest_health = min(int(getattr(self.players[pid], 'health', 0) or 0) for pid in candidates)
        tied = [pid for pid in candidates if int(getattr(self.players[pid], 'health', 0) or 0) == lowest_health]
        return random.choice(tied)

    def _bio_status_value(self, player_id: int, name: str) -> int:
        aliases = {
            'debt': ('bio:debt', 'debt', '负债'),
            'extra_healing': ('bio:extra_healing', 'extra_healing', '额外回复'),
            'shield_conversion': ('bio:shield_conversion', 'shield_conversion', '护盾转化'),
        }
        return self._custom_status_value(player_id, *aliases.get(name, (name,)))

    def _bio_set_status_value(self, player_id: int, name: str, value: int):
        aliases = {
            'debt': ('bio:debt', 'debt', '负债'),
            'extra_healing': ('bio:extra_healing', 'extra_healing', '额外回复'),
            'shield_conversion': ('bio:shield_conversion', 'shield_conversion', '护盾转化'),
        }
        keys = aliases.get(name, (name,))
        self._set_custom_status_alias_group(player_id, keys[0], keys, max(0, int(value or 0)))

    def _bio_active_equipment_targeting(self, target_id: int, *marks: str):
        for owner_id, eq in self._iter_equipment_targeting_player(target_id):
            if any(self._equipment_has_mark(eq, mark) for mark in marks):
                yield owner_id, eq

    def _active_equipment_targeting_flag(self, target_id: int, *flags: str):
        """Active equipment targeting ``target_id`` that declares any of *flags*."""
        for owner_id, eq in self._iter_equipment_targeting_player(target_id):
            card = getattr(eq, 'card_instance', None)
            if any(self._card_has_flag(card, flag) for flag in flags):
                yield owner_id, eq

    def _bio_active_equipment_targeting_flag(self, target_id: int, *flags: str):
        yield from self._active_equipment_targeting_flag(target_id, *flags)

    def _jurassic_active_equipment_targeting_flag(self, target_id: int, *flags: str):
        yield from self._active_equipment_targeting_flag(target_id, *flags)

    def _declared_card_value(self, card_or_def, key, default=None):
        """Read a raw top-level key from the card's data resource (mod.json)."""
        card_def = getattr(card_or_def, 'card_def', card_or_def)
        resource = getattr(card_def, 'v2_resource', None)
        if isinstance(resource, dict) and key in resource:
            return resource.get(key)
        value = getattr(card_def, key, None)
        return default if value is None else value

    def _equipment_card_label(self, equipment) -> str:
        """Display name of the card carried by an equipment instance."""
        card = getattr(equipment, 'card_instance', None)
        return str(getattr(card, 'name_cn', '') or getattr(equipment, 'def_id', '') or '')

    def _bio_stem_cell_after_health_loss(self, target_id: int, amount: int):
        if not self._valid_player_id(target_id):
            return
        amount = max(0, int(amount or 0))
        if amount <= 0:
            return
        for _, eq in list(self._active_equipment_targeting_flag(target_id, 'health_loss_layers')):
            custom = getattr(eq, 'custom_vars', {}) or {}
            custom['layers'] = max(0, int(custom.get('layers', 0) or 0)) + amount
            eq.custom_vars = custom

    def _bio_is_magic_card(self, card: Optional[CardInstance]) -> bool:
        if card is None:
            return False
        values = self._card_local_id_values(card)
        values.update({
            str(getattr(card, 'name_en', '') or ''),
            str(getattr(getattr(card, 'card_def', None), 'name_en', '') or ''),
        })
        return any(
            value.strip().lower().replace('_', ' ').replace('-', ' ').startswith('magic ')
            or value.strip().lower().replace('_', '').replace('-', '').startswith('magic')
            for value in values
            if value
        )

    def _bio_after_card_payment(self, player_id: int, card: CardInstance):
        if not self._valid_player_id(player_id):
            return
        ps = self.players[player_id]
        paid_e = max(0, int(getattr(card, '_paid_e_this_play', 0) or 0))
        paid_m = max(0, int(getattr(card, '_paid_m_this_play', 0) or 0))
        for _, eq in list(self._active_equipment_targeting_flag(player_id, 'shield_on_paid_elixir')):
            if paid_e > 0:
                self._add_custom_status_value(player_id, 'jungle:shield', paid_e)
                self.log_msg(
                    f"{self.pn(player_id)}的{self._equipment_card_label(eq)}使其获得{paid_e}层护盾")
        for _, eq in list(self._active_equipment_targeting_flag(player_id, 'shield_on_paid_any')):
            shield = paid_e + paid_m
            if shield > 0:
                self._add_custom_status_value(player_id, 'jungle:shield', shield)
                self.log_msg(
                    f"{self.pn(player_id)}的{self._equipment_card_label(eq)}使其获得{shield}层护盾")
            self.deal_attack_damage(
                player_id,
                2,
                1,
                attacker_id=player_id,
                source_card=eq.card_instance,
                ignore_untargetable=True,
            )

        if bool(ps.custom_vars.get('bio_blood_chromosome_active')):
            played_count = int(ps.cards_played_this_turn.get(card.def_id, 0) or 0)
            if played_count >= 2 and not self._bio_is_magic_card(card):
                dealt = self.deal_attack_damage(
                    player_id,
                    3,
                    1,
                    attacker_id=player_id,
                    source_card=card,
                    ignore_untargetable=True,
                )
                ps.gain_elixir(1)
                self.log_msg(f"{self.pn(player_id)}的血染色体使其受到{dealt}D并回复1E")

    def _bio_apply_debt_after_recovery(self, player_id: int):
        debt = self._bio_status_value(player_id, 'debt')
        if debt <= 0:
            return
        ps = self.players[player_id]
        lost = 0
        if not self._is_status_immune(player_id):
            lost = min(1, max(0, int(ps.elixir or 0)))
            ps.elixir = max(0, int(ps.elixir or 0) - lost)
        self._bio_set_status_value(player_id, 'debt', debt - 1)
        if lost > 0:
            self.log_msg(f"{self.pn(player_id)}的负债使其失去1E")

    def _bio_turn_start_setup(self, player_id: int):
        if not self._valid_player_id(player_id):
            return
        ps = self.players[player_id]
        pending = ps.custom_vars.pop('bio_job_application_pending', [])
        if not isinstance(pending, list):
            pending = [pending]
        ps.custom_vars['bio_job_application_active'] = [
            int(pid) for pid in pending
            if str(pid).lstrip('-').isdigit() and self._valid_player_id(int(pid))
        ]
        ps.custom_vars['bio_opal_used_this_turn'] = False

    def _bio_turn_end_cleanup(self, player_id: int):
        if not self._valid_player_id(player_id):
            return
        ps = self.players[player_id]
        for key in (
            'bio_blood_chromosome_active',
            'bio_job_application_active',
            'bio_opal_used_this_turn',
        ):
            ps.custom_vars.pop(key, None)

    def _bio_after_damage_hit(self, target_id: int, amount: int):
        if amount <= 0 or not self._valid_player_id(target_id) or self.current_player != target_id:
            return
        ps = self.players[target_id]
        for _, eq in list(self._active_equipment_targeting_flag(target_id, 'damage_hit_temp_swift')):
            candidates = [card for card in ps.hand if int(getattr(card, 'cost_e', 0) or 0) > 0]
            if not candidates:
                continue
            selected = random.choice(candidates)
            selected.temp_swift_value = max(0, int(getattr(selected, 'temp_swift_value', 0) or 0)) + 1
            selected.instance_flags.add('temp_swift')
            self.log_msg(
                f"{self.pn(target_id)}的{self._equipment_card_label(eq)}使{selected.name_cn}获得1层暂时迅捷")
        for _, eq in list(self._active_equipment_targeting_flag(target_id, 'damage_hit_magic_swift')):
            candidates = [card for card in ps.hand if int(getattr(card, 'cost_m', 0) or 0) > 0]
            if not candidates:
                continue
            selected = random.choice(candidates)
            selected.magic_swift_value = max(0, int(getattr(selected, 'magic_swift_value', 0) or 0)) + 2
            selected.instance_flags.add('magic_swift')
            self.log_msg(
                f"{self.pn(target_id)}的{self._equipment_card_label(eq)}使{selected.name_cn}获得2层魔力迅捷")

    def _bio_dna_candidates_for_card(self, card: CardInstance) -> List[str]:
        if card is None or not self._card_selectable_by_action(card):
            return []
        current_e = max(0, int(getattr(card, 'cost_e', 0) or 0))
        if current_e > 4:
            return []
        result = []
        for card_id, card_def in CARD_DEFS.items():
            if not self._card_allowed(card_id) or card_id == ERROR_CARD_ID:
                continue
            candidate = CardInstance(card_id)
            if not self._card_selectable_by_action(candidate):
                continue
            if int(getattr(card_def, 'cost_e', 0) or 0) != current_e + 1:
                continue
            weight = max(0, int(getattr(card_def, 'count', 0) or 0))
            result.extend([card_id] * weight)
        return result

    def _bio_queue_dna_turn_start(self, player_id: int, resume_handler: str) -> bool:
        if not self._valid_player_id(player_id):
            return False
        ps = self.players[player_id]
        queue = []
        dna_equipment = list(self._bio_active_equipment_targeting_flag(player_id, 'dna_turn_transform'))
        if not dna_equipment:
            # Round 10 built-in fallback: definitions/records that only carry the
            # historical ``mark:bio:dna`` still transform a card each turn.
            from engine_runtime_support import builtin_legacy_marks
            dna_equipment = list(self._bio_active_equipment_targeting(
                player_id, *builtin_legacy_marks('dna_turn_transform')))
        for owner_id, eq in dna_equipment:
            if any(self._bio_dna_candidates_for_card(hand_card) for hand_card in ps.hand):
                queue.append({
                    'owner_id': owner_id,
                    'equipment_instance_id': getattr(eq.card_instance, 'instance_id', None),
                    'card': eq.card_instance.to_dict(),
                })
        if not queue:
            return False
        self.custom_vars['bio_dna_turn_queue'] = queue
        self.custom_vars['bio_dna_resume_handler'] = str(resume_handler or '')
        return self._bio_queue_next_dna_choice(player_id)

    def _bio_queue_next_dna_choice(self, player_id: int) -> bool:
        queue = self.custom_vars.get('bio_dna_turn_queue')
        if not isinstance(queue, list):
            return False
        ps = self.players[player_id]
        while queue:
            entry = queue.pop(0)
            eligible = [card for card in ps.hand if self._bio_dna_candidates_for_card(card)]
            if not eligible:
                continue
            self.pending_choice = {
                'player_id': player_id,
                'choice_type': 'choose_card_from_hand',
                'choice_params': {
                    'cancellable': False,
                    'title': 'DNA：选择要变换的手牌',
                    'message': '选择1张当前E消耗不超过4E的手牌',
                },
                'card': entry.get('card'),
                'hand_cards': [card.to_dict() for card in eligible],
                'target_player_id': player_id,
                'bio_dna_turn_start': True,
            }
            return True
        self.custom_vars.pop('bio_dna_turn_queue', None)
        return False

    def _bio_finish_dna_turn_start(self, player_id: int):
        resume_handler = str(self.custom_vars.pop('bio_dna_resume_handler', '') or '')
        if resume_handler:
            handler = getattr(self, resume_handler, None)
            if callable(handler):
                handler(player_id)

    def _bio_resolve_dna_choice(self, player_id: int, pending: dict, choice: Optional[dict]) -> dict:
        self.pending_choice = None
        selected = None
        try:
            selected = self.players[player_id].find_hand_card(int((choice or {}).get('target_instance_id')))
        except Exception:
            selected = None
        candidates = self._bio_dna_candidates_for_card(selected) if selected is not None else []
        if selected is not None and candidates:
            replacement = CardInstance(random.choice(candidates))
            replacement.instance_id = selected.instance_id
            replacement.temp_swift_value = max(0, int(getattr(replacement, 'temp_swift_value', 0) or 0)) + 1
            replacement.instance_flags.add('temp_swift')
            ps = self.players[player_id]
            index = ps.hand.index(selected)
            ps.hand[index] = replacement
            self.log_msg(f"{self.pn(player_id)}的DNA完成一次手牌变换，并使该牌获得1层暂时迅捷")
        if self._bio_queue_next_dna_choice(player_id):
            return {'success': True, 'needs_choice': True}
        self._bio_finish_dna_turn_start(player_id)
        return {'success': True}

    def _bio_queue_auto_play(self, player_id: int, card: CardInstance, choice: Optional[dict],
                             no_cost: bool = False, source: str = ''):
        if not self._valid_player_id(player_id) or card is None:
            return
        ps = self.players[player_id]
        # 牌已经因手牌溢出被弃掉（或本就躺在别的区域）时不再塞回手牌，否则同
        # 一张实例会被重复放进弃牌堆（反馈 #78 爆牌的副产物）。
        if (
            ps.find_hand_card(card.instance_id) is None
            and self._find_card_by_instance_id(card.instance_id) is None
        ):
            ps.add_to_hand(card)
        queue = self.custom_vars.setdefault('bio_auto_play_queue', [])
        if not isinstance(queue, list):
            queue = []
            self.custom_vars['bio_auto_play_queue'] = queue
        queue.append({
            'player_id': player_id,
            'instance_id': int(card.instance_id),
            'choice': dict(choice or {}),
            'no_cost': bool(no_cost),
            'source': str(source or ''),
        })

    def _bio_drain_auto_play_queue(self):
        if getattr(self, '_bio_draining_auto_play', False):
            return
        if self.pending_response is not None or self.pending_choice is not None or getattr(self, 'pending_v2_ui', None):
            return
        queue = self.custom_vars.get('bio_auto_play_queue')
        if not isinstance(queue, list) or not queue:
            self.custom_vars.pop('bio_auto_play_queue', None)
            return
        self._bio_draining_auto_play = True
        try:
            while queue and not self.game_over:
                self._consume_action_work(20)
                if self.pending_response is not None or self.pending_choice is not None or getattr(self, 'pending_v2_ui', None):
                    break
                entry = queue.pop(0)
                player_id = int(entry.get('player_id', -1))
                if not self._valid_player_id(player_id) or self.players[player_id].health <= 0:
                    continue
                card = self.players[player_id].find_hand_card(entry.get('instance_id'))
                if card is None:
                    continue
                previous_auto_actor = getattr(self, '_allow_out_of_turn_auto_play_for', None)
                previous_auto_choice = getattr(self, '_auto_resolve_choices_for', None)
                previous_no_cost = getattr(self, '_auto_play_no_cost_for', None)
                self._allow_out_of_turn_auto_play_for = player_id
                self._auto_resolve_choices_for = player_id
                self._auto_play_no_cost_for = player_id if entry.get('no_cost') else previous_no_cost
                try:
                    if hasattr(self, 'num_players'):
                        target_id = self._choice_target_from_choice(entry.get('choice'), -1)
                        result = self.play_card(player_id, card.instance_id, target_player_id=target_id, choice=entry.get('choice'))
                    else:
                        result = self.play_card(player_id, card.instance_id, entry.get('choice'))
                finally:
                    self._allow_out_of_turn_auto_play_for = previous_auto_actor
                    self._auto_resolve_choices_for = previous_auto_choice
                    self._auto_play_no_cost_for = previous_no_cost
                if isinstance(result, dict) and (
                    result.get('needs_response') or result.get('needs_choice') or result.get('needs_v2_ui')
                ):
                    break
            if not queue:
                self.custom_vars.pop('bio_auto_play_queue', None)
        finally:
            self._bio_draining_auto_play = False

    def _bio_after_card_used(self, player_id: int, card: CardInstance, target_id: int,
                             choice: Optional[dict]):
        if not self._valid_player_id(player_id) or card is None:
            return
        ps = self.players[player_id]
        flags = self._effective_card_flags(card)
        card_type = getattr(card, 'card_type', '')
        paid_e = max(0, int(getattr(card, '_paid_e_this_play', 0) or 0))
        if (
            card_type in ('thorn', 'bloom')
            and 'exile' not in flags
            and 'unique' not in flags
            and paid_e > 0
            and 'bio_magic_cancer_copy' not in (getattr(card, 'setup_modifiers', set()) or set())
        ):
            cancers = list(self._bio_active_equipment_targeting_flag(player_id, 'magic_cancer_echo'))
            for _, eq in cancers:
                cost_m = paid_e * 2
                if ps.magic < cost_m:
                    continue
                ps.magic -= cost_m
                snapshot = getattr(card, '_bio_pre_play_snapshot', None)
                copy_card = fresh_card_copy_from_dict(snapshot if isinstance(snapshot, dict) else card.to_dict(), card.def_id)
                copy_card.setup_modifiers.add('bio_magic_cancer_copy')
                self._bio_queue_auto_play(player_id, copy_card, choice, no_cost=True, source='magic_cancer')
                self.log_msg(f"{self.pn(player_id)}的魔法癌细胞消耗{cost_m}M，额外打出{card.name_cn}")

        if card_type == 'thorn' and not bool(ps.custom_vars.get('bio_opal_used_this_turn')):
            opals = list(self._bio_active_equipment_targeting_flag(player_id, 'opal_auto_play_deck_thorn'))
            if opals:
                ps.custom_vars['bio_opal_used_this_turn'] = True
                top_index = next((i for i, c in enumerate(ps.deck) if getattr(c, 'card_type', '') == 'thorn'), -1)
                queued = None
                if top_index >= 0:
                    candidate = ps.deck[top_index]
                    previous_temp_swift = max(0, int(getattr(candidate, 'temp_swift_value', 0) or 0))
                    had_temp_swift_flag = 'temp_swift' in getattr(candidate, 'instance_flags', set())
                    candidate.temp_swift_value = max(0, int(getattr(candidate, 'temp_swift_value', 0) or 0)) + 1
                    candidate.instance_flags.add('temp_swift')
                    can_auto_play, _ = self.can_play_card(player_id, candidate)
                    if can_auto_play:
                        queued = ps.deck.pop(top_index)
                    else:
                        candidate.temp_swift_value = previous_temp_swift
                        if not had_temp_swift_flag:
                            candidate.instance_flags.discard('temp_swift')
                fallback_card = None
                for _, opal_eq in opals:
                    fallback_card = self._declared_card_value(
                        getattr(opal_eq, 'card_instance', None), 'fallback_card')
                    if fallback_card:
                        break
                if queued is None and fallback_card and str(fallback_card) in CARD_DEFS:
                    queued = CardInstance(str(fallback_card))
                    queued.instance_flags.add('exile')
                if queued is not None:
                    auto_target = self._default_auto_target_choice(
                        player_id,
                        allow_self='self_target' in self._effective_card_flags(queued),
                    )
                    auto_choice = dict(choice or {})
                    if auto_target >= 0:
                        auto_choice.update({
                            'target_player': auto_target,
                            'target_player_id': auto_target,
                            'target_id': auto_target,
                        })
                    self._bio_queue_auto_play(player_id, queued, auto_choice, no_cost=False, source='opal')
                    self.log_msg(f"{self.pn(player_id)}的蛋白石自动打出{queued.name_cn}")
        self._bio_drain_auto_play_queue()

    def _bio_indictment_converts_damage(self, target_id: int, amount: int,
                                        damage_type: Optional[str], damage_tag: Optional[str],
                                        source_card: Optional[CardInstance] = None) -> bool:
        amount = max(0, int(amount or 0))
        if amount <= 0 or not self._valid_player_id(target_id):
            return False
        source_card = source_card or getattr(self, '_active_v2_card', None)
        if source_card is None:
            return False
        # Round 40 / 批次 AE-3：标记从实例属性搬进 ``custom_vars``（起诉书的数据
        # 现在写 ``card_var_change``），读取方跟着换 ``custom_vars``。
        marker = (getattr(source_card, 'custom_vars', None) or {}).get('_bio_indictment_target_id', -1)
        if int(marker or -1) != target_id:
            return False
        is_physical = damage_type == DAMAGE_TYPE_PHYSICAL
        is_electric = str(damage_tag or '') in (DAMAGE_TAG_BATTERY, 'electric', '电伤')
        if not (is_physical or is_electric):
            return False
        self._add_custom_status_value(target_id, 'jungle:shield', amount)
        self.log_msg(f"{self.pn(target_id)}的起诉书将{amount}点伤害转化为{amount}层护盾")
        return True

    def _jurassic_active_equipment_targeting(self, target_id: int, *marks: str):
        for owner_id, eq in self._iter_equipment_targeting_player(target_id):
            if any(self._equipment_has_mark(eq, mark) for mark in marks):
                yield owner_id, eq

    def _jurassic_redirect_healing(self, player_id: int, amount: int) -> int:
        amount = max(0, int(amount or 0))
        if amount <= 0:
            return 0
        extra_healing = self._bio_status_value(player_id, 'extra_healing')
        if extra_healing > 0 and not self._is_status_immune(player_id):
            amount += extra_healing
        shield_conversion = self._bio_status_value(player_id, 'shield_conversion')
        if shield_conversion > 0 and not self._is_status_immune(player_id):
            shield = amount * shield_conversion
            self._bio_set_status_value(player_id, 'shield_conversion', 0)
            self._add_custom_status_value(player_id, 'jungle:shield', shield)
            self.log_msg(f"{self.pn(player_id)}的护盾转化将{amount}H转化为{shield}层护盾")
            return 0
        tooth = next(self._active_equipment_targeting_flag(player_id, 'heal_redirect_to_attack'), None)
        if tooth is None:
            return amount
        enemy_id = self._jurassic_lowest_selectable_enemy(player_id)
        if enemy_id < 0:
            return amount
        _, eq = tooth
        dealt = self.deal_attack_damage(
            enemy_id,
            amount,
            1,
            attacker_id=player_id,
            source_card=eq.card_instance,
        )
        self.log_msg(
            f"{self.pn(player_id)}的{self._equipment_card_label(eq)}将{amount}H转为对{self.pn(enemy_id)}的{dealt}D")
        return 0

    def _jurassic_redirect_magic_gain(self, player_id: int, amount: int) -> int:
        amount = max(0, int(amount or 0))
        if amount <= 0:
            return 0
        if amount > 1:
            magic_dna = list(self._active_equipment_targeting_flag(player_id, 'magic_gain_to_elixir'))
            if magic_dna:
                gained_e = 2 * len(magic_dna)
                self.players[player_id].gain_elixir(gained_e)
                self.log_msg(
                    f"{self.pn(player_id)}的{self._equipment_card_label(magic_dna[0][1])}阻止{amount}M回复并回复{gained_e}E")
                return 0
        tooth = next(self._active_equipment_targeting_flag(player_id, 'magic_gain_to_attack'), None)
        if tooth is None:
            return amount
        enemy_id = self._jurassic_lowest_selectable_enemy(player_id)
        if enemy_id < 0:
            return amount
        _, eq = tooth
        damage = amount * 3
        dealt = self.deal_attack_damage(
            enemy_id,
            damage,
            1,
            attacker_id=player_id,
            source_card=eq.card_instance,
        )
        self.log_msg(
            f"{self.pn(player_id)}的{self._equipment_card_label(eq)}将{amount}M转为对{self.pn(enemy_id)}的{dealt}D")
        return 0

    def _clear_status_immune_aliases(self, player_id: int):
        if not (0 <= player_id < len(self.players)):
            return
        ps = self.players[player_id]
        ps.custom_statuses = getattr(ps, 'custom_statuses', {}) or {}
        for key in ('status_immune', 'immune', '状态免疫'):
            ps.custom_statuses.pop(key, None)

    def _equipment_effect_target_id(self, eq: EquipmentInstance, fallback_owner_id: int) -> int:
        try:
            target_id = int(getattr(eq, 'effect_target', fallback_owner_id))
        except Exception:
            target_id = fallback_owner_id
        if not (0 <= target_id < len(self.players)):
            target_id = fallback_owner_id
        return target_id

    def _has_other_pill_targeting(self, target_id: int, exclude_eq: Optional[EquipmentInstance] = None) -> bool:
        if not (0 <= target_id < len(self.players)):
            return False
        for owner_id, player in enumerate(self.players):
            for candidate in getattr(player, 'equipment', []) or []:
                if candidate is exclude_eq:
                    continue
                if not self._equipment_runtime_active(candidate):
                    continue
                if not self._card_has_flag(getattr(candidate, 'card_instance', None), 'status_immune_equipment'):
                    continue
                if self._equipment_effect_target_id(candidate, owner_id) == target_id:
                    return True
        return False

    def _has_other_sponge_targeting(self, target_id: int, exclude_eq: Optional[EquipmentInstance] = None) -> bool:
        if not (0 <= target_id < len(self.players)):
            return False
        for owner_id, player in enumerate(self.players):
            for candidate in getattr(player, 'equipment', []) or []:
                if candidate is exclude_eq:
                    continue
                if not self._equipment_runtime_active(candidate):
                    continue
                if not self._card_has_flag(getattr(candidate, 'card_instance', None), 'sponge_active_projection'):
                    continue
                if self._equipment_effect_target_id(candidate, owner_id) == target_id:
                    return True
        return False

    def _cleanup_equipment_derived_effects(self, owner_id: int, eq: EquipmentInstance,
                                           *, run_destroy_event: bool = True) -> None:
        if not (0 <= owner_id < len(self.players)) or eq is None:
            return
        effect_target_id = self._equipment_effect_target_id(eq, owner_id)
        was_sealed_suspended = bool((getattr(eq, 'custom_vars', {}) or {}).get('_sewers_sealed_suspended'))
        non_stack_active = self._non_stack_equipment_is_active(eq)
        if self._card_has_flag(getattr(eq, 'card_instance', None), 'tracked_max_health_projection'):
            self._remove_jurassic_magic_soil_bonus(eq)
        if self._card_has_flag(getattr(eq, 'card_instance', None), 'electric_web_cleanup'):
            self._cleanup_electric_web_draw_damage(eq)
        from engine_runtime_support import apply_equipment_projection
        apply_equipment_projection(self, owner_id, eq, 'cleanup',
                                   run_destroy_event=run_destroy_event,
                                   was_sealed=was_sealed_suspended)
        # A transformation removes persistent equip bonuses, but is not a
        # destruction and must not run offensive destroy effects (for example Sponge).

        is_pill = self._card_has_flag(getattr(eq, 'card_instance', None), 'status_immune_equipment')
        has_destroy_script = self._has_card_event(eq.card_def, 'equipment_destroy')
        if run_destroy_event and has_destroy_script and non_stack_active:
            self._run_card_event(owner_id, eq.card_instance, 'equipment_destroy', None,
                                 {'source_id': owner_id, 'target_id': effect_target_id,
                                  'equipment_owner_id': owner_id})
        elif (
            self._card_has_flag(getattr(eq, 'card_instance', None), 'sponge_destroy_effect')
            and non_stack_active
            and self.players[effect_target_id].sponge_active
            and not self._has_other_sponge_targeting(effect_target_id, exclude_eq=eq)
        ):
            target_state = self.players[effect_target_id]
            poison_layers = target_state.poison
            target_state.sponge_active = False
            target_state.poison = 0
            if poison_layers > 0:
                physical_dmg = poison_layers * 2
                old_health = target_state.health
                target_state.health -= physical_dmg
                health_lost = max(
                    0,
                    int(old_health or 0) - max(0, int(target_state.health or 0)),
                )
                self._bio_stem_cell_after_health_loss(effect_target_id, health_lost)
                self._note_achievement_health(effect_target_id)
                self.log_msg(f"海绵被摧毁！{self.pn(effect_target_id)}去除{poison_layers}层中毒，受到{physical_dmg}点物理伤害")
                self._check_yggdrasil(effect_target_id)
            else:
                self.log_msg("海绵被摧毁！无中毒层数")

        if is_pill:
            other_pill_covers_target = self._has_other_pill_targeting(
                effect_target_id,
                exclude_eq=eq,
            )
            if (
                not (run_destroy_event and has_destroy_script)
                and not other_pill_covers_target
            ):
                self._clear_status_immune_aliases(effect_target_id)
                self.log_msg("药丸被摧毁！状态免疫失效")
            # Clean up immunity that may have been applied to the equipment owner by older
            # owner-derived Pill logic. Keep it if another active Pill still targets them.
            if owner_id != effect_target_id and not self._has_other_pill_targeting(owner_id, exclude_eq=eq):
                self._clear_status_immune_aliases(owner_id)

        root_layers = 0
        try:
            root_layers = int((getattr(eq, 'custom_vars', {}) or {}).get('jungle_root_layers', 0) or 0)
        except Exception:
            root_layers = 0
        if root_layers > 0 and not was_sealed_suspended:
            current = self._custom_status_value(effect_target_id, 'jungle:root_status', 'jungle:root', 'root_status')
            self._set_custom_status_alias_group(
                effect_target_id,
                'jungle:root_status',
                ('jungle:root_status', 'jungle:root', 'root_status'),
                max(0, current - root_layers),
            )
        if root_layers > 0:
            eq.custom_vars['jungle_root_layers'] = 0
        eq.custom_vars.pop('_sewers_sealed_suspended', None)
        eq.custom_vars.pop('_sewers_sealed_skip_boundary', None)
        eq.custom_vars.pop('sewers_sealed', None)

        self._apply_prop_snapshot_restore_on_leave(effect_target_id, eq)

    def _destroy_equipment(self, owner_id: int, eq: EquipmentInstance, check_protection: bool = True,
                           source_id: Optional[int] = None) -> bool:
        ps = self.players[owner_id]
        if 'indestructible' in eq.card_instance.flags:
            return False
        if check_protection and int(getattr(eq, 'armor', 0) or 0) > 0:
            eq.armor = max(0, int(getattr(eq, 'armor', 0) or 0) - 1)
            self.log_msg(f"{self.pn(owner_id)}的{eq.card_def.name_cn}装备护甲抵消了摧毁（剩余{eq.armor}）")
            return False
        if check_protection and ps.equipment_protection > 0:
            ps.equipment_protection -= 1
            self.log_msg(f"{self.pn(owner_id)}的装备保护抵消了摧毁！")
            return False
        self._cleanup_equipment_derived_effects(owner_id, eq, run_destroy_event=True)
        ps.equipment.remove(eq)
        if 'exile' in eq.card_instance.flags:
            self._put_card_in_exile(owner_id, eq.card_instance)
        else:
            self._discard_card(ps, eq.card_instance)
        self._refresh_equipment_derived_player_flags(owner_id)
        self._refresh_hand_limit_bonuses()
        self._note_achievement_equipment_destroyed(source_id)
        self._note_achievement_equipment_count(owner_id)
        self._dispatch_card_event('equipment_destroyed', owner_id if source_id is None else source_id,
                                  eq.card_instance, target_id=owner_id,
                                  equipment=eq, equipment_owner_id=owner_id)
        return True

    def end_turn(self, player_id: int) -> dict:
        if self.current_player != player_id:
            return {'success': False, 'error': '不是你的回合'}
        if self.pending_response is not None:
            return {'success': False, 'error': '等待反制响应'}
        self._end_player_turn(player_id)
        return {'success': True}

    def _end_player_turn(self, player_id: int):
        self._start_new_turn_boundary()
        ps = self.players[player_id]
        opp = self.players[1 - player_id]
        self._run_v2_event_hooks('turn_end', {
            'source_player': player_id,
            'target_player': player_id,
            'vars': {'player_id': player_id},
            'current_action': {'player_id': player_id},
        })
        if self.game_over or getattr(self, 'pending_v2_ui', None):
            return
        self._run_hand_owner_turn_end_events(player_id)
        if self.game_over or getattr(self, 'pending_v2_ui', None):
            return
        self._clear_ocean_card_hand_blind_turn_end(player_id)
        self._trigger_v2_status_events_for_player(player_id, 'on_turn_end', {'player_id': player_id})
        if self.game_over or getattr(self, 'pending_v2_ui', None):
            return
        self._run_owner_turn_end_equipment(player_id)
        if self.game_over or getattr(self, 'pending_v2_ui', None):
            return
        self._run_garden_magic_pollen_owner_turn_end(player_id)
        if self.game_over or getattr(self, 'pending_v2_ui', None):
            return
        self._drain_turn_end_event_sources(player_id)
        if self.game_over or self.pending_choice is not None or getattr(self, 'pending_v2_ui', None):
            return
        self._apply_equal_suffering_turn_end(player_id)
        if self.game_over:
            return
        self._apply_energy_surge_turn_end(player_id)
        if self.game_over:
            return
        # Turn-end phase for generic timed_effect entries (target_turn_end /
        # owner_turn_end).  Skipped turns run through _end_player_turn as well, so
        # a stunned player still reaches this phase exactly once.
        self._run_timed_effects_for_turn(player_id, 'turn_end')
        if self.game_over or getattr(self, 'pending_v2_ui', None):
            return
        from engine_runtime_support import cleanup_turn_end
        cleanup_turn_end(self, player_id)
        self._decay_equipment_armor_end_turn(player_id)
        # Fracture: clear at end of own turn. Status immunity suppresses the effect, not decay.
        if ps.fracture > 0:
            ps.fracture = 0
            self.log_msg(f"{self.pn(player_id)}的破损效果消失")
        # Weakness: decrement at end of own turn.
        if ps.weakness > 0:
            ps.weakness = max(0, ps.weakness - 1)
            if ps.weakness == 0:
                self.log_msg(f"{self.pn(player_id)}的虚弱效果消失")
        # Bleed: halve at end of turn.
        if ps.bleed > 0:
            ps.bleed = max(0, ps.bleed // 2)
            if ps.bleed == 0:
                self.log_msg(f"{self.pn(player_id)}的流血效果消失")
        try:
            hel_turn_bonus = float((getattr(ps, 'custom_vars', {}) or {}).get('hel_crit_multiplier_turn_bonus', 0) or 0)
        except Exception:
            hel_turn_bonus = 0
        if hel_turn_bonus != 0:
            ps.custom_vars['hel_crit_multiplier_turn_bonus'] = 0
            self._hel_sync_crit_multiplier_display(player_id)
            self.log_msg(f"{self.pn(player_id)}的临时暴击倍率结束")
        self._decay_end_turn_layer_statuses(player_id)
        frost = self._arctic_frost_value(player_id)
        if frost > 0:
            self._arctic_set_frost_value(player_id, frost // 2)
            if self._arctic_frost_value(player_id) <= 0:
                self.log_msg(f"{self.pn(player_id)}的霜冻效果消失")
        ps.custom_vars.pop('arctic_snowballs', None)
        ps.custom_vars.pop('arctic_ready_queue', None)
        self._clear_turn_scoped_effects(player_id)
        # Track M gained this turn for next turn's check
        ps.m_gained_last_turn = ps.m_gained_this_turn
        ps.m_gained_this_turn = False
        self._return_cogwheel_cards_now(player_id)
        void_cards = [c for c in ps.hand if 'void' in c.flags]
        for c in void_cards:
            ps.hand.remove(c)
            self._void_exile_card(player_id, c)
        self._decay_action_limit_status(player_id, 'attack_blocked', 'attack_blocked', '禁攻')
        self._decay_action_limit_status(player_id, 'attack_only', 'attack_only', '仅攻击')
        self._decay_action_limit_status(
            player_id,
            'magic_blocked',
            'magic_blocked',
            '魔力封锁',
            'troll_cards:magic_blocked',
        )
        if (
            ps.invincible
            and not ps.bandage_death_pending
            and self._should_expire_invincible_on_turn_end(player_id)
        ):
            self._clear_invincible_state(player_id)
            self.log_msg(f"{self.pn(player_id)}的无敌效果结束")
        self._decay_ocean_card_charge_turn_end(player_id)
        self._bio_turn_end_cleanup(player_id)
        from formal_logic_runtime import on_turn_end as formal_logic_turn_end
        formal_logic_turn_end(self, player_id)
        self._save_last_turn_damage_snapshot(player_id)
        self._expire_bandages_after_action(player_id)
        self._clear_turn_card_tracking(player_id)
        if self.game_over:
            return
        if player_id == self.first_player:
            other = 1 - self.first_player
            self._start_player_turn(other)
        else:
            self._end_round()

    def _void_exile_card(self, owner_id: int, card: CardInstance):
        if not (0 <= owner_id < len(self.players)) or card is None:
            return
        ps = self.players[owner_id]
        already_exiled = card in ps.exile
        self._put_card_in_exile(owner_id, card, trigger=False)
        self.log_msg(f"{self.pn(owner_id)}的{card.name_cn}因虚无被放逐")
        if not already_exiled:
            self._handle_card_exiled(owner_id, card)
        context = {
            'event': 'void_exile',
            'current_event': 'void_exile',
            'source_id': owner_id,
            'target_id': owner_id,
            'void_exiled_card': card,
        }
        if self._has_card_event(getattr(card, 'card_def', None), 'on_void_exile'):
            self._run_card_event(owner_id, card, 'on_void_exile', None, context)
        # Singularity listens globally for cards exiled by Void.
        for eq_owner_id, owner in enumerate(getattr(self, 'players', []) or []):
            for eq in list(getattr(owner, 'equipment', []) or []):
                if not self._card_has_flag(getattr(eq, 'card_instance', None), 'punish_void_exile'):
                    continue
                if not self._non_stack_equipment_is_active(eq):
                    continue
                target_id = int(getattr(eq, 'effect_target', eq_owner_id))
                if not self._valid_player_id(target_id):
                    continue
                self._deal_direct_damage(
                    target_id,
                    2,
                    '奇点',
                    eq_owner_id,
                    damage_type=DAMAGE_TYPE_MAGIC,
                    damage_tag=DAMAGE_TAG_BATTERY,
                )

    def _run_owner_turn_end_equipment(self, player_id: int):
        if not (0 <= player_id < len(self.players)):
            return
        for owner_id, eq in self._iter_equipment_targeting_player(player_id):
            if not self._has_card_event(eq.card_def, 'owner_turn_end'):
                continue
            target_id = getattr(eq, 'effect_target', owner_id)
            if not isinstance(target_id, int) or not (0 <= target_id < len(self.players)):
                target_id = player_id
            self._run_card_event(owner_id, eq.card_instance, 'owner_turn_end', None, {
                'event': 'owner_turn_end',
                'source_id': owner_id,
                'target_id': target_id,
                'current_equipment': eq,
                'selected_equipment_instance_id': getattr(eq.card_instance, 'instance_id', None),
                'selected_equipment_owner_id': owner_id,
            })

    def _decay_equipment_armor_end_turn(self, player_id: int):
        if not (0 <= player_id < len(self.players)):
            return
        for eq in list(self.players[player_id].equipment):
            armor = int(getattr(eq, 'armor', 0) or 0)
            if armor > 0:
                eq.armor = max(0, armor - 1)
            if self.game_over or getattr(self, 'pending_v2_ui', None):
                return

    def _end_round(self):
        self.round_num += 1
        if self.game_over:
            return
        self._start_draw_phase()

    def get_counter_cards(self, player_id: int, trigger_type: str) -> List[CardInstance]:
        ps = self.players[player_id]
        return [
            c for c in ps.hand
            if c.card_def.response_trigger == trigger_type
            and self._counter_card_can_counter_pending(player_id, c)
        ]

    def get_enemy_equipment(self, player_id: int) -> List[EquipmentInstance]:
        return self.players[1 - player_id].equipment

    def _data_step_targets(self, player_id, card, selector, context=None):
        """Round 32 / 批次 AA：按 v2 运行时的词表解析一步的目标玩家集合。

        生命 / 资源 / 抽牌三族原先由运行时用 ``resolve_v2_target`` +
        ``_as_player_list`` 解析目标，里面有一组只有运行时认得的"上下文集合"
        选择器（``all_selectable`` / ``play_targets`` / ``target_players`` …）；
        合并进引擎原子后必须沿用同一套解析，否则 4 人局的
        ``target:"all_selectable"`` 会从"全队"退化成"自己"。
        运行时解析为空时回落引擎自己的选择器词表（老效果表的写法国）。
        """

        resolved = []
        try:
            from mod_runtime_v2 import _as_player_list as _rt_player_list
            from mod_runtime_v2 import resolve_v2_target as _rt_resolve_target
            runtime_context = dict(context) if isinstance(context, dict) else {}
            runtime_context.setdefault('source_player', player_id)
            resolved = list(_rt_player_list(self, _rt_resolve_target(self, runtime_context, selector)))
        except Exception:
            resolved = []
        if not resolved:
            resolved = self._list_effect_targets(player_id, card, selector, context)
        return [target_id for target_id in resolved if self._valid_player_id(target_id)]

    def _list_effect_targets(self, player_id, card, selector, context=None):
        """Resolve a data-step target selector into a de-duplicated player list.

        A wide-strike play records every chosen target in the effect context, so
        generic atoms must expand that instead of collapsing back to one player.
        Accepts a single selector, an explicit list of selectors or plain ids.
        """
        if context is None or not isinstance(context, dict):
            context = getattr(self, '_active_effect_context', {}) or {}
        if isinstance(selector, (list, tuple, set)):
            resolved = []
            for item in selector:
                for target_id in self._list_effect_targets(player_id, card, item, context):
                    if target_id not in resolved:
                        resolved.append(target_id)
            return resolved
        if isinstance(selector, str) and selector.strip().lower() in (
            'target', 'event_target', 'chosen_target', 'choice_target', 'wide_strike_targets',
        ):
            if selector.strip().lower() == 'wide_strike_targets':
                expanded = []
                for target_id in self._wide_strike_target_ids(player_id, card):
                    if target_id not in expanded:
                        expanded.append(target_id)
                if expanded:
                    return expanded
                wide = context.get('wide_strike_targets') if isinstance(context, dict) else None
                if isinstance(wide, list) and wide:
                    resolved = []
                    for raw_target in wide:
                        try:
                            target_id = int(raw_target)
                        except (TypeError, ValueError):
                            continue
                        if self._valid_player_id(target_id) and target_id not in resolved:
                            resolved.append(target_id)
                    if resolved:
                        return resolved
            wide = context.get('wide_strike_targets') if isinstance(context, dict) else None
            if isinstance(wide, list) and wide:
                resolved = []
                for raw_target in wide:
                    try:
                        target_id = int(raw_target)
                    except (TypeError, ValueError):
                        continue
                    if self._valid_player_id(target_id) and target_id not in resolved:
                        resolved.append(target_id)
                if resolved:
                    return resolved
        try:
            raw_targets = self._resolve_targets(player_id, selector)
        except Exception:
            raw_targets = []
        return [target_id for target_id in raw_targets if self._valid_player_id(target_id)]

    def _resolve_target(self, player_id, target_str):
        if isinstance(target_str, int):
            return target_str
        if not target_str or target_str == 'self':
            return player_id
        elif target_str in ('target', 'choice_target', 'selected_target', 'chosen_target'):
            selected = self._selected_choice_target(-1)
            if self._target_can_be_selected(player_id, selected, allow_self=True):
                return selected
            enemy_id = 1 - player_id
            return enemy_id if self._target_can_be_selected(player_id, enemy_id, allow_self=False) else -1
        elif target_str == 'enemy':
            enemy_id = 1 - player_id
            return enemy_id if self._target_can_be_selected(player_id, enemy_id, allow_self=False) else -1
        elif target_str == 'both':
            return -1
        elif target_str == 'random':
            from engine_runtime_support import forced_random_target
            return forced_random_target(self, player_id, [player_id, 1 - player_id])
        elif target_str == 'wide_strike_targets':
            active_card = None
            active_context = getattr(self, '_active_effect_context', None)
            if isinstance(active_context, dict):
                active_card = active_context.get('card') or active_context.get('event_card')
            if active_card is None:
                active_card = self._v2_active_damage_card()
            for target_id in self._wide_strike_target_ids(player_id, active_card):
                if self._valid_player_id(target_id):
                    return target_id
            return player_id
        return player_id
    def _resolve_targets(self, player_id, target_str):
        if isinstance(target_str, int):
            return [target_str] if 0 <= target_str < len(self.players) else []
        if target_str in ('all_players', 'all'):
            return list(range(len(self.players)))
        if target_str in ('both', 'random_side'):
            return [0, 1]
        if target_str in ('all_others', 'all_except_self', 'everyone_else'):
            return [
                tid for tid in range(len(self.players))
                if tid != player_id and self._target_can_be_selected(player_id, tid, allow_self=False)
            ]
        if target_str in ('all_selectable', 'all_targets', 'every_selectable'):
            return [
                tid for tid in range(len(self.players))
                if self._target_can_be_selected(player_id, tid, allow_self=True)
            ]
        if target_str == 'wide_strike_targets':
            active_card = None
            active_context = getattr(self, '_active_effect_context', None)
            if isinstance(active_context, dict):
                active_card = active_context.get('card') or active_context.get('event_card')
            if active_card is None:
                active_card = self._v2_active_damage_card()
            return [
                tid for tid in self._wide_strike_target_ids(player_id, active_card)
                if self._valid_player_id(tid)
            ]
        if target_str in ('play_targets', 'action_targets', 'chosen_targets'):
            active_context = getattr(self, '_active_effect_context', None)
            wide = active_context.get('wide_strike_targets') if isinstance(active_context, dict) else None
            if isinstance(wide, list) and wide:
                resolved = []
                for raw_target in wide:
                    try:
                        target_id = int(raw_target)
                    except (TypeError, ValueError):
                        continue
                    if self._valid_player_id(target_id) and target_id not in resolved:
                        resolved.append(target_id)
                if resolved:
                    return resolved
            single = self._resolve_target(player_id, 'target')
            return [single] if self._valid_player_id(single) else []
        if target_str in ('friendly', 'self', None, ''):
            return [player_id]
        if target_str == 'all_friendlies':
            return [player_id]
        if target_str == 'teammate':
            return [player_id]
        if target_str == 'enemy':
            enemy_id = 1 - player_id
            return [enemy_id] if self._target_can_be_selected(player_id, enemy_id, allow_self=False) else []
        if target_str == 'all_enemies':
            enemy_id = 1 - player_id
            return [enemy_id] if self._target_can_be_selected(player_id, enemy_id, allow_self=False) else []
        if target_str == 'random_friendly':
            return [player_id]
        if target_str == 'random_enemy':
            enemy_id = 1 - player_id
            return [enemy_id] if self._target_can_be_selected(player_id, enemy_id, allow_self=False) else []
        if target_str == 'random_player':
            from engine_runtime_support import forced_random_target
            target_id = forced_random_target(self, player_id, [0, 1])
            return [target_id] if target_id >= 0 else []
        rid = self._resolve_target(player_id, target_str)
        if rid == -1:
            return []
        return [rid]
    def _card_needs_choice(self, card: CardInstance) -> bool:
        # Round 7：原先按 def_id 硬编码的 8 张卡（裂变/融合/拟态/染色体/污水/辣椒/罗盘/磁铁）
        # 已由卡数据的 ``request(type:"card")`` / ``request(type:"zone")``（Round 29 前的
        # ``choose_from_discard``）步骤覆盖；
        # 这里只保留 legacy ``effects`` 通道（第三方包兼容）。
        if card.card_def.effects:
            for e in card.card_def.effects:
                if isinstance(e, dict) and self._request_kind_of(e) in ('card', 'zone'):
                    return True
        return False
    def _get_choice_type(self, card: CardInstance) -> str:
        # Round 7：卡名名单已删除，选择类型由数据步骤（``_choice_type_for_effect``）给出；
        # 这里只保留 legacy ``effects`` 通道（第三方包兼容）。
        if card.card_def.effects:
            for e in card.card_def.effects:
                if isinstance(e, dict):
                    t = e.get('type', '')
                    if t == 'steal_enemy_card':
                        return 'choose_from_enemy_hand'
                    if self._request_kind_of(e):
                        return self._choice_type_for_effect(e, card)
        return ''
    def _eval_expr(self, player_id, expr, card=None):
        if isinstance(expr, (int, float, bool)):
            return expr
        if isinstance(expr, str):
            text = expr.strip()
            if text and text[0] in '{[':
                try:
                    return self._eval_expr(player_id, json.loads(text), card)
                except Exception:
                    pass
            try:
                return int(expr)
            except Exception:
                return expr
        if not isinstance(expr, dict):
            return 0
        ref = expr.get('ref')
        if ref == 'var':
            tid = self._resolve_target(player_id, expr.get('target', 'self'))
            name = str(expr.get('name', 'var'))
            if self._is_suppressed_status_var(tid, name):
                return 0
            return int(self.players[tid].custom_vars.get(name, 0))
        if ref == 'target_attribute':
            tid = self._resolve_target(player_id, expr.get('target', 'self'))
            return int(self._get_player_property_value(tid, expr.get('attr', 'health')))
        if ref == 'math_op':
            a = int(self._eval_expr(player_id, expr.get('a', 0), card))
            b = int(self._eval_expr(player_id, expr.get('b', 0), card))
            op = expr.get('op', '+')
            if op == '+': return a + b
            if op == '-': return a - b
            if op == '*': return a * b
            if op == '/': return 0 if b == 0 else a // b
            return 0
        if ref == 'status_count':
            tid = self._resolve_target(player_id, expr.get('target', 'self'))
            ps = self.players[tid]
            status = str(expr.get('status', ''))
            counts = {
                'poison': ps.poison,
                '中毒': ps.poison,
                'burn': ps.fire,
                'fire': ps.fire,
                '灼烧': ps.fire,
                'toxic': ps.toxic,
                '淬毒': ps.toxic,
                'dodge': ps.dodge,
                '闪避': ps.dodge,
                'equip_protection': ps.equipment_protection,
                'equipment_protection': ps.equipment_protection,
                '装备摧毁保护': ps.equipment_protection,
                '装备保护': ps.equipment_protection,
            }
            if status in counts:
                return int(counts.get(status, 0))
            # Round 19: names outside the built-in table (``hel:luck`` and the
            # rest of ``custom_statuses``) read through the shared, immune-aware
            # accessor, so data conditions such as ``幸运 + 4 > 12`` are
            # expressible without an engine-side per-card branch.
            return int(self._get_status_count(tid, status))
        if ref == 'hand_size':
            tid = self._resolve_target(player_id, expr.get('target', 'self'))
            return len(self.players[tid].hand)
        if ref == 'hand_limit':
            tid = self._resolve_target(player_id, expr.get('target', 'self'))
            return self.players[tid].hand_limit()
        if ref == 'discard_size':
            tid = self._resolve_target(player_id, expr.get('target', 'self'))
            return len(self.players[tid].discard)
        if ref == 'exile_size':
            tid = self._resolve_target(player_id, expr.get('target', 'self'))
            return len(self.players[tid].exile)
        if ref == 'deck_remaining':
            tid = self._resolve_target(player_id, expr.get('target', 'self'))
            return len(self.players[tid].deck)
        if ref == 'turn_number':
            return int(self.round_num)
        if ref == 'play_count':
            return int(getattr(card, 'play_count', 0)) if card is not None else 0
        if ref == 'equip_turns':
            return int(getattr(card, 'equip_turns', 0)) if card is not None else 0
        if ref == 'durability':
            return int(getattr(card, 'durability', 0)) if card is not None else 0
        if ref == 'incoming_damage':
            return int(self._incoming_damage_hint[player_id])
        if ref == 'last_damage':
            tid = self._resolve_target(player_id, expr.get('target', 'self')) if isinstance(expr, dict) else player_id
            return int(self._last_damage_value[tid])
        if ref == 'equip_count':
            tid = self._resolve_target(player_id, expr.get('target', 'self'))
            return len(self.players[tid].equipment)
        if ref == 'round':
            v = float(self._eval_expr(player_id, expr.get('value', 0), card))
            mode = expr.get('mode', 'round')
            return int(math.ceil(v) if mode == 'ceil' else math.floor(v) if mode == 'floor' else round(v))
        if ref == 'min_max':
            a = int(self._eval_expr(player_id, expr.get('a', 0), card))
            b = int(self._eval_expr(player_id, expr.get('b', 0), card))
            return max(a, b) if expr.get('mode', 'max') == 'max' else min(a, b)
        if ref == 'clamp':
            v = int(self._eval_expr(player_id, expr.get('value', 0), card))
            mn = int(self._eval_expr(player_id, expr.get('min', 0), card))
            mx = int(self._eval_expr(player_id, expr.get('max', 99), card))
            return max(mn, min(mx, v))
        return 0
    def _eval_condition(self, player_id, cond, card=None):
        if isinstance(cond, bool):
            return cond
        if isinstance(cond, str):
            text = cond.strip()
            if text and text[0] in '{[':
                try:
                    return self._eval_condition(player_id, json.loads(text), card)
                except Exception:
                    pass
            if text in ('true', 'True'): return True
            if text in ('false', 'False'): return False
            return False
        if not isinstance(cond, dict):
            return False
        op = cond.get('op')
        if op == 'compare':
            a = self._eval_expr(player_id, cond.get('a', 0), card)
            b = self._eval_expr(player_id, cond.get('b', 0), card)
            # Round 16: the v2 spelling ``operator: "=="`` (and ``"<>"``) must
            # mean equality/inequality here too; the old chain silently treated
            # ``==`` as ``>=``, so an engine-path condition disagreed with the
            # same condition on the runtime path.
            raw_cmp = str(cond.get('operator', '=') or '=')
            cmp = {'==': '=', '<>': '!='}.get(raw_cmp, raw_cmp)
            return (a == b) if cmp == '=' else (a != b) if cmp == '!=' else (a < b) if cmp == '<' else (a > b) if cmp == '>' else (a <= b) if cmp == '<=' else (a >= b)
        if op == 'var_compare':
            tid = self._resolve_target(player_id, cond.get('target', 'self'))
            name = str(cond.get('name', 'var'))
            if self._is_suppressed_status_var(tid, name):
                a = 0
            else:
                a = int(self.players[tid].custom_vars.get(name, 0))
            b = int(self._eval_expr(player_id, cond.get('value', 0), card))
            cmp = cond.get('operator', '=')
            return (a == b) if cmp == '=' else (a != b) if cmp == '!=' else (a < b) if cmp == '<' else (a > b) if cmp == '>' else (a <= b) if cmp == '<=' else (a >= b)
        if op == 'has_status_named':
            tid = self._resolve_target(player_id, cond.get('target', 'self'))
            status = str(cond.get('status', '')).strip()
            if self._is_status_immune(tid) and status not in ('status_immune', 'immune', '状态免疫'):
                return False
            alias_declaration = self._status_alias_declaration(status)
            if alias_declaration:
                return self._status_alias_value_for(tid, alias_declaration) > 0
            ps = self.players[tid]
            status_map = {
                'poison': ps.poison > 0,
                '中毒': ps.poison > 0,
                'burn': ps.fire > 0,
                'fire': ps.fire > 0,
                '灼烧': ps.fire > 0,
                'toxic': ps.toxic > 0,
                '淬毒': ps.toxic > 0,
                'dodge': ps.dodge > 0,
                '闪避': ps.dodge > 0,
                'equip_protection': ps.equipment_protection > 0,
                'equipment_protection': ps.equipment_protection > 0,
                '装备摧毁保护': ps.equipment_protection > 0,
                '装备保护': ps.equipment_protection > 0,
            }
            if status in status_map:
                return bool(status_map[status])
            return False
        if op == 'has_status':
            tid = self._resolve_target(player_id, cond.get('target', 'self'))
            status = str(cond.get('status', '')).strip()
            if self._is_status_immune(tid) and status not in ('status_immune', 'immune', '状态免疫'):
                return False
            ps = self.players[tid]
            status_map = {
                'poison': ps.poison > 0,
                'burn': ps.fire > 0,
                'toxic': ps.toxic > 0,
                'dodge': ps.dodge > 0,
                'equip_protection': ps.equipment_protection > 0,
                'equipment_protection': ps.equipment_protection > 0,
                '装备摧毁保护': ps.equipment_protection > 0,
                '装备保护': ps.equipment_protection > 0,
                'untargetable': bool(ps.untargetable),
            }
            return bool(status_map.get(status, False))
        if op == 'target_attribute':
            tid = self._resolve_target(player_id, cond.get('target', 'self'))
            a = int(self._get_player_property_value(tid, cond.get('attr', 'health')))
            b = int(self._eval_expr(player_id, cond.get('value', 0), card))
            cmp = cond.get('operator', '=')
            return (a == b) if cmp == '=' else (a != b) if cmp == '!=' else (a < b) if cmp == '<' else (a > b) if cmp == '>' else (a <= b) if cmp == '<=' else (a >= b)
        if op == 'and':
            return bool(self._eval_condition(player_id, cond.get('a'), card) and self._eval_condition(player_id, cond.get('b'), card))
        if op == 'or':
            return bool(self._eval_condition(player_id, cond.get('a'), card) or self._eval_condition(player_id, cond.get('b'), card))
        if op == 'not':
            return not bool(self._eval_condition(player_id, cond.get('value'), card))
        if op == 'turn_number':
            a = int(self.round_num)
            b = int(self._eval_expr(player_id, cond.get('value', 0), card))
            cmp = cond.get('operator', '=')
            return (a == b) if cmp == '=' else (a != b) if cmp == '!=' else (a < b) if cmp == '<' else (a > b) if cmp == '>' else (a <= b) if cmp == '<=' else (a >= b)
        if op == 'hand_full':
            tid = self._resolve_target(player_id, cond.get('target', 'self'))
            return not self.players[tid].can_add_to_hand()
        if op == 'hand_has_type':
            tid = self._resolve_target(player_id, cond.get('target', 'self'))
            ctype = cond.get('card_type', 'thorn')
            return any(c.card_type == ctype for c in self.players[tid].hand)
        if op == 'zone_contains':
            tid = self._resolve_target(player_id, cond.get('target', 'self'))
            zone = cond.get('zone', 'hand')
            card_selector = cond.get('card')
            zone_map = {'hand': self.players[tid].hand, 'deck': self.players[tid].deck, 'discard': self.players[tid].discard, 'exile': self.players[tid].exile}
            pool = zone_map.get(zone, [])
            if isinstance(card_selector, dict):
                return len(self._match_card_selector(player_id, pool, card_selector, card)) > 0
            return len(pool) > 0
        if op == 'event_card_type':
            return bool(card is not None and card.card_type == cond.get('card_type'))
        if op == 'equip_turns':
            a = int(getattr(card, 'equip_turns', 0)) if card is not None else 0
            b = int(self._eval_expr(player_id, cond.get('value', 0), card))
            cmp = cond.get('operator', '=')
            return (a == b) if cmp == '=' else (a != b) if cmp == '!=' else (a < b) if cmp == '<' else (a > b) if cmp == '>' else (a <= b) if cmp == '<=' else (a >= b)
        if op == 'durability':
            a = int(getattr(card, 'durability', 0)) if card is not None else 0
            b = int(self._eval_expr(player_id, cond.get('value', 0), card))
            cmp = cond.get('operator', '=')
            return (a == b) if cmp == '=' else (a != b) if cmp == '!=' else (a < b) if cmp == '<' else (a > b) if cmp == '>' else (a <= b) if cmp == '<=' else (a >= b)
        if op == 'damage_value':
            a = int(self._incoming_damage_hint[player_id])
            b = int(self._eval_expr(player_id, cond.get('value', 0), card))
            cmp = cond.get('operator', '=')
            return (a == b) if cmp == '=' else (a != b) if cmp == '!=' else (a < b) if cmp == '<' else (a > b) if cmp == '>' else (a <= b) if cmp == '<=' else (a >= b)
        if op == 'has_equip':
            tid = self._resolve_target(player_id, cond.get('target', 'self'))
            return len(self.players[tid].equipment) > 0
        return False

    EVENT_EFFECT_TYPES = {
        'on_owner_turn_start',
        'on_target_turn_start',
        'on_owner_turn_end',
        'on_enemy_turn_start',
        'on_any_turn_start',
        'on_damage_taken',
        'on_equipment_trigger',
        'on_equipment_destroy',
        'on_hand_owner_turn_start',
        'on_hand_owner_turn_end',
        'on_enter_hand',
        'on_discard_owner_turn_start',
        'on_deck_owner_turn_start',
        'on_card_used',
        'on_equipment_triggered',
        'on_equipment_destroyed',
        'on_resource_spent',
        'on_player_stat_changed',
        'on_own_card_countered',
    }

    _base_eval_expr = _eval_expr
    _base_eval_condition = _eval_condition
    _base_resolve_target = _resolve_target
    _base_resolve_targets = _resolve_targets
    _base_card_needs_choice = _card_needs_choice
    _base_get_choice_type = _get_choice_type

    SCRIPT_ENTRY_ALIASES = {
        'play': ('onPlay', 'play', 'on_play'),
        'owner_turn_start': ('onOwnerTurnStart', 'owner_turn_start', 'on_owner_turn_start'),
        'target_turn_start': ('onTargetTurnStart', 'target_turn_start', 'on_target_turn_start'),
        'owner_turn_end': ('onOwnerTurnEnd', 'owner_turn_end', 'on_owner_turn_end'),
        'enemy_turn_start': ('onEnemyTurnStart', 'enemy_turn_start', 'on_enemy_turn_start'),
        'any_turn_start': ('onAnyTurnStart', 'any_turn_start', 'on_any_turn_start'),
        'damage_taken': ('onDamageTaken', 'damage_taken', 'on_damage_taken'),
        'equipment_trigger': ('onEquipmentTrigger', 'equipment_trigger', 'on_equipment_trigger'),
        'equipment_destroy': ('onEquipmentDestroy', 'equipment_destroy', 'on_equipment_destroy', 'onDestroy'),
        'hand_owner_turn_start': ('onHandOwnerTurnStart', 'hand_owner_turn_start', 'on_hand_owner_turn_start'),
        'hand_owner_turn_end': ('onHandOwnerTurnEnd', 'hand_owner_turn_end', 'on_hand_owner_turn_end'),
        'enter_hand': ('onEnterHand', 'enter_hand', 'on_enter_hand'),
        'discard_owner_turn_start': ('onDiscardOwnerTurnStart', 'discard_owner_turn_start', 'on_discard_owner_turn_start'),
        'deck_owner_turn_start': ('onDeckOwnerTurnStart', 'deck_owner_turn_start', 'on_deck_owner_turn_start'),
        'card_used': ('onCardUsed', 'card_used', 'on_card_used'),
        'equipment_triggered': ('onEquipmentTriggered', 'equipment_triggered', 'on_equipment_triggered'),
        'equipment_destroyed': ('onEquipmentDestroyed', 'equipment_destroyed', 'on_equipment_destroyed'),
        'resource_spent': ('onResourceSpent', 'resource_spent', 'on_resource_spent'),
        'player_stat_changed': ('onPlayerStatChanged', 'player_stat_changed', 'on_player_stat_changed'),
        'own_card_countered': ('onOwnCardCountered', 'own_card_countered', 'on_own_card_countered'),
        'response': ('onResponse', 'response', 'on_response'),
    }

    # Round 36 / 批次 AD-1：旧的三个请求 op 并成 ``request`` 伞，判定由
    # :meth:`_is_choice_gate_effect`（看伞的 ``type``）负责；这张表保留给
    # 仍在读它的调用点/测试，内容是唯一公开的请求 op。
    CHOICE_EFFECT_TYPES = {'request'}

    def _script_effects_from(self, script):
        if isinstance(script, dict):
            effects = script.get('effects', [])
            return effects if isinstance(effects, list) else []
        return script if isinstance(script, list) else []

    def _has_script_entry(self, card_def, entry: str) -> bool:
        scripts = getattr(card_def, 'scripts', None) or {}
        if not isinstance(scripts, dict):
            return False
        for key in self.SCRIPT_ENTRY_ALIASES.get(entry, (entry,)):
            if key in scripts:
                return True
        return False

    def _get_script_effects(self, card_def, entry: str):
        scripts = getattr(card_def, 'scripts', None) or {}
        if not isinstance(scripts, dict):
            return []
        for key in self.SCRIPT_ENTRY_ALIASES.get(entry, (entry,)):
            if key in scripts:
                return self._script_effects_from(scripts.get(key))
        return []

    def _card_has_script(self, card_def) -> bool:
        scripts = getattr(card_def, 'scripts', None) or {}
        return isinstance(scripts, dict) and bool(scripts)

    def _has_card_event(self, card_def, event_name: str) -> bool:
        if self._has_script_entry(card_def, event_name):
            return True
        event_type = f'on_{event_name}'
        if self._card_has_v2_event(card_def, event_type):
            return True
        return any(isinstance(effect, dict) and effect.get('type') == event_type for effect in (card_def.effects or []))

    def _play_effects_for_card(self, card: CardInstance):
        if self._card_has_script(card.card_def):
            return self._get_script_effects(card.card_def, 'play')
        return card.card_def.effects or []

    def _v2_play_steps_for_card(self, card: CardInstance):
        events = getattr(card.card_def, 'v2_events', None) or {}
        event_def = events.get('on_play')
        if isinstance(event_def, dict):
            steps = event_def.get('steps', event_def.get('effects', []))
            return steps if isinstance(steps, list) else []
        return event_def if isinstance(event_def, list) else []

    def _effect_type(self, effect) -> str:
        """步骤的执行 op 名。

        Round 36 / 批次 AD-1：请求族伞原子写成
        ``{"op":"request","type":"target",…}`` —— 这里与
        ``mod_runtime_v2.run_v2_step``（``step.get("op") or step.get("type")``）
        统一口径：**显式 ``op`` 优先**，``type`` 只在旧写法 ``{"type": …}``
        里当 op 名。请求伞的 ``type`` 判别参数由 :meth:`_request_kind_of` 读。
        """
        if not isinstance(effect, dict):
            return ''
        return str(effect.get('op') or effect.get('type') or '')

    def _effect_params(self, effect) -> dict:
        if not isinstance(effect, dict):
            return {}
        params = effect.get('params')
        if isinstance(params, dict):
            return params
        return {
            key: value
            for key, value in effect.items()
            if key not in {'type', 'op', 'log', 'then', 'else', 'steps', 'body', 'condition', 'cond'}
        }

    # Round 36 / 批次 AD-1：请求族伞原子 ``request`` 的判别参数（``type``）。
    #   target        —— 旧 ``request_target``（弹选目标窗口）
    #   card          —— 旧 ``request_card``（弹选牌窗口）
    #   confirm       —— 旧 ``request_confirm``（弹二次确认）
    #   zone          —— 旧 ``choose_from_zone``（从区域选一张进手牌）
    #   forced_target —— 旧 ``declare_forced_target``（声明强制目标）
    #   discount_copy —— 旧 ``copy_choice_with_discount``（复制并打折）
    #   reorder_deck  —— 旧 ``request_reorder_deck``（请求重排牌堆）
    REQUEST_TYPES = (
        'target', 'card', 'confirm', 'zone',
        'forced_target', 'discount_copy', 'reorder_deck',
    )
    # 会先弹窗再结算、且"取消即中断后续步骤"的三类（旧 CHOICE_EFFECT_TYPES）。
    REQUEST_CHOICE_TYPES = ('target', 'card', 'confirm')

    def _request_kind_of(self, effect) -> str:
        """``request`` 节点的 ``type`` 判别参数；不是请求伞时返回 ``''``。

        同时认三种形态：

        * 卡数据扁平写法 ``{"op":"request","type":"target","allowed":"any"}``；
        * 卡数据带 ``params`` 的写法 ``{"op":"request","type":"card","params":{…}}``；
        * 引擎效果 / 旧嵌套写法 ``{"type":"request","params":{"type":"zone",…}}``。
        """

        if not isinstance(effect, dict):
            return ''
        op = effect.get('op')
        kind = effect.get('type')
        if isinstance(op, str) and op == 'request':
            if isinstance(kind, str) and kind and kind != 'request':
                return kind.strip().lower()
            kind = None
        elif not (isinstance(kind, str) and kind == 'request'):
            return ''
        params = effect.get('params')
        if isinstance(params, dict):
            return str(params.get('type') or '').strip().lower()
        return ''

    def _request_kind_any(self, effect) -> str:
        """请求伞 ``type``（``_request_kind_of`` 的调用别名）。

        Round 36 / 批次 AD-1 收尾后旧 op 名已全部退役，这里只是保留一个
        语义化入口，方便调用点读起来仍是"请求族的 kind"。
        """

        return self._request_kind_of(effect)

    def _is_choice_gate_effect(self, effect) -> bool:
        """这一步会不会先弹窗、且"取消"要中断后续效果（旧 ``request_*`` 三兄弟）。"""

        if not isinstance(effect, dict):
            return False
        return (
            self._effect_type(effect) == 'request'
            and self._request_kind_any(effect) in self.REQUEST_CHOICE_TYPES
        )

    def _walk_choice_effects(self, effects):
        for effect in effects or []:
            if not isinstance(effect, dict):
                continue
            effect_type = self._effect_type(effect)
            if effect_type in self.EVENT_EFFECT_TYPES:
                continue
            yield effect
            params = self._effect_params(effect)
            for key in ('then', 'else', 'body', 'effects', 'a', 'b'):
                nested = params.get(key)
                if isinstance(nested, list):
                    yield from self._walk_choice_effects(nested)
                direct_nested = effect.get(key)
                if isinstance(direct_nested, list):
                    yield from self._walk_choice_effects(direct_nested)

    def _play_choice_request_declaration(self, card: Optional[CardInstance]) -> dict:
        """The ``play_choice_request`` block declared by the card's data.

        Round 19: the engine no longer hardcodes which card asks what before
        being resolved.  Card data declares the prompt (``choice_key`` /
        ``needs_target`` / ``zones`` / ``condition`` / ``request``) and the
        engine only performs the structural checks below.
        """
        from engine_runtime_support import play_choice_request_declaration
        return play_choice_request_declaration(card)

    def _play_choice_request_payload(self, declaration: dict) -> Optional[dict]:
        """The client payload the declaration asks the engine to forward."""
        if not isinstance(declaration, dict):
            return None
        request = declaration.get('request')
        if isinstance(request, dict) and request:
            payload = copy.deepcopy(request)
            payload.setdefault('type', 'request_confirm')
            return payload
        params = declaration.get('params')
        if isinstance(params, dict) and params:
            return {'type': 'request_confirm', 'params': copy.deepcopy(params)}
        return None

    def _play_choice_request_options(self, declaration: dict) -> tuple:
        """The values that count as an answer to the declared ``choice_key``."""
        request = declaration.get('request') if isinstance(declaration.get('request'), dict) else {}
        params = request.get('params') if isinstance(request.get('params'), dict) else {}
        options = params.get('options')
        if options is None:
            options = declaration.get('options')
        if isinstance(options, (list, tuple, set, frozenset)):
            return tuple(str(item) for item in options)
        return ()

    def _play_choice_request_answer(self, declaration: dict, choice) -> str:
        """The value already picked for the declared ``choice_key`` ('' if none)."""
        if not isinstance(choice, dict):
            return ''
        key = str(declaration.get('choice_key') or '').strip()
        if not key:
            return ''
        return str(choice.get(key) or '')

    def _play_choice_request_zone_ok(self, declaration: dict, card: Optional[CardInstance]) -> bool:
        """``zones`` 白名单：声明了就要在那些区域里才发问。"""
        zones = declaration.get('zones')
        if isinstance(zones, (list, tuple, set, frozenset)):
            allowed = {str(zone).strip().lower() for zone in zones if str(zone).strip()}
            if allowed:
                _owner_id, zone_name, _instance = self._find_card_location(card)
                return str(zone_name or '').strip().lower() in allowed
        return True

    def _play_choice_request_owner(self, declaration: dict, card: Optional[CardInstance]):
        """The owner whose condition is evaluated, honouring ``zones``."""
        if not self._play_choice_request_zone_ok(declaration, card):
            return None
        owner_id, zone_name, _instance = self._find_card_location(card)
        if owner_id is None:
            return None
        try:
            owner_id = int(owner_id)
        except Exception:
            return None
        if not self._valid_player_id(owner_id):
            return None
        return owner_id

    def _play_choice_request_condition_met(self, declaration: dict, card: Optional[CardInstance],
                                           choice: Optional[dict]) -> bool:
        condition = declaration.get('condition')
        if condition is None:
            return True
        owner_id = self._play_choice_request_owner(declaration, card)
        if owner_id is None:
            return False
        prev_choice = getattr(self, '_active_choice', None)
        if isinstance(choice, dict):
            self._active_choice = choice
        try:
            return bool(self._eval_condition(owner_id, condition, card))
        finally:
            self._active_choice = prev_choice

    def _play_choice_request_needed(self, declaration: dict, card: Optional[CardInstance],
                                    choice: Optional[dict]) -> bool:
        """Structural check: does the declaration still need an answer?"""
        if not isinstance(declaration, dict) or not declaration:
            return False
        if not self._play_choice_request_zone_ok(declaration, card):
            return False
        if not self._play_choice_request_condition_met(declaration, card, choice):
            return False
        answer = self._play_choice_request_answer(declaration, choice)
        options = self._play_choice_request_options(declaration)
        if options:
            return answer not in options
        return not answer

    def _declared_play_choice_request(self, card: CardInstance, declaration: dict,
                                      choice: Optional[dict] = None) -> Optional[dict]:
        if not self._play_choice_request_needed(declaration, card, choice):
            return None
        if declaration.get('needs_target') and self._choice_target_from_choice(choice, -1) < 0:
            # ``needs_target``: the target picker runs before this prompt.
            return None
        return self._play_choice_request_payload(declaration)

    def _get_choice_request(self, card: CardInstance, choice: Optional[dict] = None):
        declaration = self._play_choice_request_declaration(card)
        if declaration:
            declared = self._declared_play_choice_request(card, declaration, choice)
            if declared is not None:
                return declared
        effects = list(self._play_effects_for_card(card) or []) + list(self._v2_play_steps_for_card(card) or [])
        for effect in self._walk_choice_effects(effects):
            effect_type = self._effect_type(effect)
            extra_choice_effect = effect_type in (
                'discard_choice_then_draw',
                'steal_enemy_card',
            ) or (
                # Round 36 / 批次 AD-1：``request(type:"zone")`` 承接旧
                # ``choose_from_zone``，仍然算"要弹取牌窗口"的效果。
                self._request_kind_any(effect) == 'zone'
            )
            if effect_type == 'destroy_equipment':
                # Round 31 / 批次 Z：规范名只在"真要点选"时算选择效果。
                extra_choice_effect = self._choice_type_for_effect(effect, card) == 'choose_enemy_equipment'
            is_choice_effect = self._is_choice_gate_effect(effect) or extra_choice_effect
            if not is_choice_effect:
                continue
            if self._choice_request_satisfied(effect, choice, card):
                continue
            return effect
        return None

    def _selected_choice_target(self, default=-1):
        choice = getattr(self, '_active_choice', None) or {}
        if not isinstance(choice, dict):
            return default
        for key in ('target_player', 'target_player_id', 'target_id'):
            if key in choice:
                try:
                    return int(choice.get(key))
                except Exception:
                    return default
        return default

    def _find_card_location(self, needle):
        if needle is None:
            return None, '', None
        needle_id = getattr(needle, 'instance_id', None)
        for pid, ps in enumerate(self.players):
            for zone_name in ('hand', 'deck', 'discard', 'exile'):
                zone = getattr(ps, zone_name, [])
                for card_obj in zone:
                    if card_obj is needle or (needle_id is not None and getattr(card_obj, 'instance_id', None) == needle_id):
                        return pid, zone_name, card_obj
            for eq in getattr(ps, 'equipment', []):
                card_obj = getattr(eq, 'card_instance', None)
                if card_obj is needle or (needle_id is not None and getattr(card_obj, 'instance_id', None) == needle_id):
                    return pid, 'equipment', card_obj
        return None, '', None

    def _find_card_by_instance_id(self, instance_id):
        try:
            iid = int(instance_id)
        except Exception:
            return None
        for ps in self.players:
            for zone_name in ('hand', 'deck', 'discard', 'exile'):
                for card_obj in getattr(ps, zone_name, []):
                    if getattr(card_obj, 'instance_id', None) == iid:
                        return card_obj
            for eq in getattr(ps, 'equipment', []):
                card_obj = getattr(eq, 'card_instance', None)
                if getattr(card_obj, 'instance_id', None) == iid:
                    return card_obj
        return None

    def _remember_created_card(self, card_obj, context=None):
        if card_obj is None:
            return
        self._last_created_card_instance_id = getattr(card_obj, 'instance_id', None)
        if isinstance(context, dict):
            context['last_created_card_instance_id'] = self._last_created_card_instance_id

    def _resolve_card_ref(self, player_id, card_ref, current_card=None):
        if isinstance(card_ref, CardInstance):
            return card_ref
        if card_ref is None:
            return current_card
        if isinstance(card_ref, str):
            if card_ref in ('current_card', 'this', 'this_card'):
                return current_card
            if card_ref in ('selected_card', 'choice_card', 'chosen_card'):
                context = getattr(self, '_active_effect_context', {}) or {}
                if isinstance(context, dict):
                    context_card = context.get('chosen_card') or context.get('selected_card')
                    if isinstance(context_card, CardInstance):
                        return context_card
                return self._resolve_card_ref(player_id, {'ref': 'selected_card'}, current_card)
            if card_ref in ('last_created_card', 'created_card', 'last_copied_card'):
                return self._resolve_card_ref(player_id, {'ref': 'last_created_card'}, current_card)
            return None
        if not isinstance(card_ref, dict):
            return None
        ref = card_ref.get('ref') or card_ref.get('op') or card_ref.get('type')
        if ref in ('event_card', 'used_card', 'trigger_card', 'destroyed_card'):
            context = getattr(self, '_active_effect_context', {}) or {}
            instance_id = context.get('event_card_instance_id') if isinstance(context, dict) else None
            return self._find_card_by_instance_id(instance_id)
        if ref in ('original_card', 'responded_card', 'response_card'):
            context = getattr(self, '_active_effect_context', {}) or {}
            if isinstance(context, dict):
                original = context.get('original_card')
                if isinstance(original, CardInstance):
                    return original
                instance_id = context.get('original_card_instance_id')
                if instance_id is not None:
                    return self._find_card_by_instance_id(instance_id)
            return None
        if ref in ('current_card', 'this_card'):
            return current_card
        if ref in ('last_created_card', 'created_card', 'last_copied_card'):
            context = getattr(self, '_active_effect_context', {}) or {}
            instance_id = context.get('last_created_card_instance_id') if isinstance(context, dict) else None
            if instance_id is None:
                instance_id = getattr(self, '_last_created_card_instance_id', None)
            return self._find_card_by_instance_id(instance_id)
        if ref == 'card_instance':
            return self._find_card_by_instance_id(card_ref.get('instance_id'))
        if ref == 'var':
            raw = self._var_store_for_target(player_id, card_ref.get('target', 'self')).get(str(card_ref.get('name', 'var')))
            if isinstance(raw, list):
                raw = raw[0] if raw else None
            return self._resolve_card_ref(player_id, raw, current_card)
        if ref == 'list_item':
            return self._resolve_card_ref(player_id, self._list_item_raw(player_id, card_ref, current_card), current_card)
        if ref in ('selected_card', 'choice_card', 'chosen_card'):
            context = getattr(self, '_active_effect_context', {}) or {}
            if isinstance(context, dict):
                context_card = context.get('chosen_card') or context.get('selected_card')
                if isinstance(context_card, CardInstance):
                    return context_card
            choice = getattr(self, '_active_choice', None) or {}
            if isinstance(choice, dict):
                instance_id = choice.get('target_instance_id')
                if instance_id is None and isinstance(choice.get('target_instance_ids'), list) and choice.get('target_instance_ids'):
                    instance_id = choice.get('target_instance_ids')[0]
                found = self._find_card_by_instance_id(instance_id)
                return found if found is not None and not self._card_is_sublime(found) else None
            return None
        if ref == 'selected_card_at':
            choice = getattr(self, '_active_choice', None) or {}
            if not isinstance(choice, dict):
                return None
            ids = choice.get('_selected_card_ids_snapshot') or choice.get('target_instance_ids')
            if not isinstance(ids, list):
                ids = [choice.get('target_instance_id')] if choice.get('target_instance_id') is not None else []
            index = self._eval_int(player_id, card_ref.get('index', 1), current_card, 1) - 1
            found = self._find_card_by_instance_id(ids[index]) if 0 <= index < len(ids) else None
            return found if found is not None and not self._card_is_sublime(found) else None
        if ref == 'zone_card':
            tid = self._resolve_target(player_id, card_ref.get('target', 'self'))
            if not (0 <= tid < len(self.players)):
                return None
            zone_name = str(card_ref.get('zone', 'hand'))
            ps = self.players[tid]
            if zone_name == 'equipment':
                zone = [eq.card_instance for eq in ps.equipment]
            else:
                zone = getattr(ps, zone_name, [])
            index = self._eval_int(player_id, card_ref.get('index', 1), current_card, 1) - 1
            return zone[index] if 0 <= index < len(zone) else None
        return None

    def _resolve_card_id_ref(self, player_id, card_ref, current_card=None):
        if isinstance(card_ref, str):
            return card_ref
        if isinstance(card_ref, dict) and card_ref.get('ref') == 'card_by_id':
            return str(card_ref.get('id', ''))
        if isinstance(card_ref, dict) and card_ref.get('ref') in ('var', 'list_item'):
            raw = self._var_store_for_target(player_id, card_ref.get('target', 'self')).get(str(card_ref.get('name', 'var'))) if card_ref.get('ref') == 'var' else self._list_item_raw(player_id, card_ref, current_card)
            if isinstance(raw, list):
                raw = raw[0] if raw else ''
            if isinstance(raw, str):
                return raw
            card_obj = self._resolve_card_ref(player_id, raw, current_card)
            return getattr(card_obj, 'def_id', '') if card_obj is not None else ''
        card_obj = self._resolve_card_ref(player_id, card_ref, current_card)
        return getattr(card_obj, 'def_id', '') if card_obj is not None else ''

    def _get_card_definition(self, player_id, card_ref, current_card=None):
        card_id = self._resolve_card_id_ref(player_id, card_ref, current_card)
        if not card_id:
            return None
        return CARD_DEFS.get(card_id)

    def _get_card_def_property_value(self, player_id, card_ref, prop, current_card=None):
        card_def = self._get_card_definition(player_id, card_ref, current_card)
        if card_def is None:
            return 0
        prop = str(prop or 'cost_e')
        if prop in ('flags', 'tags'):
            return sorted(str(flag) for flag in getattr(card_def, 'flags', set()) or set())
        if prop in ('cost_e', 'cost_m', 'count', 'trigger_cost_e'):
            return int(getattr(card_def, prop, 0) or 0)
        if prop in ('effect_text', 'description', 'card_type', 'quality', 'name_cn', 'name_en', 'trigger_effect_text', 'id'):
            return str(getattr(card_def, prop, '') or '')
        return getattr(card_def, prop, 0)

    def _get_card_def_tags(self, player_id, card_ref, current_card=None):
        card_def = self._get_card_definition(player_id, card_ref, current_card)
        if card_def is None:
            return []
        return sorted(str(flag) for flag in getattr(card_def, 'flags', set()) or set())

    def _remove_card_from_current_zone(self, target_card):
        owner_id, zone_name, card_obj = self._find_card_location(target_card)
        if owner_id is None or card_obj is None:
            return None, ''
        ps = self.players[owner_id]
        if zone_name == 'equipment':
            for eq in list(ps.equipment):
                if eq.card_instance is card_obj or eq.card_instance.instance_id == card_obj.instance_id:
                    self._cleanup_equipment_derived_effects(owner_id, eq, run_destroy_event=False)
                    ps.equipment.remove(eq)
                    self._refresh_equipment_derived_player_flags(owner_id)
                    self._refresh_hand_limit_bonuses()
                    return owner_id, zone_name
            return owner_id, zone_name
        zone = getattr(ps, zone_name, None)
        if isinstance(zone, list) and card_obj in zone:
            zone.remove(card_obj)
        return owner_id, zone_name

    def _var_store_for_target(self, player_id, target):
        if target == 'global':
            if not hasattr(self, 'custom_vars'):
                self.custom_vars = {}
            return self.custom_vars
        if target == 'team':
            if not hasattr(self, 'team_custom_vars'):
                self.team_custom_vars = {}
            team_id = self.team_of(player_id) if hasattr(self, 'team_of') else player_id
            key = str(team_id)
            if key not in self.team_custom_vars:
                self.team_custom_vars[key] = {}
            return self.team_custom_vars[key]
        tid = self._resolve_target(player_id, target)
        if not (0 <= tid < len(self.players)):
            tid = player_id
        return self.players[tid].custom_vars

    def _var_target_refs(self, player_id, target):
        if target in ('global', 'team'):
            return [target]
        return self._resolve_targets(player_id, target)

    def _scalar_value(self, value, default=0):
        if isinstance(value, list):
            return self._scalar_value(value[0], default) if value else default
        if isinstance(value, dict):
            if value.get('ref') == 'card_instance':
                card = self._find_card_by_instance_id(value.get('instance_id'))
                return getattr(card, 'def_id', default) if card is not None else default
            return default
        return default if value is None else value

    def _serializable_list_item(self, item):
        if isinstance(item, CardInstance):
            return {'ref': 'card_instance', 'instance_id': item.instance_id}
        if isinstance(item, list):
            return [self._serializable_list_item(v) for v in item]
        if isinstance(item, dict):
            return {k: self._serializable_list_item(v) for k, v in item.items()}
        return item

    def _zone_list(self, player_id, target, zone_name):
        tid = self._resolve_target(player_id, target)
        if not (0 <= tid < len(self.players)):
            return []
        ps = self.players[tid]
        zone = [eq.card_instance for eq in ps.equipment] if zone_name == 'equipment' else getattr(ps, zone_name, [])
        return [{'ref': 'card_instance', 'instance_id': c.instance_id} for c in zone or [] if c is not None]

    def _eval_list(self, player_id, expr, card=None):
        if isinstance(expr, str):
            text = expr.strip()
            if (text.startswith('[') and text.endswith(']')) or (text.startswith('{') and text.endswith('}')):
                try:
                    return self._eval_list(player_id, json.loads(text), card)
                except Exception:
                    pass
            value = self._eval_expr(player_id, expr, card)
            return value if isinstance(value, list) else [value]
        if isinstance(expr, list):
            return [self._serializable_list_item(v) for v in expr]
        if not isinstance(expr, dict):
            return [] if expr is None else [expr]
        ref = expr.get('ref')
        if ref in ('list', 'list_create'):
            return [self._serializable_list_item(self._eval_raw_item(player_id, item, card)) for item in expr.get('items', [])]
        if ref == 'list_var':
            raw = self._var_store_for_target(player_id, expr.get('target', 'self')).get(str(expr.get('name', 'var')), [])
            return list(raw) if isinstance(raw, list) else ([] if raw is None else [raw])
        if ref == 'var':
            raw = self._var_store_for_target(player_id, expr.get('target', 'self')).get(str(expr.get('name', 'var')), 0)
            return list(raw) if isinstance(raw, list) else ([] if raw is None else [raw])
        if ref == 'zone_list':
            return self._zone_list(player_id, expr.get('target', 'self'), str(expr.get('zone', 'hand')))
        if ref == 'card_def_tags':
            return self._get_card_def_tags(player_id, expr.get('card', ''), card)
        if ref == 'list_item':
            item = self._list_item_raw(player_id, expr, card)
            return [] if item is None else [item]
        value = self._eval_expr(player_id, expr, card)
        return value if isinstance(value, list) else [value]

    def _list_item_raw(self, player_id, expr, card=None):
        values = self._eval_list(player_id, expr.get('list', []), card) if isinstance(expr, dict) else []
        index = self._eval_int(player_id, expr.get('index', 1), card, 1) - 1 if isinstance(expr, dict) else 0
        return values[index] if 0 <= index < len(values) else None

    def _eval_raw_item(self, player_id, expr, card=None):
        if isinstance(expr, dict):
            ref = expr.get('ref')
            if ref == 'list_item':
                return self._list_item_raw(player_id, expr, card)
            if ref in ('card_instance', 'zone_card', 'selected_card', 'selected_card_at', 'current_card', 'this_card', 'event_card', 'used_card', 'trigger_card', 'destroyed_card', 'last_created_card', 'created_card', 'last_copied_card'):
                resolved = self._resolve_card_ref(player_id, expr, card)
                return self._serializable_list_item(resolved) if resolved is not None else expr
            if ref == 'var':
                raw = self._var_store_for_target(player_id, expr.get('target', 'self')).get(str(expr.get('name', 'var')))
                return raw[0] if isinstance(raw, list) and raw else raw
        return self._eval_expr(player_id, expr, card)

    def _eval_var_assignment_value(self, player_id, expr, card=None):
        if isinstance(expr, list):
            return self._serializable_list_item(expr[0]) if expr else 0
        if isinstance(expr, dict) and expr.get('ref') in ('list', 'list_create', 'list_var', 'zone_list', 'card_def_tags'):
            values = self._eval_list(player_id, expr, card)
            return self._serializable_list_item(values[0]) if values else 0
        return self._serializable_list_item(self._eval_raw_item(player_id, expr, card))

    def _same_list_item(self, a, b):
        a = self._serializable_list_item(a)
        b = self._serializable_list_item(b)
        if isinstance(a, dict) and a.get('ref') == 'card_instance' and isinstance(b, str):
            card = self._find_card_by_instance_id(a.get('instance_id'))
            return card is not None and card.def_id == b
        if isinstance(b, dict) and b.get('ref') == 'card_instance' and isinstance(a, str):
            card = self._find_card_by_instance_id(b.get('instance_id'))
            return card is not None and card.def_id == a
        return a == b

    def _effect_tree_uses_event_target(self, value):
        if isinstance(value, str) and value in (
            'event_target', 'target', 'choice_target', 'selected_target', 'chosen_target'
        ):
            return True
        if isinstance(value, list):
            return any(self._effect_tree_uses_event_target(item) for item in value)
        if isinstance(value, dict):
            # Round 36 / 批次 AD-1：``op`` 是步骤名、``type`` 是请求伞的判别值
            # （``{"op":"request","type":"target"}``），不能当成目标选择器。
            return any(
                self._effect_tree_uses_event_target(item)
                for key, item in value.items()
                if key not in ('op', 'type')
            )
        return False

    @staticmethod
    def _equipment_trigger_uses_effect_target(card_def) -> bool:
        resource = getattr(card_def, 'v2_resource', None) or {}
        return bool(isinstance(resource, dict) and resource.get('trigger_uses_effect_target'))

    def _equipment_trigger_forbids_self_target(self, card_def):
        if (
            not card_def
            or 'self_only' in getattr(card_def, 'flags', set())
            or self._equipment_trigger_uses_effect_target(card_def)
        ):
            return False
        resource = getattr(card_def, 'v2_resource', None) or {}
        if isinstance(resource, dict) and resource.get('trigger_allow_self'):
            return False
        events = getattr(card_def, 'v2_events', None) or {}
        event_def = events.get('on_equipment_trigger')
        return self._effect_tree_uses_event_target(event_def)

    def _random_selectable_candidates(self, player_id: int, selector: Optional[dict] = None) -> List[int]:
        """Selectable players for the generic ``random_selectable`` selector.

        ``exclude`` removes already-chosen players (a selector or a list of them),
        ``allow_self`` keeps the actor in the pool and ``relation`` narrows the
        pool to enemies / friendly players.
        """
        selector = selector if isinstance(selector, dict) else {}
        allow_self = selector.get('allow_self', True) is not False
        relation = str(selector.get('relation', 'any') or 'any').strip().lower()
        candidates: List[int] = []
        for target_id in range(len(self.players)):
            if not self._target_can_be_selected(player_id, target_id, allow_self=allow_self):
                continue
            if relation in ('enemy', 'enemies', 'opponent', 'opponents'):
                if not self._opposite_timer_side(player_id, target_id):
                    continue
            elif relation in ('friendly', 'ally', 'allies', 'team', 'same_side'):
                if not self._same_timer_side(player_id, target_id):
                    continue
            candidates.append(target_id)
        exclude_refs = selector.get('exclude')
        if exclude_refs is not None and candidates:
            active_card = getattr(self, '_active_v2_card', None)
            excluded = set()
            refs = exclude_refs if isinstance(exclude_refs, (list, tuple, set)) else [exclude_refs]
            for ref in refs:
                for target_id in self._list_effect_targets(player_id, active_card, ref):
                    excluded.add(target_id)
            if excluded:
                candidates = [target_id for target_id in candidates if target_id not in excluded]
        return candidates

    def _random_selectable_target(self, player_id: int, selector: Optional[dict] = None) -> int:
        candidates = self._random_selectable_candidates(player_id, selector)
        if not candidates:
            return -1
        from engine_runtime_support import forced_random_target
        return int(forced_random_target(self, player_id, candidates))

    @staticmethod
    def _is_random_selectable_selector(target_str) -> bool:
        if isinstance(target_str, str):
            return target_str.strip().lower() in ('random_selectable', 'random_selectable_player')
        if isinstance(target_str, dict):
            ref = target_str.get('ref') or target_str.get('op') or target_str.get('type')
            return str(ref or '').strip().lower() in ('random_selectable', 'random_selectable_player')
        return False

    LOWEST_HEALTH_ENEMY_SELECTORS = ('lowest_health_enemy', 'lowest_health_enemy_player')
    EQUIPMENT_TARGET_SELECTORS = ('equipment_target', 'equip_target', 'equipment_effect_target')
    EQUIPMENT_OWNER_SELECTORS = ('equipment_owner', 'equip_owner')
    TEAM_MEMBERS_SELECTORS = ('team_members', 'team_member', 'target_team_members')

    @staticmethod
    def _selector_ref(target_str) -> str:
        """Normalise a selector (string or ``{"ref": ...}``) into its bare name."""
        if isinstance(target_str, str):
            return target_str.strip().lower()
        if isinstance(target_str, dict):
            ref = target_str.get('ref') or target_str.get('op') or target_str.get('type')
            return str(ref or '').strip().lower()
        return ''

    @classmethod
    def _is_lowest_health_enemy_selector(cls, target_str) -> bool:
        return cls._selector_ref(target_str) in cls.LOWEST_HEALTH_ENEMY_SELECTORS

    @classmethod
    def _is_equipment_target_selector(cls, target_str) -> bool:
        return cls._selector_ref(target_str) in cls.EQUIPMENT_TARGET_SELECTORS

    @classmethod
    def _is_equipment_owner_selector(cls, target_str) -> bool:
        return cls._selector_ref(target_str) in cls.EQUIPMENT_OWNER_SELECTORS

    @classmethod
    def _is_team_members_selector(cls, target_str) -> bool:
        return cls._selector_ref(target_str) in cls.TEAM_MEMBERS_SELECTORS

    def _resolve_team_members_selector(self, player_id, selector, context=None) -> List[int]:
        """Every living member of the team the selected player belongs to.

        Mirrors the legacy Monstera helper: a player without a team (1v1, or a
        team of one) has no members, so the effect simply does nothing there.
        """
        selector = selector if isinstance(selector, dict) else {}
        target_ref = selector.get('target', selector.get('player', 'target'))
        target_id = -1
        if isinstance(target_ref, dict) and self._is_equipment_target_selector(target_ref):
            target_id = self._resolve_equipment_target_selector(player_id, target_ref, context)
        if not self._valid_player_id(target_id):
            target_id = self._resolve_target(player_id, target_ref)
        if not self._valid_player_id(target_id):
            return []
        members = self._jungle_team_members(target_id)
        if not members and selector.get('fallback_self'):
            members = [target_id] if self.players[target_id].health > 0 else []
        return [int(member_id) for member_id in members]

    def _resolve_context_var_target(self, selector):
        """Resolve ``{"op": "var"}`` selectors from the live effect context.

        Engine-path steps resolve ``var`` against player ``custom_vars``; steps
        that came from the v2 runtime keep their temporaries in the effect
        context instead (a listener target for example).  Returns ``None`` when
        the selector is not a context variable so the caller keeps its normal
        resolution order.
        """
        if not isinstance(selector, dict):
            return None
        ref = selector.get('ref') or selector.get('op') or selector.get('type')
        if ref not in ('var', 'temp_var') or selector.get('target'):
            return None
        name = str(selector.get('name', selector.get('var', '')) or '')
        if not name:
            return None
        context = getattr(self, '_active_effect_context', {}) or {}
        context_vars = context.get('vars') if isinstance(context, dict) else None
        if not isinstance(context_vars, dict) or name not in context_vars:
            return None
        try:
            return int(context_vars.get(name))
        except (TypeError, ValueError):
            return None

    def _resolve_raw_player_selector(self, selector):
        """``{"op": "player_id", "id": N}``: a player id with no selectability check.

        Revives and other effects that must reach a player an ordinary effect
        target may not select (a dead teammate) use this selector.
        """
        if not isinstance(selector, dict):
            return None
        ref = selector.get('ref') or selector.get('op') or selector.get('type')
        if ref not in ('player_id', 'player_at', 'raw_player'):
            return None
        raw = selector.get('id', selector.get('value', selector.get('player')))
        try:
            return int(raw)
        except (TypeError, ValueError):
            return None

    def _resolve_equipment_target_selector(self, player_id, selector, context=None) -> int:
        """Resolve "the player this equipment was played on".

        Equipment events only carry the equipment target in ``context['target_id']``
        (``context['target_player']`` is the equipment owner), so data steps that
        act on the equipment target need an explicit selector instead of "target".
        """
        if not isinstance(context, dict):
            context = getattr(self, '_active_effect_context', {}) or {}
        context = context if isinstance(context, dict) else {}
        card = context.get('card')
        _, equipment = self._find_equipment_by_card_instance_id(
            getattr(card, 'instance_id', None)
        )
        if equipment is not None:
            return self._equipment_effect_target_id(equipment, player_id)
        try:
            target_id = int(context.get('target_id', -1))
        except Exception:
            target_id = -1
        if 0 <= target_id < len(self.players):
            return target_id
        if isinstance(selector, dict) and selector.get('default') is not None:
            fallback = self._resolve_target(player_id, selector.get('default'))
            if 0 <= fallback < len(self.players):
                return fallback
        return -1

    def _resolve_equipment_owner_selector(self, player_id) -> int:
        """Resolve the owner of the equipment that is currently resolving."""
        context = getattr(self, '_active_effect_context', {}) or {}
        context = context if isinstance(context, dict) else {}
        try:
            owner_id = int(context.get('selected_equipment_owner_id', -1))
        except Exception:
            owner_id = -1
        if 0 <= owner_id < len(self.players):
            return owner_id
        card = context.get('card')
        if isinstance(card, CardInstance):
            owner_id, _, _ = self._find_card_location(card)
            if owner_id is not None and 0 <= owner_id < len(self.players):
                return owner_id
        return player_id

    def _resolve_target(self, player_id, target_str):
        context = getattr(self, '_active_effect_context', {}) or {}
        if self._is_random_selectable_selector(target_str):
            return self._random_selectable_target(player_id, target_str if isinstance(target_str, dict) else {})
        if self._is_lowest_health_enemy_selector(target_str):
            return self._jurassic_lowest_selectable_enemy(player_id)
        if self._is_equipment_target_selector(target_str):
            return self._resolve_equipment_target_selector(player_id, target_str)
        if self._is_equipment_owner_selector(target_str):
            return self._resolve_equipment_owner_selector(player_id)
        if self._is_team_members_selector(target_str):
            members = self._resolve_team_members_selector(player_id, target_str)
            return members[0] if members else -1
        context_var_id = self._resolve_context_var_target(target_str)
        if context_var_id is not None:
            return context_var_id
        raw_player_id = self._resolve_raw_player_selector(target_str)
        if raw_player_id is not None:
            return raw_player_id
        if isinstance(target_str, dict) and target_str.get('ref') == 'card_owner':
            target_card = self._resolve_card_ref(player_id, target_str.get('card'), None)
            owner_id, _, _ = self._find_card_location(target_card)
            return player_id if owner_id is None else owner_id
        if isinstance(target_str, int):
            return target_str if 0 <= target_str < len(self.players) else -1
        if target_str in ('choice_target', 'selected_target', 'chosen_target'):
            target_id = self._selected_choice_target(-1)
            if 0 <= target_id < len(self.players):
                return target_id
            try:
                context_target = int(context.get('target_id', -1))
            except Exception:
                context_target = -1
            return context_target if 0 <= context_target < len(self.players) else -1
        if target_str == 'target':
            target_id = self._selected_choice_target(-1)
            if self._target_can_be_selected(player_id, target_id, allow_self=True):
                return target_id
            try:
                context_target = int(context.get('target_id', -1))
            except Exception:
                context_target = -1
            if 0 <= context_target < len(self.players):
                return context_target
            return -1
        if target_str == 'event_target':
            return int(context.get('target_id', player_id))
        if target_str in ('event_source', 'source', 'last_actor', 'damage_source'):
            return int(context.get('source_id', player_id))
        return self._base_resolve_target(player_id, target_str)

    def _resolve_targets(self, player_id, target_str):
        if self._is_random_selectable_selector(target_str):
            tid = self._random_selectable_target(player_id, target_str if isinstance(target_str, dict) else {})
            return [] if tid < 0 else [tid]
        if self._is_lowest_health_enemy_selector(target_str):
            tid = self._jurassic_lowest_selectable_enemy(player_id)
            return [] if tid < 0 else [tid]
        if self._is_equipment_target_selector(target_str):
            tid = self._resolve_equipment_target_selector(player_id, target_str)
            return [] if tid < 0 else [tid]
        if self._is_equipment_owner_selector(target_str):
            tid = self._resolve_equipment_owner_selector(player_id)
            return [] if tid < 0 else [tid]
        if self._is_team_members_selector(target_str):
            return list(self._resolve_team_members_selector(player_id, target_str))
        context_var_id = self._resolve_context_var_target(target_str)
        if context_var_id is not None:
            return [context_var_id] if self._valid_player_id(context_var_id) else []
        raw_player_id = self._resolve_raw_player_selector(target_str)
        if raw_player_id is not None:
            return [raw_player_id] if self._valid_player_id(raw_player_id) else []
        if isinstance(target_str, int):
            return [target_str] if 0 <= target_str < len(self.players) else []
        if isinstance(target_str, dict) and target_str.get('ref') == 'card_owner':
            tid = self._resolve_target(player_id, target_str)
            return [] if tid < 0 else [tid]
        if target_str in ('choice_target', 'selected_target', 'chosen_target', 'event_target', 'target', 'event_source', 'source', 'last_actor', 'damage_source'):
            context = getattr(self, '_active_effect_context', None)
            if target_str in ('choice_target', 'selected_target', 'chosen_target', 'target') and isinstance(context, dict):
                wide_targets = context.get('wide_strike_targets')
                if isinstance(wide_targets, list):
                    return [
                        int(tid) for tid in wide_targets
                        if isinstance(tid, int) and 0 <= tid < len(self.players)
                    ]
            tid = self._resolve_target(player_id, target_str)
            return [] if tid < 0 else [tid]
        return self._base_resolve_targets(player_id, target_str)

    def _valid_player_id(self, player_id) -> bool:
        try:
            player_id = int(player_id)
        except Exception:
            return False
        return 0 <= player_id < len(self.players)

    def _log_mod_runtime_error(self, effect_type, exc, player_id=None, card=None):
        self.log_msg(MOD_RUNTIME_ERROR_MESSAGE)
        record_mod_runtime_error(
            f'{type(exc).__name__}: {exc}',
            effect_type=effect_type,
            player_id=player_id,
            card_id=getattr(card, 'def_id', None),
            room_phase=getattr(self, 'phase', ''),
        )

    def _run_effect_list(self, player_id, card, effects, choice, context):
        prev_context = getattr(self, '_active_effect_context', None)
        prev_choice = getattr(self, '_active_choice', None)
        context_dict = context if isinstance(context, dict) else ({'context': context} if context else {})
        self._active_effect_context = context_dict
        if isinstance(choice, dict):
            self._active_choice = choice
        try:
            for eff in effects or []:
                self._consume_action_work(2)
                et = eff if isinstance(eff, str) else self._effect_type(eff)
                pm = {} if isinstance(eff, str) else self._effect_params(eff)
                if isinstance(eff, dict) and 'type' not in pm:
                    # Round 36 / 批次 AD-1：扁平写法
                    # ``{"op":"request","type":"zone",…}`` 的判别参数不在
                    # ``_effect_params`` 的返回值里（``type`` 是保留键，客户端
                    # payload 才不会多出一个 "type" 字段），执行前在这里补齐。
                    request_kind = self._request_kind_of(eff)
                    if request_kind:
                        pm = {**pm, 'type': request_kind}
                lg = None if isinstance(eff, str) else eff.get('log')
                # Round 22/24（别名收敛 + C 类合并）: 引擎路径（含引擎原子
                # 自己跑的 body）也把旧名挡在实现名之前，给"已改名 / 已移除 +
                # 替代写法"的显式报错，而不是静默跑掉或只报一句 Unknown effect。
                retired_error = self._retired_atom_runtime_error(et)
                if retired_error is not None:
                    self._log_mod_runtime_error(et, retired_error, player_id, card)
                    continue
                rt = self._EFFECT_ALIASES.get(et, et)
                # Round 13: the engine path honours the same step gate as the v2
                # runtime (``condition``/``run_if`` must hold, ``unless`` must
                # not) but evaluates it with the engine's own expression language.
                # A gate the engine cannot read is logged and the step still
                # runs -- the pre-Round-13 behaviour for a step-level
                # ``condition`` -- so a data typo can never silently disable a
                # card effect or abort the play.
                try:
                    gate_allows = self._step_gate_allows(rt, eff, pm, player_id, card)
                except (ActionWorkBudgetExceeded, ModLoopBreak, ModLoopContinue):
                    raise
                except Exception as exc:
                    self._log_mod_runtime_error(et, exc, player_id, card)
                    gate_allows = True
                if not gate_allows:
                    continue
                if et in self.EVENT_EFFECT_TYPES or rt in self.EVENT_EFFECT_TYPES:
                    continue
                if (
                    isinstance(choice, dict)
                    and choice.get('cancelled')
                    and self._is_choice_gate_effect(eff)
                    and not pm.get('continue_on_cancel')
                ):
                    break
                fn = getattr(self, f'_atomic_{rt}', None)
                try:
                    before_stats = self._snapshot_player_stats()
                    if callable(fn):
                        fn(player_id, card, pm, lg, choice, context_dict)
                    elif lg:
                        self.log_msg(lg)
                    else:
                        self._log_mod_runtime_error(et, RuntimeError(f'Unknown effect: {et}'), player_id, card)
                    if rt not in ('if', 'if_else', 'repeat', 'repeat_until', 'for_each',
                                  'for_each_selected_card', 'for_each_list', 'delayed_effect',
                                  'defer_game_over'):
                        self._dispatch_player_stat_changes(before_stats, player_id, card)
                except (ModLoopBreak, ModLoopContinue):
                    raise
                except ActionWorkBudgetExceeded:
                    raise
                except Exception as exc:
                    self._log_mod_runtime_error(et, exc, player_id, card)
        finally:
            self._active_effect_context = prev_context
            self._active_choice = prev_choice

    def _step_gate_allows(self, effect_type, effect, params, player_id, card=None):
        """Step-level gate for engine-path steps (Round 13 / batch 1).

        ``condition``/``cond``/``run_if`` must evaluate true and ``unless``/
        ``skip_if`` must evaluate false, otherwise the step is skipped without
        touching the world.  ``if``/``if_else``/``repeat_until`` own
        ``condition`` as their control operand and are gated by ``run_if`` /
        ``unless`` only; the key list comes from
        :func:`mod_runtime_v2.step_gate_conditions` so both paths agree on it.
        A condition written with an op both paths cannot read is reported
        through the mod-runtime error log and then **ignored** (the step runs),
        matching the pre-gate behaviour instead of guessing.
        """
        must_hold, must_not_hold, unreadable = step_gate_conditions(effect, effect_type, params)
        for condition in unreadable:
            op = (condition.get('op') or condition.get('type')
                  if isinstance(condition, dict) else type(condition).__name__)
            self._log_mod_runtime_error(
                effect_type,
                RuntimeError(f'unsupported step condition op: {op!r}'),
                player_id,
                card,
            )
        if not must_hold and not must_not_hold:
            return True
        for condition in must_hold:
            if not self._eval_condition(player_id, condition, card):
                return False
        for condition in must_not_hold:
            if self._eval_condition(player_id, condition, card):
                return False
        return True

    def _step_text_value(self, player_id, card, value):
        """Materialize a step parameter that is consumed as text.

        ``{"op": "var", ...}`` style values are evaluated through the engine's
        expression language so data can compute a status id, a var name or a log
        message; plain strings/numbers pass through unchanged.
        """
        if isinstance(value, dict):
            try:
                value = self._eval_expr(player_id, value, card)
            except Exception:
                return value
        return value

    def _same_timer_side(self, player_a: int, player_b: int) -> bool:
        if not (0 <= player_a < len(self.players) and 0 <= player_b < len(self.players)):
            return False
        team_of = getattr(self, 'team_of', None)
        if callable(team_of):
            try:
                return team_of(player_a) == team_of(player_b)
            except Exception:
                return player_a == player_b
        return player_a == player_b

    def _opposite_timer_side(self, player_a: int, player_b: int) -> bool:
        if not (0 <= player_a < len(self.players) and 0 <= player_b < len(self.players)):
            return False
        team_of = getattr(self, 'team_of', None)
        if callable(team_of):
            try:
                return team_of(player_a) != team_of(player_b)
            except Exception:
                return player_a != player_b
        return player_a != player_b

    def _timer_trigger_matches(self, entry: dict, current_player: int, phase: str = 'normal') -> bool:
        trigger = str(entry.get('trigger') or 'target_turn_start')
        owner_id = int(entry.get('owner_id', current_player))
        target_id = int(entry.get('target_id', owner_id))
        if trigger == 'target_turn_start_after_status_clear':
            return phase == 'after_status_clear' and current_player == target_id
        if trigger == 'target_turn_start_after_draw':
            return phase == 'after_turn_start_draw' and current_player == target_id
        if trigger in ('target_turn_end', 'turn_end'):
            return phase == 'turn_end' and current_player == target_id
        if trigger == 'owner_turn_end':
            return phase == 'turn_end' and current_player == owner_id
        if trigger == 'any_turn_end':
            return phase == 'turn_end'
        if phase != 'normal':
            return False
        if trigger in ('target_turn_start', 'turn_start'):
            return current_player == target_id
        if trigger == 'owner_turn_start':
            return current_player == owner_id
        if trigger == 'friendly_turn_start':
            return self._same_timer_side(owner_id, current_player)
        if trigger == 'enemy_turn_start':
            return self._opposite_timer_side(owner_id, current_player)
        if trigger == 'any_turn_start':
            return True
        return False

    def _timer_targets(self, player_id: int, target) -> List[int]:
        if target in ('global', 'team'):
            return [player_id]
        try:
            ids = self._resolve_targets(player_id, target)
        except Exception:
            ids = [player_id]
        ids = [int(pid) for pid in ids if isinstance(pid, int) and 0 <= pid < len(self.players)]
        return ids or [player_id]

    def _clone_timer_effects(self, effects):
        try:
            return json.loads(json.dumps(effects or [], ensure_ascii=False))
        except Exception:
            return list(effects or [])

    def _register_timed_effect(self, owner_id: int, target_id: int, trigger: str, duration: int,
                               effects, card=None, condition=None):
        if duration <= 0 or not effects:
            return
        if not hasattr(self, 'timed_effects') or not isinstance(self.timed_effects, list):
            self.timed_effects = []
        timer_serial = int(getattr(self, '_timed_effect_serial', 0) or 0) + 1
        self._timed_effect_serial = timer_serial
        entry = {
            '_timer_id': timer_serial,
            'owner_id': owner_id,
            'target_id': target_id,
            'trigger': trigger or 'target_turn_start',
            'remaining': max(1, min(int(duration), 999)),
            'effects': self._clone_timer_effects(effects),
        }
        if condition is not None:
            cloned_condition = self._clone_timer_effects([condition])
            entry['condition'] = cloned_condition[0] if cloned_condition else condition
        if card is not None and getattr(card, 'instance_id', None) is not None:
            entry['card_instance_id'] = card.instance_id
        self.timed_effects.append(entry)
        if len(self.timed_effects) > 200:
            self.timed_effects = self.timed_effects[-200:]

    def _run_target_turn_start_after_draw_equipment(self, current_player: int) -> None:
        """Run equipment events that resolve after the target's turn-start draw."""
        for owner_id, eq in list(self._iter_equipment_targeting_player(current_player)):
            if self.game_over or getattr(self, 'pending_v2_ui', None) or self.pending_choice is not None:
                return
            if not self._has_card_event(eq.card_def, 'target_turn_start_after_draw'):
                continue
            try:
                effect_target_id = int(getattr(eq, 'effect_target', owner_id))
            except (TypeError, ValueError):
                effect_target_id = current_player
            if not (0 <= effect_target_id < len(self.players)):
                effect_target_id = current_player
            self._run_card_event(
                owner_id,
                eq.card_instance,
                'target_turn_start_after_draw',
                None,
                {'source_id': owner_id, 'target_id': effect_target_id},
            )

    def _run_timed_effects_for_turn(self, current_player: int, phase: str = 'normal'):
        if not getattr(self, 'timed_effects', None):
            return
        pending = list(self.timed_effects)
        self.timed_effects = []
        kept = []
        processed_count = 0
        while pending and processed_count < 512:
            entry = pending.pop(0)
            if not isinstance(entry, dict):
                continue
            if not self._timer_trigger_matches(entry, current_player, phase):
                kept.append(entry)
                continue
            timer_id = entry.get('_timer_id')
            if timer_id is None:
                timer_id = int(getattr(self, '_timed_effect_serial', 0) or 0) + 1
                self._timed_effect_serial = timer_id
                entry['_timer_id'] = timer_id
            if bool(getattr(self, '_turn_boundary_active', False)):
                key = ('timed_effect', str(phase or ''), int(current_player), int(timer_id))
                if not self._turn_boundary_claim(key):
                    kept.append(entry)
                    continue
            owner_id = int(entry.get('owner_id', current_player))
            target_id = int(entry.get('target_id', owner_id))
            remaining = int(entry.get('remaining', 0))
            timer_card = None
            if entry.get('card_instance_id') is not None:
                timer_card = self._find_card_by_instance_id(entry.get('card_instance_id'))
            timer_context = {
                'event': 'timed_effect',
                'source_id': owner_id,
                'target_id': target_id,
                'timer_current_player': current_player,
                'timer_remaining': remaining,
            }
            condition = entry.get('condition')
            condition_holds = True
            if condition is not None:
                condition_holds = self._loop_iteration_allows(owner_id, timer_card, condition, timer_context)
            if condition_holds:
                self._run_effect_list(
                    owner_id,
                    timer_card,
                    entry.get('effects', []),
                    None,
                    timer_context,
                )
            entry['remaining'] = remaining - 1
            if entry['remaining'] > 0:
                kept.append(entry)
            processed_count += 1
            if self.timed_effects:
                pending.extend(self.timed_effects)
                self.timed_effects = []
        if pending:
            kept.extend(pending)
        if self.timed_effects:
            kept.extend(self.timed_effects)
        self.timed_effects = kept[-200:]

    # ------------------------------------------------------------------
    # Round 37 / 批次 AD-2：延迟效果族三合一 —— ``delayed_effect``
    # （旧 ``timed_effect`` / ``delayed_blind_next_turn`` /
    # ``delayed_reveal_hand_next_turn``，三个旧名进 REMOVED_ATOMIC_OPS）。
    #
    # 三条分支都还是同一个 ``_register_timed_effect`` 计时表，所以**时点语义**
    # 与合并前逐条相同：
    #
    #   * ``mode:"timed"``（默认，旧 ``timed_effect``）—— ``trigger`` 透传
    #     （别名照旧归一），``duration``/``turns`` 定持续回合数，``once:true``
    #     等价于 ``duration:1``，``body``/``effects``/``steps`` 到点时按原顺序
    #     结算，可选的火时 ``condition`` 走同一条 ``_loop_iteration_allows``。
    #   * ``mode:"blind"``（旧 ``delayed_blind_next_turn``）—— 目标下回合开始、
    #     **状态清算之后**（``target_turn_start_after_status_clear``）失明
    #     ``amount`` 层 + 洗牌，固定 ``duration:1``。
    #   * ``mode:"reveal_hand"``（旧 ``delayed_reveal_hand_next_turn``）—— 目标
    #     下回合开始时（``target_turn_start``）展示其手牌，固定 ``duration:1``。
    #
    # ``target`` 三个分支共用同一个选择器集合（``_timer_targets``：「每个目标各
    # 登记一份」的口径不变）。
    # ------------------------------------------------------------------
    DELAYED_EFFECT_MODES = ('timed', 'blind', 'reveal_hand')

    def _delayed_effect_mode(self, params) -> str:
        """``delayed_effect`` 的 ``mode`` 判别值（别名归一，默认 ``timed``）。"""

        mode = str(params.get('mode') or '').strip().lower()
        return {
            '': 'timed',
            'timed_effect': 'timed',
            'timer': 'timed',
            'custom': 'timed',
            'blind_next_turn': 'blind',
            'delayed_blind_next_turn': 'blind',
            'reveal_hand_next_turn': 'reveal_hand',
            'delayed_reveal_hand_next_turn': 'reveal_hand',
        }.get(mode, mode)

    def _atomic_delayed_effect(self, player_id, card, params, log, choice, context):
        mode = self._delayed_effect_mode(params if isinstance(params, dict) else {})
        if mode not in self.DELAYED_EFFECT_MODES:
            self._log_mod_runtime_error(
                'delayed_effect', RuntimeError(f'unsupported mode: {mode}'), player_id, card,
            )
            return
        if mode == 'timed':
            # Round 16 unified listener contract: ``trigger`` (aliases
            # ``turn_start``/``turn_end``/... normalised), ``duration`` (alias
            # ``turns``), ``body`` (aliases ``effects``/``steps``) and an
            # optional fire-time ``condition`` are shared with the rest of the
            # listener family.
            trigger = str(
                self._step_text_value(player_id, card, params.get('trigger')) or ''
            )
            trigger = normalize_listener_trigger('delayed_effect', trigger, default='target_turn_start')
            if not listener_trigger_is_supported('delayed_effect', trigger):
                self._log_mod_runtime_error(
                    'delayed_effect', RuntimeError(f'unsupported trigger: {trigger}'), player_id, card,
                )
                return
            duration = self._eval_int(player_id, params.get('duration', params.get('turns', 1)), card, 1)
            if params.get('once') is True:
                duration = 1
            effects = listener_body_from_params(params)
            if not effects:
                return
            condition = listener_condition_from_params(params)
            for target_id in self._timer_targets(player_id, params.get('target', 'self')):
                self._register_timed_effect(player_id, target_id, trigger, duration, effects, card, condition=condition)
            return
        if mode == 'blind':
            amount = self._eval_int(player_id, params.get('amount', 1), card, 1)
            effects = [
                {'type': 'status_add_named', 'params': {'target': 'target', 'status': 'blind', 'amount': amount}},
                {'type': 'shuffle', 'params': {'zone': 'hand', 'target': 'target'}},
            ]
            trigger = 'target_turn_start_after_status_clear'
        else:
            # ``mode:"reveal_hand"``：固定「下回合开始时展示其手牌」。
            effects = [{'type': 'reveal', 'params': {'mode': 'enemy_hand', 'target': 'target'}}]
            trigger = 'target_turn_start'
        for target_id in self._timer_targets(player_id, params.get('target', 'target')):
            self._register_timed_effect(player_id, target_id, trigger, 1, effects, card)
            if log:
                self.log_msg(log)

    # Round 41 / 批次 AE-5：``countdown_var`` 已删除——"写一个初值 + 每次触发减 1"
    # 就是两条通用步骤：``{"op":"player_var_change","mode":"set",...}`` 加
    # ``{"op":"delayed_effect","mode":"timed","trigger":…,"duration":…,
    # "body":[{"op":"player_var_change","mode":"sub",…}]}``（Round 37 / 批次 AD-2
    # 起 ``_register_timed_effect`` 的定时器已由 ``delayed_effect(mode:"timed")`` 承接）。
    # 旧名进 ``mod_spec_v2.REMOVED_ATOMIC_OPS``，写出来是显式报错。

    def _played_cards_total_this_turn(self, target_id: int, exclude_current: bool = False,
                                      actor_id: Optional[int] = None) -> int:
        """Total cards the given player has played this turn.

        The engine records every play *before* its effects resolve, so data steps
        that want "cards played before this one" pass ``exclude_current`` and the
        acting player to drop the card that is currently being resolved.
        """
        if not self._valid_player_id(target_id):
            return 0
        played = getattr(self.players[target_id], 'cards_played_this_turn', {}) or {}
        total = 0
        for value in played.values():
            try:
                total += int(value or 0)
            except (TypeError, ValueError):
                continue
        total = max(0, total)
        if exclude_current:
            actor = target_id if actor_id is None else actor_id
            try:
                actor = int(actor)
            except (TypeError, ValueError):
                actor = target_id
            if int(target_id) == actor:
                total = max(0, total - 1)
        return total

    def _current_damage_type(self) -> str:
        """Damage type of the effect that is currently resolving.

        Used by data steps that only react to physical (or only to magic) damage,
        e.g. a blood-debt listener on the ``on_damage_taken`` event.
        """
        contexts = []
        active = getattr(self, '_active_effect_context', None)
        if isinstance(active, dict):
            contexts.append(active)
        current = getattr(self, '_current_damage_context', None)
        if isinstance(current, dict):
            contexts.append(current)
        for ctx in contexts:
            for key in ('damage_type', 'damage_kind'):
                value = ctx.get(key)
                if value:
                    return str(value)
            for nested_key in ('current_action', 'vars', 'action', 'context'):
                nested = ctx.get(nested_key)
                if not isinstance(nested, dict):
                    continue
                for key in ('damage_type', 'damage_kind'):
                    value = nested.get(key)
                    if value:
                        return str(value)
        return ''

    def _card_cost_value(self, player_id, expr: dict, card: Optional[CardInstance] = None) -> int:
        """Actual cost of a card: the per-instance override first, then the card def."""
        if not isinstance(expr, dict):
            expr = {}
        target_card = self._resolve_card_ref(player_id, expr.get('card', {'ref': 'current_card'}), card)
        if target_card is None:
            return 0
        currency = str(expr.get('currency', expr.get('resource', 'e')) or 'e').strip().lower()
        card_def = getattr(target_card, 'card_def', None)
        # ``include_extras`` folds in the cost modifiers that are only known to
        # the holder (same-name surcharge, bamboo rebate, Frost, symbiosis):
        # the "actual cost" cards such as the Arctic Ruby pay half of it.
        include_extras = bool(expr.get('include_extras', expr.get('with_extras', False)))
        if currency in ('m', 'magic', 'mana'):
            override = getattr(target_card, 'cost_m_override', None)
            if override is not None:
                return max(0, int(override))
            return max(0, int(getattr(card_def, 'cost_m', 0) or 0))
        override = getattr(target_card, 'cost_e_override', None)
        base = max(0, int(getattr(card_def, 'cost_e', 0) or 0))
        if override is not None:
            base = max(0, int(override))
        if include_extras:
            owner_id = player_id
            try:
                located_owner, _, _ = self._find_card_location(target_card)
                if located_owner is not None and 0 <= int(located_owner) < len(self.players):
                    owner_id = int(located_owner)
            except Exception:
                owner_id = player_id
            try:
                base += int(self._get_extra_e_for_card(owner_id, target_card))
            except Exception:
                pass
        return max(0, int(base))

    def _eval_expr(self, player_id, expr, card=None):
        if isinstance(expr, dict):
            ref = expr.get('ref') or expr.get('op') or expr.get('type')
            if ref in ('const', 'literal'):
                return expr.get('value', expr.get('const', 0))
            if ref in ('add', 'sub', 'mul', 'div', '+', '-', '*', '/', 'min', 'max'):
                op = {'+': 'add', '-': 'sub', '*': 'mul', '/': 'div'}.get(ref, ref)
                values = expr.get('values')
                if values is None:
                    values = [expr.get('a', 0), expr.get('b', 0)]
                nums = [self._eval_expr(player_id, value, card) for value in values]
                nums = [int(self._scalar_value(num, 0)) for num in nums]
                if op == 'add':
                    return sum(nums)
                if op == 'sub':
                    return nums[0] - sum(nums[1:]) if nums else 0
                if op == 'mul':
                    out = 1
                    for num in nums:
                        out *= num
                    return out
                if op == 'div':
                    return 0 if len(nums) < 2 or nums[1] == 0 else nums[0] // nums[1]
                if op == 'min':
                    return min(nums) if nums else 0
                if op == 'max':
                    return max(nums) if nums else 0
            if ref in ('ceil', 'floor'):
                # Percentage expressions such as the Arctic Nuke's
                # ``ceil(health * 0.08)`` need real float math: the generic
                # arithmetic ops truncate to int before the caller sees it.
                raw = expr.get('values', expr.get('value', expr.get('a', 0)))
                if isinstance(raw, (list, tuple)):
                    raw = raw[0] if raw else 0
                number = self._scalar_value(self._eval_expr(player_id, raw, card), 0)
                try:
                    number = float(number)
                except (TypeError, ValueError):
                    number = 0.0
                return int(math.ceil(number)) if ref == 'ceil' else int(math.floor(number))
            if ref in ('health_percent', 'percent_health'):
                # ``ceil`` of a percentage of the target's *current* health, used
                # by cards such as the Arctic Nuke.  Kept in float math on
                # purpose: the generic mul/div ops truncate before rounding.
                target_id = self._resolve_target(player_id, expr.get('target', 'target'))
                if not self._valid_player_id(target_id):
                    return 0
                try:
                    percent = float(expr.get('percent', expr.get('value', 0.0)) or 0.0)
                except (TypeError, ValueError):
                    percent = 0.0
                minimum = expr.get('minimum')
                value = int(math.ceil(max(0, int(self.players[target_id].health or 0)) * percent))
                if minimum is not None:
                    try:
                        value = max(value, int(minimum))
                    except (TypeError, ValueError):
                        pass
                return value
            if ref == 'equip_turns':
                eq = self._find_equipment_for_card(player_id, card)
                return int(eq.turns_equipped) if eq is not None else int(getattr(card, 'equip_turns', 0) if card is not None else 0)
            if ref == 'durability':
                return int(getattr(card, 'durability', 0)) if card is not None else 0
            if ref == 'equipment_count_named':
                tid = self._resolve_target(player_id, expr.get('target', 'self'))
                card_id = str(expr.get('card_id', '') or '')
                if tid < 0:
                    ids = range(len(self.players))
                else:
                    ids = [tid]
                id_set = set(ids)
                return sum(
                    1
                    for owner_id, ps in enumerate(self.players)
                    for eq in ps.equipment
                    if eq.def_id == card_id
                    and int(getattr(eq, 'effect_target', getattr(eq, 'owner', owner_id))) in id_set
                )
            if ref == 'damage_source':
                context = getattr(self, '_active_effect_context', {}) or {}
                return int(context.get('source_id', player_id))
            if ref in ('damage_amount', 'current_damage'):
                context = getattr(self, '_active_effect_context', {}) or {}
                return int(context.get('damage', context.get('amount', 0)) or 0)
            if ref == 'timer_remaining':
                context = getattr(self, '_active_effect_context', {}) or {}
                return int(context.get('timer_remaining', 0))
            if ref == 'loop_index':
                context = getattr(self, '_active_effect_context', {}) or {}
                return int(context.get('loop_index', context.get('list_index', context.get('equipment_index', context.get('repeat_index', 0)))) or 0)
            if ref == 'status_count':
                target_id = self._resolve_target(player_id, expr.get('target', 'self'))
                return self._get_status_count(target_id, expr.get('status', ''))
            if ref == 'zone_count':
                target_id = self._resolve_target(player_id, expr.get('target', 'self'))
                if expr.get('require_selectable'):
                    if not self._valid_player_id(target_id):
                        return 0
                    zone = str(expr.get('zone', 'hand') or 'hand')
                    return sum(
                        1 for zone_card in self._card_zone_cards(target_id, zone)
                        if self._card_selectable_by_action(zone_card)
                    )
                return self._zone_size(target_id, expr.get('zone', 'hand'))
            if ref in ('turn_damage_taken', 'turn_damage_dealt', 'last_turn_damage_taken',
                       'last_turn_damage_dealt', 'total_damage_taken', 'total_damage_dealt'):
                target_id = self._resolve_target(player_id, expr.get('target', 'self'))
                return self._get_player_property_value(target_id, ref)
            if ref == 'choice_target':
                return int(self._selected_choice_target(-1))
            if ref == 'choice_confirmed':
                active_choice = getattr(self, '_active_choice', None) or {}
                if not isinstance(active_choice, dict):
                    return 0
                return 1 if bool(active_choice.get('confirmed') or active_choice.get('accepted')) else 0
            if ref == 'selected_card_index':
                active_choice = getattr(self, '_active_choice', None) or {}
                if not isinstance(active_choice, dict):
                    return 0
                return int(active_choice.get('_selected_card_index', 0))
            if ref == 'selected_cards_count':
                active_choice = getattr(self, '_active_choice', None) or {}
                if not isinstance(active_choice, dict):
                    return 0
                ids = active_choice.get('target_instance_ids')
                if isinstance(ids, list):
                    return len(ids)
                return 1 if active_choice.get('target_instance_id') is not None else 0
            if ref in ('card_property', 'card_prop'):
                target_card = self._resolve_card_ref(player_id, expr.get('card', {'ref': 'current_card'}), card)
                if target_card is None:
                    return 0
                prop = str(expr.get('property', expr.get('prop', 'fusion_level')) or 'fusion_level')
                if prop == 'paid_e':
                    return int(getattr(target_card, '_paid_e_this_play', getattr(target_card, 'cost_e', 0)) or 0)
                if prop == 'paid_m':
                    return int(getattr(target_card, '_paid_m_this_play', getattr(target_card, 'cost_m', 0)) or 0)
                if prop == 'cost_e':
                    return int(target_card.cost_e)
                if prop == 'cost_m':
                    return int(target_card.cost_m)
                if prop == 'cost_e_override':
                    return int(target_card.cost_e_override if target_card.cost_e_override is not None else target_card.card_def.cost_e)
                if prop == 'cost_m_override':
                    return int(target_card.cost_m_override if target_card.cost_m_override is not None else target_card.card_def.cost_m)
                return int(getattr(target_card, prop, 0))
            if ref == 'card_tag_count':
                target_card = self._resolve_card_ref(player_id, expr.get('card', {'ref': 'current_card'}), card)
                if target_card is None:
                    return 0
                return len(self._effective_card_flags(target_card))
            if ref == 'card_def_property':
                return self._get_card_def_property_value(player_id, expr.get('card', ''), expr.get('property', 'cost_e'), card)
            if ref == 'card_def_tags':
                return self._get_card_def_tags(player_id, expr.get('card', ''), card)
            if ref in ('equipment_property', 'equipment_prop'):
                eq = self._resolve_equipment_ref(player_id, expr.get('equipment', {'ref': 'current_equipment'}), card)
                return self._get_equipment_property_value(eq, expr.get('property', expr.get('prop', 'turns_equipped')))
            if ref == 'player_property':
                target_id = self._resolve_target(player_id, expr.get('target', 'self'))
                return self._get_player_property_value(target_id, expr.get('property', 'health'))
            if ref == 'var':
                target = expr.get('target', 'self')
                name = str(expr.get('name', 'var'))
                target_id = self._resolve_target(player_id, target)
                if self._is_suppressed_status_var(target_id, name):
                    return 0
                store = self._var_store_for_target(player_id, target)
                if name in store:
                    return self._scalar_value(store.get(name, 0), 0)
                # Steps that came from the v2 runtime keep their temporaries in
                # the live effect context (loop bodies are evaluated here).
                if target in ('self', None, ''):
                    active_context = getattr(self, '_active_effect_context', {}) or {}
                    context_vars = active_context.get('vars') if isinstance(active_context, dict) else None
                    if isinstance(context_vars, dict) and name in context_vars:
                        return self._scalar_value(context_vars.get(name), 0)
                return 0
            if ref == 'list_var':
                return self._scalar_value(self._eval_list(player_id, expr, card), 0)
            if ref == 'list':
                return self._scalar_value(self._eval_list(player_id, expr, card), 0)
            if ref == 'zone_list':
                return self._scalar_value(self._eval_list(player_id, expr, card), 0)
            if ref == 'list_length':
                return len(self._eval_list(player_id, expr.get('list', []), card))
            if ref == 'list_item':
                return self._scalar_value(self._list_item_raw(player_id, expr, card), 0)
            if ref in ('cards_played_this_turn', 'played_cards_this_turn', 'cards_played'):
                target_id = self._resolve_target(player_id, expr.get('target', 'self'))
                if not self._valid_player_id(target_id):
                    target_id = player_id
                return self._played_cards_total_this_turn(
                    target_id,
                    exclude_current=bool(expr.get('exclude_current', expr.get('exclude_self', False))),
                    actor_id=player_id,
                )
            if ref in ('damage_type', 'current_damage_type'):
                return self._current_damage_type()
            if ref in ('card_cost', 'actual_card_cost'):
                return self._card_cost_value(player_id, expr, card)
            if ref in ('last_positive_hits', 'positive_hits'):
                active_context = getattr(self, '_active_effect_context', {}) or {}
                nested_vars = active_context.get('vars') if isinstance(active_context.get('vars'), dict) else {}
                value = active_context.get('last_positive_hits', nested_vars.get('last_positive_hits', 0))
                return int(self._scalar_value(value, 0))
            if ref in ('current_turn_player', 'turn_player', 'active_player'):
                return int(getattr(self, 'current_player', player_id) or 0)
            if ref in ('card_var', 'card_custom_var'):
                target_card = self._resolve_card_ref(player_id, expr.get('card', {'ref': 'current_card'}), card)
                if target_card is None:
                    return int(expr.get('default', 0) or 0)
                store = getattr(target_card, 'custom_vars', None)
                name = str(expr.get('name', expr.get('var', '')) or '')
                if not isinstance(store, dict) or not name:
                    return int(expr.get('default', 0) or 0)
                return int(self._scalar_value(store.get(name, expr.get('default', 0)), 0))
        return self._base_eval_expr(player_id, expr, card)

    def _eval_condition(self, player_id, cond, card=None):
        if isinstance(cond, dict) and cond.get('op') in (
            'eq', 'ne', 'gt', 'gte', 'lt', 'lte', '>', '>=', '<', '<=', '==', '!=',
        ):
            # Round 13: the v2 condition language names its comparisons
            # ``eq``/``ne``/... (and accepts the raw symbol as the op).  Both
            # execution paths must read the same gate, so map the aliases onto
            # the engine's own ``compare`` semantics before falling through.
            a = self._eval_expr(player_id, cond.get('a', 0), card)
            b = self._eval_expr(player_id, cond.get('b', 0), card)
            operator = cond.get('operator') or {
                'eq': '=', 'ne': '!=', 'gt': '>', 'gte': '>=', 'lt': '<', 'lte': '<=',
                '==': '=', '!=': '!=', '>': '>', '>=': '>=', '<': '<', '<=': '<=',
            }.get(cond.get('op'), '=')
            return (a == b) if operator in ('=', '==') else (a != b) if operator in ('!=', '<>') \
                else (a < b) if operator == '<' else (a > b) if operator == '>' \
                else (a <= b) if operator == '<=' else (a >= b)
        if isinstance(cond, dict) and cond.get('op') in ('and', 'or') and (
            isinstance(cond.get('conditions'), list) or isinstance(cond.get('values'), list)
        ):
            # ``{"op": "and", "conditions": [...]}`` is the v2 spelling; the
            # engine's own data uses the ``a``/``b`` pair handled further down.
            parts = cond.get('conditions')
            if not isinstance(parts, list):
                parts = cond.get('values') or []
            results = [bool(self._eval_condition(player_id, item, card)) for item in parts]
            return all(results) if cond.get('op') == 'and' else any(results)
        if isinstance(cond, dict) and cond.get('op') == 'not' and 'condition' in cond:
            return not bool(self._eval_condition(player_id, cond.get('condition'), card))
        if isinstance(cond, dict) and cond.get('op') == 'equip_turns':
            a = self._eval_expr(player_id, {'ref': 'equip_turns'}, card)
            b = int(self._eval_expr(player_id, cond.get('value', 0), card))
            cmp = cond.get('operator', '=')
            return (a == b) if cmp == '=' else (a != b) if cmp == '!=' else (a < b) if cmp == '<' else (a > b) if cmp == '>' else (a <= b) if cmp == '<=' else (a >= b)
        if isinstance(cond, dict) and cond.get('op') in ('target_selectable', 'player_selectable'):
            target_id = self._resolve_target(player_id, cond.get('target', 'target'))
            return bool(self._target_can_be_selected(
                player_id, target_id, allow_self=cond.get('allow_self', True),
            ))
        if isinstance(cond, dict) and cond.get('op') == 'var_compare':
            name = str(cond.get('name', 'var'))
            target_ref = self._resolve_target(player_id, cond.get('target', 'self'))
            if self._is_suppressed_status_var(target_ref, name):
                a = 0
            else:
                a = int(self._scalar_value(self._var_store_for_target(player_id, cond.get('target', 'self')).get(name, 0), 0))
            b = int(self._eval_expr(player_id, cond.get('value', 0), card))
            cmp = cond.get('operator', '=')
            return (a == b) if cmp == '=' else (a != b) if cmp == '!=' else (a < b) if cmp == '<' else (a > b) if cmp == '>' else (a <= b) if cmp == '<=' else (a >= b)
        if isinstance(cond, dict) and cond.get('op') in ('has_status_named', 'has_status'):
            target_id = self._resolve_target(player_id, cond.get('target', 'self'))
            status_name = str(cond.get('name', cond.get('status', cond.get('id', ''))))
            if self._is_status_immune(target_id) and status_name not in ('status_immune', 'immune', '状态免疫'):
                return False
        if isinstance(cond, dict) and cond.get('op') == 'list_contains':
            values = self._eval_list(player_id, cond.get('list', []), card)
            item = self._serializable_list_item(self._eval_raw_item(player_id, cond.get('item', 0), card))
            return any(self._same_list_item(value, item) for value in values)
        if isinstance(cond, dict) and cond.get('op') == 'damage_source_relation':
            context = getattr(self, '_active_effect_context', {}) or {}
            source_id = int(context.get('source_id', player_id))
            target_id = int(context.get('target_id', player_id))
            relation = str(cond.get('relation', 'any'))
            if relation == 'any':
                return 0 <= source_id < len(self.players)
            if relation == 'self':
                return source_id == target_id
            same_side = self._same_timer_side(source_id, target_id)
            if relation in ('friendly', 'ally'):
                return same_side and source_id != target_id
            if relation == 'same_side':
                return same_side
            if relation == 'enemy':
                return self._opposite_timer_side(source_id, target_id)
            return False
        if isinstance(cond, dict) and cond.get('op') == 'event_card_type':
            context = getattr(self, '_active_effect_context', {}) or {}
            expected = str(cond.get('card_type', 'any') or 'any')
            actual = str(context.get('event_card_type', '') or '')
            return expected == 'any' or expected == actual
        if isinstance(cond, dict) and cond.get('op') == 'has_tag':
            target_card = self._resolve_card_ref(player_id, cond.get('card', {'ref': 'current_card'}), card)
            if target_card is None:
                return False
            tag = normalize_card_flag(cond.get('tag', ''))
            flags = normalize_card_flags(getattr(target_card.card_def, 'flags', set()) or set())
            flags.update(normalize_card_flags(getattr(target_card, 'instance_flags', set()) or set()))
            flags.difference_update(normalize_card_flags(getattr(target_card, 'disabled_flags', set()) or set()))
            return tag in flags
        if isinstance(cond, dict) and cond.get('op') in ('damage_type_is', 'damage_type'):
            expected = str(
                cond.get('type_name') or cond.get('damage_type') or cond.get('value') or 'physical'
            ).strip().lower()
            actual = self._current_damage_type().strip().lower()
            if expected in ('any', '*', ''):
                return bool(actual)
            return actual == expected
        return self._base_eval_condition(player_id, cond, card)

    def _eval_int(self, player_id, value, card=None, default=0):
        try:
            return int(self._scalar_value(self._eval_expr(player_id, value, card), default))
        except Exception:
            try:
                return int(value)
            except Exception:
                return default

    def _card_needs_choice(self, card: CardInstance) -> bool:
        if 'wide_strike' in self._effective_card_flags(card):
            return False
        declaration = self._play_choice_request_declaration(card)
        if declaration and self._play_choice_request_needed(declaration, card, None):
            # Round 19: the pre-play prompt is declared by card data; a
            # ``needs_target`` card (Blood Sugar) asks for the attack target
            # first and for the mode right after.
            return True
        if self._card_has_flag(card, 'spikeball_boost'):
            owner_id, zone_name, _ = self._find_card_location(card)
            if owner_id is not None and zone_name == 'hand':
                try:
                    if len(self.players[owner_id].hand) < 4:
                        return False
                except Exception:
                    pass
        if self._base_card_needs_choice(card):
            return True
        if self._get_choice_request(card) is not None:
            return True
        return self._v2_play_requires_choice_target(card) or self._root_play_requires_owner_target(card)

    def _get_choice_type(self, card: CardInstance) -> str:
        if 'wide_strike' in self._effective_card_flags(card):
            return ''
        effect = self._get_choice_request(card)
        if effect:
            return self._choice_type_for_effect(effect, card)
        if self._v2_play_requires_choice_target(card) or self._root_play_requires_owner_target(card):
            return 'choose_target'
        base = self._base_get_choice_type(card)
        return base or ''

    def _choice_satisfies_request(self, card: CardInstance, choice) -> bool:
        if not self._card_needs_choice(card):
            return True
        if not isinstance(choice, dict):
            return False
        if self._get_choice_request(card, choice) is not None:
            return False
        if 'wide_strike' in self._effective_card_flags(card):
            return True
        if self._v2_play_requires_choice_target(card) or self._root_play_requires_owner_target(card):
            return self._choice_target_from_choice(choice) >= 0
        return True

    def _process_atomic_effects(self, player_id: int, card: CardInstance, choice: Optional[dict], context: str):
        context_name = context if isinstance(context, str) else str((context or {}).get('context', ''))
        context_dict = context if isinstance(context, dict) else ({'context': context} if context else {})
        effects = self._play_effects_for_card(card) if context_name == 'play' else card.card_def.effects
        prev_choice = getattr(self, '_active_choice', None)
        if isinstance(choice, dict):
            self._active_choice = choice
        try:
            for effect in effects:
                if isinstance(effect, str):
                    eff_type = effect
                    params = {}
                    log = ''
                else:
                    eff_type = effect.get('type', '')
                    params = effect.get('params', {})
                    log = effect.get('log', '')
                if context_name == 'play' and eff_type in self.EVENT_EFFECT_TYPES:
                    continue
                if self._fatal_declaration_kind(eff_type, params) and context_name == 'play':
                    if log:
                        self.log_msg(log)
                    continue
                retired_error = self._retired_atom_runtime_error(eff_type)
                if retired_error is not None:
                    self._log_mod_runtime_error(eff_type, retired_error, player_id, card)
                    continue
                resolved_type = self._EFFECT_ALIASES.get(eff_type, eff_type)
                handler = getattr(self, f'_atomic_{resolved_type}', None)
                try:
                    before_stats = self._snapshot_player_stats()
                    if handler:
                        handler(player_id, card, params, log, choice, context_dict)
                    elif log:
                        self.log_msg(log)
                    else:
                        self._log_mod_runtime_error(eff_type, RuntimeError(f'Unknown effect: {eff_type}'), player_id, card)
                    if resolved_type not in ('if', 'if_else', 'repeat', 'repeat_until', 'for_each',
                                             'for_each_selected_card', 'for_each_list', 'delayed_effect',
                                             'defer_game_over'):
                        self._dispatch_player_stat_changes(before_stats, player_id, card)
                except (ModLoopBreak, ModLoopContinue) as exc:
                    self._log_mod_runtime_error(eff_type, RuntimeError(f'{type(exc).__name__} outside loop'), player_id, card)
                except Exception as exc:
                    self._log_mod_runtime_error(eff_type, exc, player_id, card)
        finally:
            self._active_choice = prev_choice

    def _apply_card_effect(self, player_id: int, card: CardInstance, choice: Optional[dict] = None):
        previous_card = getattr(self, '_active_v2_card', None)
        self._active_v2_card = card
        try:
            from formal_logic_runtime import formal_proxy_suppresses_effect
            if formal_proxy_suppresses_effect(card):
                self.log_msg(f"{self.pn(player_id)}使用了{card.name_cn}（宏定义代理）")
                return
            engine_effect = self._declared_engine_effect(card)
            if engine_effect:
                getattr(self, engine_effect)(player_id, card, choice)
                return
            # For thorn cards with damage/hits but no dedicated effect handler,
            # apply attack damage only if the card has no v2 on_play event
            # (v2 events handle their own damage logic)
            card_damage = getattr(card.card_def, 'damage', 0)
            card_hits_val = self._card_total_hits(card)
            has_v2_play = self._card_has_v2_event(card.card_def, 'on_play')
            if card.card_type == 'thorn' and card_damage > 0 and not has_v2_play:
                method_name = f'_effect_{card.def_id.lower()}'
                if not hasattr(self, method_name):
                    dmg = self._modified_attack_damage(card_damage, card)
                    is_precision = 'precision' in self._effective_card_flags(card)
                    if 'wide_strike' in self._effective_card_flags(card):
                        target_ids = self._wide_strike_target_ids(player_id, card)
                    elif hasattr(self, '_selected_attack_target'):
                        target_id = self._selected_attack_target(player_id, choice)
                        target_ids = [target_id]
                    else:
                        target_id = 1 - player_id
                        target_ids = [target_id]
                    for target_id in target_ids:
                        if not (0 <= int(target_id) < len(self.players)):
                            continue
                        self.deal_attack_damage(target_id, dmg, card_hits_val, is_precision=is_precision, attacker_id=player_id, source_card=card)
            if self._card_has_v2_event(card.card_def, 'on_play'):
                self._run_v2_card_event(player_id, card, 'on_play', choice)
                return
            if self._card_has_script(card.card_def) or card.card_def.effects:
                self._process_atomic_effects(player_id, card, choice, 'play')
                return
            method_name = f'_effect_{card.def_id.lower()}'
            if hasattr(self, method_name):
                getattr(self, method_name)(player_id, card, choice)
            else:
                self.log_msg(f"{self.pn(player_id)}使用了{card.name_cn}")
        finally:
            self._active_v2_card = previous_card

    def _uses_atomic_play_effects(self, card: CardInstance) -> bool:
        return bool(self._card_has_v2_event(card.card_def, 'on_play') or self._card_has_script(card.card_def) or card.card_def.effects)

    def _log_card_play_summary(self, declaration: dict, player_id: int,
                               discarded: bool, discard_count: int = 0) -> None:
        """Log a data declared play summary (``events.on_play_summary``)."""
        if not isinstance(declaration, dict):
            return
        template = declaration.get('discarded_log' if discarded else 'plain_log')
        if not isinstance(template, str) or not template:
            return
        self.log_msg(self._format_step_log(
            template,
            player=self.pn(player_id),
            target=self.pn(player_id),
            count=max(1, int(discard_count or 0)),
        ))

    def _card_has_v2_event(self, card_def, event_name: str) -> bool:
        return self._get_v2_event_def(card_def, event_name) is not None

    def _get_v2_event_def(self, card_def, event_name: str):
        events = getattr(card_def, 'v2_events', None)
        if not isinstance(events, dict):
            return None
        if events.get(event_name):
            return events.get(event_name)
        if event_name.startswith('on_'):
            legacy_name = event_name[3:]
            if events.get(legacy_name):
                return events.get(legacy_name)
        return None

    def _card_is_self_only(self, card: Optional[CardInstance]) -> bool:
        if card is None:
            return False
        flags = set(getattr(card, 'flags', set()) or set())
        card_def = getattr(card, 'card_def', None)
        if card_def is not None:
            flags.update(getattr(card_def, 'flags', []) or [])
        return 'self_only' in flags or 'tag_self_only' in flags

    def _effect_tree_uses_target_selector(self, value, depth: int = 0) -> bool:
        if depth > 20:
            return False
        if isinstance(value, str):
            return value in ('target', 'event_target')
        if isinstance(value, dict):
            for key, item in value.items():
                if key in ('op', 'type'):
                    # Round 36 / 批次 AD-1：步骤的 op 名与请求伞的判别值
                    # （``{"op":"request","type":"target"}``）不是目标选择器，
                    # 别把它们当"这个事件树用了 target"。
                    continue
                if key in ('target', 'targets', 'target_player', 'effect_target') and self._effect_tree_uses_target_selector(item, depth + 1):
                    return True
                if self._effect_tree_uses_target_selector(item, depth + 1):
                    return True
            return False
        if isinstance(value, (list, tuple)):
            return any(self._effect_tree_uses_target_selector(item, depth + 1) for item in value)
        return False

    def _effect_tree_uses_choice_target(self, value, depth: int = 0) -> bool:
        if depth > 20:
            return False
        if isinstance(value, str):
            return value in ('choice_target', 'chosen_target', 'selected_target')
        if isinstance(value, dict):
            return any(self._effect_tree_uses_choice_target(item, depth + 1) for item in value.values())
        if isinstance(value, (list, tuple)):
            return any(self._effect_tree_uses_choice_target(item, depth + 1) for item in value)
        return False

    def _v2_play_requires_choice_target(self, card: Optional[CardInstance]) -> bool:
        if card is None or not getattr(card, 'card_def', None):
            return False
        if card.card_type in ('thorn', 'guard'):
            return False
        if self._card_is_self_only(card):
            return False
        events = getattr(card.card_def, 'v2_events', None) or {}
        event_def = events.get('on_play')
        return self._effect_tree_uses_choice_target(event_def) or self._effect_tree_uses_target_selector(event_def)

    def _root_equipment_events_use_effect_target(self, card: Optional[CardInstance]) -> bool:
        if card is None or not getattr(card, 'card_def', None):
            return False
        events = getattr(card.card_def, 'v2_events', None) or {}
        for event_name, event_def in events.items():
            name = str(event_name or '')
            if name in ('on_play', 'play'):
                continue
            # Manual trigger cards choose their target when triggered, not when equipped.
            if 'trigger' in name:
                continue
            if not (
                'equip' in name
                or 'turn_start' in name
                or 'turn_end' in name
                or 'damage' in name
                or 'destroy' in name
            ):
                continue
            if self._effect_tree_uses_choice_target(event_def) or self._effect_tree_uses_target_selector(event_def):
                return True
        return False

    def _root_play_requires_owner_target(self, card: Optional[CardInstance]) -> bool:
        if card is None or getattr(card, 'card_type', '') != 'root':
            return False
        if self._card_is_self_only(card):
            return False
        if self._root_equipment_events_use_effect_target(card):
            return True
        # Round 6a: the data carries the declaration now.  Root cards whose
        # play attaches them to a chosen player but whose event tree never uses
        # a target selector declare ``owner_target`` in their ``flags``; the
        # packs own that list, the engine only reads the flag.
        return 'owner_target' in self._effective_card_flags(card)

    def _default_enemy_target_for_event(self, player_id: int) -> int:
        if hasattr(self, 'get_enemies'):
            try:
                enemies = list(self.get_enemies(player_id))
            except Exception:
                enemies = []
        else:
            enemies = [1 - player_id] if len(self.players) == 2 else []
        for target_id in enemies:
            if self._target_can_be_selected(player_id, target_id, allow_self=False):
                return target_id
        return -1

    def _infer_v2_event_target(self, player_id: int, card: CardInstance, event_name: str,
                               choice: Optional[dict], extra_context: Optional[dict]) -> int:
        if event_name != 'on_play':
            return -1
        events = getattr(card.card_def, 'v2_events', None) or {}
        event_def = events.get(event_name)
        uses_choice_target = self._effect_tree_uses_choice_target(event_def)
        uses_implicit_target = self._effect_tree_uses_target_selector(event_def)
        if not uses_choice_target and not uses_implicit_target:
            return -1
        if self._card_is_self_only(card) and card.card_type != 'thorn':
            return player_id
        if card.card_type == 'guard':
            return player_id
        if isinstance(choice, dict):
            selected = self._selected_choice_target(-1)
            if 0 <= selected < len(self.players):
                return selected
            for key in ('target_player', 'target_player_id', 'target_id'):
                if key in choice:
                    try:
                        selected = int(choice.get(key))
                    except Exception:
                        selected = -1
                    if 0 <= selected < len(self.players):
                        return selected
        if uses_choice_target and not uses_implicit_target and card.card_type not in ('thorn', 'guard'):
            return -1
        selected = self._default_enemy_target_for_event(player_id)
        if selected >= 0:
            return selected
        return -1

    def _run_v2_card_event(self, player_id: int, card: CardInstance, event_name: str,
                           choice: Optional[dict] = None, extra_context: Optional[dict] = None,
                           event_def_override=None):
        event_def = (
            event_def_override
            if event_def_override is not None
            else self._get_v2_event_def(card.card_def, event_name)
        )
        extra_context = extra_context if isinstance(extra_context, dict) else {}
        current_eq = self._find_equipment_for_card(player_id, card) if event_name != 'on_play' else None
        target_id = -1
        target_explicit = False
        if isinstance(choice, dict):
            for key in ('target_player', 'target_player_id', 'target_id'):
                if key in choice:
                    try:
                        target_id = int(choice.get(key))
                        target_explicit = True
                        break
                    except Exception:
                        target_id = -1
        if target_id < 0:
            for key in ('target_player', 'target_player_id', 'target_id'):
                if key in extra_context:
                    try:
                        target_id = int(extra_context.get(key))
                        target_explicit = bool(extra_context.get('target_player_explicit', True))
                        break
                    except Exception:
                        target_id = -1
        if target_id < 0 or target_id >= len(self.players):
            inferred_target = self._infer_v2_event_target(player_id, card, event_name, choice, extra_context)
            if 0 <= inferred_target < len(self.players):
                target_id = inferred_target
        if (target_id < 0 or target_id >= len(self.players)) and event_name != 'on_play':
            target_id = player_id
        context_target_id = extra_context.get('target_id', target_id)
        if isinstance(choice, dict):
            for key in ('target_player', 'target_player_id', 'target_id'):
                if key in choice:
                    try:
                        context_target_id = int(choice.get(key))
                        break
                    except Exception:
                        pass
        context = {
            'source_player': player_id,
            'target_player': target_id,
            'source_id': extra_context.get('source_id', player_id),
            'target_id': context_target_id,
            'damage_source': extra_context.get('damage_source', extra_context.get('source_id', player_id)),
            'target_player_explicit': target_explicit,
            'card': card,
            'room': getattr(self, 'room', None),
            'loadout': getattr(self, 'v2_loadout', None),
            'vars': {**dict(extra_context), 'listener_owner_id': player_id},
            'last_damage': int(extra_context.get('last_damage', extra_context.get('damage', extra_context.get('damage_amount', 0))) or 0),
            'damage': int(extra_context.get('damage', extra_context.get('damage_amount', 0)) or 0),
            'damage_amount': int(extra_context.get('damage_amount', extra_context.get('damage', 0)) or 0),
            'event_value': extra_context.get('event_value', extra_context.get('damage_amount', extra_context.get('damage', 0))),
            'current_event': event_name,
            'current_action': {'choice': choice or {}, **extra_context},
        }
        # Response effects such as Mirror need the detached card object itself;
        # an instance id cannot resolve it after the card has left its hand.
        for response_key in ('original_card', 'original_card_instance_id', 'original_card_def_id'):
            if response_key in extra_context:
                context[response_key] = extra_context[response_key]
        # Cross-target equipment events run from the affected player's context,
        # but costs and choices still belong to the equipment owner.
        for equipment_key in ('selected_equipment_instance_id', 'selected_equipment_owner_id'):
            if equipment_key in extra_context:
                context[equipment_key] = extra_context[equipment_key]
        if event_name == 'on_play' and 'wide_strike' in self._effective_card_flags(card):
            wide_targets = self._wide_strike_target_ids(player_id, card)
            context['wide_strike_targets'] = wide_targets
            context['target_players'] = wide_targets
            context['vars']['wide_strike_targets'] = wide_targets
            context['current_action']['wide_strike_targets'] = wide_targets
            if wide_targets:
                context['target_player'] = wide_targets[0]
                context['target_id'] = wide_targets[0]
                context['target_player_explicit'] = False
        if current_eq is not None:
            context['current_equipment'] = current_eq
            context['selected_equipment_instance_id'] = current_eq.card_instance.instance_id
            context['selected_equipment_owner_id'] = player_id
        play_summary = {}
        if event_name == 'on_play':
            from engine_runtime_support import play_summary_declaration
            play_summary = play_summary_declaration(card)
            if play_summary.get('suppress_detail_logs'):
                context['suppress_detail_logs'] = True
        if isinstance(choice, dict):
            instance_ids = []
            if choice.get('target_instance_id') is not None:
                instance_ids.append(choice.get('target_instance_id'))
            if isinstance(choice.get('target_instance_ids'), list):
                instance_ids.extend(choice.get('target_instance_ids'))
            chosen_cards = []
            seen_ids = set()
            for instance_id in instance_ids:
                try:
                    iid = int(instance_id)
                except Exception:
                    continue
                if iid in seen_ids:
                    continue
                seen_ids.add(iid)
                selected = self._find_card_by_instance_id(iid)
                if selected is not None and self._card_selectable_by_action(selected):
                    chosen_cards.append(selected)
            if chosen_cards:
                context['chosen_card'] = chosen_cards[0]
                context['chosen_cards'] = chosen_cards
        result = run_v2_event(self, context, event_def)
        if isinstance(result, dict) and result.get('needs_v2_ui'):
            self._store_v2_ui_pause(result.get('v2_ui_pause') or {}, card)
        elif event_name == 'on_play' and play_summary:
            chosen_cards = context.get('chosen_cards') if isinstance(context.get('chosen_cards'), list) else []
            self._log_card_play_summary(play_summary, player_id, bool(chosen_cards), len(chosen_cards))
        return result

    def _store_v2_ui_pause(self, pause: dict, card: Optional[CardInstance] = None):
        if not isinstance(pause, dict):
            return
        request_id = str(pause.get('request_id') or '')
        component = pause.get('component') if isinstance(pause.get('component'), dict) else {}
        context = pause.get('context') if isinstance(pause.get('context'), dict) else {}
        target_player = pause.get('target_player', context.get('source_player', 0))
        try:
            target_player = int(target_player)
        except Exception:
            target_player = 0
        if target_player < 0 or target_player >= len(self.players):
            target_player = 0
        self.pending_v2_ui = {
            'request_id': request_id,
            'player_id': target_player,
            'component': component,
            'save_as': str(pause.get('save_as') or 'ui_result'),
            'timeout_ms': int(pause.get('timeout_ms') or 0),
            'on_cancel': pause.get('on_cancel', []) if isinstance(pause.get('on_cancel', []), list) else [],
            'remaining_steps': pause.get('remaining_steps', []) if isinstance(pause.get('remaining_steps', []), list) else [],
            'context': context,
            'card': card.to_dict() if card is not None else (
                context.get('card').to_dict() if isinstance(context.get('card'), CardInstance) else None
            ),
            'resume_kind': str(pause.get('resume_kind') or 'v2_steps'),
            'resume_state': copy.deepcopy(pause.get('resume_state')) if isinstance(pause.get('resume_state'), dict) else {},
        }

    def _public_v2_ui(self, for_player: int) -> Optional[dict]:
        pending = getattr(self, 'pending_v2_ui', None)
        if not pending or pending.get('player_id') != for_player:
            return None
        return {
            'request_id': pending.get('request_id'),
            'component': pending.get('component'),
            'card': pending.get('card'),
            'timeout_ms': pending.get('timeout_ms', 0),
        }

    def handle_v2_ui_response(self, player_id: int, request_id: str, response: Optional[dict]) -> dict:
        pending = getattr(self, 'pending_v2_ui', None)
        if not pending:
            return {'success': False, 'error': 'No pending v2 UI request'}
        if pending.get('player_id') != player_id or str(pending.get('request_id')) != str(request_id):
            return {'success': False, 'error': 'Invalid v2 UI response'}
        context = pending.get('context') if isinstance(pending.get('context'), dict) else {}
        component = pending.get('component') if isinstance(pending.get('component'), dict) else {}
        try:
            clean = validate_v2_ui_response(self, context, component, response or {})
            self.pending_v2_ui = None
            button = clean.get('button')
            button_role = self._v2_button_role(component, button)
            if pending.get('resume_kind') == 'formal_logic':
                from formal_logic_runtime import resume_formal_logic_actions
                result = resume_formal_logic_actions(
                    self,
                    pending.get('resume_state') or {},
                    clean,
                    cancelled=button_role == 'cancel',
                )
                self._check_game_over()
                return result if isinstance(result, dict) else {'success': True}
            if pending.get('resume_kind') == 'void_dlc':
                from engine_runtime_support import resume_void_dlc_actions
                result = resume_void_dlc_actions(
                    self,
                    pending.get('resume_state') or {},
                    clean,
                    cancelled=button_role == 'cancel',
                )
                self._check_game_over()
                return result if isinstance(result, dict) else {'success': True}
            if button_role == 'cancel':
                cancel_steps = pending.get('on_cancel', []) if isinstance(pending.get('on_cancel', []), list) else []
                if cancel_steps:
                    result = run_v2_steps(self, context, cancel_steps)
                    if isinstance(result, dict) and result.get('needs_v2_ui'):
                        self._store_v2_ui_pause(result.get('v2_ui_pause') or {})
                        return {'success': True, 'needs_v2_ui': True}
                return {'success': True, 'cancelled': True}
            context.setdefault('vars', {})[pending.get('save_as') or 'ui_result'] = clean.get('values', {})
            context['current_action'] = {
                **(context.get('current_action') if isinstance(context.get('current_action'), dict) else {}),
                'v2_ui': clean,
            }
            result = run_v2_steps(self, context, pending.get('remaining_steps') or [])
            if isinstance(result, dict) and result.get('needs_v2_ui'):
                self._store_v2_ui_pause(result.get('v2_ui_pause') or {})
                return {'success': True, 'needs_v2_ui': True}
            self._check_game_over()
            return {'success': True}
        except Exception as exc:
            self.pending_v2_ui = None
            self._log_mod_runtime_error('request_ui', exc, player_id, None)
            return {'success': False, 'error': str(exc)}

    def _v2_button_role(self, component: dict, button_id: str) -> str:
        for button in component.get('buttons', []) if isinstance(component.get('buttons'), list) else []:
            if isinstance(button, dict) and str(button.get('id')) == str(button_id):
                return str(button.get('role') or ('cancel' if button_id == 'cancel' else 'confirm'))
        return 'cancel' if button_id == 'cancel' else 'confirm'

    def _card_log_marker(self, card: CardInstance) -> str:
        try:
            payload = card.to_dict()
            payload.pop('instance_id', None)
            hidden_log_flags = {
                'ocean_no_auto',
                SPIKEBALL_BOOSTED_FLAG,
                SPIKEBALL_ADDED_PRECISION_FLAG,
                SPIKEBALL_ADDED_WIDE_STRIKE_FLAG,
                'multi_petal_fission',
            }
            payload['instance_flags'] = [
                flag for flag in (payload.get('instance_flags') or [])
                if normalize_card_flag(flag) not in hidden_log_flags
            ]
            raw = json.dumps(payload, ensure_ascii=False, separators=(',', ':')).encode('utf-8')
            encoded = base64.urlsafe_b64encode(raw).decode('ascii').rstrip('=')
            return f'\u2063CARD:{encoded}\u2063'
        except Exception:
            return ''

    def _log_card_play(self, player_id: int, card: CardInstance):
        self.log_msg(f"{self.pn(player_id)}使用了{card.name_cn}{self._card_log_marker(card)}")

    def _log_equipment_trigger(self, player_id: int, eq: EquipmentInstance):
        card = getattr(eq, 'card_instance', None)
        if card is None:
            return
        self.log_msg(f"{self.pn(player_id)}触发{card.name_cn}{self._card_log_marker(card)}")

    def _effective_card_flags(self, target_card: Optional[CardInstance]) -> Set[str]:
        if target_card is None:
            return set()
        flags = normalize_card_flags(getattr(target_card.card_def, 'flags', set()) or set())
        flags.update(normalize_card_flags(getattr(target_card, 'instance_flags', set()) or set()))
        setup_modifiers = set(getattr(target_card, 'setup_modifiers', set()) or set())
        if 'desert_citron_precision_play' in setup_modifiers:
            flags.add('precision')
        if 'desert_citron_stealth_play' in setup_modifiers:
            flags.add('stealth')
        flags.difference_update(normalize_card_flags(getattr(target_card, 'disabled_flags', set()) or set()))
        return flags

    @staticmethod
    def _actual_card_elixir_cost(card: Optional[CardInstance]) -> int:
        if card is None:
            return 0
        paid = getattr(card, '_paid_e_this_play', None)
        if paid is not None:
            return max(0, int(paid or 0))
        return max(0, int(getattr(card, 'cost_e', 0) or 0))

    def _card_blocks_response(self, card: Optional[CardInstance]) -> bool:
        return 'stealth' in self._effective_card_flags(card)

    def _prepare_desert_citron_play_flags(self, player_id: int, card: Optional[CardInstance]) -> None:
        if card is None:
            return
        card.setup_modifiers.discard('desert_citron_precision_play')
        card.setup_modifiers.discard('desert_citron_stealth_play')
        if getattr(card, 'card_type', '') != 'thorn':
            return
        citrons = [
            eq for _, eq in self._iter_equipment_targeting_player(player_id)
            if self._card_has_flag(getattr(eq, 'card_instance', None), 'citron_play_prepare')
        ]
        for _ in citrons:
            flags = self._effective_card_flags(card)
            if 'precision' in flags:
                card.setup_modifiers.add('desert_citron_stealth_play')
            else:
                card.setup_modifiers.add('desert_citron_precision_play')

    def _random_nonrepeating_attack_targets(
            self,
            player_id: int,
            count: int,
            previous_target: Optional[int] = None) -> List[int]:
        targets: List[int] = []
        try:
            previous = int(previous_target) if previous_target is not None else -1
        except (TypeError, ValueError):
            previous = -1
        for _ in range(max(0, int(count or 0))):
            candidates = [
                target_id for target_id in range(len(self.players))
                if target_id != previous
                and self._target_can_be_selected(player_id, target_id, allow_self=True)
            ]
            if not candidates:
                break
            from engine_runtime_support import forced_random_target
            previous = forced_random_target(self, player_id, candidates)
            targets.append(previous)
        return targets

    def _prepare_desert_marble_targets(self, player_id: int, card: Optional[CardInstance],
                                       choice: Optional[dict]) -> Optional[dict]:
        if self._declared_secondary_target_key(card) != '_desert_marble_targets':
            return choice
        updated = dict(choice or {})
        if not isinstance(updated.get('_desert_marble_targets'), list):
            count = (
                clamp_card_layer(getattr(card, 'fission_level', 1))
                * self._card_total_hits(card, 1)
            )
            primary_target = self._choice_target_from_choice(updated, -1)
            updated['_desert_marble_targets'] = self._random_nonrepeating_attack_targets(
                player_id,
                count,
                primary_target,
            )
        card._desert_marble_bounce_cursor = 0
        card._desert_marble_previous_target = self._choice_target_from_choice(updated, -1)
        updated = self._prepare_bounce_targets(player_id, card, updated)
        if not isinstance(updated.get('_desert_marble_targets'), list):
            updated['_desert_marble_targets'] = list(updated.get('_bounce_targets') or [])
        return updated

    def _arctic_ricochet_repeat_count(self, player_id: int, card: Optional[CardInstance]) -> int:
        params = self._bounce_params_for_card(card)
        if not params:
            return 0
        if params.get('bounces_from_positive_hits'):
            return 1
        return max(0, self._eval_int(player_id, params.get('bounces', params.get('repeats', 0)), card, 0))

    def _prepare_arctic_ricochet_targets(
            self,
            player_id: int,
            card: Optional[CardInstance],
            choice: Optional[dict]) -> Optional[dict]:
        params = self._bounce_params_for_card(card)
        if not params:
            return choice
        updated = self._prepare_bounce_targets(player_id, card, choice)
        if not isinstance(updated.get('_arctic_ricochet_targets'), list):
            updated['_arctic_ricochet_targets'] = list(updated.get('_bounce_targets') or [])
        return updated

    def _bounce_params_for_card(self, card: Optional[CardInstance]) -> Optional[dict]:
        """Return the parameters of this card's bounce/ricochet effect, if any."""
        if card is None:
            return None
        for effect in self._v2_play_steps_for_card(card):
            effect_type = self._effect_type(effect)
            resolved = self._EFFECT_ALIASES.get(effect_type, effect_type)
            if resolved not in ('ricochet_attack', 'arctic_ricochet_attack', 'desert_marble_attack'):
                continue
            params = dict(self._effect_params(effect) or {})
            params['_op'] = resolved
            return params
        return None

    def _bounce_prepare_count(self, player_id: int, card: Optional[CardInstance], params: dict) -> int:
        """How many bounce targets to draw in advance for this play."""
        if card is None or not isinstance(params, dict):
            return 0
        layers = clamp_card_layer(getattr(card, 'fission_level', 1))
        if params.get('bounces_from_positive_hits'):
            count = layers * self._card_total_hits(card, max(1, self._eval_int(player_id, params.get('hits', 1), card, 1)))
        else:
            bounces = max(0, self._eval_int(player_id, params.get('bounces', params.get('repeats', 0)), card, 0))
            count = bounces * (layers if params.get('scale_bounces_by_fission', True) else 1)
        return max(0, int(count))

    def _prepare_bounce_targets(self, player_id: int, card: Optional[CardInstance],
                                choice: Optional[dict]) -> Optional[dict]:
        """Pre-draw the non-repeating bounce target sequence of this play."""
        params = self._bounce_params_for_card(card)
        if not params:
            return choice
        updated = dict(choice or {})
        if not isinstance(updated.get('_bounce_targets'), list):
            prepared = None
            for legacy_key in ('_desert_marble_targets', '_arctic_ricochet_targets'):
                candidate = updated.get(legacy_key)
                if isinstance(candidate, list) and candidate:
                    # A picker (or older code) already chose the sequence.
                    prepared = list(candidate)
                    break
            if prepared is None:
                primary_target = self._choice_target_from_choice(updated, -1)
                prepared = self._random_nonrepeating_attack_targets(
                    player_id,
                    self._bounce_prepare_count(player_id, card, params),
                    primary_target,
                )
            updated['_bounce_targets'] = prepared
        card._bounce_cursor = 0
        card._bounce_previous_target = self._choice_target_from_choice(updated, -1)
        return updated

    def _prepare_desert_play_state(self, player_id: int, card: Optional[CardInstance],
                                   choice: Optional[dict]) -> Optional[dict]:
        self._prepare_desert_citron_play_flags(player_id, card)
        choice = self._prepare_desert_marble_targets(player_id, card, choice)
        return self._prepare_arctic_ricochet_targets(player_id, card, choice)

    def _desert_marble_target_ids(self, card: Optional[CardInstance],
                                  choice: Optional[dict]) -> List[int]:
        if self._declared_secondary_target_key(card) != '_desert_marble_targets' or not isinstance(choice, dict):
            return []
        result = []
        for raw_target_id in choice.get('_desert_marble_targets', []):
            try:
                target_id = int(raw_target_id)
            except Exception:
                continue
            if 0 <= target_id < len(self.players) and target_id not in result:
                result.append(target_id)
        return result

    def _declared_secondary_target_key(self, card: Optional[CardInstance]) -> str:
        """The choice key this card's declared bounce op stores its secondary
        target list under (data: ``secondary_target_key``).

        Round 6a: the response pipeline used to recognise "this is the Marble"
        by card id; the play op now names the key it owns (a card that declares
        no key simply owns none).
        """
        params = self._bounce_params_for_card(card)
        if not params:
            return ''
        return str(params.get('secondary_target_key') or '')

    def _arctic_ricochet_target_ids(self, card: Optional[CardInstance],
                                    choice: Optional[dict]) -> List[int]:
        if self._arctic_ricochet_repeat_count(0, card) <= 0 or not isinstance(choice, dict):
            return []
        result = []
        for raw_target_id in choice.get('_arctic_ricochet_targets', []):
            try:
                target_id = int(raw_target_id)
            except (TypeError, ValueError):
                continue
            if 0 <= target_id < len(self.players) and target_id not in result:
                result.append(target_id)
        return result

    def _secondary_attack_target_ids(self, card: Optional[CardInstance],
                                     choice: Optional[dict]) -> List[int]:
        result: List[int] = []
        for target_id in [
            *self._desert_marble_target_ids(card, choice),
            *self._arctic_ricochet_target_ids(card, choice),
            *self._bounce_target_ids(card, choice),
        ]:
            if target_id not in result:
                result.append(target_id)
        return result

    def _bounce_target_ids(self, card: Optional[CardInstance],
                           choice: Optional[dict]) -> List[int]:
        """Prepared bounce targets of a ``ricochet_attack`` play."""
        if not self._bounce_params_for_card(card) or not isinstance(choice, dict):
            return []
        raw_targets = None
        for key in ('_bounce_targets', '_arctic_ricochet_targets', '_desert_marble_targets'):
            candidate = choice.get(key)
            if isinstance(candidate, list) and candidate:
                raw_targets = candidate
                break
        if raw_targets is None:
            return []
        result: List[int] = []
        for raw_target_id in raw_targets:
            try:
                target_id = int(raw_target_id)
            except (TypeError, ValueError):
                continue
            if 0 <= target_id < len(self.players) and target_id not in result:
                result.append(target_id)
        return result

    def _wide_strike_target_ids(self, player_id: int, card: Optional[CardInstance]) -> List[int]:
        snapshot = getattr(self, '_card_resolution_target_snapshot', None)
        if (
            isinstance(snapshot, dict)
            and int(getattr(self, '_card_resolution_depth', 0) or 0) > 0
            and snapshot.get('player_id') == player_id
            and snapshot.get('card_instance_id') == getattr(card, 'instance_id', None)
            and isinstance(snapshot.get('wide_targets'), list)
        ):
            return [
                int(target_id) for target_id in snapshot['wide_targets']
                if isinstance(target_id, int) and 0 <= target_id < len(self.players)
            ]
        flags = self._effective_card_flags(card)
        allow_self = 'self_target' in flags
        targets: List[int] = []
        for tid in range(len(getattr(self, 'players', []) or [])):
            if tid == player_id and not allow_self:
                continue
            if self._target_can_be_selected(player_id, tid, allow_self=allow_self):
                targets.append(tid)
        return targets

    def _event_relation_matches(self, listener_owner: int, actor_id: int, relation: str) -> bool:
        relation = str(relation or 'any')
        if relation in ('any', 'all', 'both'):
            return 0 <= actor_id < len(self.players)
        if relation in ('self', 'owner'):
            return actor_id == listener_owner
        if relation in ('teammate', 'ally'):
            return self._same_timer_side(listener_owner, actor_id) and actor_id != listener_owner
        if relation in ('friendly', 'same_side'):
            return self._same_timer_side(listener_owner, actor_id)
        if relation == 'enemy':
            return self._opposite_timer_side(listener_owner, actor_id)
        return False

    def _event_wrapper_matches(self, owner_id: int, event_name: str, params: dict,
                               extra_context: Optional[dict]) -> bool:
        context = extra_context or {}
        relation = str(params.get('relation', 'any') or 'any')
        actor_id = int(context.get('source_id', owner_id))
        if event_name == 'equipment_destroyed':
            actor_id = int(context.get('target_id', actor_id))
        if event_name == 'player_stat_changed':
            actor_id = int(context.get('target_id', actor_id))
        if not self._event_relation_matches(owner_id, actor_id, relation):
            return False
        if event_name == 'card_used':
            expected_type = str(params.get('card_type', 'any') or 'any')
            actual_type = str(context.get('event_card_type', '') or '')
            if expected_type != 'any' and actual_type != expected_type:
                return False
        if event_name == 'resource_spent':
            expected_resource = str(params.get('resource', 'elixir') or 'elixir')
            actual_resource = str(context.get('resource', '') or '')
            if expected_resource != actual_resource:
                return False
            threshold = max(1, self._eval_int(owner_id, params.get('amount', 1), None, 1))
            if int(context.get('amount', 0) or 0) < threshold:
                return False
        if event_name == 'player_stat_changed':
            expected_prop = str(params.get('property', 'health') or 'health')
            actual_prop = str(context.get('property', '') or '')
            if expected_prop != actual_prop:
                return False
            expected_dir = str(params.get('direction', 'change') or 'change')
            actual_dir = str(context.get('direction', 'change') or 'change')
            if expected_dir != 'change' and expected_dir != actual_dir:
                return False
        return True

    def _resource_event_repeat_count(self, owner_id: int, params: dict, extra_context: Optional[dict]) -> int:
        if not extra_context:
            return 1
        amount = int(extra_context.get('amount', 0) or 0)
        threshold = max(1, self._eval_int(owner_id, params.get('amount', 1), None, 1))
        return max(1, amount // threshold)

    def _iter_event_listener_cards(self):
        seen = set()
        for owner_id, ps in enumerate(self.players):
            for eq in list(getattr(ps, 'equipment', [])):
                if not self._non_stack_equipment_is_active(eq):
                    continue
                card_obj = getattr(eq, 'card_instance', None)
                iid = getattr(card_obj, 'instance_id', None)
                if card_obj is not None and iid not in seen:
                    seen.add(iid)
                    yield owner_id, card_obj, eq
            for card_obj in list(getattr(ps, 'hand', [])):
                iid = getattr(card_obj, 'instance_id', None)
                if card_obj is not None and iid not in seen:
                    seen.add(iid)
                    yield owner_id, card_obj, None

    def _dispatch_card_event(self, event_name: str, source_id: int, event_card: Optional[CardInstance] = None,
                             target_id: Optional[int] = None, equipment: Optional[EquipmentInstance] = None,
                             equipment_owner_id: Optional[int] = None, choice: Optional[dict] = None,
                             extra_context: Optional[dict] = None):
        self._consume_action_work()
        try:
            card_user_id = int(source_id)
        except (TypeError, ValueError):
            card_user_id = -1
        if event_name == 'card_used' and event_card is not None and 0 <= card_user_id < len(self.players):
            ps = self.players[card_user_id]
            ps.achievement_total_card_plays = max(
                0,
                int(getattr(ps, 'achievement_total_card_plays', 0) or 0),
            ) + 1
        event_card_id = getattr(event_card, 'instance_id', None)
        context = {
            'source_id': source_id,
            'target_id': source_id if target_id is None else target_id,
            'event_card': event_card,
            'event_choice': dict(choice or {}) if isinstance(choice, dict) else {},
            'event_card_instance_id': event_card_id,
            'event_card_def_id': getattr(event_card, 'def_id', ''),
            'event_card_type': getattr(event_card, 'card_type', getattr(getattr(event_card, 'card_def', None), 'card_type', '')),
            'event_card_cost_e': int(getattr(event_card, '_paid_e_this_play', getattr(event_card, 'cost_e', 0)) or 0) if event_card is not None else 0,
            'event_card_cost_m': int(getattr(event_card, '_paid_m_this_play', getattr(event_card, 'cost_m', 0)) or 0) if event_card is not None else 0,
        }
        if equipment is not None:
            context['selected_equipment_instance_id'] = getattr(getattr(equipment, 'card_instance', None), 'instance_id', None)
            context['selected_equipment_owner_id'] = equipment_owner_id if equipment_owner_id is not None else source_id
        if isinstance(extra_context, dict):
            context.update(extra_context)
        for owner_id, listener_card, _ in list(self._iter_event_listener_cards()):
            self._consume_action_work(2)
            if getattr(listener_card, 'instance_id', None) == event_card_id:
                continue
            if not self._has_card_event(listener_card.card_def, event_name):
                continue
            listener_context = dict(context)
            listener_eq = self._find_equipment_for_card(owner_id, listener_card)
            if listener_eq is not None:
                listener_context['selected_equipment_instance_id'] = listener_eq.card_instance.instance_id
                listener_context['selected_equipment_owner_id'] = owner_id
            self._run_card_event(owner_id, listener_card, event_name, choice, listener_context)
        if event_name == 'card_used' and event_card is not None:
            # Compatibility: games saved before the snowball conversion still
            # carry ``arctic_snowballs`` registrations.
            self._arctic_trigger_snowballs_after_play(card_user_id, event_card)
            self._run_play_listeners(card_user_id, event_card)
            self._bio_after_card_used(card_user_id, event_card, int(context.get('target_id', card_user_id)), choice)
            from formal_logic_runtime import finalize_card_used as formal_logic_finalize_card_used
            formal_logic_finalize_card_used(self, card_user_id, event_card)
        elif event_name == 'equipment_triggered' and event_card is not None:
            from formal_logic_runtime import on_equipment_triggered as formal_logic_equipment_triggered
            formal_logic_equipment_triggered(self, card_user_id, event_card)

    def _has_fatal_prevention(self, player_id: int) -> bool:
        if not (0 <= player_id < len(self.players)):
            return False
        ps = self.players[player_id]
        if ps.invincible or (ps.bandage_active and not self._is_status_immune(player_id)):
            return True
        for card in list(ps.hand):
            for effect in getattr(card.card_def, 'effects', []) or []:
                if not isinstance(effect, dict):
                    continue
                effect_params = effect.get('params', {}) or {}
                if self._fatal_declaration_kind(effect.get('type'), effect_params) == self.FATAL_EXILE:
                    return True
        return False

    TRACKED_PLAYER_STATS = (
        'health', 'max_health', 'elixir', 'max_elixir', 'magic', 'max_magic',
        'armor', 'dodge', 'poison', 'fire', 'toxic',
        'equipment_protection', 'hand_limit',
    )

    def _snapshot_player_stats(self):
        return [
            {prop: self._get_player_property_value(pid, prop) for prop in self.TRACKED_PLAYER_STATS}
            for pid in range(len(self.players))
        ]

    def _dispatch_player_stat_changes(self, before, source_id: int, source_card: Optional[CardInstance] = None):
        if not before:
            return
        depth = int(getattr(self, '_stat_change_event_depth', 0))
        if depth >= 4:
            return
        self._stat_change_event_depth = depth + 1
        try:
            for pid in range(min(len(before), len(self.players))):
                for prop, old_value in before[pid].items():
                    new_value = self._get_player_property_value(pid, prop)
                    if new_value == old_value:
                        continue
                    direction = 'increase' if new_value > old_value else 'decrease'
                    self._dispatch_card_event(
                        'player_stat_changed',
                        source_id,
                        source_card,
                        target_id=pid,
                        extra_context={
                            'property': prop,
                            'old_value': old_value,
                            'new_value': new_value,
                            'delta': new_value - old_value,
                            'direction': direction,
                        },
                    )
        finally:
            self._stat_change_event_depth = depth

    def _declared_aura_elixir_bonus(self, equipment, owner_id: int) -> int:
        """Round 32 / 批次 AA：``aura_enemy_elixir_recovery`` 声明的合计数值。

        旧声明写法是 ``{"type":"aura_enemy_elixir_recovery","params":{"amount":N}}``；
        新写法是 ``{"op":"resource_op","mode":"aura_recovery","amount":N}``。
        两种都读、逐条累加（旧实现就是累加），未声明时是 ``0``。
        """

        card_def = getattr(equipment, 'card_def', None)
        card_instance = getattr(equipment, 'card_instance', None)
        total = 0
        for effect in getattr(card_def, 'effects', None) or []:
            if not isinstance(effect, dict):
                continue
            params = effect.get('params') if isinstance(effect.get('params'), dict) else {}
            eff_type = effect.get('type')
            if eff_type == 'aura_enemy_elixir_recovery':
                total += self._eval_int(owner_id, params.get('amount', 0), card_instance)
            elif eff_type == 'resource_op' and str(params.get('mode') or '').strip().lower() in (
                'aura', 'aura_recovery', 'aura_enemy_elixir_recovery',
            ):
                total += self._eval_int(
                    owner_id, params.get('amount', params.get('delta', 0)), card_instance,
                )
        return total

    def _spend_resource(self, player_id: int, resource: str, amount: int, source_card: Optional[CardInstance] = None) -> int:
        if not (0 <= player_id < len(self.players)):
            return 0
        amount = max(0, int(amount or 0))
        if amount <= 0:
            return 0
        ps = self.players[player_id]
        attr = 'magic' if resource == 'magic' else 'elixir'
        before = self._snapshot_player_stats()
        actual = min(amount, int(getattr(ps, attr, 0)))
        setattr(ps, attr, max(0, int(getattr(ps, attr, 0)) - amount))
        if actual > 0:
            self._dispatch_card_event(
                'resource_spent',
                player_id,
                source_card,
                target_id=player_id,
                extra_context={'resource': attr, 'amount': actual},
            )
        self._dispatch_player_stat_changes(before, player_id, source_card)
        return actual

    def _equipment_trigger_max_uses(self, eq: EquipmentInstance) -> int:
        if eq is None:
            return 0
        events = getattr(eq.card_def, 'v2_events', None)
        if isinstance(events, dict):
            event_def = events.get('on_equipment_trigger')
            if isinstance(event_def, dict):
                value = event_def.get('max_uses_per_turn', event_def.get('max_uses', 0))
                try:
                    return max(0, int(value or 0))
                except Exception:
                    return 0
        for effect in getattr(eq.card_def, 'effects', []) or []:
            if not isinstance(effect, dict) or effect.get('type') != 'on_equipment_trigger':
                continue
            params = effect.get('params', {}) or {}
            value = params.get('max_uses_per_turn', params.get('max_uses', 0))
            try:
                return max(0, int(value or 0))
            except Exception:
                return 0
        return 0

    def _event_requirement_matches(self, requirement, context: dict) -> bool:
        """Evaluate a data declared event filter (``events.<hook>.require``).

        The block lists context fields that must match before the hook runs, for
        example ``{"damage_kind": "attack", "damage_type": "physical",
        "min_damage": 1}``.  Cards own their trigger conditions instead of the
        engine listing their names.
        """
        if not isinstance(requirement, dict) or not requirement:
            return True
        context = context if isinstance(context, dict) else {}
        for key, expected in requirement.items():
            if key == 'min_damage':
                actual_damage = int(context.get('damage_amount', context.get('damage', 0)) or 0)
                try:
                    if actual_damage < int(expected):
                        return False
                except (TypeError, ValueError):
                    return False
                continue
            actual = context.get(key)
            if isinstance(expected, (list, tuple, set)):
                if actual not in expected:
                    return False
            elif str(actual if actual is not None else '') != str(expected):
                return False
        return True

    def _run_card_event(self, owner_id: int, card: CardInstance, event_name: str,
                        choice: Optional[dict] = None, extra_context: Optional[dict] = None) -> bool:
        equipped = self._find_equipment_for_card(owner_id, card)
        if equipped is not None and not self._equipment_runtime_active(equipped):
            return False
        v2_event_name = f'on_{event_name}'
        event_def = self._get_v2_event_def(card.card_def, v2_event_name)
        if isinstance(event_def, dict) and event_def.get('require'):
            if not self._event_requirement_matches(event_def.get('require'), extra_context or {}):
                return False
        if event_def:
            if not self._claim_turn_boundary_card_event(owner_id, card, event_name, extra_context):
                return True
            self._run_v2_card_event(owner_id, card, v2_event_name, choice, extra_context)
            return True
        if self._has_script_entry(card.card_def, event_name):
            effects = self._get_script_effects(card.card_def, event_name)
            if not effects:
                return False
            if not self._claim_turn_boundary_card_event(owner_id, card, event_name, extra_context):
                return True
            self._run_effect_list(
                owner_id,
                card,
                effects,
                choice,
                {'event': event_name, **(extra_context or {})},
            )
            return True
        event_type = f'on_{event_name}'
        matching_effects = []
        for effect in card.card_def.effects or []:
            if not isinstance(effect, dict) or effect.get('type') != event_type:
                continue
            params = effect.get('params', {}) or {}
            if self._event_wrapper_matches(owner_id, event_name, params, extra_context):
                matching_effects.append((effect, params))
        if not matching_effects:
            return False
        if not self._claim_turn_boundary_card_event(owner_id, card, event_name, extra_context):
            return True
        ran = False
        for effect, params in matching_effects:
            if event_type == 'on_equipment_trigger' and params.get('destroy_self'):
                eq = self._find_equipment_for_card(owner_id, card)
                if eq is not None and not self._destroy_equipment(owner_id, eq):
                    ran = True
                    continue
            repeat_count = self._resource_event_repeat_count(owner_id, params, extra_context) if event_name == 'resource_spent' else 1
            for repeat_index in range(repeat_count):
                self._run_effect_list(
                    owner_id,
                    card,
                    params.get('effects', []),
                    choice,
                    {'event': event_name, 'repeat_index': repeat_index + 1, **(extra_context or {}), 'listener_owner_id': owner_id},
                )
            ran = True
        return ran

    def _run_zone_owner_turn_start_events(self, player_id: int):
        if not (0 <= player_id < len(self.players)):
            return
        ps = self.players[player_id]
        for zone_name, event_name in (
            ('hand', 'hand_owner_turn_start'),
            ('discard', 'discard_owner_turn_start'),
            ('deck', 'deck_owner_turn_start'),
        ):
            zone = getattr(ps, zone_name, [])
            for zone_card in list(zone):
                if zone_card in zone and self._has_card_event(zone_card.card_def, event_name):
                    self._run_card_event(player_id, zone_card, event_name, None,
                                         {'source_id': player_id, 'target_id': player_id, 'zone': zone_name})

    def _run_hand_owner_turn_end_events(self, player_id: int):
        if not (0 <= player_id < len(self.players)):
            return
        ps = self.players[player_id]
        for zone_card in list(ps.hand):
            if zone_card in ps.hand and self._has_card_event(zone_card.card_def, 'hand_owner_turn_end'):
                self._run_card_event(player_id, zone_card, 'hand_owner_turn_end', None,
                                     {'source_id': player_id, 'target_id': player_id, 'zone': 'hand'})

    def _turn_boundary_processed_count(self) -> int:
        processed = getattr(self, '_turn_boundary_processed_sources', None)
        return len(processed) if isinstance(processed, set) else 0

    def _drain_turn_end_event_sources(self, player_id: int):
        if not bool(getattr(self, '_turn_boundary_active', False)):
            return
        for _ in range(64):
            before = self._turn_boundary_processed_count()
            self._trigger_v2_status_events_for_player(player_id, 'on_turn_end', {'player_id': player_id})
            self._run_hand_owner_turn_end_events(player_id)
            self._run_owner_turn_end_equipment(player_id)
            if (
                self.game_over
                or self.pending_choice is not None
                or getattr(self, 'pending_v2_ui', None)
            ):
                return
            if self._turn_boundary_processed_count() <= before:
                return

    def _drain_turn_start_event_sources(self, player_id: int):
        if not bool(getattr(self, '_turn_boundary_active', False)):
            return
        for _ in range(64):
            before = self._turn_boundary_processed_count()
            self._trigger_v2_status_events_for_player(player_id, 'on_turn_start', {'player_id': player_id})
            self._run_zone_owner_turn_start_events(player_id)
            self._run_timed_effects_for_turn(player_id)
            self._run_timed_effects_for_turn(player_id, 'after_status_clear')
            for owner_id, owner_state in enumerate(self.players):
                for eq in list(getattr(owner_state, 'equipment', []) or []):
                    if self._has_card_event(eq.card_def, 'any_turn_start'):
                        self._run_card_event(
                            owner_id,
                            eq.card_instance,
                            'any_turn_start',
                            None,
                            {'source_id': owner_id, 'target_id': player_id},
                        )
            if hasattr(self, 'get_all_enemies'):
                enemy_ids = list(self.get_all_enemies(player_id))
            else:
                enemy_ids = [1 - player_id] if len(self.players) == 2 else []
            for enemy_id in enemy_ids:
                if not (0 <= enemy_id < len(self.players)):
                    continue
                for eq in list(getattr(self.players[enemy_id], 'equipment', []) or []):
                    if self._has_card_event(eq.card_def, 'enemy_turn_start'):
                        self._run_card_event(
                            enemy_id,
                            eq.card_instance,
                            'enemy_turn_start',
                            None,
                            {'source_id': enemy_id, 'target_id': player_id},
                        )
            for owner_id, eq in list(self._iter_equipment_targeting_player(player_id)):
                effect_target_id = getattr(eq, 'effect_target', owner_id)
                if not isinstance(effect_target_id, int) or not (0 <= effect_target_id < len(self.players)):
                    effect_target_id = player_id
                context = {
                    'source_id': owner_id,
                    'target_id': effect_target_id,
                    'current_equipment': eq,
                    'selected_equipment_instance_id': getattr(eq.card_instance, 'instance_id', None),
                    'selected_equipment_owner_id': owner_id,
                }
                if self._has_card_event(eq.card_def, 'target_turn_start'):
                    self._run_card_event(owner_id, eq.card_instance, 'target_turn_start', None, context)
                if self._has_card_event(eq.card_def, 'owner_turn_start'):
                    self._run_card_event(owner_id, eq.card_instance, 'owner_turn_start', None, context)
            if (
                self.game_over
                or self.pending_choice is not None
                or getattr(self, 'pending_v2_ui', None)
            ):
                return
            if self._turn_boundary_processed_count() <= before:
                return

    def _equipment_turn_start_key(self, eq) -> int:
        return int(getattr(getattr(eq, 'card_instance', None), 'instance_id', id(eq)) or id(eq))

    def _effect_tree_contains_heal(self, value, depth: int = 0) -> bool:
        if depth > 16:
            return False
        if isinstance(value, dict):
            op = str(value.get('op') or value.get('type') or '').strip()
            if op == 'heal':
                return True
            return any(self._effect_tree_contains_heal(v, depth + 1) for v in value.values())
        if isinstance(value, (list, tuple)):
            return any(self._effect_tree_contains_heal(item, depth + 1) for item in value)
        return False

    def _owner_turn_start_equipment_heals(self, eq) -> bool:
        if eq is None:
            return False
        card_def = getattr(eq, 'card_def', None)
        if card_def is None:
            return False
        events = getattr(card_def, 'v2_events', None)
        if isinstance(events, dict) and self._effect_tree_contains_heal(events.get('on_owner_turn_start')):
            return True
        for effect in getattr(card_def, 'effects', []) or []:
            if isinstance(effect, dict) and effect.get('type') == 'on_owner_turn_start':
                if self._effect_tree_contains_heal(effect):
                    return True
        if self._has_script_entry(card_def, 'owner_turn_start'):
            return self._effect_tree_contains_heal(self._get_script_effects(card_def, 'owner_turn_start'))
        return False

    def _iter_equipment_targeting_player(self, player_id: int):
        for owner_id, owner_state in enumerate(self.players):
            for eq in list(getattr(owner_state, 'equipment', [])):
                if not self._non_stack_equipment_is_active(eq):
                    continue
                try:
                    effect_target = int(getattr(eq, 'effect_target', owner_id))
                except (TypeError, ValueError):
                    effect_target = owner_id
                if effect_target == player_id:
                    yield owner_id, eq

    def _decay_poison_after_turn_start(self, player_id: int):
        if not (0 <= player_id < len(self.players)):
            return
        ps = self.players[player_id]
        if ps.poison <= 0:
            return
        if getattr(ps, 'stagnation', 0) > 0 and not self._is_status_immune(player_id):
            self.log_msg(f"{self.pn(player_id)}的滞留使中毒未减半")
            return
        ps.poison = ps.poison // 2
        if ps.poison > 0:
            self.log_msg(f"{self.pn(player_id)}中毒减半为{ps.poison}层")

    def _apply_toxic_poison_after_poison_settlement(self, player_id: int):
        if not (0 <= player_id < len(self.players)) or self._is_status_immune(player_id):
            return
        from engine_runtime_support import effective_toxic_poison
        amount = effective_toxic_poison(self, player_id)
        if amount <= 0:
            return
        ps = self.players[player_id]
        ps.poison += amount
        self._normalize_status_value(ps, 'poison')
        self.log_msg(f"{self.pn(player_id)}的剧毒施加{amount}层中毒")

    def _decay_end_turn_layer_statuses(self, player_id: int):
        if not (0 <= player_id < len(self.players)):
            return
        ps = self.players[player_id]
        for attr, label in (('stagnation', '滞留'),):
            value = int(getattr(ps, attr, 0) or 0)
            if value <= 0:
                continue
            value = max(0, value - 1)
            setattr(ps, attr, value)
            if value == 0:
                self.log_msg(f"{self.pn(player_id)}的{label}效果消失")

    def _player_choices_are_uncancellable(self, player_id: int) -> bool:
        """Blindness makes every card choice of that player impossible to cancel."""
        if not (0 <= player_id < len(self.players)):
            return False
        if self._is_status_immune(player_id):
            return False
        try:
            blind = max(0, int(getattr(self.players[player_id], 'blind', 0) or 0))
        except (TypeError, ValueError):
            blind = 0
        return blind > 0

    def _decay_ocean_card_charge_turn_end(self, player_id: int):
        if not (0 <= player_id < len(self.players)):
            return
        ps = self.players[player_id]
        reduced = 0
        for card in list(getattr(ps, 'hand', []) or []):
            charge = int(getattr(card, 'charge_value', 0) or 0)
            if charge > 0:
                card.charge_value = max(0, charge - 1)
                reduced += 1
                if card.charge_value <= 0:
                    card.instance_flags.discard('charge')
        if reduced:
            self.log_msg(f"{self.pn(player_id)}的手牌电荷减少")

    def _clear_ocean_card_hand_blind_turn_end(self, player_id: int):
        if not (0 <= player_id < len(self.players)):
            return
        cleared = 0
        for card in list(getattr(self.players[player_id], 'hand', []) or []):
            if int(getattr(card, 'hand_blind_turns', 0) or 0) > 0:
                card.hand_blind_turns = 0
                card.instance_flags.discard('ocean_blinded')
                cleared += 1
        if cleared:
            self.log_msg(f"{self.pn(player_id)}的{cleared}张手牌蒙蔽消失")

    def _clear_turn_start_action_statuses(self, player_id: int):
        if not (0 <= player_id < len(self.players)):
            return
        ps = self.players[player_id]
        immune = self._is_status_immune(player_id)
        cleared = []
        for attr, label in (('blind', '失明'), ('dodge', '闪避')):
            value = int(getattr(ps, attr, 0) or 0)
            if value <= 0:
                continue
            if attr == 'blind' and ps.hand and not immune:
                random.shuffle(ps.hand)
                self.log_msg(f"{self.pn(player_id)}因失明打乱手牌")
            setattr(ps, attr, 0)
            cleared.append(label)
        if cleared:
            self.log_msg(f"{self.pn(player_id)}的{ '、'.join(cleared) }效果清除")

    def _clear_sluggish_after_draw(self, player_id: int):
        if not (0 <= player_id < len(self.players)):
            return
        ps = self.players[player_id]
        if int(getattr(ps, 'sluggish', 0) or 0) <= 0:
            return
        ps.sluggish = 0
        self.log_msg(f"{self.pn(player_id)}的迟缓效果清除")

    def _return_cogwheel_cards_now(self, player_id: int):
        """齿轮收牌例程（Round 41 / 批次 AE-5：开关与排除实例改读玩家变量）。

        开关/排除实例全部来自卡数据写下的 ``custom_vars``：
        ``cogwheel_active``（真值 = 本回合启用这一条例程）与
        ``cogwheel_exclude_instance_id``（本次不回收的实例 id，通常是齿轮自己）。
        收完即把两个变量清空，行为与旧的引擎级 ``_cogwheel_active``
        （一次性开关）逐条一致。
        """
        if not (0 <= player_id < len(self.players)):
            return
        ps = self.players[player_id]
        custom_vars = getattr(ps, 'custom_vars', None)
        if not isinstance(custom_vars, dict):
            return
        if not custom_vars.get('cogwheel_active'):
            return
        try:
            exclude_id = int(custom_vars.get('cogwheel_exclude_instance_id', -1) or -1)
        except (TypeError, ValueError):
            exclude_id = -1
        exclude_def_id = ''
        for zone in (getattr(ps, 'hand', []), getattr(ps, 'discard', []), getattr(ps, 'exile', [])):
            for c in list(zone or []):
                try:
                    if int(getattr(c, 'instance_id', -1) or -1) == exclude_id:
                        exclude_def_id = str(getattr(c, 'def_id', '') or '')
                        break
                except Exception:
                    continue
            if exclude_def_id:
                break
        played_ids = list(getattr(ps, 'cards_played_this_turn_instance_ids', []) or [])
        returned = []
        for instance_id in played_ids:
            try:
                iid = int(instance_id)
            except Exception:
                continue
            if iid == exclude_id:
                continue
            found = None
            source_zone = None
            for zone in (getattr(ps, 'deck', []), getattr(ps, 'discard', [])):
                for c in list(zone):
                    if int(getattr(c, 'instance_id', -1) or -1) == iid:
                        found = c
                        source_zone = zone
                        break
                if found is not None:
                    break
            if found is None:
                continue
            if not self._card_selectable_by_action(found):
                continue
            if self._card_has_flag(found, 'excluded_from_cogwheel_return'):
                continue
            if exclude_def_id and str(getattr(found, 'def_id', '') or '') == exclude_def_id:
                continue
            if not ps.can_add_to_hand():
                continue
            source_zone.remove(found)
            found.mimic_discount = 0
            found.instance_flags.add('symbiosis')
            ps.add_to_hand(found)
            returned.append(found.name_cn)
        # 一次性开关：收完就清空玩家变量（与旧 ``_cogwheel_active[id] = False`` 等价，
        # 但不会在 ``custom_vars`` 里留下长期残留，A/B 状态摘要因此保持一致）。
        custom_vars.pop('cogwheel_active', None)
        custom_vars.pop('cogwheel_exclude_instance_id', None)
        if returned:
            self.log_msg(f"{self.pn(player_id)}的齿轮效果：{len(returned)}张牌回到手中并获得共生")

    def _effect_tree_contains_action_status(self, value, depth: int = 0) -> bool:
        if depth > 30:
            return False
        action_statuses = {
            'sluggish', '迟缓', 'foresight', '预知', 'blind', '失明',
            'stunned', 'dizzy', 'skip_turn', '眩晕', 'attack_blocked', '禁攻',
            'attack_only', '仅攻击', 'magic_blocked', '魔力封锁',
        }
        if isinstance(value, dict):
            op = str(value.get('op') or value.get('type') or '')
            status = value.get('status') or value.get('name') or value.get('id')
            if op == 'electric_web_arm':
                return True
            if op in ('status_add_named', 'set_status_named') and str(status) in action_statuses:
                return True
            return any(self._effect_tree_contains_action_status(v, depth + 1) for v in value.values())
        if isinstance(value, list):
            return any(self._effect_tree_contains_action_status(v, depth + 1) for v in value)
        return False

    def _owner_turn_start_equipment_action_statuses(self, eq) -> bool:
        card_def = getattr(eq, 'card_def', None)
        if card_def is None:
            return False
        events = getattr(card_def, 'v2_events', None)
        if isinstance(events, dict) and self._effect_tree_contains_action_status(events.get('on_owner_turn_start')):
            return True
        for effect in getattr(card_def, 'effects', []) or []:
            if isinstance(effect, dict) and effect.get('type') == 'on_owner_turn_start':
                if self._effect_tree_contains_action_status(effect):
                    return True
        if self._has_script_entry(card_def, 'owner_turn_start'):
            return self._effect_tree_contains_action_status(self._get_script_effects(card_def, 'owner_turn_start'))
        return False

    def _run_owner_turn_start_action_status_equipment(self, player_id: int) -> set:
        handled = set()
        for owner_id, eq in self._iter_equipment_targeting_player(player_id):
            if not self._owner_turn_start_equipment_action_statuses(eq):
                continue
            key = self._equipment_turn_start_key(eq)
            if key in handled:
                continue
            eq.turns_equipped += 1
            handled.add(key)
            if self._has_card_event(eq.card_def, 'owner_turn_start'):
                self._run_card_event(owner_id, eq.card_instance, 'owner_turn_start', None,
                                     {'source_id': owner_id, 'target_id': player_id})
        return handled

    def _run_owner_turn_start_healing_equipment(self, player_id: int) -> set:
        if not (0 <= player_id < len(self.players)):
            return set()
        ps = self.players[player_id]
        handled = set()
        for owner_id, eq in self._iter_equipment_targeting_player(player_id):
            if not self._owner_turn_start_equipment_heals(eq):
                continue
            key = self._equipment_turn_start_key(eq)
            if key in handled:
                continue
            eq.turns_equipped += 1
            handled.add(key)
            if self._has_card_event(eq.card_def, 'owner_turn_start') and self._run_card_event(
                    owner_id, eq.card_instance, 'owner_turn_start', None,
                    {'source_id': owner_id, 'target_id': player_id}):
                continue
        return handled

    def _run_magic_yucca_pre_draw_equipment(self, player_id: int) -> set:
        if not (0 <= player_id < len(self.players)):
            return set()
        handled = set()
        for owner_id, eq in self._iter_equipment_targeting_player(player_id):
            if 'early_owner_turn_start' not in self._effective_card_flags(getattr(eq, 'card_instance', None)):
                continue
            key = self._equipment_turn_start_key(eq)
            if key in handled:
                continue
            eq.turns_equipped += 1
            handled.add(key)
            effect_target_id = int(getattr(eq, 'effect_target', owner_id))
            if not (0 <= effect_target_id < len(self.players)):
                effect_target_id = player_id
            if self._has_card_event(eq.card_def, 'owner_turn_start'):
                self._run_card_event(owner_id, eq.card_instance, 'owner_turn_start', None,
                                     {'source_id': owner_id, 'target_id': effect_target_id})
        return handled

    def _apply_turn_start_effects(self, player_id: int):
        ps = self.players[player_id]
        self._decay_sealed_equipment_for_owner_turn(player_id)
        self._activate_pending_corruption()
        self._clear_forced_target_at_turn_start(player_id)
        opp_id = 1 - player_id
        opp = self.players[opp_id]
        self._save_turn_start_snapshot(player_id)
        self._antennae_reveal[player_id] = None
        self._reset_turn_damage_counters()
        self._run_v2_event_hooks('turn_start', {
            'source_player': player_id,
            'target_player': player_id,
            'vars': {'player_id': player_id},
            'current_action': {'player_id': player_id},
        })
        self._trigger_v2_status_events_for_player(player_id, 'on_turn_start', {'player_id': player_id})
        if self.game_over or getattr(self, 'pending_v2_ui', None):
            return
        self._apply_jungle_turn_start_statuses(player_id)
        self._run_zone_owner_turn_start_events(player_id)
        self._run_timed_effects_for_turn(player_id)
        untargetable_layers = max(0, int(getattr(ps, 'untargetable', 0) or 0))
        if untargetable_layers > 0:
            ps.untargetable = max(0, untargetable_layers - 1)
            if ps.untargetable <= 0:
                self.log_msg(f"{self.pn(player_id)}的不可选中效果结束")
        if ps.shovel_active:
            ps.shovel_active = False
        self._clear_turn_start_action_statuses(player_id)
        self._run_timed_effects_for_turn(player_id, 'after_status_clear')
        early_owner_turn_start_equipment = self._run_owner_turn_start_action_status_equipment(player_id)
        if self.game_over or getattr(self, 'pending_v2_ui', None):
            return
        early_owner_turn_start_equipment |= self._run_magic_yucca_pre_draw_equipment(player_id)
        if self.game_over or getattr(self, 'pending_v2_ui', None):
            return
        ocean_action_skip = int(ps.custom_vars.get('ocean_action_skip_turns', 0) or 0)
        skip_draw_recovery = ocean_action_skip > 0
        if skip_draw_recovery:
            ps.custom_vars['ocean_action_skip_turns'] = ocean_action_skip - 1
            self._skip_current_turn_after_start = True
        self._defer_turn_start_death_checks = True
        if self.round_num > 1 and not skip_draw_recovery:
            sluggish_reduction = ps.sluggish if not self._is_status_immune(player_id) else 0
            from formal_logic_runtime import consume_draw_reduction
            draw_count = max(0, DRAW_PER_TURN - sluggish_reduction - consume_draw_reduction(self, player_id))
            if self._queue_foresight_replace_choice(player_id, draw_count, 'turn_start_after_foresight'):
                self._pending_turn_start_early_owner_equipment = set(early_owner_turn_start_equipment)
                return
            drawn = self._draw_cards_with_v2_hooks(player_id, draw_count, 'turn_start')
            self.log_msg(f"{self.pn(player_id)}抽{len(drawn)}张牌")
            if sluggish_reduction > 0:
                self.log_msg(f"{self.pn(player_id)}的迟缓减少{min(sluggish_reduction, DRAW_PER_TURN)}张抽牌")
            self._clear_sluggish_after_draw(player_id)
            self._run_timed_effects_for_turn(player_id, 'after_turn_start_draw')
            self._run_target_turn_start_after_draw_equipment(player_id)
            if self.game_over or getattr(self, 'pending_v2_ui', None) or self.pending_choice is not None:
                self._defer_turn_start_death_checks = False
                return
        for owner_id, owner_state in enumerate(self.players):
            for eq in list(owner_state.equipment):
                if self._has_card_event(eq.card_def, 'any_turn_start'):
                    self._run_card_event(owner_id, eq.card_instance, 'any_turn_start', None,
                                         {'source_id': owner_id, 'target_id': player_id})
        for eq in list(opp.equipment):
            if self._has_card_event(eq.card_def, 'enemy_turn_start') and self._run_card_event(
                    opp_id, eq.card_instance, 'enemy_turn_start', None,
                    {'source_id': opp_id, 'target_id': player_id}):
                continue
        early_owner_turn_start_equipment |= self._run_owner_turn_start_healing_equipment(player_id)
        if self.game_over or getattr(self, 'pending_v2_ui', None):
            self._defer_turn_start_death_checks = False
            return
        self._hel_apply_blazing_fire_turn_start(player_id)
        if ps.poison > 0:
            if not self._is_status_immune(player_id):
                dmg = ps.poison
                self._deal_direct_damage(player_id, dmg, '中毒', damage_type=DAMAGE_TYPE_MAGIC, damage_tag=DAMAGE_TAG_POISON)
            self._decay_poison_after_turn_start(player_id)
            self._apply_toxic_poison_after_poison_settlement(player_id)
        if ps.fire > 0 and not self._is_status_immune(player_id):
            self._deal_direct_damage(player_id, ps.fire, '灼烧', damage_type=DAMAGE_TYPE_MAGIC, damage_tag=DAMAGE_TAG_FIRE)
        if self.round_num > 1 and not skip_draw_recovery:
            elixir_recovery = ELIXIR_RECOVERY
            from engine_runtime_support import declared_elixir_recovery_aura
            for eq in list(opp.equipment):
                elixir_recovery += self._declared_aura_elixir_bonus(eq, opp_id)
                aura = declared_elixir_recovery_aura(self, eq, opp_id)
                elixir_recovery += aura.elixir
                if aura.overload > 0:
                    ps.overload += aura.overload
                    self.log_msg(self._format_step_log(
                        aura.log or "{target}获得{amount}层超载",
                        target=self.pn(player_id),
                        amount=aura.overload,
                        player=self.pn(player_id),
                    ))
            elixir_recovery += self._opening_event_elixir_recovery_bonus(player_id)
            ps.gain_elixir(elixir_recovery)
            self.log_msg(f"{self.pn(player_id)}回复{elixir_recovery}E")
            self._bio_apply_debt_after_recovery(player_id)
        # Overload: deduct E at turn start, then clear
        if ps.overload > 0:
            if not self._is_status_immune(player_id):
                deduct = min(ps.overload, ps.elixir)
                ps.elixir -= deduct
                self.log_msg(f"{self.pn(player_id)}的超载扣除{deduct}E")
            ps.overload = 0
        for owner_state in self.players:
            for eq in getattr(owner_state, 'equipment', []):
                eq.uses_this_turn = 0
        for owner_id, eq in self._iter_equipment_targeting_player(player_id):
            eq_key = self._equipment_turn_start_key(eq)
            if eq_key not in early_owner_turn_start_equipment:
                eq.turns_equipped += 1
            else:
                continue
            effect_target_id = int(getattr(eq, 'effect_target', owner_id))
            if not (0 <= effect_target_id < len(self.players)):
                effect_target_id = player_id
            if self._has_card_event(eq.card_def, 'target_turn_start') and self._run_card_event(
                    owner_id, eq.card_instance, 'target_turn_start', None,
                    {'source_id': owner_id, 'target_id': effect_target_id}):
                continue
            if self._has_card_event(eq.card_def, 'owner_turn_start') and self._run_card_event(
                    owner_id, eq.card_instance, 'owner_turn_start', None,
                    {'source_id': owner_id, 'target_id': effect_target_id}):
                continue
        if not self.game_over:
            self._apply_jungle_turn_start_regen(player_id)
        self._drain_turn_start_event_sources(player_id)
        if self.pending_choice is not None or getattr(self, 'pending_v2_ui', None):
            return
        self._defer_turn_start_death_checks = False
        if ps.health <= 0:
            self._check_yggdrasil(player_id)
            self._check_game_over()

    def _queue_foresight_replace_choice(self, player_id: int, draw_count: int, resume_handler: str) -> bool:
        ps = self.players[player_id]
        if ps.foresight <= 0:
            return False
        if self._is_status_immune(player_id) or not ps.deck or not ps.hand:
            ps.foresight = 0
            self.log_msg(f"{self.pn(player_id)}的预知效果清除")
            return False
        select_limit = min(ps.foresight, len(ps.hand), len(ps.deck))
        if select_limit <= 0:
            ps.foresight = 0
            self.log_msg(f"{self.pn(player_id)}的预知效果清除")
            return False
        self._pending_foresight = {
            'player_id': player_id,
            'draw_count': draw_count,
            'select_limit': select_limit,
            'resume_handler': resume_handler,
        }
        self.pending_choice = {
            'player_id': player_id,
            'choice_type': 'foresight_replace',
            'card': None,
            'choice_params': {'max_count': select_limit},
            'hand_cards': [c.to_dict() for c in ps.hand],
            'max_replace': select_limit,
            'message': f'预知：选择最多{select_limit}张手牌丢弃，然后抽对应张牌',
        }
        return True

    def _resume_turn_start_after_foresight(self, player_id: int, foresight_result: Optional[dict] = None):
        ps = self.players[player_id]
        opp_id = 1 - player_id
        opp = self.players[opp_id]
        early_owner_turn_start_equipment = getattr(self, '_pending_turn_start_early_owner_equipment', set()) or set()
        self._pending_turn_start_early_owner_equipment = set()
        self._defer_turn_start_death_checks = True
        for owner_id, owner_state in enumerate(self.players):
            for eq in list(owner_state.equipment):
                if self._has_card_event(eq.card_def, 'any_turn_start'):
                    self._run_card_event(owner_id, eq.card_instance, 'any_turn_start', None,
                                         {'source_id': owner_id, 'target_id': player_id})
        for eq in list(opp.equipment):
            if self._has_card_event(eq.card_def, 'enemy_turn_start') and self._run_card_event(
                    opp_id, eq.card_instance, 'enemy_turn_start', None,
                    {'source_id': opp_id, 'target_id': player_id}):
                continue
        early_owner_turn_start_equipment |= self._run_owner_turn_start_healing_equipment(player_id)
        if self.game_over or getattr(self, 'pending_v2_ui', None):
            self._defer_turn_start_death_checks = False
            return
        self._hel_apply_blazing_fire_turn_start(player_id)
        if self.round_num > 1:
            from formal_logic_runtime import consume_draw_reduction
            draw_count = max(
                0,
                int((foresight_result or {}).get('draw_count', 0) or 0)
                - consume_draw_reduction(self, player_id),
            )
            drawn = self._draw_cards_with_v2_hooks(player_id, draw_count, 'turn_start')
            self.log_msg(f"{self.pn(player_id)}抽{len(drawn)}张牌")
            if ps.sluggish > 0 and not self._is_status_immune(player_id):
                self.log_msg(f"{self.pn(player_id)}的迟缓减少{min(ps.sluggish, DRAW_PER_TURN)}张抽牌")
            self._clear_sluggish_after_draw(player_id)
        if ps.poison > 0:
            if not self._is_status_immune(player_id):
                dmg = ps.poison
                self._deal_direct_damage(player_id, dmg, '中毒', damage_type=DAMAGE_TYPE_MAGIC, damage_tag=DAMAGE_TAG_POISON)
            self._decay_poison_after_turn_start(player_id)
            self._apply_toxic_poison_after_poison_settlement(player_id)
        if ps.fire > 0 and not self._is_status_immune(player_id):
            self._deal_direct_damage(player_id, ps.fire, '灼烧', damage_type=DAMAGE_TYPE_MAGIC, damage_tag=DAMAGE_TAG_FIRE)
        if self.round_num > 1:
            elixir_recovery = ELIXIR_RECOVERY
            from engine_runtime_support import declared_elixir_recovery_aura
            for eq in list(opp.equipment):
                elixir_recovery += self._declared_aura_elixir_bonus(eq, opp_id)
                aura = declared_elixir_recovery_aura(self, eq, opp_id)
                elixir_recovery += aura.elixir
                if aura.overload > 0:
                    ps.overload += aura.overload
                    self.log_msg(self._format_step_log(
                        aura.log or "{target}获得{amount}层超载",
                        target=self.pn(player_id),
                        amount=aura.overload,
                        player=self.pn(player_id),
                    ))
            elixir_recovery += self._opening_event_elixir_recovery_bonus(player_id)
            ps.gain_elixir(elixir_recovery)
            self.log_msg(f"{self.pn(player_id)}回复{elixir_recovery}E")
            self._bio_apply_debt_after_recovery(player_id)
        if ps.overload > 0:
            if not self._is_status_immune(player_id):
                deduct = min(ps.overload, ps.elixir)
                ps.elixir -= deduct
                self.log_msg(f"{self.pn(player_id)}的超载扣除{deduct}E")
            ps.overload = 0
        for owner_state in self.players:
            for eq in getattr(owner_state, 'equipment', []):
                eq.uses_this_turn = 0
        for owner_id, eq in self._iter_equipment_targeting_player(player_id):
            eq_key = self._equipment_turn_start_key(eq)
            if eq_key not in early_owner_turn_start_equipment:
                eq.turns_equipped += 1
            else:
                continue
            effect_target_id = int(getattr(eq, 'effect_target', owner_id))
            if not (0 <= effect_target_id < len(self.players)):
                effect_target_id = player_id
            if self._has_card_event(eq.card_def, 'owner_turn_start') and self._run_card_event(
                    owner_id, eq.card_instance, 'owner_turn_start', None,
                    {'source_id': owner_id, 'target_id': effect_target_id}):
                continue
        if not self.game_over:
            self._apply_jungle_turn_start_regen(player_id)
        self._drain_turn_start_event_sources(player_id)
        if self.pending_choice is not None or getattr(self, 'pending_v2_ui', None):
            return
        self._defer_turn_start_death_checks = False
        if ps.health <= 0:
            self._check_yggdrasil(player_id)
            self._check_game_over()
        if self.game_over:
            return
        if getattr(self, '_skip_current_turn_after_start', False):
            self._skip_current_turn_after_start = False
            self._clear_honey_control_state(player_id, include_pending=True)
            self.log_msg(f"{self.pn(player_id)}被魔法珊瑚影响，跳过本回合行动")
            self._end_player_turn(player_id)
            return
        if ps.forced_skip_turn > 0:
            ps.forced_skip_turn -= 1
            self._clear_honey_control_state(player_id, include_pending=True)
            self.log_msg(f"{self.pn(player_id)}被跳过本回合")
            self._end_player_turn(player_id)
            return
        if ps.skip_turn > 0 and self._is_status_immune(player_id):
            ps.skip_turn = max(0, int(ps.skip_turn) - 1)
        elif ps.skip_turn > 0:
            ps.skip_turn -= 1
            self._clear_honey_control_state(player_id, include_pending=True)
            self.log_msg(f"{self.pn(player_id)}被眩晕，跳过本回合！")
            self._end_player_turn(player_id)
            return
        if ps.health <= 0:
            self._check_yggdrasil(player_id)
            if ps.health <= 0:
                self._check_game_over()
                return
        from engine_runtime_support import queue_turn_start_choices
        if queue_turn_start_choices(self, player_id, '_bio_enter_player_action_phase'):
            return
        if self._bio_queue_dna_turn_start(player_id, '_bio_enter_player_action_phase'):
            return
        self._enter_player_action_phase(player_id)

    def deal_attack_damage(self, target_id: int, amount: int, hits: int = 1,
                           is_battery: bool = False, is_precision: bool = False,
                           attacker_id: int = -1,
                           source_card: Optional[CardInstance] = None,
                           ignore_untargetable: bool = False,
                           crit_bonus_multiplier: float = 1.0,
                           crit_bonus_damage: int = 0) -> int:
        if not isinstance(target_id, int):
            try:
                target_id = int(target_id)
            except Exception:
                return 0
        if not (0 <= target_id < len(self.players)):
            return 0
        hits = clamp_damage_hits(hits)
        if source_card is not None:
            self._clamp_card_layers(source_card)
        ps = self.players[target_id]
        if ps.health <= 0 and self._game_over_defer_depth <= 0:
            return 0
        from engine_runtime_support import maybe_defer_attack_damage
        if maybe_defer_attack_damage(
            self,
            target_id,
            amount,
            hits,
            attacker_id,
            source_card,
            is_battery=is_battery,
            is_precision=is_precision,
            ignore_untargetable=ignore_untargetable,
        ):
            return 0
        if attacker_id < 0:
            attacker_id = 1 - target_id
        if ps.untargetable and not is_battery and not ignore_untargetable and not self._is_status_immune(target_id):
            self.log_msg(f"{self.pn(target_id)}无法被攻击选中")
            return 0
        total_dealt = 0
        if not isinstance(getattr(self, '_last_positive_damage_hits', None), list) or len(self._last_positive_damage_hits) != len(self.players):
            self._last_positive_damage_hits = [0] * len(self.players)
        self._last_positive_damage_hits[target_id] = 0
        immune = self._is_status_immune(target_id)
        for _ in range(hits):
            self._consume_action_work(4)
            precision_dodged = False
            plank_blocks_attack = False
            if ps.dodge > 0 and not immune:
                ps.dodge -= 1
                if is_precision:
                    precision_dodged = True
                    if not getattr(self, '_suppress_next_precision_dodge_log', False):
                        self.log_msg(f"{self.pn(target_id)}的闪避被精准消耗")
                else:
                    prevented = self._estimate_avoided_attack_damage(
                        amount,
                        hits,
                        attacker_id,
                        source_card,
                    )
                    self.log_msg(f"{self.pn(target_id)}闪避了攻击")
                    self._record_dodge_damage_prevented(target_id, prevented)
                    self._record_achievement_damage_output(attacker_id, prevented)
                    continue
            if ps.invincible:
                self._record_achievement_damage_output(
                    attacker_id,
                    self._estimate_avoided_attack_damage(amount, hits, attacker_id, source_card),
                )
                self.log_msg(f"{self.pn(target_id)}无敌，免疫伤害")
                continue
            source_power = 0
            if source_card is not None:
                try:
                    source_power = clamp_card_power(getattr(source_card, 'power_value', 0) or 0)
                except Exception:
                    source_power = 0
            if amount <= 0 and source_power <= 0 and hits <= 1:
                break
            if source_card is not None and self._equipment_flag_or_legacy_mark(target_id, 'blocks_cheap_attacks'):
                try:
                    if (
                        getattr(source_card, 'card_type', '') == 'thorn'
                        and self._actual_card_elixir_cost(source_card) <= 1
                    ):
                        plank_blocks_attack = True
                except Exception:
                    pass
            dmg = amount
            power = 0
            if source_card is not None:
                try:
                    power = clamp_card_power(getattr(source_card, 'power_value', 0) or 0)
                except Exception:
                    power = 0
            if power != 0:
                dmg += int(math.ceil(power / max(1, int(hits or 1))))
                dmg = max(0, dmg)
            if 0 <= attacker_id < len(self.players):
                multiplier = float(getattr(self.players[attacker_id], 'damage_multiplier', 1.0) or 1.0)
                if multiplier != 1.0:
                    dmg = int(math.ceil(dmg * multiplier))
                    self.players[attacker_id].damage_multiplier = 1.0
                try:
                    puppeteer_multiplier = float((getattr(self.players[attacker_id], 'custom_vars', {}) or {}).get('void_puppeteer_damage_multiplier', 1.0) or 1.0)
                except Exception:
                    puppeteer_multiplier = 1.0
                if puppeteer_multiplier != 1.0:
                    dmg = int(math.ceil(dmg * puppeteer_multiplier))
            dmg = self._apply_corruption_multiplier_to_damage(dmg, log=False)
            dmg = self._apply_damage_dealt_equipment_multiplier(dmg, attacker_id)
            if plank_blocks_attack:
                self._record_achievement_damage_output(attacker_id, dmg)
                dmg = 0
            damage_context = self._v2_damage_context(
                target_id,
                dmg,
                attacker_id,
                damage_kind='attack',
                damage_tag=DAMAGE_TAG_PHYSICAL,
                damage_type=DAMAGE_TYPE_PHYSICAL,
                is_battery=is_battery,
                is_precision=is_precision,
            )
            before_v2_modifiers = max(0, int(dmg or 0))
            dmg = self._run_v2_damage_modifiers(damage_context, dmg)
            if getattr(self, 'pending_v2_ui', None):
                break
            self._record_achievement_damage_output(
                attacker_id,
                max(0, before_v2_modifiers - max(0, int(dmg or 0))),
            )
            # Weakness belongs to the attacker: it reduces physical damage they deal to others.
            attacker_state = self.players[attacker_id] if 0 <= attacker_id < len(self.players) else None
            attacker_immune = self._is_status_immune(attacker_id) if attacker_state is not None else False
            if dmg > 0 and attacker_state is not None and attacker_state.weakness > 0 and not attacker_immune:
                reduction = min(0.6, 0.2 * attacker_state.weakness)
                dmg = max(1, int(dmg * (1.0 - reduction)))
            dmg, _hel_crit = self._hel_apply_lucky_crit_to_damage(
                attacker_id, dmg, source_card, crit_bonus_damage
            )
            before_halving = max(0, int(dmg or 0))
            dmg = self._apply_attack_damage_halving(target_id, dmg, precision_dodged)
            self._record_achievement_damage_output(attacker_id, max(0, before_halving - dmg))
            if immune:
                root_armor = 0
                fragile = 0
            else:
                root_armor = self._custom_status_value(target_id, 'jungle:root', 'jungle:root_status', 'root_status')
                fragile = self._custom_status_value(target_id, 'jungle:fragile', 'fragile')
            effective_armor = int(ps.armor) + root_armor - fragile
            before_armor = max(0, int(dmg or 0))
            dmg = max(0, dmg - effective_armor)
            self._record_achievement_damage_output(attacker_id, max(0, before_armor - dmg))
            # Nazar transforms the physical damage remaining after armor and Fragile.
            nazar_stacks = 0 if immune else self._nazar_status_value(target_id)
            if dmg > 0 and nazar_stacks > 0:
                original_dmg = dmg
                dmg = max(1, dmg - 9)
                self._record_achievement_damage_output(attacker_id, original_dmg - dmg)
                if original_dmg >= 10:
                    self._set_nazar_status_value(target_id, nazar_stacks - 1)
            if self._bio_indictment_converts_damage(
                target_id,
                dmg,
                DAMAGE_TYPE_PHYSICAL,
                DAMAGE_TAG_PHYSICAL,
                source_card,
            ):
                self._record_achievement_damage_output(attacker_id, dmg)
                continue
            if ps.sponge_active and dmg > 0 and not immune:
                converted = min(10, dmg // 2)
                ps.poison += converted
                self._record_achievement_damage_output(attacker_id, dmg)
                dmg = 0
            before_shields = max(0, int(dmg or 0))
            dmg = self._apply_universal_damage_shields(target_id, dmg, attacker_id, '攻击', DAMAGE_TYPE_PHYSICAL)
            self._record_achievement_damage_output(attacker_id, max(0, before_shields - dmg))
            if _hel_crit and crit_bonus_multiplier != 1.0:
                dmg = max(0, int(math.ceil(int(dmg) * crit_bonus_multiplier)))
            if (
                dmg > 0
                and getattr(self, '_prediction_capture_target_id', None) == target_id
                and int(getattr(self, '_prediction_first_attack_damage', 0) or 0) <= 0
            ):
                self._prediction_first_attack_damage = int(dmg)
            if dmg > 0:
                if self._consume_absorb_attack_damage(target_id, source_card, dmg, attacker_id):
                    self._record_achievement_damage_output(attacker_id, dmg)
                    continue
                from engine_runtime_support import try_declared_damage_absorb
                if try_declared_damage_absorb(self, target_id, dmg, "attack"):
                    self._record_achievement_damage_output(attacker_id, dmg)
                    continue
            old_health = ps.health
            ps.health -= dmg
            health_lost = max(0, int(old_health or 0) - max(0, int(ps.health or 0)))
            self._bio_stem_cell_after_health_loss(target_id, health_lost)
            self._note_achievement_health(target_id)
            total_dealt += dmg
            if dmg > 0:
                self._last_positive_damage_hits[target_id] += 1
            self._record_damage(target_id, dmg, attacker_id)
            self.log_msg(f"{self.pn(target_id)}受到{dmg}点伤害（H={ps.health}）")
            if dmg > 0:
                self._sewers_grow_toilet_paper_power(target_id)
                self._garden_magic_cutter_after_hit(attacker_id, target_id, dmg)
            self._run_v2_after_damage_hooks(damage_context, dmg)
            if dmg > 0:
                self._apply_ocean_blood_debt_after_physical_damage(target_id, attacker_id)
            if dmg > 0 and not immune:
                root_layers = self._custom_status_value(target_id, 'jungle:root', 'jungle:root_status', 'root_status')
                if root_layers > 0:
                    self._set_custom_status_alias_group(target_id, 'jungle:root_status', ('jungle:root', 'jungle:root_status', 'root_status'), root_layers - 1)
                    self._consume_jungle_root_layer_from_equipment(target_id)
            if dmg > 0 and ps.toxic > 0 and not immune:
                from engine_runtime_support import effective_poison_coating
                ps.poison += effective_poison_coating(self, target_id)
            self._game_over_defer_depth += 1
            try:
                self._check_yggdrasil(target_id)
                if dmg > 0 and not is_battery:
                    for equipment_owner_id, eq in list(self._iter_equipment_targeting_player(target_id)):
                        if self._card_has_flag(eq.card_instance, 'retaliate_on_attack_hit'):
                            dealt = self._deal_direct_damage(
                                attacker_id, 3, '电池电击', target_id,
                                damage_type=DAMAGE_TYPE_MAGIC,
                                damage_tag=DAMAGE_TAG_BATTERY,
                            )
                            if dealt > 0:
                                self.log_msg(f"{self.pn(target_id)}的电池效果：对{self.pn(attacker_id)}造成{dealt}电伤")
                            else:
                                self.log_msg(f"{self.pn(target_id)}的电池触发，但{self.pn(attacker_id)}未受到电伤")
                        elif self._card_has_flag(eq.card_instance, 'mana_on_attack_hit'):
                            owner_state = self.players[equipment_owner_id]
                            if owner_state.magic_battery_m_this_turn < 3:
                                owner_state.gain_magic(1)
                                owner_state.magic_battery_m_this_turn += 1
                                owner_state.custom_vars['魔法电池本回合回魔'] = owner_state.magic_battery_m_this_turn
                                self.log_msg(f"{self.pn(equipment_owner_id)}的魔法电池效果：+1M")
                        elif self._has_card_event(eq.card_def, 'damage_taken') and self._run_card_event(
                                target_id, eq.card_instance, 'damage_taken', None,
                                {
                                    'source_id': attacker_id,
                                    'target_id': target_id,
                                    'damage': dmg,
                                    'damage_amount': dmg,
                                    'damage_kind': 'attack',
                                    'damage_type': DAMAGE_TYPE_PHYSICAL,
                                    'damage_tag': DAMAGE_TAG_PHYSICAL,
                                    'selected_equipment_instance_id': eq.card_instance.instance_id,
                                    'selected_equipment_owner_id': equipment_owner_id,
                                }):
                            continue
            finally:
                self._game_over_defer_depth -= 1
            self._check_game_over()
            if ps.health <= 0 and self._game_over_defer_depth <= 0:
                break
        return total_dealt

    def _execute_card_effect(self, player_id: int, card: CardInstance, choice: Optional[dict] = None) -> dict:
        card_resolution_depth = max(0, int(getattr(self, '_card_resolution_depth', 0) or 0))
        outermost_resolution = card_resolution_depth == 0
        if outermost_resolution and getattr(self, '_deferred_card_alive_before', None) is None:
            self._deferred_card_alive_before = [ps.health > 0 for ps in self.players]
        if outermost_resolution:
            selected_target = self._choice_target_from_choice(choice, -1)
            snapshot = getattr(self, '_card_resolution_target_snapshot', None)
            same_card = bool(
                isinstance(snapshot, dict)
                and snapshot.get('card_instance_id') == getattr(card, 'instance_id', None)
            )
            if not same_card:
                flags = self._effective_card_flags(card)
                wide_targets = self._wide_strike_target_ids(player_id, card) if 'wide_strike' in flags else None
                self._card_resolution_target_snapshot = {
                    'player_id': player_id,
                    'card_instance_id': getattr(card, 'instance_id', None),
                    'selected_target': selected_target,
                    'wide_targets': wide_targets,
                }
            elif selected_target >= 0:
                snapshot['selected_target'] = selected_target
        previous_formal_card = getattr(self, '_formal_logic_current_play_card', None)
        self._formal_logic_current_play_card = card
        self._card_resolution_depth = card_resolution_depth + 1
        self._game_over_defer_depth += 1
        try:
            return self._execute_card_effect_impl(player_id, card, choice)
        finally:
            self._formal_logic_current_play_card = previous_formal_card
            self._game_over_defer_depth = max(0, self._game_over_defer_depth - 1)
            self._card_resolution_depth = max(0, int(getattr(self, '_card_resolution_depth', 1) or 1) - 1)
            has_pending_action = bool(
                self.pending_response is not None
                or self.pending_choice is not None
                or getattr(self, 'pending_v2_ui', None) is not None
            )
            if outermost_resolution and self._card_resolution_depth == 0 and not has_pending_action:
                alive_before = getattr(self, '_deferred_card_alive_before', None)
                self._deferred_card_alive_before = None
                self._card_resolution_target_snapshot = None
                # Death cleanup can itself emit damage or run destroy hooks. Keep
                # game-over checks deferred until every part of this card settles.
                self._game_over_defer_depth += 1
                try:
                    self._finalize_deferred_card_deaths(alive_before)
                finally:
                    self._game_over_defer_depth = max(0, self._game_over_defer_depth - 1)
                self._check_game_over()

    def _finalize_deferred_card_deaths(self, alive_before: Optional[List[bool]] = None):
        """Mode hook for cleanup that must happen after the full card resolves."""

    def _execute_card_effect_impl(self, player_id: int, card: CardInstance, choice: Optional[dict] = None) -> dict:
        ps = self.players[player_id]
        result = {'success': True, 'card': card.to_dict()}
        if 'ocean_nitro_negated' in getattr(card, 'instance_flags', set()):
            card.instance_flags.discard('ocean_nitro_negated')
            self._log_card_play(player_id, card)
            reset_card_after_play(card)
            if 'exile' in card.flags:
                self._put_card_in_exile(ps.player_id, card)
            else:
                self._discard_card(ps, card)
            self._garden_return_first_played_card(player_id, card)
            self._dispatch_card_event('card_used', player_id, card, target_id=player_id, choice=choice)
            self._run_v2_play_hook('after_play_card', player_id, card, choice)
            result['card'] = card.to_dict()
            result['countered'] = True
            return result
        if card.card_type == 'thorn' and (card.fission_level > 1 or card.fusion_level > 1):
            self.log_msg(f"[特效] {card.name_cn} 聚变={card.fusion_level} 裂变={card.fission_level}")
        if self.negated_card and card.card_type == 'bloom':
            self.negated_card = False
            self._log_card_play(player_id, card)
            reset_card_after_play(card)
            if 'exile' in card.flags:
                self._put_card_in_exile(ps.player_id, card)
            else:
                self._discard_card(ps, card)
            self._garden_return_first_played_card(player_id, card)
            self._dispatch_card_event('card_used', player_id, card, target_id=player_id, choice=choice)
            self._run_v2_play_hook('after_play_card', player_id, card, choice)
            result['countered'] = True
            result['negated'] = True
            return result
        # Magic Nazar: check for magic_nazar status on opponent
        if card.card_type == 'bloom':
            for opp_id in self._magic_nazar_counter_player_ids(player_id, card, choice):
                if not (0 <= opp_id < len(self.players)):
                    continue
                opp = self.players[opp_id]
                magic_nazar_stacks = 0 if self._is_status_immune(opp_id) else int(opp.custom_statuses.get('magic_nazar', 0) or 0)
                if magic_nazar_stacks <= 0:
                    continue
                card_cost_e = int(getattr(card, '_paid_e_this_play', getattr(card, 'cost_e', 0)) or 0)
                if card_cost_e <= 1:
                    self.log_msg(f"{self.pn(player_id)}的{card.name_cn}被魔法邪眼反制，失效！")
                    opp.custom_statuses['magic_nazar'] = magic_nazar_stacks - 1
                    if opp.custom_statuses['magic_nazar'] <= 0:
                        opp.custom_statuses.pop('magic_nazar', None)
                    self._log_card_play(player_id, card)
                    reset_card_after_play(card)
                    if 'exile' in card.flags:
                        self._put_card_in_exile(ps.player_id, card)
                    else:
                        self._discard_card(ps, card)
                    self._garden_return_first_played_card(player_id, card)
                    self._dispatch_card_event('card_used', player_id, card, target_id=player_id, choice=choice)
                    self._run_v2_play_hook('after_play_card', player_id, card, choice)
                    return result
                break
        self.negated_card = False
        needs_choice = self._card_needs_choice(card)
        if needs_choice and not self._choice_satisfies_request(card, choice):
            queued = self._queue_card_choice(player_id, card, choice, already_paid=True)
            if queued:
                return queued
        if 'mimic_special_cost' in self._effective_card_flags(card) and isinstance(choice, dict) and choice.get('target_instance_id') is not None:
            target = ps.find_hand_card(choice.get('target_instance_id'))
            if target is not None and not self._card_selectable_by_action(target):
                self._undo_pending_choice_play_side_effects(player_id, card)
                return {'success': False, 'error': '目标无效'}
            if target is not None and not self._can_pay_mimic_special_cost(player_id, target):
                self._undo_pending_choice_play_side_effects(player_id, card)
                return {'success': False, 'error': '\u80fd\u91cf\u4e0d\u8db3'}
        play_log_marker = len(self.log)
        from engine_runtime_support import play_summary_declaration as _play_summary
        if self._uses_atomic_play_effects(card) and not _play_summary(card).get('suppress_play_log'):
            self._log_card_play(player_id, card)
        if card.card_type == 'thorn':
            self._clamp_card_layers(card)
            fission_level = clamp_card_layer(getattr(card, 'fission_level', 1))
            for hit_idx in range(fission_level):
                self._consume_action_work(4)
                if self.game_over:
                    break
                card.fission_hit = hit_idx
                self._apply_card_effect(player_id, card, choice)
            card.fission_hit = 0
        else:
            self._apply_card_effect(player_id, card, choice)
        if (
            self.pending_response is None
            and self.pending_choice is None
            and getattr(self, 'pending_v2_ui', None) is None
        ):
            from formal_logic_runtime import consume_double_resolution
            if consume_double_resolution(self, player_id):
                self.log_msg(f"{card.name_cn}因登场效果额外结算1次")
                if card.card_type == 'thorn':
                    for hit_idx in range(clamp_card_layer(getattr(card, 'fission_level', 1))):
                        self._consume_action_work(4)
                        card.fission_hit = hit_idx
                        self._apply_card_effect(player_id, card, choice)
                    card.fission_hit = 0
                else:
                    self._apply_card_effect(player_id, card, choice)
        # Check if an effect (e.g. request(type:"reorder_deck") / assembler_effect) set
        # pending_choice during execution
        # Must check BEFORE card disposition (discard/equip) to allow the choice to complete first
        if self.pending_choice is not None:
            if getattr(self, '_auto_resolve_choices_for', None) == player_id:
                auto_pending = self.pending_choice
                auto_choice = self._default_choice_for_pending(auto_pending)
                if isinstance(auto_choice, dict):
                    auto_result = self.resolve_choice(player_id, auto_choice)
                    if self.pending_choice is None:
                        return auto_result if isinstance(auto_result, dict) else {'success': True}
            pending = self.pending_choice
            if pending.get('choice_type') == 'magic_salt_reflect':
                pass
            else:
                keep_paid_choice = bool(pending.get('keep_paid'))
                if keep_paid_choice:
                    pending['play_log_marker'] = play_log_marker
                else:
                    self._undo_pending_choice_play_side_effects(player_id, card, play_log_marker=play_log_marker)
                return {
                    'success': True,
                    'needs_choice': True,
                    'choice_type': pending.get('choice_type', ''),
                    'choice_params': pending.get('choice_params', {}),
                    'card': card.to_dict(),
                    'hand_cards': pending.get('hand_cards', []),
                    'deck_cards': pending.get('deck_cards', []),
                    'discard_cards': pending.get('discard_cards', []),
                    'target_player_id': pending.get('target_player_id'),
                    'max_replace': pending.get('max_replace'),
                    'message': pending.get('message', ''),
                }
        from formal_logic_runtime import on_card_resolved_before_disposition
        formal_target_id = self._choice_target_from_choice(choice, player_id)
        on_card_resolved_before_disposition(self, player_id, card, formal_target_id, choice)
        # Fracture: take damage when playing a card
        if ps.fracture > 0 and not self._is_status_immune(player_id):
            frac_dmg = ps.fracture
            self._deal_direct_damage(player_id, frac_dmg, '破损', player_id,
                                     damage_type=DAMAGE_TYPE_MAGIC, damage_tag=DAMAGE_TAG_FRACTURE)
        # Bleed: take damage when playing attack card
        if ps.bleed > 0 and card.card_type == 'thorn' and not self._is_status_immune(player_id):
            bleed_dmg = ps.bleed
            self._deal_direct_damage(player_id, bleed_dmg, '流血', player_id,
                                     damage_type=DAMAGE_TYPE_MAGIC, damage_tag=DAMAGE_TAG_BLEED)
        placed_as_equipment = bool(getattr(card, '_placed_as_equipment', False))
        from formal_logic_runtime import formal_proxy_suppresses_effect
        script_controls_play = self._card_has_script(card.card_def) or formal_proxy_suppresses_effect(card)
        explicit_equip_owner = hasattr(card, '_placed_as_equipment_owner')
        equip_owner_id = int(getattr(card, '_placed_as_equipment_owner', player_id))
        if equip_owner_id < 0 or equip_owner_id >= len(self.players):
            equip_owner_id = player_id
        equip_owner = self.players[equip_owner_id]
        blood_knife_return = bool((getattr(card, 'custom_vars', {}) or {}).pop('bio_blood_knife_return', False))
        reset_card_after_play(card)
        force_exile_after_auto_play = 'ocean_no_auto' in getattr(card, 'instance_flags', set()) and 'exile' in card.flags
        if (card.card_type == 'root' and not script_controls_play) or placed_as_equipment:
            eq = self._find_equipment_for_card(equip_owner_id, card)
            if eq is None:
                eq = EquipmentInstance(card, equip_owner_id)
                if isinstance(choice, dict):
                    for key in ('target_player', 'target_player_id', 'target_id'):
                        if key in choice:
                            try:
                                selected_effect_target = int(choice.get(key))
                            except Exception:
                                selected_effect_target = -1
                            if 0 <= selected_effect_target < len(self.players):
                                eq.effect_target = selected_effect_target
                                break
                equip_owner.equipment.append(eq)
                self._note_achievement_equipment_count(equip_owner_id)
                self._refresh_hand_limit_bonuses()
                # Round 41 / 批次 AE-5：``continuous_deck_reveal``（护目镜）是数据
                # 声明的视图权限，装备落场时按装备的目标补一条与旧原子逐字一致的战报。
                if self._card_has_flag(card, 'continuous_deck_reveal'):
                    self.log_msg(
                        f"{self.pn(equip_owner_id)}给"
                        f"{self.pn(self._equipment_effect_target_id(eq, equip_owner_id))}"
                        f"启用了牌堆查看"
                    )
                self.log_msg(f"{self.pn(equip_owner_id)}装备了{card.name_cn}")
                if self._card_has_flag(card, 'electric_web_arm_on_place'):
                    arm_target = int(getattr(eq, 'effect_target', equip_owner_id))
                    if not (0 <= arm_target < len(self.players)):
                        arm_target = equip_owner_id
                    self._apply_electric_web_arm(equip_owner_id, eq, arm_target, 2)
            if hasattr(card, '_placed_as_equipment'):
                delattr(card, '_placed_as_equipment')
            if hasattr(card, '_placed_as_equipment_owner'):
                delattr(card, '_placed_as_equipment_owner')
        elif blood_knife_return:
            ps.add_to_hand(card)
            self.log_msg(f"{self.pn(player_id)}的{card.name_cn}因实际回复能量回到手中")
        elif force_exile_after_auto_play:
            card.instance_flags.discard('return_to_hand')
            owner_id, zone_name, _ = self._find_card_location(card)
            if owner_id is None or zone_name is None:
                self._put_card_in_exile(ps.player_id, card)
        elif 'return_to_hand' in card.instance_flags:
            card.instance_flags.discard('return_to_hand')
            ps.add_to_hand(card)
            # A card that only marks the tag after it really recovered elixir
            # can ship its own wording with the tag step (`return_log`).
            custom = getattr(card, 'custom_vars', None)
            template = custom.pop('return_to_hand_log', None) if isinstance(custom, dict) else None
            if isinstance(template, str) and template:
                self.log_msg(self._format_step_log(
                    template,
                    player=self.pn(player_id),
                    card=card.name_cn,
                    name=card.name_cn,
                    target=self.pn(player_id),
                    source=self.pn(player_id),
                    amount=0,
                ))
            else:
                self.log_msg(f"{self.pn(player_id)}的{card.name_cn}立即回到手中")
        elif 'exile' in card.flags:
            # 反馈 #100：放逐优先于回转；两者同时存在时进入放逐区。
            owner_id, zone_name, _ = self._find_card_location(card)
            if owner_id is None or zone_name is None:
                self._put_card_in_exile(ps.player_id, card)
        elif 'rebound' in card.flags:
            ps.add_to_hand(card)
            self.log_msg(f"{self.pn(player_id)}的{card.name_cn}因回转回到手中")
        elif 'floating' in card.flags:
            owner_id, zone_name, _ = self._find_card_location(card)
            if owner_id is None or zone_name is None:
                insert_at = random.randint(0, len(ps.deck)) if ps.deck else 0
                ps.deck.insert(insert_at, card)
                self.log_msg(f"{self.pn(player_id)}的{card.name_cn}因漂浮洗入抽牌堆")
        else:
            owner_id, zone_name, _ = self._find_card_location(card)
            if owner_id is None or zone_name is None:
                self._discard_card(ps, card)
        self._garden_return_first_played_card(player_id, card)
        target_id = player_id
        if isinstance(choice, dict):
            for key in ('target_player', 'target_player_id', 'target_id'):
                if key in choice:
                    try:
                        target_id = int(choice.get(key))
                        break
                    except Exception:
                        target_id = player_id
        self._dispatch_card_event('card_used', player_id, card, target_id=target_id, choice=choice)
        self._run_v2_play_hook('after_play_card', player_id, card, choice)
        self._check_game_over()
        if getattr(self, 'pending_v2_ui', None):
            result['needs_v2_ui'] = True
        try:
            ps.custom_vars['void_last_played_def_id'] = getattr(card, 'def_id', '')
            ps.custom_vars.pop('void_current_previous_def_id', None)
        except Exception:
            pass
        if (
            int(getattr(self, '_card_resolution_depth', 0) or 0) <= 1
            and not self.game_over
            and self.phase == 'action'
            and self.current_player == player_id
            and self.pending_response is None
            and self.pending_choice is None
            and not getattr(self, 'pending_v2_ui', None)
            and bool(getattr(ps, 'force_end_turn', False))
        ):
            # "结束你的回合" resolves after the card finished, unlike
            # 无法行动直到下回合开始 which only blocks actions.
            ps.force_end_turn = False
            self._end_player_turn(player_id)
        return result

    def _atomic_place_as_equip(self, player_id, card, params, log, choice, context):
        source = self.players[player_id]
        target_card = self._resolve_card_ref(player_id, params.get('card', {'ref': 'current_card'}), card)
        if target_card is None:
            return
        owner_expr = params.get('owner', params.get('equip_owner'))
        owner_id = self._resolve_target(player_id, owner_expr) if owner_expr is not None else player_id
        if owner_id < 0 or owner_id >= len(self.players):
            owner_id = player_id
        owner = self.players[owner_id]
        if target_card in source.hand:
            source.hand.remove(target_card)
        else:
            self._remove_card_from_current_zone(target_card)
        if self._find_equipment_for_card(owner_id, target_card) is None:
            target_card.durability = target_card.card_def.durability if getattr(target_card.card_def, 'durability', 0) > 0 else 3
            eq = EquipmentInstance(target_card, owner_id)
            if 'effect_target' in params:
                effect_target = self._resolve_target(player_id, params.get('effect_target'))
                if not (0 <= effect_target < len(self.players)) and isinstance(context, dict):
                    try:
                        effect_target = int(context.get('target_id', -1))
                    except Exception:
                        effect_target = -1
                if 0 <= effect_target < len(self.players):
                    eq.effect_target = effect_target
            else:
                selected_target = self._selected_choice_target(-1)
                if not (0 <= selected_target < len(self.players)) and isinstance(context, dict):
                    try:
                        selected_target = int(context.get('target_id', -1))
                    except Exception:
                        selected_target = -1
                if 0 <= selected_target < len(self.players):
                    eq.effect_target = selected_target
            owner.equipment.append(eq)
            if self._equipment_uses_non_stack_rule(eq):
                self._ensure_non_stack_equipment_order(eq)
            self._note_achievement_equipment_count(owner_id)
            self._refresh_hand_limit_bonuses()
            self._refresh_equipment_derived_player_flags(owner_id)
            self.log_msg(log or f"{self.pn(owner_id)}装备了{target_card.name_cn}")
            if self._card_has_flag(target_card, 'electric_web_arm_on_place'):
                arm_target = int(getattr(eq, 'effect_target', owner_id))
                if not (0 <= arm_target < len(self.players)):
                    arm_target = owner_id
                self._apply_electric_web_arm(owner_id, eq, arm_target, 2)
        if target_card is card:
            card._placed_as_equipment = True
            card._placed_as_equipment_owner = owner_id

    def _atomic_status_add_named(self, player_id, card, params, log, choice, context):
        """Round 31 / 批次 Z：``status_add_named`` 现在用 ``mode`` 区分加/设。

        ``mode`` 缺省 ``add``（层数叠加）；``mode:"set"`` 即旧
        ``set_status_named``（把状态设为 N 层，``stack`` 仍是它的默认值来源）。
        两个名字的参数面完全一致，合并后只多一个 ``mode`` 键。
        """

        mode = str(params.get('mode', 'add') or 'add').strip().lower()
        mode = {'=': 'set', 'set_to': 'set', 'assign': 'set', 'replace': 'set',
                'stack': 'add', '+': 'add', '+=': 'add', 'increase': 'add'}.get(mode, mode)
        op = 'set_status_named' if mode == 'set' else 'status_add_named'
        self._apply_status_add_family(player_id, card, params, log, op=op)

    # Round 30 / 批次 Y：旧写法 ``add_status`` / ``remove_status`` / ``set_status``
    # （Round 15 起是"未写 ``log`` 时默播报层数"的真原子）已随零用量清理删除。
    # 规范写法 ``status_add_named`` / ``status_remove_named`` 现在**只**按步骤
    # 自己写的 ``log`` 决定战报（``log:true`` 就是旧默认那句），因此
    # ``STATUS_LEGACY_ANNOUNCING_OPS`` 也一并消失。
    # Round 31 / 批次 Z：``set_status_named`` 也并进 ``status_add_named(mode:"set")``。


    def _atomic_add_tag(self, player_id, card, params, log, choice, context):
        """Round 31 / 批次 Z：卡内标签族的单卡一半（``mode`` 选加/减/清空）。

        覆盖 ``add_tag``（默认）/ ``remove_tag``（``mode:"remove"``）/
        ``clear_tags``（``mode:"clear"``，把所有有效标签压进 ``disabled_flags``
        再清空 ``instance_flags``）。默认模式与默认战报逐字保留。
        """

        mode = str(params.get('mode', 'add') or 'add').strip().lower()
        mode = {'+': 'add', 'add_tag': 'add', 'remove_tag': 'remove', 'del': 'remove',
                'delete': 'remove', 'unset': 'remove', 'clear_tags': 'clear',
                'reset': 'clear', 'none': 'clear'}.get(mode, mode)
        target_card = self._resolve_card_ref(player_id, params.get('card', {'ref': 'current_card'}), card)
        if target_card is None:
            return
        if mode == 'clear':
            all_flags = self._effective_card_flags(target_card)
            target_card.instance_flags = set()
            target_card.disabled_flags = set(getattr(target_card, 'disabled_flags', set()) or set())
            target_card.disabled_flags.update(all_flags)
            if log:
                self.log_msg(log)
            return
        tag = normalize_card_flag(params.get('tag', ''))
        if not tag:
            return
        if mode == 'remove':
            if hasattr(target_card, 'instance_flags'):
                target_card.instance_flags.discard(tag)
            if params.get('silent') or params.get('no_log') or log is False:
                return
            self.log_msg(log or f"{target_card.name_cn}移除{self._card_flag_log_text(tag)}")
            return
        target_card.instance_flags = getattr(target_card, 'instance_flags', set())
        target_card.instance_flags.add(tag)
        return_log = params.get('return_log')
        if isinstance(return_log, str) and return_log:
            custom = getattr(target_card, 'custom_vars', None)
            if isinstance(custom, dict):
                custom[f'{tag}_log'] = return_log
        if params.get('silent') or params.get('no_log') or log is False:
            return
        self.log_msg(log or f"{target_card.name_cn}获得{self._card_flag_log_text(tag)}")

    def _atomic_add_tag_to_zone(self, player_id, card, params, log, choice, context):
        """Add a tag to all cards in one or more zones, optionally filtered by card_type.

        ``zone`` takes a single zone (hand/deck/discard/exile) and ``zones`` a list,
        which may also contain ``equipment`` (the attached equipment cards).
        ``summary`` collapses the per-zone reports into one combined battle-log
        line, e.g. "玩家1使玩家2的12张攻击牌获得被揭示".

        Round 14 / batch 2: 区域名走统一词表（见 mod_runtime_v2.ZONE_NAMES），
        未知区域显式报错；``target`` 与 ``add_tag_to_zone`` 的其它同族 op 共用
        ``first``/``exclude``/``relation``/``allow_self``/``filter`` 修饰键。
        """
        targets = self._step_target_ids(
            player_id, card, params, context, op='add_tag_to_zone', default='enemy',
        )
        if not targets:
            return
        zone_names = self._step_zone_names(params, op='add_tag_to_zone', default='hand')
        tag = str(params.get('tag', '')).strip()
        card_type_filter = str(params.get('card_type', '') or '').strip().lower()
        if not tag or not zone_names:
            return
        tag = normalize_card_flag(tag)
        mode = str(params.get('mode', 'add') or 'add').strip().lower()
        mode = {'+': 'add', 'add_tag': 'add', 'add': 'add',
                'remove_tag': 'remove', 'remove': 'remove', 'del': 'remove', 'delete': 'remove',
                'toggle': 'toggle', 'flip': 'toggle', 'toggle_tag': 'toggle'}.get(mode, mode)
        if mode == 'toggle':
            # Round 31 / 批次 Z：旧 ``toggle_tag_in_zone`` 的逐张翻转。
            log_value = log
            for target_id in targets:
                ps = self.players[target_id]
                changed = 0
                for zone_name in zone_names:
                    for candidate in list(self._player_zone_cards(ps, zone_name) or []):
                        if candidate is None:
                            continue
                        if card_type_filter and getattr(candidate, 'card_type', '') != card_type_filter:
                            continue
                        if tag in self._effective_card_flags(candidate):
                            candidate.instance_flags.discard(tag)
                            candidate.disabled_flags.add(tag)
                        else:
                            candidate.instance_flags.add(tag)
                            candidate.disabled_flags.discard(tag)
                        changed += 1
                if changed <= 0 or not log_value:
                    continue
                self.log_msg(self._format_step_log(
                    log_value, target=self.pn(target_id), count=changed, tag=tag,
                ))
            return
        if mode == 'remove':
            # Round 31 / 批次 Z：旧 ``remove_tag_from_zone`` 的"区域摘标签"。
            counts = {}
            for target_id in targets:
                ps = self.players[target_id]
                count = 0
                for zone_name in zone_names:
                    for candidate in self._player_zone_cards(ps, zone_name):
                        if candidate is None:
                            continue
                        if card_type_filter and getattr(candidate, 'card_type', '') != card_type_filter:
                            continue
                        if tag in getattr(candidate, 'instance_flags', set()):
                            candidate.instance_flags.discard(tag)
                            count += 1
                        candidate.disabled_flags.discard(tag)
                counts[target_id] = count
            if params.get('silent') or params.get('no_log') or log is False:
                return
            if log:
                for target_id in targets:
                    self.log_msg(self._format_step_log(
                        log, target=self.pn(target_id), source=self.pn(player_id),
                        count=counts.get(target_id, 0),
                    ))
                return
            zone_desc = '/'.join(self._zone_log_label(zone_name) for zone_name in zone_names)
            for target_id in targets:
                self.log_msg(
                    f"{self.pn(player_id)}使{self.pn(target_id)}{zone_desc}中的"
                    f"{counts.get(target_id, 0)}张牌失去{self._card_flag_log_text(tag)}"
                )
            return
        summary = bool(
            params.get('summary')
            or params.get('summary_log')
            or str(params.get('log_mode', '') or '').strip().lower() == 'summary'
        )
        counts = {}
        for target_id in targets:
            ps = self.players[target_id]
            count = 0
            for zone_name in zone_names:
                zone_cards = self._player_zone_cards(ps, zone_name)
                for candidate in list(zone_cards or []):
                    if candidate is None:
                        continue
                    if card_type_filter and getattr(candidate, 'card_type', '') != card_type_filter:
                        continue
                    if tag not in candidate.flags:
                        candidate.instance_flags.add(tag)
                        candidate.disabled_flags.discard(tag)
                        count += 1
            counts[target_id] = count
        if params.get('silent') or params.get('no_log') or log is False:
            return
        if log:
            for target_id in targets:
                self.log_msg(self._format_step_log(
                    log,
                    target=self.pn(target_id),
                    source=self.pn(player_id),
                    count=counts.get(target_id, 0),
                    amount=counts.get(target_id, 0),
                ))
            return
        type_desc = self._card_type_log_label(card_type_filter)
        for target_id in targets:
            count = counts.get(target_id, 0)
            if summary:
                tag_desc = self._card_flag_log_label(tag)
                self.log_msg(f"{self.pn(player_id)}使{self.pn(target_id)}的{count}张{type_desc}获得{tag_desc}")
                continue
            zone_desc = self._zone_log_label(zone_names[0])
            flag_text = self._card_flag_log_text(tag)
            self.log_msg(
                f"{self.pn(player_id)}使{self.pn(target_id)}{zone_desc}中的"
                f"{count}张{type_desc}获得{flag_text}"
            )

    def _atomic_give_card_to_hand(self, player_id, card, params, log, choice, context):
        # Round 14 / batch 2: 目的区自洽校验 + 位置词表校验 + ``target`` 集合语义。
        # 标量选择器（self/target/enemy）仍旧只解析出一个目标，旧数据行为不变；
        # 多目标选择器（all_players/play_targets…）改为每个目标各给一张。
        self._assert_step_zone(params, 'hand', op='give_card_to_hand')
        self._step_zone_position_or_none(params, op='give_card_to_hand')
        target_ids = self._step_target_ids(player_id, card, params, context, op='give_card_to_hand')
        card_ref = self._resolve_card_id_ref(player_id, self._give_card_step_ref(params), card)
        if not card_ref or not target_ids:
            return
        amount = self._give_card_step_amount(player_id, card, params)
        missing_skip = str(params.get('missing') or '').strip().lower() == 'skip'
        overflow_discard = str(params.get('overflow') or '').strip().lower() == 'discard'
        for target_id in target_ids:
            if card_ref == ERROR_CARD_ID or missing_skip:
                if card_ref not in CARD_DEFS:
                    continue
            card_def = CARD_DEFS.get(card_ref) or CARD_DEFS.get(ERROR_CARD_ID)
            if not card_def:
                continue
            if card_def.id == ERROR_CARD_ID and missing_skip:
                continue
            if card_def.id != ERROR_CARD_ID and not self._card_allowed(card_def.id):
                continue
            ts = self.players[target_id]
            for _ in range(amount):
                if card_def.id != ERROR_CARD_ID and not ts.can_add_to_hand():
                    # ``overflow: discard`` mirrors PlayerState.add_to_hand, which
                    # sends the new card to the discard pile when the hand is full.
                    if not overflow_discard:
                        break
                new_card = CardInstance(def_id=card_def.id)
                self._apply_setup_modifiers_to_card(target_id, new_card)
                if not self._can_normally_acquire_card(target_id, new_card):
                    self.log_msg(f"{self.pn(target_id)}已拥有唯一牌{new_card.name_cn}，未获得额外实例")
                    break
                ts.add_to_hand(new_card)
                self._remember_created_card(new_card, context)
            if log and card_def.id != ERROR_CARD_ID:
                self.log_msg(log)



    def _atomic_copy_card_instance(self, player_id, card, params, log, choice, context):
        """Copy a card *instance* (optionally from its pre-play snapshot).

        Unlike :meth:`_atomic_copy_card` this keeps the copied instance's own
        upgrades, can reset it like a freshly played card, can stamp extra tags
        and layers, and can drop the copy into hand, discard or deck. It backs
        the "make an upgraded copy of myself" family of cards.
        """
        source_ref = params.get('source', params.get('card', {'ref': 'current_card'}))
        from_snapshot = isinstance(source_ref, str) and source_ref in ('pre_play_snapshot', 'snapshot')
        copied = None
        if from_snapshot:
            if card is not None:
                snapshot = getattr(card, '_bio_pre_play_snapshot', None)
                copied = fresh_card_copy_from_dict(
                    snapshot if isinstance(snapshot, dict) else card.to_dict(),
                    getattr(card, 'def_id', ''),
                )
        else:
            source_card = self._resolve_card_ref(player_id, source_ref, card)
            if source_card is not None:
                if params.get('base_instance') or params.get('fresh_instance'):
                    # "play another copy of <card>" spawns a plain instance: the
                    # played card's power/layers/tags stay on the original.
                    copied = CardInstance(source_card.def_id)
                else:
                    copied = source_card.copy()
        if copied is None:
            return
        if params.get('reset_after_play'):
            reset_card_after_play(copied)
        copied.instance_flags = getattr(copied, 'instance_flags', set())
        copied.disabled_flags = getattr(copied, 'disabled_flags', set())
        for flag in normalize_card_flags(params.get('flags', []) or []):
            copied.instance_flags.add(flag)
            copied.disabled_flags.discard(flag)
        for modifier in params.get('setup_modifiers', []) or []:
            copied.setup_modifiers.add(str(modifier))
        if params.get('fission_level') is not None:
            copied.fission_level = clamp_card_layer(self._eval_int(player_id, params['fission_level'], card, 1))
            copied.fission_count = max(0, copied.fission_level - 1)
            copied.fission_hit = 0
        if params.get('swift_value') is not None:
            copied.swift_value = max(0, self._eval_int(player_id, params['swift_value'], card, 0))
        if params.get('unique_copy_penalty'):
            try:
                self._apply_forced_unique_copy_penalty(player_id, copied)
            except Exception:
                pass
        zone = str(params.get('zone', 'hand') or 'hand').lower()
        position = str(params.get('position', 'top') or 'top').lower()
        target_id = self._resolve_target(player_id, params.get('target', 'self'))
        if not self._valid_player_id(target_id):
            target_id = player_id
        target = self.players[target_id]
        if zone == 'discard':
            if position == 'random':
                target.discard.insert(random.randint(0, len(target.discard)), copied)
            else:
                target.discard.append(copied)
            self._note_achievement_enemy_card_total(player_id)
        elif zone == 'deck':
            if position == 'random':
                target.deck.insert(random.randint(0, len(target.deck)), copied)
            elif position == 'bottom':
                target.deck.append(copied)
            else:
                target.deck.insert(0, copied)
        elif params.get('forced') or str(params.get('hand_full') or '').strip().lower() == 'discard':
            self._add_forced_copy_to_hand(
                player_id, copied, source_owned=bool(params.get('source_owned', True)),
            )
        elif target.can_add_to_hand():
            target.add_to_hand(copied)
        else:
            return
        self._remember_created_card(copied, context)
        self._last_created_card_instance_id = getattr(copied, 'instance_id', None)
        if log is False or not log:
            return
        self.log_msg(self._format_step_log(
            log, target=self.pn(player_id), source=self.pn(player_id), count=1,
        ))

    def _atomic_create_copies_to_deck_top(self, player_id, card, params, log, choice, context):
        target_id = self._resolve_target(player_id, params.get('target', 'self'))
        def_id = str(params.get('def_id') or (getattr(card, 'def_id', '') if card else ''))
        if not self._card_allowed(def_id):
            return
        count = min(20, max(0, self._eval_int(player_id, params.get('count', 1), card, 1)))
        flags = normalize_card_flags(params.get('flags', []))
        swift = self._eval_int(player_id, params.get('swift_value', 0), card, 0)
        magic_swift = self._eval_int(player_id, params.get('magic_swift_value', 0), card, 0)
        power = clamp_card_power(self._eval_int(player_id, params.get('power_value', 0), card, 0))
        extra_hits = clamp_card_extra_hits(self._eval_int(player_id, params.get('extra_hits', 0), card, 0))
        ps = self.players[target_id]
        made = []
        for _ in range(max(0, count)):
            new_card = CardInstance(def_id)
            new_card.instance_flags.update(flags)
            if swift > 0:
                new_card.swift_value = swift
                new_card.instance_flags.add('swift')
            if magic_swift > 0:
                new_card.magic_swift_value = magic_swift
                new_card.instance_flags.add('magic_swift')
            if power > 0:
                new_card.power_value = power
                new_card.instance_flags.add('power')
            if extra_hits > 0:
                new_card.extra_hits = extra_hits
                new_card.setup_modifiers.add('explicit_extra_hits')
            self._apply_setup_modifiers_to_card(target_id, new_card)
            self._apply_forced_unique_copy_penalty(
                target_id,
                new_card,
                source_owned=(card is not None and getattr(card, 'def_id', None) == def_id),
            )
            ps.deck.insert(0, new_card)
            made.append(new_card)
        if log:
            self.log_msg(log)



    def _atomic_queue_auto_play(self, player_id, card, params, log, choice, context):
        """Register a card so it is played automatically at the owner's turn start."""
        if not self._valid_player_id(player_id):
            return
        source_card = self._resolve_card_ref(
            player_id, params.get('card', {'ref': 'current_card'}), card
        )
        if source_card is None:
            source_card = card
        if source_card is None:
            return
        markers = set(getattr(source_card, 'instance_flags', set()) or set())
        if markers & {'ocean_no_auto', self.AUTO_PLAY_QUEUE_MARKER}:
            # A copy produced by the queue never registers itself again.
            return
        if bool(params.get('once_per_play', True)):
            try:
                if int(getattr(source_card, 'fission_hit', 0) or 0) > 0:
                    # Fission replays the same play; only the first hit queues.
                    return
            except Exception:
                pass
        ps = self.players[player_id]
        queue = self._auto_play_queue_entries(ps, create=True)
        if bool(params.get('dedupe', False)):
            # 表格14 R170（魔法珍珠）：效果是"每个回合开始时自动对其打出1张"，
            # 不是"本局每打出过1次就多1张"。同一张牌的旧队列项先移除，只保留
            # 最新一次（目标也会跟着更新到最近一次选择）。
            source_def = str(getattr(source_card, 'def_id', '') or '')
            queue[:] = [
                existing for existing in queue
                if not (
                    isinstance(existing, dict)
                    and str(existing.get('def_id') or '') == source_def
                )
            ]
        max_entries = max(
            1,
            self._eval_int(
                player_id,
                params.get('max_entries', self.AUTO_PLAY_QUEUE_MAX_ENTRIES),
                card,
                self.AUTO_PLAY_QUEUE_MAX_ENTRIES,
            ),
        )
        if len(queue) >= max_entries:
            return
        target_spec = params.get('target', 'target')
        target_ref = None
        if self._is_dynamic_auto_play_target(target_spec):
            target_id = -1
            target_ref = target_spec
        else:
            target_id = self._resolve_target(player_id, target_spec)
        source = str(params.get('source', 'snapshot') or 'snapshot').strip().lower()
        if source not in ('snapshot', 'instance'):
            source = 'snapshot'
        entry = {
            'def_id': str(getattr(source_card, 'def_id', '') or ''),
            'source': source,
            'target_id': int(target_id),
            'target_ref': target_ref,
            'swift_value': self._eval_int(player_id, params.get('swift_value', 0), card, 0),
            'magic_swift_value': self._eval_int(
                player_id, params.get('magic_swift_value', 0), card, 0
            ),
            'exile': bool(params.get('exile', False)),
            'each_turn': bool(params.get('each_turn', True)),
            'cost': str(params.get('cost', 'normal') or 'normal').strip().lower(),
            'marker': str(params.get('marker') or self.AUTO_PLAY_QUEUE_MARKER),
            'require_selectable': bool(params.get('require_selectable', True)),
            'allow_self': bool(params.get('allow_self', False)),
            'log': str(params.get('log') or ''),
            'no_auto': True,
        }
        if source == 'instance':
            entry['card_instance_id'] = int(getattr(source_card, 'instance_id', -1) or -1)
        else:
            entry['card'] = source_card.to_dict() if hasattr(source_card, 'to_dict') else None
        queue.append(entry)


    _MULTI_TARGET_SELECTORS = (
        'all', 'all_players', 'all_enemies', 'all_others', 'all_except_self', 'all_selectable',
        'all_friendlies', 'wide_strike_targets', 'play_targets', 'target_players', 'both',
        'random_side',
    )







    def _atomic_equipment_op(self, player_id, card, params, log, choice, context):
        """Round 33 / 批次 AC：``equipment_op`` 伞（7 合 1）。

        统一参数 ``mode``：``place``（缺省，把牌置入装备栏，旧 ``place_as_equip``）、
        ``give``（造一张装备卡给目标，旧 ``add_equipment_to_zone``）、
        ``armor``（旧 ``add_equipment_armor``）、``destroy``（旧
        ``destroy_equipment``；内部再选 ``pick``=choice/random/all/self 与
        ``filter``/``record_count``）、``seal``（旧 ``seal_equipment``）、
        ``unprotect``（旧 ``remove_equip_protection``）、``each``（旧
        ``for_each_equipment``，收 ``body``/``steps`` 子步骤）。七段实现体与
        合并前逐字一致。
        """

        mode = str(params.get('mode') or params.get('action') or '').strip().lower()
        forwarded = dict(params)
        forwarded.pop('action', None)
        if mode in ('destroy', 'break', 'smash', '摧毁'):
            forwarded['mode'] = str(
                params.get('pick',
                          params.get('destroy',
                                    params.get('destroy_mode',
                                              params.get('sub_mode', 'choice'))))
                or 'choice'
            ).strip().lower()
            return self._equipment_op_destroy_payload(player_id, card, forwarded, log, choice, context)
        forwarded.pop('mode', None)
        if mode in ('', 'place', 'equip', 'self'):
            return self._equipment_op_place_payload(player_id, card, forwarded, log, choice, context)
        if mode in ('give', 'create', 'to_zone', 'zone'):
            return self._equipment_op_give_payload(player_id, card, forwarded, log, choice, context)
        if mode in ('armor', 'add_armor', 'shield'):
            return self._equipment_op_armor_payload(player_id, card, forwarded, log, choice, context)
        if mode in ('seal', 'dust', 'sealed'):
            return self._equipment_op_seal_payload(player_id, card, forwarded, log, choice, context)
        if mode in ('unprotect', 'remove_protection', 'protection_off'):
            return self._equipment_op_unprotect_payload(player_id, card, forwarded, log, choice, context)
        if mode in ('each', 'for_each', 'loop'):
            return self._equipment_op_each_payload(player_id, card, forwarded, log, choice, context)
        self._log_mod_runtime_error(
            'equipment_op', RuntimeError(f'unsupported mode: {mode}'), player_id, card,
        )

    def _equipment_op_place_payload(self, player_id, card, params, log, choice, context):
        # Round 33 / 批次 AC：``equipment_op(mode:"place")`` 的实现体（旧
        # ``place_as_equip``：把牌置入装备栏并跑装备步骤）。
        source = self.players[player_id]
        target_card = self._resolve_card_ref(player_id, params.get('card', {'ref': 'current_card'}), card)
        if target_card is None:
            return
        owner_expr = params.get('owner', params.get('equip_owner'))
        owner_id = self._resolve_target(player_id, owner_expr) if owner_expr is not None else player_id
        if owner_id < 0 or owner_id >= len(self.players):
            owner_id = player_id
        owner = self.players[owner_id]
        if target_card in source.hand:
            source.hand.remove(target_card)
        else:
            self._remove_card_from_current_zone(target_card)
        if self._find_equipment_for_card(owner_id, target_card) is None:
            target_card.durability = target_card.card_def.durability if getattr(target_card.card_def, 'durability', 0) > 0 else 3
            eq = EquipmentInstance(target_card, owner_id)
            if 'effect_target' in params:
                effect_target = self._resolve_target(player_id, params.get('effect_target'))
                if not (0 <= effect_target < len(self.players)) and isinstance(context, dict):
                    try:
                        effect_target = int(context.get('target_id', -1))
                    except Exception:
                        effect_target = -1
                if 0 <= effect_target < len(self.players):
                    eq.effect_target = effect_target
            else:
                selected_target = self._selected_choice_target(-1)
                if not (0 <= selected_target < len(self.players)) and isinstance(context, dict):
                    try:
                        selected_target = int(context.get('target_id', -1))
                    except Exception:
                        selected_target = -1
                if 0 <= selected_target < len(self.players):
                    eq.effect_target = selected_target
            owner.equipment.append(eq)
            if self._equipment_uses_non_stack_rule(eq):
                self._ensure_non_stack_equipment_order(eq)
            self._note_achievement_equipment_count(owner_id)
            self._refresh_hand_limit_bonuses()
            self._refresh_equipment_derived_player_flags(owner_id)
            self.log_msg(log or f"{self.pn(owner_id)}装备了{target_card.name_cn}")
            if self._card_has_flag(target_card, 'electric_web_arm_on_place'):
                arm_target = int(getattr(eq, 'effect_target', owner_id))
                if not (0 <= arm_target < len(self.players)):
                    arm_target = owner_id
                self._apply_electric_web_arm(owner_id, eq, arm_target, 2)
        if target_card is card:
            card._placed_as_equipment = True
            card._placed_as_equipment_owner = owner_id

    def _equipment_op_give_payload(self, player_id, card, params, log, choice, context):
        # Round 33 / 批次 AC：``equipment_op(mode:"give")`` 的实现体（旧
        # ``add_equipment_to_zone``：凭空造一张装备卡并挂到目标装备区）。
        card_id = self._resolve_card_id_ref(player_id, params.get('card', self.SETUP_CARD_LEAF), card)
        card_def = CARD_DEFS.get(card_id)
        if card_def is not None and not self._card_allowed(card_def.id):
            return
        owner_ids = self._resolve_targets(player_id, params.get('target', params.get('owner', 'self')))
        if not owner_ids:
            owner_ids = [player_id]
        if card_def is None:
            error_def = CARD_DEFS.get(ERROR_CARD_ID)
            if not error_def:
                return
            for owner_id in owner_ids:
                if owner_id < 0 or owner_id >= len(self.players):
                    continue
                new_card = CardInstance(def_id=ERROR_CARD_ID)
                self.players[owner_id].add_to_hand(new_card)
                self._remember_created_card(new_card, context if isinstance(context, dict) else None)
            return
        for owner_id in owner_ids:
            if owner_id < 0 or owner_id >= len(self.players):
                continue
            new_card = CardInstance(def_id=card_def.id)
            self._apply_setup_modifiers_to_card(owner_id, new_card)
            new_card.durability = card_def.durability if getattr(card_def, 'durability', 0) > 0 else 3
            eq = EquipmentInstance(new_card, owner_id)
            if 'effect_target' in params:
                effect_target = self._resolve_target(player_id, params.get('effect_target'))
                if 0 <= effect_target < len(self.players):
                    eq.effect_target = effect_target
            else:
                eq.effect_target = owner_id
            self.players[owner_id].equipment.append(eq)
            if self._equipment_uses_non_stack_rule(eq):
                self._ensure_non_stack_equipment_order(eq)
            self._note_achievement_equipment_count(owner_id)
            self._refresh_hand_limit_bonuses()
            self._refresh_equipment_derived_player_flags(owner_id)
            self._remember_created_card(new_card, context if isinstance(context, dict) else None)
            if log is False or params.get('silent') or params.get('no_log'):
                continue
            self.log_msg(log or f"{self.pn(owner_id)}获得装备{card_def.name_cn}")

    def _atomic_request(self, player_id, card, params, log, choice, context):
        """Round 36 / 批次 AD-1：请求族伞原子（旧 op 全部并进这里）。

        ``params["type"]``（扁平写法里是步骤的 ``type``，由 ``_run_effect_list``
        在执行前补进 ``params``）选类别：

        * ``target`` / ``card`` / ``confirm`` —— 占位返回 ``None``：真正的人机
          交互由引擎的 pending_choice 流程在出牌前处理（合并前这三个
          ``_atomic_*`` 就是空操作）。
        * ``zone`` / ``forced_target`` / ``discount_copy`` / ``reorder_deck`` ——
          交给各自的私有实现体（``_request_*_payload``，逐字搬运合并前的实现）。

        未知类别显式报错，不静默。
        """

        request_type = str(params.get('type') or '').strip().lower()
        if request_type in ('target', 'card', 'confirm', ''):
            return None
        if request_type == 'zone':
            return self._request_zone_payload(player_id, card, params, log, choice, context)
        if request_type == 'forced_target':
            return self._request_forced_target_payload(player_id, card, params, log, choice, context)
        if request_type == 'discount_copy':
            return self._request_discount_copy_payload(player_id, card, params, log, choice, context)
        if request_type == 'reorder_deck':
            return self._request_reorder_deck_payload(player_id, card, params, log, choice, context)
        raise V2ZoneError(
            f"request 只认 type=target/card/confirm/zone/forced_target/discount_copy/reorder_deck，"
            f"收到 {request_type!r}"
        )

    # Round 41 / 批次 AE-5：``response_declare`` 已删除——它是一条返回 ``None`` 的
    # 空占位步骤，从来没有行为；反制窗口由卡数据的 ``response_trigger`` 与引擎的
    # 响应/选择系统承载（``bio:indictment`` 在 Round 40 起也改用 ``card_var_change``）。
    # 旧名进 ``mod_spec_v2.REMOVED_ATOMIC_OPS``（替代写法为空 = 该 op 没有等价写法）。

    # Round 32 / 批次 AA：``aura_enemy_elixir_recovery`` 已并入
    # ``resource_op(mode:"aura_recovery")``（声明本身是空操作，数值由
    # ``_declared_aura_elixir_bonus`` 在回合开始的 E 回复里读）。

    # Round 31 / 批次 Z：``destroy_self_equipment`` / ``destroy_current_equipment``
    # 已并入 ``destroy_equipment(mode:"self")``（``source`` 仍是可选的摧毁者）。

    def _atomic_deal_damage(self, player_id, card, params, log, choice, context):
        # Round 15 / batch 3: the runtime branch resolves the selector as a set
        # (``target`` may be ``all`` / a list / a wide-strike snapshot), so the
        # engine atom iterates the same way instead of forcing one player.
        for target_id in self._resolve_targets(player_id, params.get('target', 'enemy')):
            self._deal_damage_to_target(player_id, card, params, log, choice, context, target_id)

    def _deal_damage_to_target(self, player_id, card, params, log, choice, context, target_id):
        """One target of a ``deal_damage`` step (shared parameter surface)."""

        if not self._valid_player_id(target_id):
            return
        amount = self._eval_int(player_id, params.get('amount', 6), card, 6)
        base_hits = self._eval_int(player_id, params.get('hits', 1), card, 1)
        # Data steps may opt out of the card's layered extra hits (子瓣/Fission extra
        # petals) so a fixed-hit segment keeps its own hit count.  Default keeps the
        # historical behaviour of inheriting the current card's extra hits.
        inherit_extra_hits = params.get('inherit_extra_hits', params.get('use_card_extra_hits', True)) is not False
        if inherit_extra_hits:
            hits = self._card_total_hits(card, base_hits)
        else:
            hits = clamp_damage_hits(base_hits)
        is_precision = bool(params.get('is_precision', params.get('precision', False)))
        is_precision = is_precision or 'precision' in self._effective_card_flags(card)
        amount = self._modified_attack_damage(amount, card)
        self._incoming_damage_hint[target_id] = int(amount)
        crit_bonus_multiplier = 1.0
        try:
            crit_bonus_multiplier = float(params.get('crit_bonus_multiplier', 1.0) or 1.0)
        except (TypeError, ValueError):
            crit_bonus_multiplier = 1.0
        crit_bonus_damage = self._eval_int(player_id, params.get('crit_bonus_damage', 0), card, 0)
        if params.get('precognition') and not is_precision and self._attack_will_crit_before_dodge(
            player_id, amount, hits, card
        ):
            # Temporary Precision for this play only; the bonus multiplier is
            # applied after shields by deal_attack_damage.
            is_precision = True
        force_crit = bool(params.get('force_crit', False))
        no_luck_crit = bool(params.get('no_luck_crit', False))
        old_force = getattr(card, '_hel_force_crit', False) if card is not None else False
        old_no_luck = getattr(card, '_hel_no_luck_crit', False) if card is not None else False
        prev_crit_hits = getattr(self, '_hel_current_crit_hits', 0)
        if card is not None:
            if force_crit:
                card._hel_force_crit = True
            if no_luck_crit:
                card._hel_no_luck_crit = True
        self._hel_current_crit_hits = 0
        try:
            dealt = self.deal_attack_damage(
                target_id,
                amount,
                hits,
                is_precision=is_precision,
                attacker_id=player_id,
                source_card=card,
                ignore_untargetable=bool(params.get('ignore_untargetable', False)),
                crit_bonus_multiplier=crit_bonus_multiplier,
                crit_bonus_damage=crit_bonus_damage,
            )
        except TypeError:
            dealt = self.deal_attack_damage(target_id, amount, hits, is_precision=is_precision)
        if params.get('power_once') is True and card is not None:
            # The Arctic Nuke spends its Power on the first segment only.
            try:
                if clamp_card_power(getattr(card, 'power_value', 0) or 0) > 0:
                    card.power_value = 0
                    card.instance_flags.discard('power')
            except Exception:
                pass
        crit_hits = int(getattr(self, '_hel_current_crit_hits', 0) or 0)
        self._hel_current_crit_hits = prev_crit_hits
        if card is not None:
            if force_crit and not old_force:
                card.__dict__.pop('_hel_force_crit', None)
            if no_luck_crit and not old_no_luck:
                card.__dict__.pop('_hel_no_luck_crit', None)
        self._last_attack_crit_hits = crit_hits
        self._last_damage_value[target_id] = int(dealt)
        on_crit = params.get('on_crit')
        if crit_hits > 0 and isinstance(on_crit, list):
            child_context = dict(context or {})
            child_context.update({
                'event': 'on_crit',
                'source_id': player_id,
                'target_id': target_id,
                'damage': int(dealt),
                'crit_hits': crit_hits,
            })
            child_context.setdefault('vars', {})['last_crit_hits'] = crit_hits
            self._run_effect_list(player_id, card, on_crit, choice, child_context)
        on_hit = params.get('on_hit')
        on_hit_once = params.get('on_hit_once')
        if dealt > 0 and isinstance(on_hit_once, list):
            # The per-target "hit once" callback the runtime branch already had;
            # e.g. Cryo Bomb's 5 frost layers hang off it.
            child_context = dict(context or {})
            child_context.update({
                'event': 'on_hit',
                'source_id': player_id,
                'target_id': target_id,
                'damage': int(dealt),
                'last_damage': int(dealt),
            })
            child_context.setdefault('vars', {})['target_id'] = target_id
            self._run_effect_list(player_id, card, on_hit_once, choice, child_context)
        if dealt > 0 and isinstance(on_hit, list):
            hit_count = 1
            try:
                hit_count = max(1, int((getattr(self, '_last_positive_damage_hits', []) or [])[target_id] or 0))
            except Exception:
                hit_count = 1
            for hit_index in range(hit_count):
                child_context = dict(context or {})
                child_context.update({
                    'event': 'on_hit',
                    'source_id': player_id,
                    'target_id': target_id,
                    'damage': int(dealt),
                    'hit_index': hit_index,
                })
                self._run_effect_list(player_id, card, on_hit, choice, child_context)
        # Round 28：伤害族统一日志开关——``silent``/``no_log``/``hide_log`` 与
        # ``log: false`` 等价（运行时分支走 ``_render_step_log``，这里对齐）。
        if log is not False and not step_is_silent(None, params) and log:
            self.log_msg(self._format_step_log(log, target=self.pn(target_id), source=self.pn(player_id)))

    def _atomic_defer_game_over(self, player_id, card, params, log, choice, context):
        """Run a body of steps with death checks deferred, then settle deaths once.

        Data counterpart of the ``_game_over_defer_depth`` wrappers the blood
        chromosome / arctic nuke atoms used: the body may drop a player to 0 HP
        mid-loop, but the death (and Yggdrasil revival) is only resolved after the
        whole body finished.

        Round 38 / 批次 AD-3（参数命名对齐）：body 键改走监听/循环族共用的
        ``listener_body_from_params``（``body`` → ``steps`` → ``effects``），与
        ``delayed_effect`` / ``on_event`` / ``for_each`` 同一口径；此前是本方法
        自己写的 ``body`` → ``effects`` → ``steps``。官方包只用 ``body``（2 步），
        两个键同时出现的步骤 0 处，所以顺序差异不影响任何既有数据。
        """
        body = listener_body_from_params(params)
        if not isinstance(body, list):
            body = []
        alive_before = getattr(self, '_deferred_card_alive_before', None)
        if not isinstance(alive_before, list):
            alive_before = [player.health > 0 for player in self.players]
        self._game_over_defer_depth += 1
        try:
            if body:
                self._run_effect_list(player_id, card, body, choice, context)
        finally:
            self._game_over_defer_depth = max(0, self._game_over_defer_depth - 1)
        self._game_over_defer_depth += 1
        try:
            self._finalize_deferred_card_deaths(alive_before)
        finally:
            self._game_over_defer_depth = max(0, self._game_over_defer_depth - 1)
        self._check_game_over()

    def _move_card_random_payload(self, player_id, card, params, log, choice, context):
        """Move random selectable cards from a zone into the target's hand.

        Round 33 / 批次 AB：``move_card(mode:"random")`` 的实现体（旧
        ``random_zone_card_to_hand``）——统一参数里来源区写 ``source_zone``，
        目的区固定 ``hand``；旧 ``zone``/``zones`` 写法继续认。

        ``zone``（或 ``zones``）接受 hand/deck/discard/exile，``count`` 是张数，
        ``tag`` 是给每张移出的牌打的 flag（升华牌永远不可选，和其它"选一张牌"
        的效果一致）。手牌满就停下，不会溢出。

        Round 14 / batch 2: 区域名走统一词表（``draw``/``draw_pile``/
        ``exile_pile`` 仍是别名），未知区域显式报错；``equipment`` 不是合法的
        取牌区（要拆装备请用 ``destroy_equipment``）；``target`` 按选择器集合
        解析，多目标时按顺序取第一个可用目标。
        """
        forwarded = dict(params)
        source_zone = forwarded.get('source_zone', forwarded.get('from'))
        if source_zone not in (None, ''):
            forwarded['zone'] = source_zone
            forwarded.pop('zones', None)
        raw_zone_target = str(forwarded.get('target_zone', 'hand') or 'hand').strip().lower()
        if normalize_zone_name(raw_zone_target, allow_equipment=False, op='move_card(mode:"random")', param='target_zone') != 'hand':
            raise V2ZoneError(f'move_card(mode:"random") 只能取进 hand，收到 {raw_zone_target!r}')
        target_ids = self._step_target_ids(
            player_id, card, forwarded, context, op='move_card', default='target',
        )
        zone_names = self._step_zone_names(
            forwarded, op='move_card', allow_equipment=False, default='discard',
        )
        if not target_ids or not zone_names:
            return
        target_id = target_ids[0]
        count = max(0, self._eval_int(player_id, params.get('count', 1), card, 1))
        tag = str(params.get('tag', '') or '').strip()
        tag = normalize_card_flag(tag) if tag else ''
        target = self.players[target_id]
        zones = [
            (zone_name, getattr(target, zone_name, None))
            for zone_name in zone_names
        ]
        zones = [(zone_name, zone) for zone_name, zone in zones if isinstance(zone, list)]
        if count <= 0 or not zones:
            return
        moved = 0
        for _ in range(count):
            if not target.can_add_to_hand():
                break
            candidates = [
                (zone_name, zone, candidate)
                for zone_name, zone in zones
                for candidate in list(zone)
                if self._card_selectable_by_action(candidate)
            ]
            if not candidates:
                break
            _zone_name, zone, picked = random.choice(candidates)
            zone.remove(picked)
            if tag:
                picked.instance_flags.add(tag)
                picked.disabled_flags.discard(tag)
            target.add_to_hand(picked)
            moved += 1
            per_card = params.get('per_card') or params.get('on_card') or params.get('after_each')
            if isinstance(per_card, list) and per_card:
                # Blood chromosome deals 2 damage to itself after every random
                # card it pulls out of the discard pile.
                self._run_effect_list(player_id, card, per_card, choice, context)
        if params.get('silent') or log is False:
            return
        if log:
            if moved > 0:
                self.log_msg(self._format_step_log(
                    log, target=self.pn(target_id), source=self.pn(player_id), amount=moved, count=moved,
                ))
            elif params.get('empty_log'):
                self.log_msg(self._format_step_log(
                    params.get('empty_log'), target=self.pn(target_id),
                    source=self.pn(player_id), amount=0, count=0,
                ))
            return
        zone_label = '/'.join(self._zone_log_label(zone_name) for zone_name in zone_names)
        if moved > 0:
            extra = f"并使其获得{self._card_flag_log_text(tag)}" if tag else ''
            self.log_msg(f"{self.pn(target_id)}从{zone_label}中随机获得{moved}张牌{extra}")
        else:
            self.log_msg(f"{self.pn(target_id)}的{zone_label}没有可加入手牌的牌")

    def _equipment_op_seal_payload(self, player_id, card, params, log, choice, context):
        # Round 33 / 批次 AC：``equipment_op(mode:"seal")`` 的实现体（旧
        # ``seal_equipment``：给目标所有装备叠尘封层数）。
        """Seal every piece of equipment on the target(s) by ``amount`` layers."""
        amount = max(0, self._eval_int(player_id, params.get('amount', 1), card, 1))
        if amount <= 0:
            return
        for target_id in self._resolve_step_targets(player_id, card, params.get('target', 'target'), context):
            if not self._valid_player_id(target_id):
                continue
            affected = 0
            for eq in list(getattr(self.players[target_id], 'equipment', []) or []):
                if self._apply_sealed_to_equipment(target_id, eq, amount) > 0:
                    affected += 1
            if affected <= 0 or params.get('silent') or log is False:
                continue
            if log:
                self.log_msg(self._format_step_log(
                    log, target=self.pn(target_id), source=self.pn(player_id), amount=amount, count=affected,
                ))
            else:
                self.log_msg(f"{self.pn(target_id)}的{affected}张装备获得{amount}层尘封")

    _MULTI_TARGET_SELECTORS = (
        'all', 'all_players', 'all_enemies', 'all_others', 'all_except_self', 'all_selectable',
        'all_friendlies', 'wide_strike_targets', 'play_targets', 'target_players', 'both',
        'random_side',
    )

    def _resolve_step_targets(self, player_id, card, selector, context=None):
        """Player list for a generic data step.

        Scalar selectors keep the single-target semantics the replaced bespoke
        atoms used; only an explicit list or a known multi-target selector expands
        to several players.
        """
        if isinstance(selector, (list, tuple, set)):
            return self._list_effect_targets(player_id, card, selector, context)
        if isinstance(selector, str) and selector.strip().lower() in self._MULTI_TARGET_SELECTORS:
            return self._list_effect_targets(player_id, card, selector, context)
        target_id = self._resolve_target(player_id, selector)
        return [target_id] if self._valid_player_id(target_id) else []

    # ------------------------------------------------------------------
    # Round 14 / 批次 2：区域、位置与选择器的统一入口
    #
    # 词表（hand/deck/discard/exile/equipment、top/bottom/random/random_top）
    # 单点定义在 mod_runtime_v2，两条执行路径共用；这里只做"从步骤参数里取
    # 出来 + 落到引擎的解析器上"。未知区域/位置抛 V2ZoneError，由
    # `_run_effect_list` 记成 mod 运行时错误（不再静默变成"什么也不做"或
    # "进弃牌堆"）。
    # ------------------------------------------------------------------
    def _step_zone_names(self, params, *, op, allow_equipment=True, default='hand'):
        """步骤的区域参数：``zones``（多区，优先）或 ``zone``（单区）。

        参数缺失/为空时用 ``default``（与旧行为一致）；写了**不认识**的区域名则
        显式报错。
        """
        raw = params.get('zones')
        if raw is None:
            raw = params.get('zone', default)
        if raw in (None, ''):
            raw = default
        return normalize_zone_names(raw, allow_equipment=allow_equipment, op=op, param='zone/zones')

    @staticmethod
    def _player_zone_cards(ps, zone_name):
        """One player's cards in a zone; ``equipment`` yields the attached instances."""
        if zone_name == 'equipment':
            return [
                getattr(equipment, 'card_instance', None)
                for equipment in list(getattr(ps, 'equipment', []) or [])
            ]
        return list(getattr(ps, zone_name, []) or [])

    def _assert_step_zone(self, params, expected, *, op, allow_equipment=False):
        """目的区由 op 名决定；数据若另写 ``zone``/``to`` 就必须自洽。

        ``move_to_deck(zone:"hand")`` 这类自相矛盾的写法以前会被静默忽略
        （按 op 名入堆），现在直接报错，避免"看着像改了目的区"的假象。
        """
        raw = params.get('zone')
        if raw in (None, ''):
            raw = params.get('to')
        if raw in (None, ''):
            return expected
        canonical = normalize_zone_name(
            raw, allow_equipment=allow_equipment, op=op, param='zone',
        )
        if canonical != expected:
            raise V2ZoneError(
                f"{op} 的目的区固定为 {expected}，数据里的 zone/to={raw!r} 与它冲突；"
                f"要改目的区请用 move_card(zone=...)"
            )
        return expected

    def _step_zone_position(self, params, *, op, default='top'):
        """统一位置参数（``random_top`` 对单张牌等同 ``top``）。"""
        return normalize_zone_position(params.get('position', default), op=op)

    def _step_zone_position_or_none(self, params, *, op):
        """给 hand/discard/exile 用的位置参数：只校验取值，不改变落点。"""
        if params.get('position') in (None, ''):
            return None
        return normalize_zone_position(params.get('position'), op=op)

    def _step_target_ids(self, player_id, card, params, context=None, *,
                         op, default='self', keys=SELECTOR_TARGET_KEYS):
        """统一的玩家选择器解析：集合语义 + ``first``/``exclude``/``relation``/
        ``allow_self``/``filter`` 修饰键。

        标量选择器（``self``/``enemy``/``target``…）仍然解析成一个目标，只有显式
        列表、已知多目标选择器（``all_players``/``play_targets``…）或
        ``wide_strike_targets`` 上下文才展开——旧写法因此保持原样。
        """
        raw = None
        for key in keys:
            if params.get(key) is not None:
                raw = params.get(key)
                break
        if raw is None:
            raw = default
        targets = self._list_effect_targets(player_id, card, raw, context)

        exclude_ref = params.get('exclude')
        if exclude_ref is not None and targets:
            excluded = set()
            refs = exclude_ref if isinstance(exclude_ref, (list, tuple, set)) else [exclude_ref]
            for ref in refs:
                for target_id in self._list_effect_targets(player_id, card, ref, context):
                    excluded.add(target_id)
            if excluded:
                targets = [target_id for target_id in targets if target_id not in excluded]

        if params.get('allow_self') is False:
            targets = [target_id for target_id in targets if target_id != player_id]

        relation = str(params.get('relation', '') or '').strip().lower()
        if relation and relation != 'any':
            if relation in ('enemy', 'enemies', 'opponent', 'opponents'):
                targets = [
                    target_id for target_id in targets
                    if self._opposite_timer_side(player_id, target_id)
                ]
            elif relation in ('friendly', 'ally', 'allies', 'team', 'same_side'):
                targets = [
                    target_id for target_id in targets
                    if self._same_timer_side(player_id, target_id)
                ]
            else:
                raise V2ZoneError(
                    f"{op} 的 relation 不支持取值 {relation!r}；只支持 enemy/friendly"
                )

        filter_spec = None
        for key in SELECTOR_FILTER_KEYS:
            if params.get(key) is not None:
                filter_spec = params.get(key)
                break
        if filter_spec is not None and targets:
            targets = [
                target_id for target_id in targets
                if self._eval_condition(target_id, filter_spec, card)
            ]

        for key in SELECTOR_FIRST_KEYS:
            value = params.get(key)
            if value in (None, False):
                continue
            if isinstance(value, str) and value.strip().lower() in ('false', 'no', 'off', '0'):
                continue
            targets = targets[:1]
            break
        return targets

    def _resolve_step_number(self, player_id, value, card=None, default=0) -> int:
        """Evaluate a step number, preferring the effect context for ``var``.

        Engine-path steps (timer bodies, loops) are evaluated by
        :meth:`_eval_expr`, whose ``var`` reads the player's ``custom_vars``;
        bodies that come from the v2 runtime keep their temporaries in the
        effect context instead.  Both spellings must work for converted cards.
        """
        if isinstance(value, dict):
            ref = value.get('op') or value.get('ref') or value.get('type')
            name = str(value.get('name', value.get('var', '')) or '')
            if ref in ('var', 'temp_var') and name and not value.get('target'):
                context = getattr(self, '_active_effect_context', {}) or {}
                context_vars = context.get('vars') if isinstance(context, dict) else None
                if isinstance(context_vars, dict) and name in context_vars:
                    try:
                        return int(self._scalar_value(context_vars.get(name), default) or 0)
                    except (TypeError, ValueError):
                        return default
        return self._eval_int(player_id, value, card, default)

    def _resolve_step_card_batch(self, player_id, card, selector, context=None, choice=None):
        """Resolve a data-step card batch reference into card instances."""
        if selector is None:
            return []
        if isinstance(selector, (list, tuple, set)):
            batch = []
            for item in selector:
                for card_instance in self._resolve_step_card_batch(player_id, card, item, context, choice):
                    if card_instance not in batch:
                        batch.append(card_instance)
            return batch
        if isinstance(selector, CardInstance):
            return [selector]
        context = context if isinstance(context, dict) else (getattr(self, '_active_effect_context', {}) or {})
        choice = choice if isinstance(choice, dict) else (getattr(self, '_active_choice', None) or {})

        def _from_choice():
            ids = []
            if choice.get('target_instance_id') is not None:
                ids.append(choice.get('target_instance_id'))
            if isinstance(choice.get('target_instance_ids'), list):
                ids.extend(choice.get('target_instance_ids'))
            cards = []
            for instance_id in ids:
                found = self._find_card_by_instance_id(instance_id)
                if found is not None and self._card_selectable_by_action(found) and found not in cards:
                    cards.append(found)
            return cards

        def _named_cards(*keys):
            for key in keys:
                value = context.get(key) if isinstance(context, dict) else None
                if isinstance(value, list):
                    cards = [item for item in value if isinstance(item, CardInstance)]
                    if cards:
                        return cards
                elif isinstance(value, CardInstance):
                    return [value]
            return []

        if isinstance(selector, dict):
            ref = str(selector.get('ref') or selector.get('op') or selector.get('type') or '').strip().lower()
            if ref in ('selected_cards', 'chosen_cards', 'selected_card_list'):
                return _named_cards('chosen_cards', 'selected_cards') or _from_choice()
            if ref in ('selected_card', 'chosen_card', 'choice_card'):
                return _named_cards('chosen_card', 'selected_card') or _from_choice()[:1]
            if ref == 'current_card':
                return [card] if isinstance(card, CardInstance) else []
            if ref == 'card':
                found = self._resolve_card_ref(player_id, selector.get('card'), card)
                return [found] if isinstance(found, CardInstance) else []
            return []
        text = str(selector).strip().lower()
        if text in ('selected_cards', 'chosen_cards', 'selected_card_list'):
            return _named_cards('chosen_cards', 'selected_cards') or _from_choice()
        if text in ('selected_card', 'chosen_card', 'choice_card'):
            return _named_cards('chosen_card', 'selected_card') or _from_choice()[:1]
        if text in ('current_card', 'this_card'):
            return [card] if isinstance(card, CardInstance) else []
        return []

    def _move_card_batch_payload(self, player_id, card, params, log, choice, context):
        """Move a batch of cards into the owner's deck.

        Round 33 / 批次 AB：``move_card(mode:"batch")`` 的实现体（旧
        ``move_cards_to_deck``）——统一参数 ``cards``（一批牌，缺省
        ``selected_cards``）、``target_zone``（固定 ``deck``）、``owner``/``target``、
        ``position``、``silent``、``log``。

        ``position`` is ``top`` (default), ``bottom``, ``random`` (one random slot
        each) or ``random_top`` (shuffle the moved cards first, then put the whole
        block on top - the desert compass order).
        """
        # Round 14 / batch 2: 目的区（deck）+ 位置词表（含 random_top 及其历史别名
        # ``shuffled_top``）走统一校验；``owner``/``target`` 按选择器解析，一批牌
        # 只能进一个牌堆，所以取第一个有效目标。
        raw_zone = params.get('target_zone', params.get('zone', 'deck'))
        zone_name = normalize_zone_name(
            raw_zone, allow_equipment=False, op='move_card(mode:"batch")', param='target_zone',
        )
        if zone_name not in ('deck', 'discard', 'exile'):
            raise V2ZoneError(
                f'move_card(mode:"batch") 只能进 deck/discard/exile，收到 {raw_zone!r}'
            )
        self._assert_step_zone(params, zone_name, op='move_card')
        if zone_name == 'deck':
            position = self._step_zone_position(params, op='move_card')
        else:
            # 弃牌堆 / 放逐区没有位置概念；仍走词表校验（写了非法值会显式报错）。
            self._step_zone_position_or_none(params, op='move_card')
            position = 'top'
        # Round 40 / 批次 AE-4：``source_zone`` 存在时改走"按 filter 批量搬区域牌"的
        # 形态（每人各搬自己的区域），``cards`` 选择器那条老路径逐字保持不变。
        source_zone = str(params.get('source_zone') or '').strip().lower()
        if source_zone:
            return self._move_card_batch_zone_payload(
                player_id, card, params, log, choice, context,
                source_zone=normalize_zone_name(
                    source_zone, allow_equipment=False,
                    op='move_card(mode:"batch")', param='source_zone',
                ),
                target_zone=zone_name,
            )
        owner_ids = self._step_target_ids(
            player_id, card, params, context, op='move_card',
            default='self', keys=('owner', 'target'),
        )
        owner_id = owner_ids[0] if owner_ids else player_id
        raw_ref = params.get('cards', 'selected_cards')
        batch = self._resolve_step_card_batch(player_id, card, raw_ref, context, choice)
        if not batch and isinstance(raw_ref, str) and raw_ref.strip().lower() in ('hand', 'deck', 'discard', 'exile'):
            zone = getattr(self.players[owner_id], raw_ref.strip().lower(), None)
            batch = list(zone) if isinstance(zone, list) else []
        ps = self.players[owner_id]
        moved = []
        for card_instance in batch:
            if not isinstance(card_instance, CardInstance) or card_instance is card:
                continue
            holder_id, zone_name, _ = self._find_card_location(card_instance)
            if holder_id is None or zone_name not in ('hand', 'deck', 'discard', 'exile'):
                continue
            holder = self.players[holder_id] if self._valid_player_id(holder_id) else None
            zone = getattr(holder, zone_name, None) if holder is not None else None
            if isinstance(zone, list) and card_instance in zone:
                zone.remove(card_instance)
            if card_instance not in moved:
                moved.append(card_instance)
        if not moved:
            if log and params.get('empty_log'):
                self.log_msg(self._format_step_log(
                    params.get('empty_log'), target=self.pn(owner_id), source=self.pn(player_id),
                    amount=0, count=0,
                ))
            return
        if position == 'bottom':
            ps.deck.extend(moved)
        elif position == 'random_top':
            random.shuffle(moved)
            ps.deck[0:0] = moved
        elif position == 'random':
            for card_instance in moved:
                index = random.randint(0, len(ps.deck))
                ps.deck.insert(index, card_instance)
        else:
            ps.deck[0:0] = moved
        if params.get('silent') or log is False:
            return
        if log:
            self.log_msg(self._format_step_log(
                log, target=self.pn(owner_id), source=self.pn(player_id), amount=len(moved), count=len(moved),
            ))
            return
        if position == 'bottom':
            self.log_msg(f"{self.pn(owner_id)}将{len(moved)}张牌置于抽牌堆底")
        elif position == 'random_top':
            self.log_msg(f"{self.pn(owner_id)}将{len(moved)}张牌随机置于抽牌堆顶")
        elif position == 'random':
            self.log_msg(f"{self.pn(owner_id)}将{len(moved)}张牌随机放入抽牌堆")
        else:
            self.log_msg(f"{self.pn(owner_id)}将{len(moved)}张牌置于抽牌堆顶")

    def _move_card_batch_zone_payload(self, player_id, card, params, log, choice, context,
                                      *, source_zone: str, target_zone: str):
        """``move_card(mode:"batch", source_zone:…)``：按 ``filter`` 批量搬区域里的牌。

        Round 40 / 批次 AE-4：通用能力先行 —— 旧 ``discard_hand_by_paid_e``
        （"风吹走全场 E 消耗不超过 X 的手牌"）需要的"按条件批量弃手牌"在这里
        下沉成数据：``owner``/``target`` 按**集合**语义解析（``all_players``
        这类选择器每人各搬一次），``source_zone`` 选来源区，``filter`` 复用
        选牌窗口那张规格表（``card_type``/``exclude_flags``/``max_cost_e``/
        ``exclude_error``…），``amount``/``count`` 限定每人最多搬几张（默认全部）。

        ``target_zone`` 只认 ``discard`` / ``exile``（进 ``hand``/``deck`` 的
        批量搬牌仍走 ``cards`` 选择器那条老路径，顺序语义更明确）。弃牌走
        :meth:`_discard_card_and_note`（``count_as_active_discard`` 默认 true，
        与旧原子一致），放逐走 :meth:`_put_card_in_exile`；战报只在真的搬走了
        牌时打印（``{source}``/``{target}``/``{count}``/``{amount}`` 由数据提供模板）。
        """

        if target_zone not in ('discard', 'exile'):
            raise V2ZoneError(
                f'move_card(mode:"batch") 的 source_zone 形态只支持 target_zone=discard/exile，'
                f'收到 {target_zone!r}；进 hand/deck 请改用 cards 选择器'
            )
        # ``filter`` 在这里是**卡牌**筛选规格（与取牌窗口同一张表）。玩家集合
        # 走 ``owner``/``target`` 选择器本身，不能交给 ``_step_target_ids``——
        # 那条路会把 ``filter`` 当成"筛选玩家"的条件用。
        owner_ids = self._list_effect_targets(
            player_id, card, params.get('owner', params.get('target', 'self')), context,
        )
        exclude_ids = set()
        if params.get('exclude') is not None:
            for target_id in self._list_effect_targets(player_id, card, params.get('exclude'), context):
                exclude_ids.add(target_id)
        if exclude_ids:
            owner_ids = [target_id for target_id in owner_ids if target_id not in exclude_ids]
        if not owner_ids:
            owner_ids = [player_id]
        spec = params.get('filter')
        spec = dict(spec) if isinstance(spec, dict) else {}
        spec['zone'] = source_zone
        limit_raw = params.get('amount', params.get('count'))
        if limit_raw in (None, '', 'all', '全部'):
            limit = None
        else:
            limit = max(0, self._eval_int(player_id, limit_raw, card, 0))
        count_as_active_discard = params.get('count_as_active_discard', True) is not False
        moved = 0
        for owner_id in (owner_ids or [player_id]):
            if not self._valid_player_id(owner_id):
                continue
            zone = getattr(self.players[owner_id], source_zone, None)
            if not isinstance(zone, list) or not zone:
                continue
            candidates = self._filter_candidates(
                {**spec, 'owner': owner_id}, player_id,
                source_card=card, default_owner_id=owner_id,
            )
            if limit is not None:
                candidates = candidates[:limit]
            for target_card in candidates:
                if target_card not in zone:
                    continue
                zone.remove(target_card)
                if target_zone == 'discard':
                    self._discard_card_and_note(owner_id, target_card, count_as_active_discard)
                else:
                    self._put_card_in_exile(owner_id, target_card)
                moved += 1
        if moved <= 0:
            if log and params.get('empty_log'):
                self.log_msg(self._format_step_log(
                    params.get('empty_log'), target=self.pn(player_id), source=self.pn(player_id),
                    amount=0, count=0,
                ))
            return
        if params.get('silent') or params.get('no_log') or params.get('hide_log') or log is False:
            return
        if log:
            self.log_msg(self._format_step_log(
                log, target=self.pn(player_id), source=self.pn(player_id),
                amount=moved, count=moved,
            ))
            return
        label = '弃牌堆' if target_zone == 'discard' else '放逐区'
        self.log_msg(f"{self.pn(player_id)}将{moved}张牌移入{label}")

    def _status_field_for(self, status: str) -> str:
        key = str(status or '').strip()
        if not key:
            return ''
        if key in STATUS_FIELD_ALIASES:
            return STATUS_FIELD_ALIASES[key]
        lowered = key.lower()
        if lowered in STATUS_FIELD_ALIASES:
            return STATUS_FIELD_ALIASES[lowered]
        return ''

    def _clear_player_statuses(self, target_id: int, statuses='all', include_custom: bool = True) -> int:
        """Clear statuses on one player; returns how many status kinds were cleared."""
        if not self._valid_player_id(target_id):
            return 0
        ps = self.players[target_id]
        clear_all = True
        if isinstance(statuses, str):
            clear_all = statuses.strip().lower() in ('all', '*', '')
            names = [] if clear_all else [statuses]
        elif isinstance(statuses, (list, tuple, set)):
            names = [str(item) for item in statuses]
            clear_all = False
        else:
            names = []
            clear_all = True
        cleared = 0
        fields = list(CLEARABLE_STATUS_FIELDS) if clear_all else []
        custom_names = []
        for name in names:
            attr = self._status_field_for(name)
            if attr:
                fields.append(attr)
            elif name:
                custom_names.append(name)
        for attr in dict.fromkeys(fields):
            current = getattr(ps, attr, 0)
            if attr == 'nazar':
                if self._nazar_status_value(target_id) > 0:
                    cleared += 1
                self._set_nazar_status_value(target_id, 0)
                continue
            if isinstance(current, bool):
                if current:
                    cleared += 1
                setattr(ps, attr, False)
            else:
                try:
                    if int(current or 0) > 0:
                        cleared += 1
                except (TypeError, ValueError):
                    pass
                setattr(ps, attr, 0)
        custom = getattr(ps, 'custom_statuses', {}) or {}
        if include_custom:
            if clear_all:
                if any(int(value or 0) > 0 for value in custom.values()):
                    cleared += 1
                ps.custom_statuses = {}
            else:
                for name in custom_names:
                    if name in custom:
                        cleared += 1
                    self._set_custom_status_value(target_id, name, 0)
        for attr in dict.fromkeys(fields):
            try:
                self._normalize_status_value(ps, attr)
            except Exception:
                continue
        return cleared

    def _status_op_clear_payload(self, player_id, card, params, log, choice, context):
        # Round 33 / 批次 AC：本方法从公开原子降为 ``status_op(op:"clear")`` 的
        # 实现体（preset 名单式清状态，名单与默认战报逐字保留）。
        """Clear a status (or every status) from the target(s).

        ``statuses`` is ``"all"`` (default) or a list of status ids/aliases;
        ``include_custom`` also drops mod-defined custom statuses.

        Round 24：``preset`` (``buffs`` / ``debuffs`` / ``all``) 覆盖了原来的
        ``clear_buffs`` / ``clear_debuffs`` / ``clear_all_effects`` 三个专用 op——
        三张名单与默认战报都原样保留（见 ``CLEAR_STATUS_PRESETS``）。
        """
        preset = str(params.get('preset', '') or '').strip().lower()
        if preset:
            if preset not in self.CLEAR_STATUS_PRESETS and preset != 'all':
                return
            cleared_targets = []
            for target_id in self._list_effect_targets(player_id, card, params.get('target', 'self'), context):
                if self._clear_status_preset(target_id, preset) > 0:
                    cleared_targets.append(target_id)
            if not cleared_targets or params.get('silent') or log is False:
                return
            if log:
                self.log_msg(self._format_step_log(
                    log, target=self.pn(cleared_targets[0]), source=self.pn(player_id),
                    count=len(cleared_targets),
                ))
                return
            label = self.CLEAR_STATUS_PRESET_LABELS.get(preset, '所有效果')
            for target_id in cleared_targets:
                self.log_msg(f"{self.pn(target_id)}的{label}已清除")
            return
        statuses = params.get('statuses', params.get('status', 'all'))
        include_custom = params.get('include_custom', params.get('custom', True)) is not False
        cleared_targets = []
        for target_id in self._list_effect_targets(player_id, card, params.get('target', 'self'), context):
            if self._clear_player_statuses(target_id, statuses, include_custom=include_custom) > 0:
                cleared_targets.append(target_id)
        if not cleared_targets or params.get('silent') or log is False:
            return
        if log:
            self.log_msg(self._format_step_log(
                log, target=self.pn(cleared_targets[0]), source=self.pn(player_id), count=len(cleared_targets),
            ))

    def _settle_status_for_player(self, actor_id, target_id: int, status: str,
                                  decay: bool = True, fill_from: Optional[dict] = None,
                                  source_label: str = '') -> int:
        """Resolve one damage-over-time status once, reusing the engine's helpers."""
        if not self._valid_player_id(target_id):
            return 0
        ps = self.players[target_id]
        status_key = str(status or 'poison').strip().lower()
        immune = self._is_status_immune(target_id)
        fill_status = ''
        ensure = 0
        when_empty = True
        refill = True
        if isinstance(fill_from, dict):
            fill_status = str(fill_from.get('status') or fill_from.get('id') or '').strip()
            try:
                ensure = max(0, int(fill_from.get('ensure', 1) or 0))
            except (TypeError, ValueError):
                ensure = 0
            when_empty = fill_from.get('when_empty', True) is not False
            refill = fill_from.get('refill', True) is not False
        if status_key in ('poison', '中毒', 'p', 'toxic_damage'):
            if fill_status and not immune:
                raw_stacks = max(0, int(self._get_status_count(target_id, fill_status) or 0))
                if raw_stacks <= 0 and ensure > 0:
                    self._add_custom_status_value(target_id, fill_status, ensure)
                    raw_stacks = max(0, int(self._get_status_count(target_id, fill_status) or 0))
                if when_empty and int(ps.poison or 0) <= 0 and raw_stacks > 0:
                    ps.poison += raw_stacks
                    self._normalize_status_value(ps, 'poison')
            dealt = 0
            if int(ps.poison or 0) > 0 and not immune:
                dealt = int(self._deal_direct_damage(
                    target_id,
                    int(ps.poison),
                    source_label or '中毒',
                    actor_id,
                    damage_type=DAMAGE_TYPE_MAGIC,
                    damage_tag=DAMAGE_TAG_POISON,
                ) or 0)
            if decay:
                self._decay_poison_after_turn_start(target_id)
                if refill:
                    self._apply_toxic_poison_after_poison_settlement(target_id)
            return dealt
        if status_key in ('burn', 'fire', '灼烧'):
            stacks = max(0, int(getattr(ps, 'fire', 0) or 0))
            dealt = 0
            if stacks > 0 and not immune:
                dealt = int(self._deal_direct_damage(
                    target_id,
                    stacks,
                    source_label or '灼烧',
                    actor_id,
                    damage_type=DAMAGE_TYPE_MAGIC,
                    damage_tag=DAMAGE_TAG_FIRE,
                ) or 0)
            if decay:
                ps.fire = 0
            return dealt
        stacks = max(0, int(self._get_status_count(target_id, status_key) or 0))
        if stacks > 0 and decay:
            self._clear_player_statuses(target_id, [status_key], include_custom=True)
        return 0

    def _status_op_settle_payload(self, player_id, card, params, log, choice, context):
        # Round 33 / 批次 AC：本方法从公开原子降为 ``status_op(op:"settle")`` 的
        # 实现体（DoT 结算唯一实现）。
        """Resolve a status immediately (poison/burn damage, decay, toxic refill).

        ``fill_from`` can name another status that supplies the settled status when
        it is empty (``{"status": "jungle:toxic_poison", "when_empty": true}``);
        ``after`` runs data steps once the settlement finished.

        Round 31 / 批次 Z：``reduce``（别名 ``reduce_amount`` / ``decay_amount``）
        走"结算一次 + 只减 N 层"的分支，吸收旧 ``resolve_status_once``（默认
        ``status:"fire"``、``reduce:1``）——伤害来源标签、伤害类型与默认战报
        逐字保留；不写 ``reduce`` 时仍是"整段清零"的 ``decay`` 口径。
        """
        status = str(params.get('status', 'poison') or 'poison')
        reduce_raw = params.get('reduce', params.get('reduce_amount', params.get('decay_amount')))
        if reduce_raw is not None:
            return self._settle_status_with_reduce(
                player_id, card, params, log, status, reduce_raw,
            )
        decay = params.get('decay', True) is not False
        fill_from = params.get('fill_from') if isinstance(params.get('fill_from'), dict) else None
        source_label = str(params.get('source_label') or params.get('source') or '')
        after = params.get('after', params.get('body', params.get('effects')))
        results = []
        for target_id in self._list_effect_targets(player_id, card, params.get('target', 'target'), context):
            if not self._valid_player_id(target_id):
                continue
            dealt = self._settle_status_for_player(
                player_id, target_id, status, decay=decay, fill_from=fill_from, source_label=source_label,
            )
            results.append((target_id, int(dealt or 0)))
        if isinstance(after, list) and after:
            child_context = dict(context or {})
            child_context['last_damage'] = sum(dealt for _, dealt in results)
            self._run_effect_list(player_id, card, after, choice, child_context)
        if params.get('silent') or log is False:
            return
        if log:
            total = sum(dealt for _, dealt in results)
            self.log_msg(self._format_step_log(
                log,
                target=self.pn(results[0][0]) if results else '',
                source=self.pn(player_id),
                amount=total,
                count=len(results),
            ))

    def _settle_status_with_reduce(self, player_id, card, params, log, status, reduce_raw):
        """Round 31 / 批次 Z：旧 ``resolve_status_once`` 的实现体（整段搬过来）。

        只结算 ``stacks`` 点伤害并把层数减 ``reduce``（不是清零），默认战报是
        ``"{target}的{status}结算{amount}点并减少{N}层"``。``log: false`` 现在
        与其他步骤一样静音（旧实现把 ``log: false`` 当成"用默认战报"，是
        Round 31 顺手统一的偏差，见报告）。
        """

        status = str(status or 'fire')
        reduce_amount = self._eval_int(player_id, reduce_raw, card, 1)
        for target_id in self._resolve_targets(player_id, params.get('target', 'target')):
            if not self._valid_player_id(target_id):
                continue
            ps = self.players[target_id]
            attr = self._status_attr_field(status) or ''
            if attr == 'fire' or str(status).strip().lower() in ('burn', 'fire', '灼烧'):
                stacks = max(0, int(getattr(ps, 'fire', 0) or 0))
            elif attr == 'poison' or str(status).strip().lower() in ('poison', '中毒', 'p'):
                stacks = max(0, int(getattr(ps, 'poison', 0) or 0))
            else:
                stacks = max(0, int(self._get_status_count(target_id, status) or 0))
            dealt = 0
            if stacks > 0 and not self._is_status_immune(target_id):
                label = str(params.get('source_label') or params.get('source') or '')
                if attr == 'fire' or str(status).strip().lower() in ('burn', 'fire', '灼烧'):
                    dealt = self._deal_direct_damage(
                        target_id,
                        stacks,
                        label or '灼烧',
                        damage_type=DAMAGE_TYPE_MAGIC,
                        damage_tag=DAMAGE_TAG_FIRE,
                    )
                else:
                    dealt = self._deal_direct_damage(
                        target_id,
                        stacks,
                        label or self._status_log_label(status),
                        damage_type=DAMAGE_TYPE_MAGIC,
                    )
            if stacks > 0:
                remaining = max(0, stacks - max(0, reduce_amount))
                if attr == 'fire':
                    ps.fire = remaining
                elif attr == 'poison':
                    ps.poison = remaining
                else:
                    self._remove_named_status_layers(target_id, status, max(0, reduce_amount))
                self._normalize_status_value(ps, status)
            if log is False or params.get('silent'):
                continue
            self.log_msg(
                self._format_step_log(
                    log, target=self.pn(target_id), amount=int(dealt or 0),
                    stacks=stacks, reduce=max(0, reduce_amount), count=int(dealt or 0),
                )
                or f"{self.pn(target_id)}的{self._status_log_label(status)}结算"
                   f"{int(dealt or 0)}点并减少{max(0, reduce_amount)}层"
            )

    def _atomic_direct_damage(self, player_id, card, params, log, choice, context):
        target_id = self._resolve_target(player_id, params.get('target', 'enemy'))
        if not self._valid_player_id(target_id):
            return
        amount = self._eval_int(player_id, params.get('amount', 1), card, 1)
        # Round 28（伤害族词汇表）：``source_text`` → ``source_name`` → ``label``
        # 三级回落与运行时分支对齐；都不写才回落到 ``source``（旧行为）与卡名。
        source = params.get('source_text') or params.get('source_name') or params.get('label')
        if source is None:
            source = params.get('source', card.name_cn if card else '效果')
        source = str(source)
        damage_type = params.get('damage_type')
        damage_tag = params.get('damage_tag')
        # ``hits`` lets one data step resolve several independent damage
        # instances (e.g. a 5-hit electric discharge that follows 子瓣), with
        # per-hit ``on_hit`` callbacks exactly like ``deal_damage``.
        hits = max(1, self._eval_int(player_id, params.get('hits', 1), card, 1))
        if params.get('inherit_extra_hits', params.get('use_card_extra_hits', False)) is True and card is not None:
            # Opt-in: a segment that should grow with the card's 子瓣/extra hits.
            hits = max(1, self._card_total_hits(card, hits))
        total = 0
        positive_hits = 0
        silent_damage = log is False or step_is_silent(None, params)
        for _ in range(hits):
            dealt = max(0, int(self._deal_direct_damage(
                target_id,
                amount,
                source,
                player_id,
                damage_type=damage_type,
                damage_tag=damage_tag,
                silent=silent_damage,
            ) or 0))
            total += dealt
            if dealt > 0:
                positive_hits += 1
        self._last_damage_value[target_id] = int(total)
        if isinstance(context, dict):
            context['last_damage'] = int(total)
            context['last_positive_hits'] = int(positive_hits)
            vars_dict = context.get('vars')
            if not isinstance(vars_dict, dict):
                vars_dict = {}
                context['vars'] = vars_dict
            vars_dict['last_damage'] = int(total)
            vars_dict['last_positive_hits'] = int(positive_hits)
        on_hit_once = params.get('on_hit_once')
        if total > 0 and isinstance(on_hit_once, list):
            child_context = dict(context or {})
            child_vars = dict(child_context.get('vars') or {})
            child_vars.update({'target_id': target_id, 'damage': int(total), 'last_damage': int(total)})
            child_context.update({
                'event': 'on_hit',
                'source_id': player_id,
                'target_id': target_id,
                'damage': int(total),
                'hit_count': max(1, int(positive_hits or 1)),
                'vars': child_vars,
            })
            self._run_effect_list(player_id, card, on_hit_once, choice, child_context)
        on_hit = params.get('on_hit')
        if total > 0 and isinstance(on_hit, list):
            for hit_index in range(max(1, int(positive_hits or 1))):
                child_context = dict(context or {})
                child_vars = dict(child_context.get('vars') or {})
                child_vars.update({
                    'target_id': target_id,
                    'damage': int(total),
                    'last_damage': int(total),
                    'hit_index': hit_index,
                })
                child_context.update({
                    'event': 'on_hit',
                    'source_id': player_id,
                    'target_id': target_id,
                    'damage': int(total),
                    'hit_index': hit_index,
                    'vars': child_vars,
                })
                self._run_effect_list(player_id, card, on_hit, choice, child_context)
        # Round 28：与运行时分支同一个日志开关（`silent`/`no_log`/`hide_log`
        # 与 `log: false` 等价），这一步自带的那行总结文案同样受它控制。
        if log is not False and not silent_damage and log:
            # A data-authored summary line, same contract as ``deal_damage``.
            self.log_msg(self._format_step_log(
                log, target=self.pn(target_id), source=self.pn(player_id),
                amount=int(total), damage=int(total),
            ))

    # Round 42 / 批次 AF：``lifesteal_damage`` 与 ``triangle_damage`` 已删除。
    #
    # 两者与 ``deal_damage`` 共用同一条攻击管线（``_modified_attack_damage`` +
    # ``deal_attack_damage`` + 精准旗标继承 + ``_last_damage_value``），差别只在
    # 结算后的附加动作，而这些都能用既有原子表达：
    #
    #   * 吸血 = ``deal_damage`` + ``health_op(mode:"heal", amount:floor(last_damage*ratio))``
    #     （``last_damage`` 取值形态读的正是上一步写进 ``_last_damage_value`` 的值）。
    #     为保证"反治疗"判定不退化，``_would_heal`` 同步认 ``health_op`` 的
    #     ``mode:"heal"``（见下面的实现）。
    #   * 三角 = ``deal_damage(amount: add(base, mul(per_stack, player_var(层数名))))``
    #     + 门控在 ``last_damage > 0``、上限用 ``compare`` 的 ``if_else`` +
    #     ``player_var_change(add, name:"三角形层数")``（``custom_vars`` 与
    #     ``triangle_stacks`` 的别名同步由 ``_sync_custom_var_alias`` 负责）。

    def _atomic_discard_choice_then_draw(self, player_id, card, params, log, choice, context):
        ps = self.players[player_id]
        discarded = False
        if choice and 'target_instance_id' in choice:
            target = ps.find_hand_card(choice['target_instance_id'])
            if target and self._card_selectable_by_action(target) and getattr(target, 'instance_id', None) != getattr(card, 'instance_id', None):
                ps.hand.remove(target)
                self._discard_card(ps, target)
                discarded = True
        ps.draw_cards(1)
        from engine_runtime_support import play_summary_declaration as _play_summary
        summary = _play_summary(card)
        if summary:
            self._log_card_play_summary(summary, player_id, discarded, 1 if discarded else 0)
            return
        self.log_msg(log or f"{self.pn(player_id)}抽1张牌")

    # Round 32 / 批次 AA：``coffee_gain_e`` 已并入
    # ``resource_op(resource:"e", delta:N, reset_coffee:true, card_heavy:1)``
    # （默认战报仍是"获得{n}E；本牌获得1层沉重"）。

    def _request_discount_copy_payload(self, player_id, card, params, log, choice, context):
        """``request(type:"discount_copy")`` 的实现体（旧 ``copy_choice_with_discount``）：
        复制选中的手牌并按 ``discount_e`` 打折（拟态）。"""

        ps = self.players[player_id]
        if not (choice and 'target_instance_id' in choice):
            return
        target = ps.find_hand_card(choice['target_instance_id'])
        if target is None or not self._card_selectable_by_action(target) or not ps.can_add_to_hand():
            return
        if card is not None and 'mimic_special_cost' in self._effective_card_flags(card) and not self._pay_mimic_special_cost(player_id, target, card):
            return
        copy_card = self._make_mimic_copy_card(target)
        default_discount = 0 if card is not None and 'mimic_special_cost' in self._effective_card_flags(card) else 1
        copy_card.mimic_discount = self._eval_int(player_id, params.get('discount_e', default_discount), card, default_discount)
        self._add_forced_copy_to_hand(player_id, copy_card)
        self._note_creative_mode_mana_pool(player_id, card, target)
        if log:
            self.log_msg(log)

    def _set_card_property_value(self, player_id, current_card, params, value):
        target_card = self._resolve_card_ref(player_id, params.get('card', {'ref': 'current_card'}), current_card)
        if target_card is None:
            return None
        prop = str(params.get('property', 'fusion_level'))
        if prop == 'cost_e':
            prop = 'cost_e_override'
        elif prop == 'cost_m':
            prop = 'cost_m_override'
        value = int(value)
        if prop in ('fusion_level', 'fission_level'):
            value = clamp_card_layer(value)
        elif prop == 'extra_hits':
            value = clamp_card_extra_hits(value)
        elif prop == 'power_value':
            value = clamp_card_power(value)
        elif prop in ('mimic_discount', 'cost_e_override', 'cost_m_override', 'bonus_damage', 'return_to_hand_turns',
                      'held_turns', 'swift_value', 'magic_swift_value', 'heavy_value', 'temp_swift_value', 'temp_heavy_value', 'temp_magic_heavy_value'):
            value = max(0, value)
        elif prop in ('charge_value', 'hand_blind_turns', 'blind_level'):
            value = max(0, value)
        # Round 42 / 批次 AF：``play_count`` / ``equip_turns`` 是卡内计数器
        # （``card_counter`` 已删除），二者既被卡数据读取（``{"ref":"play_count"}``
        # / ``{"ref":"equip_turns"}`` 与 ``equip_turns`` 条件算子），又在
        # ``to_dict`` 里，所以补进属性白名单后就能用 ``card_prop_change`` 写。
        elif prop in ('play_count', 'equip_turns'):
            value = max(0, value)
        # Round 29：耐久（装备的 ``durability``）并入卡牌属性族——旧
        # ``gain_durability`` / ``lose_durability`` / ``set_durability`` 三个
        # 同形原子由此改为 ``card_prop_add`` / ``card_prop_set``（见
        # mod_spec_v2.REMOVED_ATOMIC_OPS）。耐久永不为负，与旧
        # ``lose_durability`` 的 ``max(0, ...)`` 钳位一致。
        elif prop == 'durability':
            value = max(0, value)
        # Round 10: property caps are declared by the card data (``property_caps``);
        # the built-in fallback covers definitions without a data resource.
        builtin_cap = self._card_property_cap(target_card, prop)
        if builtin_cap is not None:
            value = min(builtin_cap, value)
        if prop in ('fusion_level', 'fission_level', 'extra_hits', 'mimic_discount', 'cost_e_override', 'cost_m_override',
                    'bonus_damage', 'return_to_hand_turns', 'held_turns', 'swift_value', 'magic_swift_value', 'heavy_value',
                    'power_value', 'temp_swift_value', 'temp_heavy_value', 'temp_magic_heavy_value',
                    'charge_value', 'hand_blind_turns', 'blind_level', 'durability',
                    'play_count', 'equip_turns'):
            setattr(target_card, prop, value)
            if prop == 'fusion_level':
                target_card.fusion_multiplier = float(value)
            elif prop == 'fission_level':
                target_card.fission_count = max(0, int(value) - 1)
            elif prop == 'charge_value':
                if value > 0:
                    target_card.instance_flags.add('charge')
                    target_card.disabled_flags.discard('charge')
                else:
                    target_card.instance_flags.discard('charge')
                    target_card.disabled_flags.add('charge')
            elif prop == 'swift_value':
                if value > 0:
                    target_card.instance_flags.add('swift')
                    target_card.disabled_flags.discard('swift')
                else:
                    target_card.instance_flags.discard('swift')
                    target_card.disabled_flags.add('swift')
            elif prop == 'magic_swift_value':
                if value > 0:
                    target_card.instance_flags.add('magic_swift')
                    target_card.disabled_flags.discard('magic_swift')
                else:
                    target_card.instance_flags.discard('magic_swift')
                    target_card.disabled_flags.add('magic_swift')
            elif prop == 'heavy_value':
                if value > 0:
                    target_card.instance_flags.add('heavy')
                    target_card.disabled_flags.discard('heavy')
                else:
                    target_card.instance_flags.discard('heavy')
                    target_card.disabled_flags.add('heavy')
            elif prop == 'power_value':
                if value != 0:
                    target_card.instance_flags.add('power')
                    target_card.disabled_flags.discard('power')
                else:
                    target_card.instance_flags.discard('power')
                    target_card.disabled_flags.add('power')
            elif prop == 'temp_swift_value':
                if value > 0:
                    target_card.instance_flags.add('temp_swift')
                    target_card.disabled_flags.discard('temp_swift')
                else:
                    target_card.instance_flags.discard('temp_swift')
                    target_card.disabled_flags.add('temp_swift')
            elif prop == 'temp_heavy_value':
                if value > 0:
                    target_card.instance_flags.add('temp_heavy')
                    target_card.disabled_flags.discard('temp_heavy')
                else:
                    target_card.instance_flags.discard('temp_heavy')
                    target_card.disabled_flags.add('temp_heavy')
            elif prop == 'temp_magic_heavy_value':
                if value > 0:
                    target_card.instance_flags.add('temp_magic_heavy')
                    target_card.disabled_flags.discard('temp_magic_heavy')
                else:
                    target_card.instance_flags.discard('temp_magic_heavy')
                    target_card.disabled_flags.add('temp_magic_heavy')
        return target_card

    def _get_card_property_numeric_value(self, target_card, prop):
        if prop in ('cost_e', 'cost_e_override'):
            value = target_card.cost_e_override if target_card.cost_e_override is not None else target_card.card_def.cost_e
        elif prop in ('cost_m', 'cost_m_override'):
            value = target_card.cost_m_override if target_card.cost_m_override is not None else target_card.card_def.cost_m
        else:
            value = getattr(target_card, prop, 0)
        if value is None:
            return 0
        value = int(value)
        # Round 10: property caps are declared by the card data (``property_caps``);
        # the built-in fallback covers definitions without a data resource.
        builtin_cap = self._card_property_cap(target_card, prop)
        if builtin_cap is not None:
            return min(builtin_cap, max(0, value))
        if prop == 'power_value':
            return clamp_card_power(value)
        return value

    def _atomic_card_prop_change(self, player_id, card, params, log, choice, context):
        """Round 31 / 批次 Z：卡牌属性写值族三合一。

        覆盖 ``card_prop_set``（``mode:"set"``，默认）/ ``card_prop_add``
        （``mode:"add"``）/ ``card_prop_mul``（``mode:"mul"``）。参数与
        ``player_prop_change`` 对齐：``mode`` + ``property``/``prop`` +
        ``value``/``amount``（乘法也认 ``multiplier``），``card`` 缺省当前牌。

        三段实现逐条搬过来（钳位、``power_value`` 上限、``fission_level`` 的
        ``multi_petal`` 双倍特例都保留），默认值也保持原样：

        * ``set`` 用 ``value``（默认 0），经 ``_set_card_property_value`` 钳位；
        * ``add`` 用 ``amount``，缺省回落 ``value``，先读当前值再相加；
        * ``mul`` 用 ``multiplier``，缺省回落 ``amount``/``value``（旧实现默认 1）。
        """

        mode = str(params.get('mode', 'set') or 'set').strip().lower()
        mode = {'=': 'set', 'set_to': 'set', 'assign': 'set', 'add': 'add', '+': 'add', '+=': 'add',
                'increase': 'add', 'mul': 'mul', 'multiply': 'mul', '*': 'mul', 'times': 'mul',
                'x': 'mul'}.get(mode, mode)
        if mode not in ('set', 'add', 'mul'):
            return
        if mode == 'set':
            value = self._eval_int(player_id, params.get('value', 0), card)
            target_card = self._set_card_property_value(player_id, card, params, value)
            if target_card is not None and log:
                self.log_msg(log)
            return
        target_card = self._resolve_card_ref(player_id, params.get('card', {'ref': 'current_card'}), card)
        if target_card is None:
            return
        prop = str(params.get('property', params.get('prop', 'fusion_level')))
        if mode == 'mul':
            current = self._get_card_property_numeric_value(target_card, prop)
            multiplier = self._eval_int(
                player_id, params.get('multiplier', params.get('amount', params.get('value', 1))), card, 1,
            )
            value = current * multiplier
        else:
            current = self._get_card_property_numeric_value(target_card, prop)
            amount = self._eval_int(player_id, params.get('amount', params.get('value', 0)), card)
            if (
                prop == 'fission_level'
                and self._card_has_flag(card, 'multi_petal_base')
                and 'multi_petal' in getattr(card, 'setup_modifiers', set())
                and int(amount) == 1
            ):
                amount = 2
            value = current + amount
        self._set_card_property_value(player_id, card, {'card': params.get('card', {'ref': 'current_card'}), 'property': prop}, value)
        if log:
            self.log_msg(log)

    def _atomic_card_prop_add_to_zone(self, player_id, card, params, log, choice, context):
        """Add a numeric card property to every matching card of one zone.

        Generic bulk counterpart of :meth:`_atomic_card_prop_add`: mods use it
        for "every card in your hand gains N layers of X" effects. ``count``
        limits how many cards are affected (``random`` picks a random sample),
        ``card_type`` filters by card type, and ``tag`` adds the flag that makes
        the client show the layer badge next to the card.

        Round 14 / batch 2: ``zones``（多区）与 ``add_tag_to_zone`` 完全对齐，
        未知区域显式报错（以前会被静默跳过）；``silent``/``no_log``/``log:false``
        与同族 op 一样能压掉默认战报（以前只有 ``log`` 能覆盖）；``target`` 走统一
        选择器解析。
        """
        target_ids = self._step_target_ids(player_id, card, params, context, op='card_prop_add_to_zone')
        zone_names = self._step_zone_names(params, op='card_prop_add_to_zone', default='hand')
        if not target_ids or not zone_names:
            return
        silent = bool(params.get('silent') or params.get('no_log')) or log is False
        prop = str(params.get('property') or params.get('prop') or '')
        if not prop:
            return
        amount = self._eval_int(player_id, params.get('amount', params.get('value', 0)), card, 0)
        card_type = str(params.get('card_type', '') or '').strip().lower()
        raw_tag = str(params.get('tag', '') or '').strip()
        tag = normalize_card_flag(raw_tag) if raw_tag else ''
        count_param = params.get('count')
        for target_id in target_ids:
            ps = self.players[target_id]
            zone = [
                candidate
                for zone_name in zone_names
                for candidate in self._player_zone_cards(ps, zone_name)
            ]
            candidates = [
                candidate for candidate in list(zone or [])
                if candidate is not None
                and (not card_type or str(getattr(candidate, 'card_type', '') or '') == card_type)
                and (params.get('require_selectable') is False or self._card_selectable_by_action(candidate))
            ]
            if count_param is not None and str(count_param).strip() not in ('', 'all', '全部'):
                limit = max(0, self._eval_int(player_id, count_param, card, 0))
                if limit and len(candidates) > limit:
                    candidates = random.sample(candidates, limit) if params.get('random') else candidates[:limit]
            changed = 0
            for candidate in candidates:
                current = self._get_card_property_numeric_value(candidate, prop)
                mode = str(params.get('mode') or params.get('write') or 'add').strip().lower()
                if mode in ('max', 'at_least'):
                    # "raise to at least N" style writes (e.g. blind a card for
                    # one turn without lowering a longer blind).
                    new_value = max(current, amount)
                elif mode in ('set', 'set_to'):
                    new_value = amount
                else:
                    new_value = current + amount
                self._set_card_property_value(
                    player_id,
                    card,
                    {'card': {'ref': 'card_instance', 'instance_id': candidate.instance_id}, 'property': prop},
                    new_value,
                )
                if tag:
                    candidate.instance_flags.add(tag)
                    candidate.disabled_flags.discard(tag)
                changed += 1
            if changed <= 0 or silent:
                continue
            default_log = (
                f"{self.pn(player_id)}使{self.pn(target_id)}的{changed}张牌获得"
                f"{self._card_flag_log_text(tag) if tag else prop}"
            )
            self.log_msg(
                self._format_step_log(
                    log,
                    target=self.pn(target_id),
                    count=changed,
                    amount=amount,
                    tag=self._card_flag_log_text(tag) if tag else '',
                    property=prop,
                ) or default_log
            )

    # Round 31 / 批次 Z：``toggle_tag_in_zone`` 已并入
    # ``add_tag_to_zone(mode:"toggle")``（``target``/``zone``/``tag`` 参数同名同义，
    # 显式写 ``target`` 即与旧默认 ``target`` 一致）。

    # Round 41 / 批次 AE-5：``card_damage_multiply`` 已删除——它就是
    # ``card_prop_change(mode:"mul", property:"fusion_level", multiplier:N)``
    # （同一张 ``_set_card_property_value`` 钳位路径），旧名进
    # ``mod_spec_v2.REMOVED_ATOMIC_OPS``，写出来是显式报错。

    # Round 31 / 批次 Z：``clear_tags`` 已并入 ``add_tag(mode:"clear")``。

    def _atomic_equipment_prop_set(self, player_id, card, params, log, choice, context):
        value = self._eval_int(player_id, params.get('value', 0), card)
        eq = self._set_equipment_property_value(player_id, card, params, value)
        if eq is not None and log:
            self.log_msg(log)

    def _atomic_equipment_prop_add(self, player_id, card, params, log, choice, context):
        eq = self._resolve_equipment_ref(player_id, params.get('equipment', {'ref': 'current_equipment'}), card)
        if eq is None:
            return
        prop = str(params.get('property', 'turns_equipped'))
        current = self._get_equipment_property_value(eq, prop)
        value = current + self._eval_int(player_id, params.get('amount', 0), card)
        self._set_equipment_property_value(player_id, card, params, value)
        if log:
            self.log_msg(log)

    def _atomic_player_prop_change(self, player_id, card, params, log, choice, context):
        """Round 29 / 批次 X：玩家属性写值的"设为 / 增加"两条合并成一条。

        ``mode`` 选 ``set``（默认）或 ``add``；``property``/``prop`` 选属性名，
        ``value``/``amount`` 给数值。两段实现逐条搬过来，因此口径保持原样：

        * ``set`` 用 ``value``（默认 0）经 ``_eval_int`` 求值后直接写入；
        * ``add`` 用 ``amount``，缺省回落到 ``value``，读取时带
          ``include_suppressed=True``（状态免疫期间照常累加，见
          ``tests/test_status_immunity_application.py``），再写回。

        ``target`` 默认 ``self``，与两条旧实现一致。
        """
        mode = str(params.get('mode', 'set') or 'set').strip().lower()
        mode = {'=': 'set', 'set_to': 'set', 'assign': 'set',
                '+': 'add', '+=': 'add', 'increase': 'add'}.get(mode, mode)
        if mode not in ('set', 'add'):
            return
        prop = str(params.get('property') or params.get('prop', 'health'))
        if mode == 'add':
            amount = self._eval_int(player_id, params.get('amount') or params.get('value', 0), card)
            for tid in self._resolve_targets(player_id, params.get('target', 'self')):
                current = self._get_player_property_value(tid, prop, include_suppressed=True)
                if self._set_player_property_value(tid, prop, current + amount) is not None and log:
                    self.log_msg(log)
            return
        value = self._eval_int(player_id, params.get('value', 0), card)
        for tid in self._resolve_targets(player_id, params.get('target', 'self')):
            if self._set_player_property_value(tid, prop, value) is not None and log:
                self.log_msg(log)

    # Round 31 / 批次 Z：``player_prop_set`` / ``player_prop_add`` 两个兼容垫片
    # 已删除（``player_prop_change(mode=...)`` 是唯一实现）。

    # Round 40 / 批次 AE-4：``discard_hand_by_paid_e``（风的"按本牌实际花费 E
    # 批量弃手牌"专用原子）已删除，能力下沉成通用批量移动 —— 数据写
    # ``move_card(mode:"batch", source_zone:"hand", target_zone:"discard",
    # filter:{max_cost_e:…, exclude_error:true}, count_as_active_discard:true)``
    # （见 :meth:`_move_card_batch_zone_payload` 与
    # ``mod_spec_v2.REMOVED_ATOMIC_OPS["discard_hand_by_paid_e"]``）。

    def _atomic_snapshot(self, player_id, card, params, log, choice, context):
        """Round 33 / 批次 AB：``snapshot`` 伞。

        目前只有 ``mode:"card_props"``（旧 ``snapshot_card_props``：把区域里
        每张牌的某个属性原值记进 ``store``，供 :meth:`_atomic_restore` 还原）。
        ``mode`` 缺省即 ``card_props``，旧数据的参数面不变。
        """

        mode = str(params.get('mode') or 'card_props').strip().lower()
        if mode in ('card_props', 'card', 'props'):
            return self._snapshot_card_props_payload(player_id, card, params, log, choice, context)
        raise V2ZoneError(f"snapshot 只认 mode=card_props，收到 {mode!r}")

    def _atomic_restore(self, player_id, card, params, log, choice, context):
        """Round 33 / 批次 AB：``restore`` 伞（``restore_card_props`` /
        ``restore_match_start_stats`` / ``restore_turn_start_stats`` 三合一）。

        统一参数 ``mode``：``card_props``（缺省，还原 ``snapshot`` 记下的属性，
        参数 ``store``/``property``/``clear``）、``match_start``（``target``/
        ``extra_self_e_loss``/``exclude_self``）、``turn_start``（同上）。三段
        实现体与合并前逐字一致。
        """

        mode = str(params.get('mode') or '').strip().lower()
        if mode in ('match_start', 'match', 'match_start_stats'):
            return self._restore_match_start_payload(player_id, card, params, log, choice, context)
        if mode in ('turn_start', 'turn', 'turn_start_stats'):
            return self._restore_turn_start_payload(player_id, card, params, log, choice, context)
        if mode in ('', 'card_props', 'card', 'props'):
            return self._restore_card_props_payload(player_id, card, params, log, choice, context)
        raise V2ZoneError(f"restore 只认 mode=card_props/match_start/turn_start，收到 {mode!r}")

    def _restore_turn_start_payload(self, player_id, card, params, log, choice, context):
        extra_self_e_loss = self._eval_int(player_id, params.get('extra_self_e_loss', 0), card)
        for tid in self._resolve_targets(player_id, params.get('target', 'self')):
            if params.get('exclude_self') and tid == player_id:
                continue
            self._restore_turn_start_snapshot(tid, extra_self_e_loss if tid == player_id else 0)
        if log:
            self.log_msg(log)

    def _restore_match_start_payload(self, player_id, card, params, log, choice, context):
        extra_self_e_loss = self._eval_int(player_id, params.get('extra_self_e_loss', 0), card)
        for tid in self._resolve_targets(player_id, params.get('target', 'self')):
            if params.get('exclude_self') and tid == player_id:
                continue
            self._restore_match_start_snapshot(tid, extra_self_e_loss if tid == player_id else 0)
            if int(getattr(self.players[tid], 'health', 0) or 0) > 0:
                self.log_msg(f"{self.pn(tid)}回到对局开始时的状态")
        if log:
            self.log_msg(log)

    def _atomic_counter_pending_attack_damage(self, player_id, card, params, log, choice, context):
        ratio = float(params.get('ratio', params.get('multiplier', 0.5)) or 0)
        incoming = 0
        if isinstance(context, dict):
            try:
                incoming = int(context.get('first_hit_damage', context.get('first_damage', 0)) or 0)
            except Exception:
                incoming = 0
            parts = context.get('incoming_damage_parts')
            if isinstance(parts, (list, tuple)) and parts:
                try:
                    incoming = int(context.get('first_hit_damage') or context.get('first_damage') or parts[0] or 0)
                except Exception:
                    incoming = 0
            # Do not fall back to total incoming damage here. Salt-style
            # counters reflect only the first hit of a multi-hit card; old
            # prediction fallbacks may store the total as one synthetic part.
        amount = max(0, int(math.ceil(incoming * ratio)))
        if amount <= 0:
            return
        # Round 28：与 direct_damage / 运行时分支同一串来源文案回落。
        source_text = params.get('source_text') or params.get('source_name') or params.get('label')
        if source_text is None:
            source_text = params.get('source', getattr(card, 'name_cn', '反击'))
        source = str(source_text)
        damage_type = params.get('damage_type', DAMAGE_TYPE_PHYSICAL)
        damage_tag = params.get('damage_tag')
        target_ref = params.get('target', 'target')
        if target_ref in ('all_enemies', 'enemies'):
            targets = list(self.get_all_enemies(player_id)) if hasattr(self, 'get_all_enemies') else [1 - player_id]
        else:
            targets = self._resolve_targets(player_id, target_ref)
        # Round 15 / batch 3: the runtime branch always defaulted to ``direct``;
        # the engine atom used to default to ``attack``, so the same step could
        # resolve differently depending on where it was nested.
        mode = str(params.get('mode', params.get('damage_mode', 'direct')) or 'direct').lower()
        total = 0
        for tid in targets:
            if 0 <= tid < len(self.players):
                if mode in ('direct', 'effect'):
                    total += int(self._deal_direct_damage(
                        tid, amount, source, player_id,
                        damage_type=damage_type, damage_tag=damage_tag,
                    ) or 0)
                else:
                    total += int(self.deal_attack_damage(
                        tid, amount, 1, is_precision=False, attacker_id=player_id,
                    ) or 0)
        if isinstance(context, dict):
            context['last_damage'] = int(total)
        if log:
            self.log_msg(self._format_step_log(
                log, target=self.pn(targets[0]) if targets else '',
                source=self.pn(player_id), amount=int(total), damage=int(total),
            ))

    # Round 32 / 批次 AA：``lose_health`` 已并入 ``health_op(mode:"lose")``
    # （实现整段搬进 ``_atomic_health_op``，含无敌分支与 ``_check_game_over``）。

    def _equipment_op_destroy_payload(self, player_id, card, params, log, choice, context):
        # Round 33 / 批次 AC：``equipment_op(mode:"destroy")`` 的实现体（旧
        # ``destroy_equipment``；内部 ``mode``=choice/random/all/self 由伞的
        # ``pick`` 参数喂进来）。
        """Round 29 + Round 31：摧毁装备族的唯一实现。

        覆盖 ``destroy_equipment``（运行时原生薄封装）/ ``destroy_random_equip`` /
        ``destroy_all_equip`` / ``destroy_all_field_equip``（Round 29）以及
        ``destroy_equipment_choice_or_first`` / ``destroy_self_equipment`` /
        ``destroy_current_equipment`` / ``destroy_all_destroyable_equipment``
        （Round 31 / 批次 Z）：

        * ``mode`` 选 ``choice``（默认，拆"玩家点选的那件 / 数据点名的
          ``equipment``·``card`` 引用 / 第一件"）、``random``（随机拆 1 件）、
          ``all``（拆光）或 ``self``（拆"这张牌自己挂着的那件装备"，即旧
          ``destroy_self_equipment`` 与 ``destroy_current_equipment`` 的并集：
          先按实例 id 全场找，再回落 ``_find_equipment_for_card``）；
        * ``scope`` 选 ``target``（默认）或 ``field``（全场每名玩家）；
          ``mode:"all"`` 的 ``target`` 支持集合选择器（旧
          ``destroy_all_destroyable_equipment`` 的 ``target:"both"``）；
        * ``filter`` 写 ``destroyable`` / ``destructible`` 时跳过
          ``indestructible``（旧 ``destroy_all_destroyable_equipment`` 的过滤，
          在 ``field`` 域也生效）；
        * ``record_count: true`` 把摧毁件数写进 ``context`` 的
          ``last_destroyed_equipment_count``（含 ``vars``，旧
          ``destroy_all_destroyable_equipment`` 的记账）；
        * ``source`` 覆盖"摧毁者"（旧 ``destroy_self_equipment`` 的可选来源），
          缺省与同族一致是本步的玩家。

        四段实现逐条搬过来：``choice`` 先看 ``choice.target_instance_id``，再看
        ``equipment`` 引用（实例 id / ``_resolve_equipment_ref`` 认的写法），最后
        回落到第一件；``random`` / ``all`` 在 ``target`` 域先按 ``indestructible``
        过滤（旧 ``destroy_random_equip`` / ``destroy_all_equip`` 的写法），
        ``field`` 域不过滤、直接交给 ``_destroy_equipment`` 判定（旧
        ``destroy_all_field_equip`` 的写法——护甲/装备保护照常抵消），因此战报
        与"抵消"行为逐字一致。
        """
        mode = str(params.get('mode', 'choice') or 'choice').strip().lower()
        mode = {
            'one': 'random', 'single': 'random', 'random_one': 'random', 'pick': 'random',
            'every': 'all', 'destroy_all': 'all',
            'first': 'choice', 'chosen': 'choice', 'selected': 'choice', 'target': 'choice',
            'self': 'self', 'current': 'self', 'this': 'self', 'attached': 'self',
            'self_equipment': 'self', 'current_equipment': 'self',
        }.get(mode, mode)
        if mode not in ('choice', 'random', 'all', 'self'):
            return
        filter_value = str(params.get('filter', '') or '').strip().lower()
        destroyable_only = filter_value in ('destroyable', 'destructible', 'not_indestructible', 'breakable')
        record_count = params.get('record_count') is True or params.get('record') is True
        source_id = player_id
        if params.get('source') is not None:
            try:
                resolved_source = int(self._resolve_target(player_id, params.get('source')))
            except (TypeError, ValueError):
                resolved_source = player_id
            if self._valid_player_id(resolved_source):
                source_id = resolved_source
        destroyed_count = 0
        if mode == 'self':
            owner_id, eq = self._find_equipment_owner_of_card(player_id, card)
            if eq is not None and self._destroy_equipment(owner_id, eq, check_protection=False, source_id=source_id):
                if log:
                    self.log_msg(log)
            return
        scope = str(params.get('scope', 'target') or 'target').strip().lower()
        if scope in ('field', 'board', 'both', 'all', 'everyone', 'all_players'):
            scope = 'field'
        if scope == 'field':
            player_ids = [index for index in range(len(self.players))]
        else:
            # 标量选择器保持"只动一名玩家"的旧语义；只有显式集合选择器
            # （``both`` / ``play_targets`` …）才展开——旧
            # ``destroy_all_destroyable_equipment`` 的 ``target:"both"`` 正是要这个。
            player_ids = self._resolve_step_targets(
                player_id, card, params.get('target', 'enemy'), context,
            )
            if not player_ids:
                return
        for pid in player_ids:
            if mode == 'choice':
                eq = self._destroy_equipment_choice_target(pid, card, params, choice)
                if eq is None:
                    continue
                eq_name = eq.card_def.name_cn
                if self._destroy_equipment(pid, eq, source_id=source_id):
                    destroyed_count += 1
                    self.log_msg(log or f"{self.pn(player_id)}摧毁了{self.pn(pid)}的{eq_name}")
                elif log:
                    self.log_msg(log)
                continue
            if scope == 'field' and not destroyable_only:
                candidates = list(self.players[pid].equipment)
            else:
                candidates = [
                    eq for eq in self.players[pid].equipment
                    if 'indestructible' not in eq.card_instance.flags
                ]
            if not candidates:
                continue
            if mode == 'random':
                candidates = [random.choice(candidates)]
            for eq in candidates:
                eq_name = eq.card_def.name_cn
                if self._destroy_equipment(pid, eq, source_id=source_id):
                    destroyed_count += 1
                    self.log_msg(log or f"{self.pn(player_id)}摧毁了{self.pn(pid)}的{eq_name}")
                elif log:
                    self.log_msg(log)
        if record_count and isinstance(context, dict):
            context['last_destroyed_equipment_count'] = destroyed_count
            vars_obj = context.setdefault('vars', {})
            if isinstance(vars_obj, dict):
                vars_obj['last_destroyed_equipment_count'] = destroyed_count

    def _find_equipment_owner_of_card(self, player_id, card):
        """``mode:"self"`` 的选件：先按实例 id 全场找，再回落当前玩家。

        旧 ``destroy_current_equipment`` 全场按 ``instance_id`` 找，
        ``destroy_self_equipment`` 用 ``_find_equipment_for_card``（只看自己）；
        合并后先做全场精确匹配，两者对同一张装备牌给出同一件装备。
        """

        instance_id = getattr(card, 'instance_id', None)
        if instance_id is not None:
            for owner_id, owner_state in enumerate(self.players):
                for eq in list(getattr(owner_state, 'equipment', []) or []):
                    if getattr(getattr(eq, 'card_instance', None), 'instance_id', None) == instance_id:
                        return owner_id, eq
        eq = self._find_equipment_for_card(player_id, card)
        if eq is not None:
            return player_id, eq
        return player_id, None

    def _destroy_equipment_choice_target(self, owner_id, card, params, choice):
        """``destroy_equipment(mode:"choice")`` 的选件口径（合并前的两套合一）。

        优先级：玩家点选（``choice.target_instance_id``）→ 数据点名的
        ``equipment``/``card`` 引用（实例 id 或 ``_resolve_equipment_ref`` 的写法）→
        该玩家的第一件装备。``require_selection: true`` 时不回落到第一件。
        """
        ps = self.players[owner_id]
        if isinstance(choice, dict) and choice.get('target_instance_id') is not None:
            eq = ps.find_equipment(choice.get('target_instance_id'))
            if eq is not None:
                return eq
        raw = params.get('equipment')
        if raw is None:
            raw = params.get('card')
        if raw is not None:
            if isinstance(raw, EquipmentInstance):
                return raw
            try:
                instance_id = int(raw)
            except (TypeError, ValueError):
                instance_id = None
            if instance_id is None and isinstance(raw, dict) and raw.get('op'):
                try:
                    instance_id = int(self._eval_int(owner_id, raw, card, 0))
                except (TypeError, ValueError):
                    instance_id = None
            if instance_id is not None:
                eq = ps.find_equipment(instance_id)
                if eq is not None:
                    return eq
            eq = self._resolve_equipment_ref(owner_id, raw, card)
            if eq is not None:
                return eq
        if params.get('require_selection'):
            return None
        return ps.equipment[0] if ps.equipment else None

    # Round 31 / 批次 Z：``destroy_all_destroyable_equipment`` 已并入
    # ``destroy_equipment(mode:"all", filter:"destroyable", record_count:true)``
    # （``target`` 缺省要显式写 ``"both"`` 才与旧默认一致）。

    # Round 42 / 批次 AF：``activate_corruption`` 已删除——它做的就是
    # "把当前牌对应的装备的 ``corruption_active`` 置真"，而同一个 setter
    # （``_set_equipment_property_value`` 的 ``corruption_active`` 分支）已经由
    # ``equipment_prop_set`` 这条既有 op 覆盖（默认 ``equipment`` 引用
    # ``current_equipment`` 与旧实现的 ``_find_equipment_for_card`` 同解）。
    # 旧名进 ``REMOVED_ATOMIC_OPS``，替代写法带完整 JSON。

    def _atomic_health_op(self, player_id, card, params, log, choice, context):
        """Round 32 / 批次 AA：生命族六合一。

        覆盖 ``heal`` / ``lose_health`` / ``set_health`` / ``swap_health`` /
        ``on_fatal_set_health_exile`` / ``on_fatal_invincible_then_die``：
        ``mode`` 选 ``heal``（默认）/ ``lose`` / ``set`` / ``swap`` / ``fatal``，
        ``fatal`` 再用 ``kind`` 选 ``exile`` / ``invincible_die``。

        六段旧实现逐条搬进来，默认值、钳位与默认战报逐字保留：

        * ``heal``：目标走 ``_list_effect_targets``（集合 / 广域选择器照常展开），
          数值走 ``PlayerState.heal`` —— ``heal_block`` 减半并消耗一层、
          ``_heal_callback``、上限 ``base_max_health`` 都在那里，原子本身不重复
          实现；战报按**实际回复量**，``log_positive_only`` 与
          ``silent``/``no_log``/``log:false`` 静音，未回复时默认播报"未回复生命"。
        * ``lose``：无视护甲的失去生命，保留无敌免疫分支、成就记账、
          ``_bio_stem_cell_after_health_loss``、``_record_damage``、世界树检查与
          ``_check_game_over``（触发时点与旧实现一致）。
        * ``set``：``max(0, min(amount, max_health))`` 上限截断 + 成就记账。
        * ``swap``：两名玩家互换生命值，不钳位（旧实现就是直接赋值）。
        * ``fatal``：**被动声明**，只点灯 / 播报；真正的触发在
          ``_check_yggdrasil``（``exile``）与 ``_check_yggdrasil`` 的绷带分支
          （``invincible_die``），与旧 ``on_fatal_*`` 原子完全一致。
        """

        raw_mode = str(params.get('mode') or '').strip().lower()
        kind = str(params.get('kind') or '').strip().lower()
        if not raw_mode and kind in ('exile', 'invincible_die', 'bandage', 'die', 'invincible'):
            raw_mode = 'fatal'
        mode = raw_mode or 'heal'

        if mode in ('lose', 'lose_health', 'losehealth'):
            amount = max(0, self._eval_int(player_id, params.get('amount', 0), card))
            source_id = self._resolve_target(player_id, params.get('source', 'self'))
            source = str(params.get('source_text', getattr(card, 'name_cn', '效果')))
            for tid in self._resolve_targets(player_id, params.get('target', 'self')):
                if not (0 <= tid < len(self.players)) or amount <= 0:
                    continue
                ps = self.players[tid]
                if ps.invincible:
                    self._record_achievement_damage_output(source_id, amount)
                    self.log_msg(f"{self.pn(tid)}无敌，免疫{source}伤害")
                    continue
                old_health = ps.health
                ps.health -= amount
                health_lost = max(0, int(old_health or 0) - max(0, int(ps.health or 0)))
                self._bio_stem_cell_after_health_loss(tid, health_lost)
                self._note_achievement_health(tid)
                self._record_damage(tid, amount, source_id)
                self.log_msg(log or f"{self.pn(tid)}受到{amount}点{source}伤害（H={ps.health}）")
                self._check_yggdrasil(tid)
            self._check_game_over()
            return

        if mode in ('set', 'set_health', 'sethealth'):
            amount = self._eval_int(player_id, params.get('amount', params.get('value', 60)), card, 60)
            for target_id in self._resolve_targets(player_id, params.get('target', 'self')):
                if 0 <= target_id < len(self.players):
                    self.players[target_id].health = max(0, min(amount, self.players[target_id].max_health))
                    self._note_achievement_health(target_id)
                    if log is False:
                        continue
                    self.log_msg(self._format_step_log(
                        log or f"{self.pn(target_id)}血量设为{amount}",
                        target=self.pn(target_id),
                        source=self.pn(player_id),
                        amount=amount,
                    ))
            return

        if mode in ('swap', 'swap_health', 'swaphealth'):
            t1 = self._resolve_target(player_id, params.get('target1', 'self'))
            t2 = self._resolve_target(player_id, params.get('target2', 'enemy'))
            if not (self._valid_player_id(t1) and self._valid_player_id(t2)):
                return
            h1 = self.players[t1].health
            h2 = self.players[t2].health
            self.players[t1].health = h2
            self.players[t2].health = h1
            self._note_achievement_health(t1)
            self._note_achievement_health(t2)
            self.log_msg(log or f"{self.pn(t1)}与{self.pn(t2)}交换生命值")
            return

        if mode in ('fatal', 'on_fatal', 'death'):
            if kind in ('invincible_die', 'bandage', 'die', 'invincible'):
                if self._status_application_blocked(player_id, 'bandage_active'):
                    return
                self.players[player_id].bandage_active = True
                self.log_msg(log or f"{self.pn(player_id)}受到致命伤害时将H设为1并获得无敌；自己回合结束时死亡")
                return
            health_amount = params.get('health', 5)
            self.log_msg(log or f"{self.pn(player_id)}的{card.name_cn}被动效果：受到致命伤害时清除所有效果，生命值设为{health_amount}，无敌直到下一个自己回合结束")
            return

        # ``mode`` 缺省 = 旧的 ``heal``。
        amount = self._eval_int(player_id, params.get('amount', 0), card)
        positive_only = bool(params.get('log_positive_only'))
        silent = log is False or params.get('silent') or params.get('no_log')
        for target_id in self._data_step_targets(player_id, card, params.get('target', 'self'), context):
            before = self.players[target_id].health
            self.players[target_id].heal(amount)
            healed = max(0, self.players[target_id].health - before)
            if silent or (positive_only and healed <= 0):
                continue
            # 自定义模板照旧用**实际回复量**渲染；模板在满血时也照播（旧运行时
            # 分支的行为，卡数据里的"毒回复"句因此逐字保留），要静音就写
            # ``log_positive_only``。
            default_line = (
                f"{self.pn(target_id)}回复{healed}H"
                if healed
                else f"{self.pn(target_id)}未回复生命"
            )
            if log:
                self.log_msg(self._format_step_log(
                    log,
                    target=self.pn(target_id),
                    amount=healed,
                    count=healed,
                    source=self.pn(player_id),
                ) or default_line)
                continue
            self.log_msg(default_line)

    def _atomic_draw(self, player_id, card, params, log, choice, context):
        """Round 32 / 批次 AA：抽牌族四合一。

        覆盖 ``draw``（引擎原子）/ ``draw_cards``（引擎原子 + 运行时原生分支）/
        ``equip_reduce_draw``（抽牌修正），参数是 ``count``（旧 ``amount``，
        默认 1）+ ``modifiers``。

        * 抽牌本身：``hooks:false`` 时直接 ``PlayerState.draw_cards``（旧 ``draw``
          的路径，不触发 ``before_draw``/``after_draw`` 事件）；默认
          ``hooks:true`` 走 ``_draw_cards_with_v2_hooks``（旧 ``draw_cards``
          的路径），两条路径的默认值都与各自旧实现一致。
        * 战报数量：``log_amount`` 选 ``requested``（旧 ``draw``：播报请求值）
          或 ``drawn``（默认，旧 ``draw_cards``：播报真正到手的张数）。
          ``suppress_detail_logs``（卡面 ``on_play_summary`` 声明）在这一层
          统一生效。
        * ``modifiers`` 是抽牌修正列表（也接受单个 dict 或字符串）：目前支持
          ``{"type":"sluggish"|"reduce_draw","amount":N,"target":sel,"log":...}``，
          即旧 ``equip_reduce_draw`` 的"给目标叠迟缓"（默认战报"敌方获得N层迟缓"
          逐字保留）。``count`` 为 0 时只结算修正、不抽牌也不播报抽牌。
        """

        targets = self._data_step_targets(player_id, card, params.get('target', 'self'), context)
        if not targets:
            targets = [player_id]
        amount_expr = params.get('count', params.get('amount', 1))
        amount = max(0, self._eval_int(player_id, amount_expr, card, 1))
        use_hooks = params.get('hooks', params.get('use_hooks', True)) is not False
        log_requested = str(params.get('log_amount') or '').strip().lower() in (
            'requested', 'declared', 'intended', 'asked',
        )
        silent = log is False or params.get('silent') or params.get('no_log')
        suppress = isinstance(context, dict) and bool(context.get('suppress_detail_logs'))
        for modifier in self._draw_modifier_specs(params):
            self._apply_draw_modifier(player_id, card, modifier, context)
        if amount <= 0:
            return
        for target_id in targets:
            if not self._valid_player_id(target_id):
                continue
            if use_hooks and hasattr(self, '_draw_cards_with_v2_hooks') and not (
                isinstance(context, dict) and context.get('current_event') in ('before_draw', 'after_draw')
            ):
                drawn = self._draw_cards_with_v2_hooks(target_id, amount, 'draw')
            else:
                drawn = self.players[target_id].draw_cards(amount)
            if silent or suppress:
                continue
            log_count = amount if log_requested else len(drawn)
            # 反馈 #84：``log`` 里的占位符要在这里格式化，不能原样打印。
            self.log_msg(
                self._format_step_log(
                    log, target=self.pn(target_id), source=self.pn(player_id),
                    amount=log_count, count=log_count,
                ) or f"{self.pn(target_id)}抽{log_count}张牌"
            )

    @staticmethod
    def _draw_modifier_specs(params) -> list:
        raw = params.get('modifiers', params.get('modifier'))
        if raw is None:
            return []
        if isinstance(raw, (str, dict)):
            return [raw]
        if isinstance(raw, (list, tuple)):
            return list(raw)
        return []

    def _apply_draw_modifier(self, player_id, card, modifier, context) -> None:
        """结算一条 ``draw`` 修正（目前只有旧 ``equip_reduce_draw`` 的迟缓）。"""

        if isinstance(modifier, str):
            spec = {'type': modifier}
        elif isinstance(modifier, dict):
            spec = modifier
        else:
            return
        kind = str(spec.get('type') or spec.get('kind') or spec.get('op') or '').strip().lower()
        if kind not in ('sluggish', 'reduce_draw', 'draw_reduce', '迟缓'):
            return
        amount = self._eval_int(player_id, spec.get('amount', 1), card, 1)
        target_ids = self._resolve_step_targets(
            player_id, card, spec.get('target', 'enemy'), context,
        )
        for target_id in target_ids:
            if not self._valid_player_id(target_id):
                continue
            self.players[target_id].sluggish += amount
            self._note_achievement_status_peak(target_id)
            if spec.get('log') is False:
                continue
            default = (
                f"敌方获得{amount}层迟缓" if target_id != player_id
                else f"{self.pn(target_id)}获得{amount}层迟缓"
            )
            self.log_msg(self._format_step_log(spec.get('log') or '', target=self.pn(target_id), amount=amount) or default)

    # Round 26: ``draw_to_hand_limit`` 的公式（手牌上限 - 手牌数）搬进了卡数据
    # ——``if(gap > 0)`` + ``draw_cards(amount: player_stat hand_limit - hand_count,
    # log_amount: "requested")``。旧名写在数据里会拿到 REMOVED_ATOMIC_OPS 的
    # 显式报错。

    # Round 32 / 批次 AA：``gain_e`` / ``gain_m`` 已并入
    # ``resource_op(resource:"e"/"m", delta:...)``（正数获得、负数消耗，
    # 上限截断与默认战报逐字保留；见 ``_atomic_resource_op``）。

    def _atomic_magic_salt_reflect(self, player_id, card, params, log, choice, context):
        if not isinstance(context, dict):
            return
        # Magic Salt responds to physical attack-card damage, not status or
        # other direct damage that also uses the generic damage-taken event.
        action = context.get('current_action') if isinstance(context.get('current_action'), dict) else {}
        vars_dict = context.get('vars') if isinstance(context.get('vars'), dict) else {}
        damage_kind = context.get('damage_kind') or action.get('damage_kind') or vars_dict.get('damage_kind')
        damage_type = context.get('damage_type') or action.get('damage_type') or vars_dict.get('damage_type')
        if str(damage_kind or '') not in ('', 'attack'):
            return
        if str(damage_type or '') not in ('', DAMAGE_TYPE_PHYSICAL):
            return
        if self.pending_choice is not None or getattr(self, 'pending_response', None) is not None or getattr(self, 'pending_v2_ui', None) is not None:
            return
        try:
            damage = int(context.get('damage', 0) or 0)
            attacker_id = int(context.get('source_id', -1))
            target_id = int(context.get('target_id', player_id))
        except Exception:
            return
        if damage <= 0 or not self._valid_player_id(attacker_id) or not self._valid_player_id(target_id):
            return
        owner_id = player_id
        try:
            owner_id = int((context or {}).get('selected_equipment_owner_id', owner_id))
        except Exception:
            pass
        eq = self._find_equipment_for_card(owner_id, card)
        if eq is not None:
            owner_id = int(getattr(eq, 'owner', player_id))
        if not self._valid_player_id(owner_id):
            owner_id = player_id
        cost_m = max(0, self._eval_int(player_id, params.get('cost_m', 1), card, 1))
        owner = self.players[owner_id]
        if owner.magic < cost_m:
            return
        ratio = float(params.get('ratio', 0.5) or 0.5)
        reflect = int(math.ceil(damage * ratio))
        if reflect <= 0:
            return
        self.pending_choice = {
            'card': card.to_dict(),
            'player_id': owner_id,
            'choice_type': 'magic_salt_reflect',
            'choice_params': {
                'owner_id': owner_id,
                'attacker_id': attacker_id,
                'target_id': target_id,
                'damage': damage,
                'reflect': reflect,
                'ratio': ratio,
                'cost_m': cost_m,
                'cancellable': True,
                'title': '魔法盐',
                'message': f'是否支付{cost_m}M，对{self.pn(attacker_id)}反弹{reflect}D？',
                'ok_text': '支付并反伤',
                'cancel_text': '不触发',
            },
            'already_paid': True,
            'message': f'是否支付{cost_m}M，对{self.pn(attacker_id)}反弹{reflect}D？',
        }

    # Round 24：``add_armor`` / ``gain_dodge``（别名 ``dodge_permanent``）/
    # ``apply_poison`` / ``apply_burn`` / ``apply_toxic`` 这批同形小原子已并入
    # ``player_stat_change`` 与 ``status_add_named``：
    #   * 护甲/闪避 → ``{"op":"player_stat_change","mode":"add","stat":"armor",...}``
    #   * 中毒/灼烧/淬毒 → ``{"op":"status_add_named","status":"poison"|"burn"|"toxic",...}``
    # 旧名写出来会拿到 mod_spec_v2.REMOVED_ATOMIC_OPS 的显式报错。

    # Round 26：``apply_jungle_status`` / ``magic_grapes_damage`` /
    # ``consume_magic_for_status`` / ``yin_yang_effect`` / ``flower_burst`` /
    # ``draw_to_hand_limit`` 这六个"带公式的专用原子"已把公式搬进卡数据
    # （取值表达式 + 通用原子），实现整个删除；旧名写出来会拿到
    # ``mod_spec_v2.REMOVED_ATOMIC_OPS`` 的显式报错（含替代写法指路）：
    #   * 施加丛林状态 → ``status_add_named(status=…, log="{target}获得{amount}层…")``
    #   * 魔法葡萄      → ``direct_damage(hits: 1 + equipment_count(target))``
    #   * 消耗 M 叠状态 → ``set_var`` + ``player_prop_set(magic=0)`` + ``status_add_named``
    #   * 阴阳          → ``set_var(deck_count)`` + ``move_cards_to_deck(bottom)`` + ``draw_cards``
    #   * 花朵绽放      → ``if(equipment_prop turns_equipped >= 1)`` + ``status_add_named``
    #                     + ``destroy_current_equipment``
    #   * 抽到手牌上限  → ``if(gap > 0)`` + ``draw_cards(amount: hand_limit - hand_count)``
    # 完整对照表与 A/B 证据见 docs/引擎原子与数据步骤清单.md §24。

    # Round 27：``discard``（自弃手牌尾部 N 张）与 ``random_discard_from_hand``
    # （随机弃目标手牌 N 张）也搬进卡数据——共性缺口只有"区域取牌"这一个取值
    # 能力，已补在 ``mod_runtime_v2.eval_v2_value``：
    #   * ``zone_random_ids``（新的取值表达式）= 区域里随机 N 张的 instance_id
    #   * ``zone_top_ids`` 新增 ``order: "bottom"`` = 从尾部往前取 N 张
    # 拆出来的写法（旧名写在 mod_spec_v2.REMOVED_ATOMIC_OPS 里带替代 JSON）：
    #   * 随机弃牌 → ``for_each(zone_random_ids)`` + ``move_to_discard`` + ``log``
    #   * 自弃尾部 → ``for_each(zone_top_ids(order: "bottom"))`` + ``move_to_discard``
    # 记账走统一的 :meth:`_discard_card_and_note`（与 ``move_to_discard`` /
    # ``discard_hand_by_paid_e`` 同一份实现）。A/B 见 docs/引擎原子与数据步骤清单.md §25。

    def _atomic_apply_turn_regen(self, player_id, card, params, log, choice, context):
        target_id = self._resolve_target(player_id, params.get('target', 'self'))
        if self._status_application_blocked(target_id, 'turn_magic_turns' if str(params.get('kind', 'heal')) == 'magic' else 'turn_heal_turns'):
            return
        turns = self._eval_int(player_id, params.get('turns', 1), card, 1)
        power = self._eval_int(player_id, params.get('power', 1), card, 1)
        kind = str(params.get('kind', 'heal'))
        suppressed = self._is_status_immune(target_id)
        if kind == 'magic':
            merged_turns, merged_power = self._merge_turn_regen_status(target_id, 'magic', turns, power)
            if not suppressed:
                self.players[target_id].gain_magic(power)
            remaining_turns = max(0, merged_turns - 1)
            self._set_custom_status_alias_group(target_id, 'jungle:turn_magic_turns', ('jungle:turn_magic_turns', 'turn_magic_turns'), remaining_turns)
            if remaining_turns <= 0:
                self._set_custom_status_alias_group(target_id, 'jungle:turn_magic_power', ('jungle:turn_magic_power', 'turn_magic_power'), 0)
            suffix = '' if suppressed else f'，+{power}M'
            self.log_msg(log or f"{self.pn(target_id)}获得魔力回合回复：{remaining_turns};{merged_power}{suffix}")
        else:
            merged_turns, merged_power = self._merge_turn_regen_status(target_id, 'heal', turns, power)
            if not suppressed:
                self.players[target_id].heal(power)
            remaining_turns = max(0, merged_turns - 1)
            self._set_custom_status_alias_group(target_id, 'jungle:turn_heal_turns', ('jungle:turn_heal_turns', 'turn_heal_turns'), remaining_turns)
            if remaining_turns <= 0:
                self._set_custom_status_alias_group(target_id, 'jungle:turn_heal_power', ('jungle:turn_heal_power', 'turn_heal_power'), 0)
            suffix = '' if suppressed else f'，+{power}H'
            self.log_msg(log or f"{self.pn(target_id)}获得回合回复：{remaining_turns};{merged_power}{suffix}")

    def _copy_copies_to_deck_top_payload(self, player_id, card, params, log, choice, context):
        # Round 33 / 批次 AB：``copy_card(to_zone:"deck_top", count:N)`` 的实现体
        # （``def_id`` 造牌、``flags``/``swift_value``/``magic_swift_value`` 等
        # 参数与旧 ``create_copies_to_deck_top`` 逐字一致）。
        target_id = self._resolve_target(player_id, params.get('target', 'self'))
        def_id = str(params.get('def_id') or (getattr(card, 'def_id', '') if card else ''))
        if not self._card_allowed(def_id):
            return
        count = min(20, max(0, self._eval_int(player_id, params.get('count', 1), card, 1)))
        flags = normalize_card_flags(params.get('flags', []))
        swift = self._eval_int(player_id, params.get('swift_value', 0), card, 0)
        magic_swift = self._eval_int(player_id, params.get('magic_swift_value', 0), card, 0)
        power = clamp_card_power(self._eval_int(player_id, params.get('power_value', 0), card, 0))
        extra_hits = clamp_card_extra_hits(self._eval_int(player_id, params.get('extra_hits', 0), card, 0))
        ps = self.players[target_id]
        made = []
        for _ in range(max(0, count)):
            new_card = CardInstance(def_id)
            new_card.instance_flags.update(flags)
            if swift > 0:
                new_card.swift_value = swift
                new_card.instance_flags.add('swift')
            if magic_swift > 0:
                new_card.magic_swift_value = magic_swift
                new_card.instance_flags.add('magic_swift')
            if power > 0:
                new_card.power_value = power
                new_card.instance_flags.add('power')
            if extra_hits > 0:
                new_card.extra_hits = extra_hits
                new_card.setup_modifiers.add('explicit_extra_hits')
            self._apply_setup_modifiers_to_card(target_id, new_card)
            self._apply_forced_unique_copy_penalty(
                target_id,
                new_card,
                source_owned=(card is not None and getattr(card, 'def_id', None) == def_id),
            )
            ps.deck.insert(0, new_card)
            made.append(new_card)
        if log:
            self.log_msg(log)

    def _jungle_team_members(self, target_id: int) -> List[int]:
        teams = getattr(self, 'teams', None)
        if not isinstance(teams, list):
            return []
        for team in teams:
            if not isinstance(team, (list, tuple)) or target_id not in team or len(team) < 2:
                continue
            return [
                int(member_id)
                for member_id in team
                if self._valid_player_id(member_id)
                and int(getattr(self.players[member_id], 'health', 0) or 0) > 0
            ]
        return []

    def _consume_jungle_root_layer_from_equipment(self, owner_id: int):
        if not (0 <= owner_id < len(self.players)):
            return
        candidates = []
        for equip_owner_id, owner_state in enumerate(self.players):
            for eq in list(getattr(owner_state, 'equipment', []) or []):
                tracked_layers = int(eq.custom_vars.get('jungle_root_layers', 0) or 0)
                if tracked_layers <= 0 and not self._card_matches_any_id(eq.card_instance, eq.card_def, ['Root', 'jungle:root']):
                    continue
                try:
                    effect_target = int(getattr(eq, 'effect_target', equip_owner_id))
                except (TypeError, ValueError):
                    effect_target = equip_owner_id
                if effect_target != owner_id:
                    continue
                candidates.append(eq)
        for eq in candidates:
            layers = int(eq.custom_vars.get('jungle_root_layers', 0) or 0)
            if layers <= 0:
                continue
            eq.custom_vars['jungle_root_layers'] = layers - 1
            return

    def _card_matches_any_id(self, card=None, card_def=None, ids=None) -> bool:
        """Return whether a card/equipment definition matches any legacy or namespaced id."""
        wanted = {str(item).strip().lower() for item in (ids or []) if str(item).strip()}
        if not wanted:
            return False
        candidates = []
        for obj in (card, card_def):
            if obj is None:
                continue
            for attr in ('def_id', 'id', 'legacy_id'):
                value = getattr(obj, attr, None)
                if value not in (None, ''):
                    candidates.append(str(value))
            nested_def = getattr(obj, 'card_def', None)
            if nested_def is not None and nested_def is not obj:
                for attr in ('def_id', 'id', 'legacy_id'):
                    value = getattr(nested_def, attr, None)
                    if value not in (None, ''):
                        candidates.append(str(value))
        for value in candidates:
            text = value.strip().lower()
            if text in wanted or text.split(':')[-1] in wanted:
                return True
        return False

    def _atomic_plank_immunity(self, player_id, card, params, log, choice, context):
        # Implemented through damage modifier hook; kept as an atomic no-op for readable mod data.
        return None

    def _shuffle_hand_payload(self, player_id, card, params, log, choice, context):
        # Round 33 / 批次 AB：``shuffle(zone:"hand")`` 的实现体（``target`` 走
        # 选择器集合；失明状态在这里静默跳过，战报文本保持原样）。
        for tid in self._resolve_targets(player_id, params.get('target', 'self')):
            if not (0 <= tid < len(self.players)):
                continue
            ps = self.players[tid]
            if ps.hand and not self._is_status_immune(tid):
                random.shuffle(ps.hand)
                self.log_msg(log or f"{self.pn(tid)}因失明打乱手牌")

    # Round 31 / 批次 Z：``for_each_target``（Round 16 的薄转发）已删除——
    # ``for_each(source:"wide_strike_targets", bind:"target")`` 是同一个循环驱动
    # 预设（``_loop_target_child_context`` 就是它的实现），因此不再需要一条
    # 独立原子。唯一的行为差是 ``for_each`` 不因 ``game_over`` 中断循环（本
    # 就不是公开契约），0 处卡数据使用。

    def _prepare_ocean_charge_for_play(self, card: Optional[CardInstance]):
        if card is None:
            return
        custom = getattr(card, 'custom_vars', None)
        if not isinstance(custom, dict):
            custom = {}
            card.custom_vars = custom
        custom.pop('_ocean_charge_resolved_this_play', None)
        used = custom.get('_once_per_play')
        if isinstance(used, dict):
            used.pop('ocean_charge', None)

    # Round 42 / 批次 AF 复核：``charge_self_damage`` **保留**。它与其它候选不同
    # ——**不是卡数据步骤，而是引擎在出牌结算内部自己调用的钩子**：
    # ``_play_card``（game_engine.py:8154/9096）、响应牌结算（:8486）与
    # 2v2 的对应位置（game_engine_2v2.py:868/1542）都在"扣费→进弃牌堆→
    # ``_prepare_ocean_charge_for_play``"之后直接调用它，读的是卡属性
    # ``charge_value`` 并用 ``_once_per_play`` 的 ``ocean_charge`` 标记记账。
    # 数据层没有插进这段时机的入口（写``on_event(this_play)`` 的替代写法会让
    # 引擎的自动调用消失、时序也变），因此按"管线型"保留。
    # （Round 41 判定里写的"卡面机制直接依赖"就是这四个调用点。）
    def _atomic_charge_self_damage(self, player_id, card, params, log, choice, context):
        """Resolve the "charge" keyword: the charged player damages itself once per play."""
        if card is None:
            return
        if self._once_per_play_used(card, 'ocean_charge'):
            return
        self._mark_once_per_play(card, 'ocean_charge')
        amount = max(0, int(getattr(card, 'charge_value', 0) or 0))
        if amount <= 0:
            return
        self._deal_direct_damage(
            player_id,
            amount,
            '电荷',
            player_id,
            damage_type=DAMAGE_TYPE_MAGIC,
            damage_tag=DAMAGE_TAG_BATTERY,
        )

    def _apply_ocean_blood_debt_after_physical_damage(self, target_id: int, attacker_id: int):
        if not (self._valid_player_id(target_id) and self._valid_player_id(attacker_id)):
            return
        stacks = self._custom_status_value(target_id, 'ocean:blood_debt', 'blood_debt', '血债')
        if stacks <= 0:
            return
        self._set_custom_status_alias_group(target_id, 'ocean:blood_debt', ('ocean:blood_debt', 'blood_debt', '血债'), 0)
        self.players[attacker_id].gain_elixir(stacks)
        self.log_msg(f"{self.pn(target_id)}的血债解除，{self.pn(attacker_id)}获得{stacks}E")

    # ------------------------------------------------------------------
    # Turn-start auto-play queue (generic)
    #
    # ``auto_play_queue`` holds one entry per "play this card again at the
    # start of my next turns" registration.  Entries are created by the
    # ``queue_auto_play`` data op and consumed by
    # ``_run_auto_play_queue_turn_start``.  ``ocean_auto_cards`` is the
    # pre-rename name of the same list: it is kept as an alias (the very same
    # list object) so a battle that is already running when the server is
    # updated keeps its queue, and so older tooling keeps reading it.
    # ------------------------------------------------------------------
    AUTO_PLAY_QUEUE_KEY = 'auto_play_queue'
    AUTO_PLAY_QUEUE_LEGACY_KEYS = ('ocean_auto_cards',)
    AUTO_PLAY_QUEUE_MARKER = 'auto_play_no_queue'
    AUTO_PLAY_QUEUE_MAX_ENTRIES = 32
    AUTO_PLAY_DYNAMIC_TARGETS = (
        'lowest_health_enemy',
        'lowest_health_enemy_player',
        'random_selectable',
        'random_selectable_player',
    )

    def _normalise_auto_play_entry(self, entry):
        """Upgrade a queue entry written by an older build to the current shape."""
        if not isinstance(entry, dict):
            return None
        normalised = dict(entry)
        normalised.setdefault(
            'source',
            'instance' if normalised.get('card_instance_id') is not None else 'snapshot',
        )
        # Older entries always exiled the played copy.
        normalised.setdefault('exile', True)
        normalised.setdefault('each_turn', True)
        normalised.setdefault('cost', 'normal')
        normalised.setdefault('marker', self.AUTO_PLAY_QUEUE_MARKER)
        normalised.setdefault('require_selectable', True)
        normalised.setdefault('allow_self', False)
        normalised.setdefault('swift_value', 0)
        normalised.setdefault('magic_swift_value', 0)
        normalised.setdefault('log', '')
        normalised.setdefault('target_id', -1)
        return normalised

    def _auto_play_queue_entries(self, ps, create: bool = False):
        """Return this player's auto-play queue, migrating the legacy key once."""
        queue = ps.custom_vars.get(self.AUTO_PLAY_QUEUE_KEY)
        if not isinstance(queue, list):
            queue = []
        for legacy_key in self.AUTO_PLAY_QUEUE_LEGACY_KEYS:
            legacy = ps.custom_vars.get(legacy_key)
            if isinstance(legacy, list) and legacy is not queue:
                for raw_entry in legacy:
                    entry = self._normalise_auto_play_entry(raw_entry)
                    if entry is not None:
                        queue.append(entry)
        if create or queue or self.AUTO_PLAY_QUEUE_KEY in ps.custom_vars:
            ps.custom_vars[self.AUTO_PLAY_QUEUE_KEY] = queue
            for legacy_key in self.AUTO_PLAY_QUEUE_LEGACY_KEYS:
                # Deprecated alias pointing at the same list: one queue, one
                # play per entry, no matter which name a reader uses.
                ps.custom_vars[legacy_key] = queue
        return queue

    @classmethod
    def _is_dynamic_auto_play_target(cls, target_spec) -> bool:
        return cls._selector_ref(target_spec) in cls.AUTO_PLAY_DYNAMIC_TARGETS

    def _resolve_auto_play_target(self, player_id: int, entry: dict) -> int:
        """Resolve the target of a queued entry (dynamic entries at trigger time)."""
        if not isinstance(entry, dict):
            return -1
        target_spec = entry.get('target_ref')
        if target_spec is None:
            target_spec = entry.get('target')
        if target_spec is not None and self._is_dynamic_auto_play_target(target_spec):
            return self._resolve_target(player_id, target_spec)
        try:
            target_id = int(entry.get('target_id', -1))
        except (TypeError, ValueError):
            target_id = -1
        return target_id

    @staticmethod
    def _remove_auto_play_entry(entries, entry) -> None:
        for index, candidate in enumerate(list(entries)):
            if candidate is entry:
                del entries[index]
                return

    def _auto_play_queue_payload(self, player_id, card, params, log, choice, context):
        # Round 33 / 批次 AC：``auto_play(mode:"queue")`` 的实现体（旧
        # ``queue_auto_play``：登记"拥有者回合开始时自动打出"的队列条目）。
        """Register a card so it is played automatically at the owner's turn start."""
        if not self._valid_player_id(player_id):
            return
        source_card = self._resolve_card_ref(
            player_id, params.get('card', {'ref': 'current_card'}), card
        )
        if source_card is None:
            source_card = card
        if source_card is None:
            return
        markers = set(getattr(source_card, 'instance_flags', set()) or set())
        if markers & {'ocean_no_auto', self.AUTO_PLAY_QUEUE_MARKER}:
            # A copy produced by the queue never registers itself again.
            return
        if bool(params.get('once_per_play', True)):
            try:
                if int(getattr(source_card, 'fission_hit', 0) or 0) > 0:
                    # Fission replays the same play; only the first hit queues.
                    return
            except Exception:
                pass
        ps = self.players[player_id]
        queue = self._auto_play_queue_entries(ps, create=True)
        if bool(params.get('dedupe', False)):
            # 表格14 R170（魔法珍珠）：效果是"每个回合开始时自动对其打出1张"，
            # 不是"本局每打出过1次就多1张"。同一张牌的旧队列项先移除，只保留
            # 最新一次（目标也会跟着更新到最近一次选择）。
            source_def = str(getattr(source_card, 'def_id', '') or '')
            queue[:] = [
                existing for existing in queue
                if not (
                    isinstance(existing, dict)
                    and str(existing.get('def_id') or '') == source_def
                )
            ]
        max_entries = max(
            1,
            self._eval_int(
                player_id,
                params.get('max_entries', self.AUTO_PLAY_QUEUE_MAX_ENTRIES),
                card,
                self.AUTO_PLAY_QUEUE_MAX_ENTRIES,
            ),
        )
        if len(queue) >= max_entries:
            return
        target_spec = params.get('target', 'target')
        target_ref = None
        if self._is_dynamic_auto_play_target(target_spec):
            target_id = -1
            target_ref = target_spec
        else:
            target_id = self._resolve_target(player_id, target_spec)
        source = str(params.get('source', 'snapshot') or 'snapshot').strip().lower()
        if source not in ('snapshot', 'instance'):
            source = 'snapshot'
        entry = {
            'def_id': str(getattr(source_card, 'def_id', '') or ''),
            'source': source,
            'target_id': int(target_id),
            'target_ref': target_ref,
            'swift_value': self._eval_int(player_id, params.get('swift_value', 0), card, 0),
            'magic_swift_value': self._eval_int(
                player_id, params.get('magic_swift_value', 0), card, 0
            ),
            'exile': bool(params.get('exile', False)),
            'each_turn': bool(params.get('each_turn', True)),
            'cost': str(params.get('cost', 'normal') or 'normal').strip().lower(),
            'marker': str(params.get('marker') or self.AUTO_PLAY_QUEUE_MARKER),
            'require_selectable': bool(params.get('require_selectable', True)),
            'allow_self': bool(params.get('allow_self', False)),
            'log': str(params.get('log') or ''),
            'no_auto': True,
        }
        if source == 'instance':
            entry['card_instance_id'] = int(getattr(source_card, 'instance_id', -1) or -1)
        else:
            entry['card'] = source_card.to_dict() if hasattr(source_card, 'to_dict') else None
        queue.append(entry)

    def _void_add_card_to_deck_random(self, target_id: int, card: CardInstance):
        if not self._valid_player_id(target_id) or card is None:
            return
        deck = self.players[target_id].deck
        deck.insert(random.randint(0, len(deck)) if deck else 0, card)

    def _void_weighted_card_id(self, card_type: Optional[str] = None, exclude: Optional[Set[str]] = None) -> Optional[str]:
        exclude = exclude or set()
        allowed_ids = getattr(self, 'allowed_card_ids', None)
        allowed_ids = set(allowed_ids or []) if allowed_ids is not None else None
        weighted = []
        for def_id, card_def in CARD_DEFS.items():
            if def_id in exclude or def_id == ERROR_CARD_ID:
                continue
            if allowed_ids is not None and def_id not in allowed_ids:
                continue
            if card_type and getattr(card_def, 'card_type', '') != card_type:
                continue
            if int(getattr(card_def, 'count', 0) or 0) <= 0:
                continue
            card_flags = normalize_card_flags(getattr(card_def, 'flags', set()) or set())
            if 'sublime' in card_flags:
                continue
            # 反馈 #101：队伍限定牌只允许在带队伍的模式（2v2）进入疤痕随机池。
            if 'team_limited' in card_flags and not hasattr(self, 'team_of'):
                continue
            weighted.extend([def_id] * max(1, int(getattr(card_def, 'count', 0) or 0)))
        return random.choice(weighted) if weighted else None

    def _void_resolve_card_def_id(self, raw_id: Any) -> Optional[str]:
        text = str(raw_id or '').strip()
        if not text:
            return None
        if text in CARD_DEFS:
            return text
        for def_id, card_def in CARD_DEFS.items():
            resource = getattr(card_def, 'v2_resource', {}) or {}
            known = {
                str(resource.get('id', '') or ''),
                str(resource.get('legacy_id', '') or ''),
                str(resource.get('runtime_id', '') or ''),
                str(getattr(card_def, 'id', '') or ''),
            }
            if text in known:
                return def_id
        path = text.split(':', 1)[1] if ':' in text else text
        pascal = ''.join(part.capitalize() for part in path.replace('-', '_').split('_') if part)
        return pascal if pascal in CARD_DEFS else None

    def _restore_prop_snapshot_store(self, target_id: int, store_name: str) -> None:
        """Restore every card property remembered under ``store_name``."""
        if not self._valid_player_id(target_id) or not store_name:
            return
        ps = self.players[target_id]
        snapshots = ps.custom_vars.pop(store_name, {})
        if not isinstance(snapshots, dict):
            return
        for instance_id, original in snapshots.items():
            restored_card = self._find_card_by_instance_id(instance_id)
            if restored_card is None:
                continue
            owner_id, _, _ = self._find_card_location(restored_card)
            if owner_id != target_id:
                continue
            if isinstance(original, dict):
                setattr(
                    restored_card,
                    str(original.get('property', 'cost_e_override')),
                    original.get('value'),
                )
            else:
                restored_card.cost_e_override = original

    def _prop_snapshot_restore_info(self, eq) -> Optional[dict]:
        custom = getattr(getattr(eq, 'card_instance', None), 'custom_vars', None)
        if not isinstance(custom, dict):
            return None
        info = custom.get('_prop_snapshot_restore')
        return info if isinstance(info, dict) else None

    def _has_other_prop_snapshot_targeting(self, target_id: int, store_name: str, exclude_eq=None) -> bool:
        for owner_id, owner_state in enumerate(self.players):
            for candidate in list(getattr(owner_state, 'equipment', []) or []):
                if candidate is exclude_eq:
                    continue
                info = self._prop_snapshot_restore_info(candidate)
                if not info or str(info.get('store') or '') != str(store_name or ''):
                    continue
                if self._equipment_effect_target_id(candidate, owner_id) == target_id:
                    return True
        return False

    def _apply_prop_snapshot_restore_on_leave(self, effect_target_id: int, eq) -> None:
        """Restore a registered snapshot when its equipment leaves play."""
        info = self._prop_snapshot_restore_info(eq)
        if not info:
            return
        store_name = str(info.get('store') or '')
        if not store_name:
            return
        try:
            owner_target = int(info.get('owner', effect_target_id))
        except (TypeError, ValueError):
            owner_target = effect_target_id
        if not self._valid_player_id(owner_target):
            owner_target = effect_target_id
        if self._has_other_prop_snapshot_targeting(owner_target, store_name, exclude_eq=eq):
            return
        self._restore_prop_snapshot_store(owner_target, store_name)

    def _random_auto_play_target(self, actor_id: int, top_card: CardInstance) -> int:
        """Random legal target for a card that is played automatically.

        The card decides what it needs: ``wide_strike``/``self_only`` cards need
        no target, attack cards hit an enemy (plus the player itself when they
        carry ``self_target``) and every other card follows the ``allowed``
        value of its own target request.
        """
        flags = self._effective_card_flags(top_card)
        if 'wide_strike' in flags or 'self_only' in flags:
            return -1
        if top_card.card_type == 'thorn':
            if hasattr(self, 'get_enemies'):
                candidate_ids = list(self.get_enemies(actor_id))
            else:
                candidate_ids = [pid for pid in range(len(self.players)) if pid != actor_id]
            if 'self_target' in flags:
                candidate_ids.append(actor_id)
            candidates = [
                tid for tid in dict.fromkeys(candidate_ids)
                if self._target_can_be_selected(actor_id, tid, allow_self='self_target' in flags)
            ]
            from engine_runtime_support import forced_random_target
            return forced_random_target(self, actor_id, candidates)
        needs_target = self._v2_play_requires_choice_target(top_card) or self._root_play_requires_owner_target(top_card)
        if not needs_target:
            return -1
        request = self._get_choice_request(top_card)
        request_params = self._effect_params(request) if isinstance(request, dict) else {}
        allowed = str(request_params.get('allowed', 'any') or 'any').strip().lower()
        if allowed in ('self', 'owner'):
            candidate_ids = [actor_id]
        elif allowed in ('enemy', 'enemies', 'opponent', 'opponents'):
            candidate_ids = list(self.get_enemies(actor_id)) if hasattr(self, 'get_enemies') else [pid for pid in range(len(self.players)) if pid != actor_id]
        elif allowed in ('friendly', 'ally', 'allies'):
            candidate_ids = [pid for pid in range(len(self.players)) if self._same_timer_side(actor_id, pid)]
        else:
            candidate_ids = list(range(len(self.players)))
        candidates = [
            tid for tid in dict.fromkeys(candidate_ids)
            if self._target_can_be_selected(actor_id, tid, allow_self=True)
        ]
        from engine_runtime_support import forced_random_target
        return forced_random_target(self, actor_id, candidates)

    def _auto_play_zone_top_payload(self, player_id, card, params, log, choice, context):
        # Round 33 / 批次 AC：``auto_play(mode:"zone_top")`` 的实现体（旧
        # ``auto_play_zone_top``：把某区顶牌自动打出，Kitty 类）。
        """Make a player play the first selectable card of one of their zones.

        Used by equipment that forces another player to keep playing cards; the
        default parameters reproduce the void Kitty behaviour (deck top, free
        play, random legal target, card returned to its zone when it cannot be
        played).
        """
        if not self._valid_player_id(player_id):
            return
        require_turn_player = params.get('require_turn_player', 'self')
        if require_turn_player is not None:
            turn_player_id = (
                player_id
                if str(require_turn_player).strip().lower() in ('self', 'owner', 'source')
                else self._resolve_target(player_id, require_turn_player)
            )
            if int(getattr(self, 'current_player', -1)) != int(turn_player_id):
                return
            if getattr(self, '_turn_start_skipped_player_id', None) == turn_player_id:
                return
            owner = self.players[turn_player_id] if self._valid_player_id(turn_player_id) else None
            if owner is not None and (
                int(getattr(owner, 'skip_turn', 0) or 0) > 0
                or int(getattr(owner, 'forced_skip_turn', 0) or 0) > 0
            ):
                return
        actor_selector = params.get('actor', {'ref': 'equipment_target'})
        actor_id = self._resolve_target(player_id, actor_selector)
        if not self._valid_player_id(actor_id) or self.players[actor_id].health <= 0:
            return
        if bool(params.get('skip_when_actor_skipped', True)):
            actor = self.players[actor_id]
            if (
                int(getattr(actor, 'skip_turn', 0) or 0) > 0
                or int(getattr(actor, 'forced_skip_turn', 0) or 0) > 0
            ):
                return
        zone = str(params.get('zone', 'deck') or 'deck').strip().lower()
        actor_ps = self.players[actor_id]
        live_zone = {
            'deck': actor_ps.deck,
            'discard': actor_ps.discard,
            'exile': actor_ps.exile,
        }.get(zone, actor_ps.hand)
        card_index = -1
        for index, candidate in enumerate(list(live_zone)):
            if self._card_selectable_by_action(candidate):
                card_index = index
                break
        if card_index < 0:
            return
        top_card = live_zone[card_index]
        flags = self._effective_card_flags(top_card)
        target_id = -1
        if bool(params.get('random_target', True)):
            needs_target = top_card.card_type == 'thorn' or (
                'self_only' not in flags
                and (
                    self._v2_play_requires_choice_target(top_card)
                    or self._root_play_requires_owner_target(top_card)
                )
            )
            target_id = self._random_auto_play_target(actor_id, top_card)
            if needs_target and 'wide_strike' not in flags and 'self_only' not in flags and target_id < 0:
                return
        else:
            target_id = self._resolve_target(actor_id, params.get('target', 'target'))
        if top_card not in live_zone:
            return
        live_zone.remove(top_card)
        self.players[actor_id].add_to_hand(
            top_card,
            trigger_enter_hand=bool(params.get('enter_hand_trigger', False)),
        )
        card_name = top_card.name_cn
        self.log_msg(self._format_step_log(
            log or "小猫使{actor}自动打出{card}",
            target=self.pn(actor_id),
            source=self.pn(player_id),
            name=card_name,
            card=card_name,
            actor=self.pn(actor_id),
            count=1,
        ))
        auto_choice = {'_ally_approved': True}
        if target_id >= 0:
            auto_choice.update({'target_player_id': target_id, 'target_player': target_id, 'target_id': target_id})
        previous_auto_actor = getattr(self, '_allow_out_of_turn_auto_play_for', None)
        previous_auto_choice = getattr(self, '_auto_resolve_choices_for', None)
        previous_auto_no_cost = getattr(self, '_auto_play_no_cost_for', None)
        out_of_turn = bool(params.get('out_of_turn', True))
        free_play = str(params.get('cost', 'free') or 'free').strip().lower() == 'free'
        if out_of_turn:
            self._allow_out_of_turn_auto_play_for = actor_id
        if bool(params.get('auto_resolve_choices', True)):
            self._auto_resolve_choices_for = actor_id
        if free_play:
            self._auto_play_no_cost_for = actor_id
        result = None
        try:
            if hasattr(self, 'teams'):
                result = self.play_card(actor_id, top_card.instance_id, target_id, auto_choice)
            else:
                result = self.play_card(actor_id, top_card.instance_id, auto_choice)
        finally:
            self._allow_out_of_turn_auto_play_for = previous_auto_actor
            self._auto_resolve_choices_for = previous_auto_choice
            self._auto_play_no_cost_for = previous_auto_no_cost
        failure_mode = str(params.get('on_failure', 'return') or 'return').strip().lower()
        pending_windows = (
            result is not None
            and (
                result.get('needs_response')
                or result.get('needs_choice')
                or result.get('needs_v2_ui')
            )
        )
        if (
            failure_mode != 'keep_hand'
            and not pending_windows
            and top_card in self.players[actor_id].hand
        ):
            # The play did not consume the card: put it back where it came from
            # so a forced play can never strand a card in the actor's hand.
            self.players[actor_id].hand.remove(top_card)
            index = min(max(0, card_index), len(live_zone))
            live_zone.insert(index, top_card)

    def _fresh_void_transformed_card(self, player_id: int, def_id: str) -> CardInstance:
        """Create a clean replacement containing only the destination card's own rules."""
        transformed = CardInstance(def_id)
        card_def = transformed.card_def
        transformed.fission_level = clamp_card_layer(getattr(card_def, 'fission_level', 1) or 1)
        transformed.fusion_level = clamp_card_layer(getattr(card_def, 'fusion_level', 1) or 1)
        transformed.fission_count = max(0, transformed.fission_level - 1)
        transformed.fusion_multiplier = float(transformed.fusion_level)
        self._apply_setup_modifiers_to_card(player_id, transformed)
        return transformed

    def _run_void_transformed_equipment_on_equip(self, owner_id: int, eq: EquipmentInstance) -> None:
        """Run immediate equip effects without equipping the transformed card twice."""
        event_def = self._get_v2_event_def(eq.card_def, 'on_play')
        if not event_def:
            return
        if isinstance(event_def, dict):
            raw_steps = event_def.get('steps', event_def.get('effects', []))
        else:
            raw_steps = event_def
        if not isinstance(raw_steps, list):
            return
        steps = [
            step for step in raw_steps
            if not self._is_target_request_step(step)
            and self._effect_type(step) != 'place_as_equip'
        ]
        if not steps:
            return
        target_id = self._equipment_effect_target_id(eq, owner_id)
        selected_target = owner_id if self._card_is_self_only(eq.card_instance) else target_id
        equip_choice = {
            'target_player': selected_target,
            'target_player_id': selected_target,
            'target_id': selected_target,
        }
        self._run_v2_card_event(
            owner_id,
            eq.card_instance,
            'on_play',
            equip_choice,
            {
                'source_id': owner_id,
                'target_id': selected_target,
                'target_player': selected_target,
                'target_player_explicit': True,
                'equipment_owner_id': owner_id,
            },
            {'steps': steps},
        )

    def _garden_equipment_targeting(self, player_id: int, *marks: str):
        if not self._valid_player_id(player_id):
            return []
        return [
            (owner_id, eq)
            for owner_id, eq in self._iter_equipment_targeting_player(player_id)
            if any(self._equipment_has_mark(eq, mark) for mark in marks)
        ]

    def _garden_equipment_flag_targeting(self, player_id: int, *flags: str):
        """Active equipment targeting ``player_id`` that declares any of *flags*."""
        if not self._valid_player_id(player_id):
            return []
        return [
            (owner_id, eq)
            for owner_id, eq in self._iter_equipment_targeting_player(player_id)
            if any(self._card_has_flag(getattr(eq, 'card_instance', None), flag) for flag in flags)
        ]

    def _garden_players_are_enemies(self, first_id: int, second_id: int) -> bool:
        if not self._valid_player_id(first_id) or not self._valid_player_id(second_id):
            return False
        is_enemy = getattr(self, 'is_enemy', None)
        if callable(is_enemy):
            try:
                return bool(is_enemy(first_id, second_id))
            except Exception:
                pass
        return first_id != second_id

    def _garden_snapshot_current_cards(self, player_id: int, zones=None) -> List[dict]:
        if not self._valid_player_id(player_id):
            return []
        ps = self.players[player_id]
        wanted = [str(zone) for zone in zones] if isinstance(zones, (list, tuple, set)) else None
        if wanted is None:
            wanted = ['hand', 'deck', 'discard', 'exile', 'equipment']
        cards = []
        for zone in wanted:
            if zone == 'equipment':
                cards.extend(
                    eq.card_instance
                    for eq in list(getattr(ps, 'equipment', []) or [])
                    if getattr(eq, 'card_instance', None) is not None
                )
            else:
                cards.extend(list(getattr(ps, zone, []) or []))
        return [
            copy.deepcopy(card.to_dict())
            for card in cards
            if getattr(card, 'def_id', ERROR_CARD_ID) != ERROR_CARD_ID
        ]

    def _clear_turn_scoped_effects(self, player_id: int):
        """Drop turn-scoped registrations owned by the player whose turn ended."""
        if not self._valid_player_id(player_id):
            return
        ps = self.players[player_id]
        entries = ps.custom_vars.get(PLAY_LISTENERS_KEY)
        if isinstance(entries, list):
            kept = [
                entry for entry in entries
                if isinstance(entry, dict) and str(entry.get('duration') or 'turn') != 'turn'
            ]
            if kept:
                ps.custom_vars[PLAY_LISTENERS_KEY] = kept
            else:
                ps.custom_vars.pop(PLAY_LISTENERS_KEY, None)
        self._clear_stale_absorbers(player_id)

    def _clear_stale_absorbers(self, owner_id: int):
        """Absorbers that never triggered expire with their owner's turn."""
        events = self.custom_vars.get(ABSORB_ATTACK_DAMAGE_KEY)
        if not isinstance(events, dict):
            return
        for key in list(events.keys()):
            entries = events.get(key)
            if not isinstance(entries, list):
                events.pop(key, None)
                continue
            # Round 16: ``duration`` joins the listener contract; a default
            # ``turn`` absorber expires with its owner's turn exactly as before,
            # a longer-lived one is kept.
            kept = [
                entry for entry in entries
                if not (
                    int(entry.get('owner_id', -1)) == int(owner_id)
                    and str(entry.get('duration') or 'turn') == 'turn'
                )
            ]
            if kept:
                events[key] = kept
            else:
                events.pop(key, None)
        if not events:
            self.custom_vars.pop(ABSORB_ATTACK_DAMAGE_KEY, None)

    def _atomic_absorb_attack_damage(self, player_id, card, params, log, choice, context):
        """Register a one-shot absorber for the next attack hit.

        The registration is consumed by :meth:`_consume_absorb_attack_damage`
        from inside ``deal_attack_damage`` -- the same hook the legacy copper rod
        used -- so the damage never lands and ``body`` runs with
        ``vars['absorbed_damage']`` set to the prevented amount.

        Round 16 shares the listener contract: ``trigger`` (``attack_hit``),
        ``duration`` (default ``turn``), ``body`` (aliases
        ``effects``/``steps``), an optional fire-time ``condition`` and
        ``once`` (default true, preserving the historical one-shot absorber).
        """
        trigger = normalize_listener_trigger('absorb_attack_damage', params.get('trigger'), default='attack_hit')
        if not listener_trigger_is_supported('absorb_attack_damage', trigger):
            self._log_mod_runtime_error(
                'absorb_attack_damage', RuntimeError(f'unsupported trigger: {trigger}'), player_id, card,
            )
            return
        live_context = context if isinstance(context, dict) else {}
        scope = str(params.get('scope', 'responded_card') or 'responded_card')
        target_id = self._resolve_target(player_id, params.get('target', 'self'))
        if not self._valid_player_id(target_id):
            return
        original = live_context.get('original_card')
        if scope in ('any', 'any_attack', 'all_attacks'):
            key = '_any'
        else:
            key = str(getattr(original, 'instance_id', '') or '')
            if not key:
                key = '_any'
        events = self.custom_vars.get(ABSORB_ATTACK_DAMAGE_KEY)
        if not isinstance(events, dict):
            events = {}
            self.custom_vars[ABSORB_ATTACK_DAMAGE_KEY] = events
        entries = events.get(key)
        if not isinstance(entries, list):
            entries = []
            events[key] = entries
        entries.append({
            'owner_id': player_id,
            'target_id': target_id,
            'source_card': card.to_dict() if card is not None else None,
            'effects': listener_body_from_params(params),
            'once': params.get('once', True) is not False,
            'duration': str(params.get('duration', params.get('turns', 'turn')) or 'turn'),
            'condition': listener_condition_from_params(params),
        })
        if log is not False and log:
            self.log_msg(self._format_step_log(log, target=self.pn(target_id), source=self.pn(player_id)))

    def _consume_absorb_attack_damage(self, target_id: int, source_card, damage: int,
                                      attacker_id: int = -1) -> bool:
        """Consume a registered absorber for *target_id* and run its body."""
        if damage <= 0 or not self._valid_player_id(target_id):
            return False
        events = self.custom_vars.get(ABSORB_ATTACK_DAMAGE_KEY)
        if not isinstance(events, dict) or not events:
            return False
        card_key = str(getattr(source_card, 'instance_id', '') or '')
        entry = None
        used_key = None
        for candidate_key in (card_key, '_any'):
            if not candidate_key:
                continue
            entries = events.get(candidate_key)
            if not isinstance(entries, list):
                continue
            for item in entries:
                if not isinstance(item, dict):
                    continue
                if int(item.get('target_id', -1)) == int(target_id):
                    entry = item
                    used_key = candidate_key
                    break
            if entry is not None:
                break
        if entry is None:
            return False
        condition = entry.get('condition')
        if condition is not None:
            gate_context = {
                'source_player': int(entry.get('owner_id', target_id) or target_id),
                'target_player': int(target_id),
                'source_id': int(attacker_id),
                'target_id': int(target_id),
            }
            if not self._loop_iteration_allows(
                int(entry.get('owner_id', target_id) or target_id),
                source_card,
                condition,
                gate_context,
            ):
                return False
        if entry.get('once', True) is not False:
            entries = events.get(used_key) or []
            try:
                entries.remove(entry)
            except ValueError:
                pass
            if not entries:
                events.pop(used_key, None)
            if not events:
                self.custom_vars.pop(ABSORB_ATTACK_DAMAGE_KEY, None)
        owner_id = int(entry.get('owner_id', -1))
        if not self._valid_player_id(owner_id):
            owner_id = target_id
        body = entry.get('effects') if isinstance(entry.get('effects'), list) else []
        source_dict = entry.get('source_card')
        if isinstance(source_dict, dict):
            try:
                body_card = CardInstance.from_dict(copy.deepcopy(source_dict))
            except Exception:
                body_card = source_card
        else:
            body_card = source_card
        if body_card is None:
            body_card = card
        ctx = {
            'source_player': owner_id,
            'target_player': target_id,
            'source_id': attacker_id,
            'target_id': target_id,
            'damage_source': attacker_id,
            'absorbed_damage': int(damage),
            'absorb_attacker': int(attacker_id),
            'card': body_card,
            'vars': {
                'absorbed_damage': int(damage),
                'absorb_attacker': int(attacker_id),
                'absorb_target': int(target_id),
                'target_player': int(target_id),
            },
        }
        if body:
            self._run_effect_list(owner_id, body_card, body, None, ctx)
        return True

    def _atomic_add_charge_to_hand(self, player_id, card, params, log, choice, context):
        """Add charge layers to every hand card of the target.

        ``total`` is the amount to spread, ``mode`` how to spread it:
        ``ceil_even`` (default, matches the copper rod: every card gains
        ``ceil(total / hand size)``), ``exact`` (``total // hand size``) and
        ``fixed`` (``amount`` per card).
        """
        total = self._resolve_step_number(player_id, params.get('total', 0), card, 0)
        mode = str(params.get('mode', 'ceil_even') or 'ceil_even')
        for tid in self._resolve_step_targets(player_id, params.get('target', 'self'), context):
            if not self._valid_player_id(tid):
                continue
            hand = list(getattr(self.players[tid], 'hand', []) or [])
            amount = 0
            if mode == 'fixed':
                amount = max(0, self._eval_int(player_id, params.get('amount', 1), card, 1))
            elif hand and total > 0:
                if mode == 'exact':
                    amount = total // len(hand)
                else:
                    amount = int(math.ceil(total / float(len(hand))))
            if amount > 0:
                for hand_card in hand:
                    hand_card.charge_value = max(0, int(getattr(hand_card, 'charge_value', 0) or 0)) + amount
                    hand_card.instance_flags.add('charge')
                    hand_card.disabled_flags.discard('charge')
            if log is not False and log:
                self.log_msg(self._format_step_log(
                    log,
                    target=self.pn(tid),
                    source=self.pn(player_id),
                    amount=amount,
                    count=len(hand),
                    total=total,
                ))

    # ------------------------------------------------------------------
    # Round 37 / 批次 AD-2：监听 / 收尾 / 触发四合一 —— ``on_event``
    # （旧 ``once_per_play`` / ``register_play_listener`` / ``after_all`` /
    # ``magic_relic_trigger``，四个旧名进 REMOVED_ATOMIC_OPS）。
    #
    # ``trigger`` 选**监听的是哪个时点**；四条分支的实现体逐字沿用旧原子，
    # 所以时点语义与合并前一致：
    #
    #   * ``play``（默认，旧 ``register_play_listener``）—— 登记一条"拥有者
    #     本回合每次出牌后"的监听（``PLAY_LISTENERS_KEY`` / ``_run_play_listeners``）；
    #     ``scope`` / ``duration`` / ``target`` / ``exclude_card_ids`` / ``once`` /
    #     ``condition`` 与原写法逐字对齐。
    #   * ``this_play``（旧 ``once_per_play``）—— 本次出牌内**立即**结算 body，
    #     每张牌实例每个 ``name`` 最多一次（标记存在卡实例上，随每次出牌清理）。
    #     ``once`` 键在这个分支照旧被忽略（旧 ``once_per_play`` 就是"每次出牌
    #     一次"本身），只在 ``play`` 分支里有意义。
    #   * ``after_all``（旧 ``after_all``，也可写成 ``after: true``）—— 把 body
    #     放到当前效果之后执行（与旧实现一样是"就地跑 body"，等价于 ``sequence``）。
    #   * ``equipment_trigger`` + ``effect:"magic_relic"``（旧
    #     ``magic_relic_trigger``）—— 魔法遗物：消耗队友 2M、自己 +3M；1v1
    #     没有队友，按旧实现直接返回。
    # ------------------------------------------------------------------
    ON_EVENT_TRIGGERS = ('play', 'this_play', 'after_all', 'equipment_trigger')
    ON_EVENT_EFFECTS = ('magic_relic',)

    def _atomic_on_event(self, player_id, card, params, log, choice, context):
        raw_trigger = str(self._step_text_value(player_id, card, params.get('trigger')) or '')
        if not raw_trigger.strip() and params.get('after') is True:
            # ``after: true`` 是 ``trigger:"after_all"`` 的简写（§33 的参数表）。
            raw_trigger = 'after_all'
        trigger = normalize_listener_trigger('on_event', raw_trigger, default='play')
        if not listener_trigger_is_supported('on_event', trigger):
            self._log_mod_runtime_error(
                'on_event', RuntimeError(f'unsupported trigger: {trigger}'), player_id, card,
            )
            return
        if trigger == 'play':
            self._register_play_listener_effect(player_id, card, params, log)
            return
        if trigger == 'this_play':
            self._this_play_once_effect(player_id, card, params, log, choice, context)
            return
        if trigger == 'after_all':
            body = listener_body_from_params(params)
            if body:
                self._run_effect_list(player_id, card, body, choice, context)
            return
        effect = str(params.get('effect') or params.get('preset') or '').strip().lower()
        if not effect or effect in self.ON_EVENT_EFFECTS:
            self._magic_relic_effect(player_id, card, params, log)
            return
        self._log_mod_runtime_error(
            'on_event', RuntimeError(f'unsupported effect: {effect}'), player_id, card,
        )

    def _register_play_listener_effect(self, player_id, card, params, log):
        """``on_event(trigger:"play")``：旧 ``register_play_listener`` 的实现体。

        The body runs through the engine effect pipeline with the *source* card
        put back into the context, so ``deal_damage`` keeps applying the card's
        own power/fusion modifiers exactly like the legacy snowball atom did.
        Round 16 shares the listener contract: ``trigger`` (``play``),
        ``duration`` (alias ``turns``), ``body`` (aliases ``effects``/``steps``),
        an optional fire-time ``condition`` and an optional ``once``.
        """
        target_id = self._resolve_target(player_id, params.get('target', 'target'))
        if not self._valid_player_id(target_id):
            return
        entries = self.players[player_id].custom_vars.get(PLAY_LISTENERS_KEY)
        if not isinstance(entries, list):
            entries = []
            self.players[player_id].custom_vars[PLAY_LISTENERS_KEY] = entries
        body = listener_body_from_params(params)
        entries.append({
            'owner_id': player_id,
            'target_id': target_id,
            'source_card': card.to_dict() if card is not None else None,
            'effects': body,
            'duration': str(params.get('duration', params.get('turns', 'turn')) or 'turn'),
            'scope': str(params.get('scope', 'owner_turn') or 'owner_turn'),
            'exclude_ids': [
                str(item) for item in (params.get('exclude_card_ids') or [])
                if str(item)
            ],
            'condition': listener_condition_from_params(params),
            'once': params.get('once') is True,
        })
        if log is not False and log:
            self.log_msg(self._format_step_log(log, target=self.pn(target_id), source=self.pn(player_id)))

    def _this_play_once_effect(self, player_id, card, params, log, choice, context):
        """``on_event(trigger:"this_play")``：旧 ``once_per_play`` 的实现体。

        The marker lives on the card instance and is cleared with the card's
        other per-play state, so copies of the card stay independent.  A false
        fire-time ``condition`` does **not** consume the marker (same as before).

        ``once`` 在这个分支里**照旧被忽略**：旧 ``once_per_play`` 就是
        "每次出牌一次"本身，0 处卡数据写过 ``once:false``，本批不为它引入新的
        行为（``once`` 只在 ``trigger:"play"`` 分支里有意义，那个分支沿用旧
        ``register_play_listener`` 的 ``once`` 语义）。
        """
        if card is None:
            return
        key = str(params.get('name') or params.get('key') or 'effect')
        if self._once_per_play_used(card, key):
            return
        body = listener_body_from_params(params)
        condition = listener_condition_from_params(params)
        if not self._loop_iteration_allows(player_id, card, condition, context):
            return
        self._mark_once_per_play(card, key)
        if body:
            self._run_effect_list(player_id, card, body, choice, context)

    def _magic_relic_effect(self, player_id, card, params, log):
        """``on_event(trigger:"equipment_trigger", effect:"magic_relic")``。"""

        if not hasattr(self, 'get_teammate'):
            return
        try:
            mate_id = self.get_teammate(player_id)
        except Exception:
            return
        if not (0 <= mate_id < len(self.players)):
            return
        mate = self.players[mate_id]
        if int(getattr(mate, 'magic', 0) or 0) < 2:
            return
        mate.magic -= 2
        self.players[player_id].gain_magic(3)
        self.log_msg(log or f"{self.pn(player_id)}的魔法遗物消耗{self.pn(mate_id)}2M，自己+3M")

    def _run_play_listeners(self, player_id: int, played_card: Optional[CardInstance]):
        """Fire every play listener registered by ``player_id`` for a played card."""
        if not self._valid_player_id(player_id) or played_card is None:
            return
        if self.current_player != player_id or self.phase != 'action':
            return
        entries = self.players[player_id].custom_vars.get(PLAY_LISTENERS_KEY)
        if not isinstance(entries, list) or not entries:
            return
        played_id = str(getattr(played_card, 'def_id', '') or '')
        for entry in list(entries):
            if not isinstance(entry, dict):
                continue
            exclude_ids = entry.get('exclude_ids') or []
            if exclude_ids:
                if played_id and str(played_id) in [str(item) for item in exclude_ids]:
                    continue
                if self._card_matches_any_id(played_card, getattr(played_card, 'card_def', None), exclude_ids):
                    continue
                played_local = self._card_local_id_values(played_card)
                if played_local & {str(item) for item in exclude_ids}:
                    continue
            try:
                target_id = int(entry.get('target_id', -1))
            except (TypeError, ValueError):
                continue
            if not self._valid_player_id(target_id) or int(self.players[target_id].health or 0) <= 0:
                continue
            source_dict = entry.get('source_card')
            if not isinstance(source_dict, dict):
                continue
            try:
                source_card = CardInstance.from_dict(copy.deepcopy(source_dict))
            except Exception:
                continue
            body = entry.get('effects')
            if not isinstance(body, list) or not body:
                continue
            context = {
                'source_player': player_id,
                'target_player': target_id,
                'source_id': player_id,
                'target_id': target_id,
                'card': source_card,
                'listener_target_id': target_id,
                'listener_owner_id': player_id,
                'vars': {
                    'listener_target_id': target_id,
                    'listener_owner_id': player_id,
                    'listener_played_card_id': getattr(played_card, 'instance_id', None),
                    'listener_played_card_def_id': played_id,
                },
            }
            condition = entry.get('condition')
            if condition is not None and not self._loop_iteration_allows(player_id, source_card, condition, context):
                continue
            self._run_effect_list(player_id, source_card, body, None, context)
            if entry.get('once') is True:
                try:
                    entries.remove(entry)
                except ValueError:
                    pass

    def _atomic_card_var_change(self, player_id, card, params, log, choice, context):
        """Round 29 / 批次 X：卡牌自定义变量的"设为 / 增加"两条合并成一条。

        ``mode`` 选 ``set``（默认）或 ``add``；``card`` 选目标牌（默认当前牌），
        ``name``/``var`` 选变量名。两段实现逐条搬过来，因此钳位口径保持原样：

        * ``set`` 认 ``clamp``（0..clamp 之间）与 ``max``（取更小值）；
        * ``add`` 认 ``maximum``/``max``（上限）与 ``minimum``/``min``（下限）。

        日志沿用旧行为：只在 ``log`` 是真值且不是 ``false`` 时打印（默认静默）。
        """
        mode = str(params.get('mode', 'set') or 'set').strip().lower()
        mode = {'=': 'set', 'set_to': 'set', 'assign': 'set',
                '+': 'add', '+=': 'add', 'increase': 'add'}.get(mode, mode)
        if mode not in ('set', 'add'):
            return
        target_card = self._resolve_card_ref(player_id, params.get('card', {'ref': 'current_card'}), card)
        if target_card is None:
            return
        name = str(params.get('name', params.get('var', '')) or '')
        if not name:
            return
        store = getattr(target_card, 'custom_vars', None)
        if not isinstance(store, dict):
            store = {}
            target_card.custom_vars = store
        if mode == 'add':
            amount = self._eval_int(player_id, params.get('value', params.get('amount', 0)), card, 0)
            value = int(store.get(name, 0) or 0) + amount
            maximum = params.get('maximum', params.get('max'))
            if maximum is not None:
                try:
                    value = min(int(self._eval_int(player_id, maximum, card, value)), value)
                except (TypeError, ValueError):
                    pass
            if params.get('minimum', params.get('min')) is not None:
                try:
                    value = max(int(self._eval_int(player_id, params.get('minimum', params.get('min')), card, value)), value)
                except (TypeError, ValueError):
                    pass
        else:
            value = self._eval_int(player_id, params.get('value', 0), card, 0)
            if params.get('clamp') is not None:
                try:
                    value = max(0, min(int(params.get('clamp') or 0), value))
                except (TypeError, ValueError):
                    pass
            if params.get('max') is not None:
                try:
                    value = min(int(self._eval_int(player_id, params.get('max'), card, value)), value)
                except (TypeError, ValueError):
                    pass
        store[name] = value
        if log is not False and log:
            self.log_msg(self._format_step_log(log, target=self.pn(player_id), amount=value))

    # Round 31 / 批次 Z：``card_var_set`` / ``card_var_add`` 两个兼容垫片已删除
    # （``card_var_change(mode=...)`` 是唯一实现）。

    def _reveal_card_set_payload(self, player_id, card, params, log, choice, context):
        """Privately reveal a card set (default: the target's starting deck).

        The payload is stored per viewer and shipped by ``get_public_state`` so
        only the requesting player sees the cards (garden magic antennae).
        Round 33 / 批次 AB：本方法从公开原子降为 ``reveal(mode:"card_set")``
        的实现体（私有名去掉 ``_atomic_`` 前缀，不再单独登记为 op）。
        """
        target_id = self._resolve_target(player_id, params.get('target', 'target'))
        if not self._valid_player_id(player_id) or not self._valid_player_id(target_id):
            return
        source = str(params.get('source', 'initial_deck') or 'initial_deck')
        viewer_id = self._resolve_target(player_id, params.get('viewer', 'self'))
        if not self._valid_player_id(viewer_id):
            viewer_id = player_id
        self._ensure_garden_initial_deck_storage()
        if source in ('initial_deck', 'starting_deck'):
            cards = self._garden_initial_decks[target_id]
            if not cards:
                cards = self._garden_snapshot_current_cards(target_id)
                self._garden_initial_decks[target_id] = copy.deepcopy(cards)
            label = '初始牌组'
        else:
            cards = self._garden_snapshot_current_cards(target_id, zones=(source,))
            label = {
                'hand': '手牌',
                'deck': '抽牌堆',
                'discard': '弃牌堆',
                'exile': '放逐区',
            }.get(source, source)
        # Round 31 / 批次 Z：``amount``/``top``/``limit`` 只展示前 N 张（吸收旧
        # ``reveal_deck_top`` 的"看牌堆顶 N 张"）；缺省仍是整个区。
        limit_raw = params.get('amount', params.get('top', params.get('limit')))
        if limit_raw is not None:
            limit = max(0, self._eval_int(player_id, limit_raw, card, 0))
            cards = list(cards)[:limit] if limit else []
        self._garden_initial_deck_reveal_serial = int(
            getattr(self, '_garden_initial_deck_reveal_serial', 0) or 0
        ) + 1
        self._garden_initial_deck_reveal[viewer_id] = {
            'token': self._garden_initial_deck_reveal_serial,
            'target_player_id': target_id,
            'target_name': self.pn(target_id),
            'cards': copy.deepcopy(cards),
        }
        default_log = f"{self.pn(viewer_id)}查看了{self.pn(target_id)}的{label}"
        self.log_msg(log or default_log)

    def _prop_snapshot_store(self, owner_id: int, store_name: str) -> dict:
        ps = self.players[owner_id]
        store = ps.custom_vars.get(store_name)
        if not isinstance(store, dict):
            store = {}
            ps.custom_vars[store_name] = store
        return store

    def _card_zone_cards(self, owner_id: int, zone: str) -> List[CardInstance]:
        if not self._valid_player_id(owner_id):
            return []
        if zone == 'equipment':
            return [
                eq.card_instance
                for eq in list(getattr(self.players[owner_id], 'equipment', []) or [])
                if getattr(eq, 'card_instance', None) is not None
            ]
        return list(getattr(self.players[owner_id], zone, []) or [])

    def _snapshot_filtered_cards(self, owner_id: int, zone: str, params: dict,
                                 player_id: int, card) -> List[CardInstance]:
        cards = self._card_zone_cards(owner_id, zone)
        max_base = params.get('max_base', params.get('max_base_cost_e'))
        max_base_value = None
        if max_base is not None:
            max_base_value = max(0, self._eval_int(player_id, max_base, card, 0))
        if max_base_value is None:
            return cards
        filtered = []
        for zone_card in cards:
            base = int(getattr(getattr(zone_card, 'card_def', None), 'cost_e', 0) or 0)
            if base <= max_base_value:
                filtered.append(zone_card)
        return filtered

    def _snapshot_card_props_payload(self, player_id, card, params, log, choice, context):
        """Remember a card property (per instance) so it can be restored later.

        Generic counterpart of the Quantum equipment: the store lives in the
        owner's ``custom_vars`` under ``store`` and records the *original* value
        of ``property`` for every card of the zone that passes the optional
        ``max_base`` (card definition ``cost_e``) filter.
        Round 33 / 批次 AB：本方法从公开原子降为 ``snapshot(mode:"card_props")``
        的实现体。
        """
        owner_id = self._resolve_target(player_id, params.get('owner', params.get('target', 'self')))
        if not self._valid_player_id(owner_id):
            return
        zone = str(params.get('zone', 'hand') or 'hand')
        store_name = str(params.get('store', params.get('store_as', 'card_prop_snapshot')) or 'card_prop_snapshot')
        prop = str(params.get('property', params.get('prop', 'cost_e_override')) or 'cost_e_override')
        store = self._prop_snapshot_store(owner_id, store_name)
        for zone_card in self._snapshot_filtered_cards(owner_id, zone, params, player_id, card):
            key = str(getattr(zone_card, 'instance_id', '') or '')
            if not key:
                continue
            store.setdefault(key, {
                'property': prop,
                'value': copy.deepcopy(getattr(zone_card, prop, None)),
            })
        restore_info = params.get('restore_on_destroy')
        if isinstance(restore_info, dict) and card is not None:
            custom = getattr(card, 'custom_vars', None)
            if not isinstance(custom, dict):
                custom = {}
                card.custom_vars = custom
            custom['_prop_snapshot_restore'] = {
                'store': store_name,
                'owner': owner_id,
            }
        if log is not False and log:
            self.log_msg(self._format_step_log(log, target=self.pn(owner_id), source=self.pn(player_id)))

    def _atomic_set_card_prop_random(self, player_id, card, params, log, choice, context):
        """Set ``property`` of every matching card to a random value in a range."""
        owner_id = self._resolve_target(player_id, params.get('owner', params.get('target', 'self')))
        if not self._valid_player_id(owner_id):
            return
        zone = str(params.get('zone', 'hand') or 'hand')
        prop = str(params.get('property', params.get('prop', 'cost_e_override')) or 'cost_e_override')
        low = self._eval_int(player_id, params.get('min', params.get('minimum', 1)), card, 1)
        high = self._eval_int(player_id, params.get('max', params.get('maximum', low)), card, low)
        if high < low:
            low, high = high, low
        for zone_card in self._snapshot_filtered_cards(owner_id, zone, params, player_id, card):
            setattr(zone_card, prop, random.randint(int(low), int(high)))
        if log is not False and log:
            self.log_msg(self._format_step_log(log, target=self.pn(owner_id), source=self.pn(player_id)))

    def _restore_card_props_payload(self, player_id, card, params, log, choice, context):
        """Restore the values remembered by :meth:`_snapshot_card_props_payload`."""
        owner_id = self._resolve_target(player_id, params.get('owner', params.get('target', 'self')))
        if not self._valid_player_id(owner_id):
            return
        store_name = str(params.get('store', params.get('store_as', 'card_prop_snapshot')) or 'card_prop_snapshot')
        prop = str(params.get('property', params.get('prop', '')) or '')
        ps = self.players[owner_id]
        snapshots = ps.custom_vars.pop(store_name, {})
        if not isinstance(snapshots, dict):
            snapshots = {}
        for instance_id, original in snapshots.items():
            restored_card = self._find_card_by_instance_id(instance_id)
            if restored_card is None:
                continue
            located_owner, _, _ = self._find_card_location(restored_card)
            if located_owner is not None and located_owner != owner_id:
                continue
            if isinstance(original, dict):
                target_prop = str(original.get('property', prop or 'cost_e_override'))
                setattr(restored_card, target_prop, original.get('value'))
            else:
                setattr(restored_card, prop or 'cost_e_override', original)
        marker = params.get('clear')
        if marker:
            ps.custom_vars.pop(str(marker), None)
        if log is not False and log:
            self.log_msg(self._format_step_log(log, target=self.pn(owner_id), source=self.pn(player_id)))

    def _atomic_transform_cards(self, player_id, card, params, log, choice, context):
        """Turn every card of the given zones into a random card of its category.

        Generic counterpart of the Void Scar: cards are looked up by weight
        (each definition contributes ``count`` entries) among the allowed card
        pool, Sublime cards are never produced, and equipment keeps the armor it
        already had and re-runs its equip steps.

        Round 14 / batch 2: ``owner``/``target`` 走统一选择器解析（多目标时逐人
        变换自己区域里的牌；标量选择器仍是单目标），``zone``/``zones`` 走统一
        区域词表，未知区域显式报错。``zones`` 里的 ``equipment`` 依旧由
        ``equipment_card_type`` 控制。
        """
        owner_ids = self._step_target_ids(
            player_id, card, params, context, op='transform_cards',
            default='self', keys=('owner', 'target'),
        )
        zones = self._step_zone_names(
            params, op='transform_cards',
            default=('hand', 'deck', 'discard', 'exile'),
        )
        if not owner_ids or not zones:
            return
        same_type = str(params.get('card_type', 'same') or 'same')
        include_self = params.get('exclude_self', True) is False
        equipment_type = str(params.get('equipment_card_type', 'root') or 'root')
        for owner_id in owner_ids:
            ps = self.players[owner_id]
            for zone in zones:
                if zone == 'equipment':
                    continue
                cards = list(getattr(ps, zone, []) or [])
                for index, old_card in enumerate(cards):
                    card_type = None if same_type in ('same', '') else same_type
                    if card_type is None:
                        card_type = getattr(old_card, 'card_type', '') or None
                    exclude = {getattr(old_card, 'def_id', '')} if not include_self else set()
                    new_id = self._void_weighted_card_id(card_type, exclude=exclude)
                    if not new_id:
                        continue
                    zone_list = getattr(ps, zone)
                    if index < len(zone_list) and zone_list[index] is old_card:
                        zone_list[index] = self._fresh_void_transformed_card(owner_id, new_id)
            transformed_equipment = []
            for eq in list(getattr(ps, 'equipment', []) or []):
                exclude = {getattr(eq, 'def_id', '')} if not include_self else set()
                new_id = self._void_weighted_card_id(equipment_type, exclude=exclude)
                if not new_id:
                    continue
                armor = getattr(eq, 'armor', 0)
                target = getattr(eq, 'effect_target', owner_id)
                self._cleanup_equipment_derived_effects(owner_id, eq, run_destroy_event=False)
                eq.card_instance = self._fresh_void_transformed_card(owner_id, new_id)
                eq.armor = armor
                eq.turns_equipped = 0
                eq.uses_this_turn = 0
                eq.corruption_active = False
                eq.custom_vars = {}
                flags = self._effective_card_flags(eq.card_instance)
                eq.effect_target = owner_id if 'self_only' in flags else target
                if self._equipment_uses_non_stack_rule(eq):
                    self._ensure_non_stack_equipment_order(eq)
                transformed_equipment.append(eq)
            if params.get('run_equip_effects', True) is not False:
                for eq in transformed_equipment:
                    self._run_void_transformed_equipment_on_equip(owner_id, eq)
            self._refresh_hand_limit_bonuses()
            self._refresh_equipment_derived_player_flags(owner_id)
            if log is not False and log:
                self.log_msg(self._format_step_log(log, target=self.pn(owner_id), source=self.pn(player_id)))

    def _garden_refresh_coal_cards(self):
        return

    def _garden_has_sunflower_targeting(self, player_id: int) -> bool:
        return bool(self._garden_equipment_flag_targeting(player_id, 'shield_decay_immune'))

    def _refresh_garden_magic_disc_bonuses(self):
        for target_id, ps in enumerate(self.players):
            old_bonus = max(0, int(ps.custom_vars.get('garden_magic_disc_armor_applied', 0) or 0))
            count = len(self._garden_equipment_flag_targeting(target_id, 'armor_per_copy_shield_scaled'))
            shield = self._custom_status_value(target_id, 'jungle:shield', 'shield')
            new_bonus = count * (3 if shield > 0 else 1)
            if old_bonus != new_bonus:
                ps.armor = max(0, int(ps.armor or 0) - old_bonus) + new_bonus
            if new_bonus > 0:
                ps.custom_vars['garden_magic_disc_armor_applied'] = new_bonus
            else:
                ps.custom_vars.pop('garden_magic_disc_armor_applied', None)

    def _garden_magic_cutter_after_hit(self, attacker_id: int, target_id: int, damage: int):
        if damage <= 0 or not self._garden_players_are_enemies(attacker_id, target_id):
            return
        copies = len(self._garden_equipment_flag_targeting(attacker_id, 'shield_on_attack_hit'))
        if copies <= 0:
            return
        amount = copies * 2
        current = self._custom_status_value(attacker_id, 'jungle:shield', 'shield')
        self._set_custom_status_alias_group(
            attacker_id,
            'jungle:shield',
            ('jungle:shield', 'shield'),
            current + amount,
        )
        self.log_msg(f"{self.pn(attacker_id)}的魔法锯齿使其获得{amount}层护盾")

    def _run_garden_magic_pollen_owner_turn_end(self, player_id: int):
        if not self._valid_player_id(player_id):
            return
        owner = self.players[player_id]
        for eq in list(getattr(owner, 'equipment', []) or []):
            if not self._card_has_flag(getattr(eq, 'card_instance', None), 'pollen_turn_end_fracture'):
                continue
            if not self._non_stack_equipment_is_active(eq) or owner.magic < 1:
                continue
            target_id = self._equipment_effect_target_id(eq, player_id)
            if not self._valid_player_id(target_id):
                continue
            petals = self._card_total_hits(eq.card_instance)
            self._spend_resource(player_id, 'magic', 1, eq.card_instance)
            self.players[target_id].fracture += petals
            self._note_achievement_status_peak(target_id)
            self.log_msg(f"{self.pn(player_id)}的魔法花粉消耗1M，使{self.pn(target_id)}获得{petals}层破损")

    def _garden_return_first_played_card(self, player_id: int, card: CardInstance):
        if not self._valid_player_id(player_id) or card is None:
            return
        if int(getattr(self, 'current_player', -1)) != player_id or self.phase != 'action':
            return
        marker = f"{int(getattr(self, '_turn_boundary_id', 0) or 0)}:{player_id}"
        ps = self.players[player_id]
        if str(ps.custom_vars.get('garden_cat_ears_return_marker', '')) == marker:
            return
        if not self._garden_equipment_flag_targeting(player_id, 'return_first_play_each_turn'):
            return
        owner_id, zone_name, located = self._find_card_location(card)
        if owner_id != player_id or zone_name not in ('deck', 'discard') or located is None:
            return
        zone = getattr(ps, zone_name)
        try:
            zone.remove(located)
        except ValueError:
            return
        ps.add_to_hand(located)
        ps.custom_vars['garden_cat_ears_return_marker'] = marker
        self.log_msg(f"{self.pn(player_id)}的猫耳使{located.name_cn}回到手中")

    def _dispatch_own_card_countered(self, card_user_id: int, responder_id: int,
                                     countered_card: Optional[CardInstance] = None) -> bool:
        """Fire the generic ``on_own_card_countered`` event.

        Generic counterpart of ``_trigger_sewers_cheese_after_counter``: only the
        owner of the countered card learns about it, and only when the counter
        came from the opposite side.  Listener cards (equipment or hand) then
        decide what to do with it, which keeps every "when my card is countered"
        card in card data instead of the engine.
        """
        if (
            not self._valid_player_id(card_user_id)
            or not self._valid_player_id(responder_id)
            or not self._opposite_timer_side(card_user_id, responder_id)
            or countered_card is None
        ):
            return False
        self._dispatch_card_event(
            'own_card_countered',
            card_user_id,
            countered_card,
            target_id=responder_id,
            extra_context={
                'counterer_id': responder_id,
                'countered_owner_id': card_user_id,
                'countered_card_instance_id': getattr(countered_card, 'instance_id', None),
                'countered_card_def_id': getattr(countered_card, 'def_id', ''),
            },
        )
        return True

    def _sewers_neem_after_poison_health_loss(self, victim_id: int, health_lost: int) -> None:
        health_lost = max(0, int(health_lost or 0))
        if health_lost <= 0:
            return
        amount = health_lost // 2
        if amount <= 0:
            return
        for owner_id, owner in enumerate(self.players):
            for eq in list(getattr(owner, 'equipment', []) or []):
                if not self._card_has_flag(getattr(eq, 'card_instance', None), 'heals_target_on_poison_loss'):
                    continue
                if not self._non_stack_equipment_is_active(eq):
                    continue
                target_id = self._equipment_effect_target_id(eq, owner_id)
                if target_id == victim_id or not self._valid_player_id(target_id):
                    continue
                target = self.players[target_id]
                before = int(getattr(target, 'health', 0) or 0)
                target.heal(amount)
                healed = max(0, int(getattr(target, 'health', 0) or 0) - before)
                if healed > 0:
                    self.log_msg(f"{self.pn(owner_id)}的苦楝使{self.pn(target_id)}回复{healed}H")

    def _sewers_grow_toilet_paper_power(self, target_id: int) -> None:
        if not self._valid_player_id(target_id):
            return
        for hand_card in list(getattr(self.players[target_id], 'hand', []) or []):
            if not self._card_has_flag(hand_card, 'grows_on_physical_damage'):
                continue
            custom = getattr(hand_card, 'custom_vars', {}) or {}
            gained = max(0, int(custom.get('sewers_toilet_paper_power', 0) or 0))
            if gained >= 24:
                continue
            custom['sewers_toilet_paper_power'] = gained + 1
            hand_card.custom_vars = custom
            hand_card.power_value = clamp_card_power(int(getattr(hand_card, 'power_value', 0) or 0) + 1)
            hand_card.instance_flags.add('power')

    def _arctic_trigger_snowballs_after_play(self, player_id: int, played_card: Optional[CardInstance]):
        if not self._valid_player_id(player_id) or played_card is None:
            return
        if self._card_flag_or_legacy_mark(played_card, 'skip_legacy_snowball_replay'):
            return
        if self.current_player != player_id or self.phase != 'action':
            return
        entries = self.players[player_id].custom_vars.get('arctic_snowballs')
        if not isinstance(entries, list) or not entries:
            return
        for entry in list(entries):
            try:
                target_id = int(entry.get('target_id', -1))
            except Exception:
                continue
            if not self._valid_player_id(target_id) or self.players[target_id].health <= 0:
                continue
            card_data = entry.get('source_card') if isinstance(entry, dict) else None
            if isinstance(card_data, dict):
                source_card = CardInstance.from_dict(card_data)
            else:
                # Round 10 built-in fallback: legacy records without a payload.
                source_card = CardInstance(self._legacy_fallback_def_id('snowball'))
            dealt = self.deal_attack_damage(
                target_id,
                self._modified_attack_damage(2, source_card),
                1,
                attacker_id=player_id,
                source_card=source_card,
            )
            if dealt > 0:
                self._arctic_add_frost(target_id, 1)

    def _atomic_ricochet_attack(self, player_id, card, params, log, choice, context):
        """Attack one target, then bounce onto further random selectable players.

        ``bounces`` (or, with ``bounces_from_positive_hits``, the number of main
        damage segments that actually landed) extra hits are dealt, each one to
        a different player than the previous hit.  The sequence is pre-drawn at
        play time (``_prepare_bounce_targets``) so responses and precognition
        can see every player the play will touch.
        """
        target_id = self._resolve_target(player_id, params.get('target', 'target'))
        if not self._valid_player_id(target_id):
            return
        bounce_amount = self._modified_attack_damage(
            max(0, self._eval_int(player_id, params.get('bounce_amount', params.get('amount', 6)), card, 6)),
            card,
        )
        amount = self._modified_attack_damage(
            max(0, self._eval_int(player_id, params.get('amount', 6), card, 6)),
            card,
        )
        hits = max(1, self._eval_int(player_id, params.get('hits', 1), card, 1))
        # Round 28：攻击族统一用 ``inherit_extra_hits``；``use_card_extra_hits``
        # 是 deal_damage / direct_damage 认的等价旧名，这里一并接受。
        if bool(params.get('inherit_extra_hits', params.get('use_card_extra_hits', False))):
            hits = self._card_total_hits(card, hits)
        bounce_hits = max(1, self._eval_int(player_id, params.get('bounce_hits', 1), card, 1))
        if bool(params.get('inherit_bounce_extra_hits', False)):
            bounce_hits = self._card_total_hits(card, bounce_hits)
        allow_self = bool(params.get('allow_self', False))
        exclude_previous = bool(params.get('exclude_previous', True))
        is_precision = bool(params.get('precision_inherit', True)) and (
            'precision' in self._effective_card_flags(card)
        )
        self.deal_attack_damage(
            target_id,
            amount,
            hits,
            is_precision=is_precision,
            attacker_id=player_id,
            source_card=card,
        )
        if params.get('bounces_from_positive_hits'):
            try:
                bounces = max(0, int((getattr(self, '_last_positive_damage_hits', []) or [])[target_id] or 0))
            except (IndexError, TypeError, ValueError):
                bounces = 0
        else:
            bounces = max(0, self._eval_int(
                player_id,
                params.get('bounces', params.get('repeats', 0)),
                card,
                0,
            ))
        prepared_targets = self._bounce_target_ids(card, choice)
        cursor = max(0, int(getattr(card, '_bounce_cursor', 0) or 0))
        previous_target = int(getattr(card, '_bounce_previous_target', target_id) or 0)
        for _ in range(bounces):
            prepared_target = prepared_targets[cursor] if cursor < len(prepared_targets) else -1
            cursor += 1
            try:
                bounced_target = int(prepared_target)
            except (TypeError, ValueError):
                bounced_target = -1
            if (
                (exclude_previous and bounced_target == previous_target)
                or not self._target_can_be_selected(player_id, bounced_target, allow_self=allow_self)
            ):
                candidates = [
                    tid for tid in range(len(self.players))
                    if (not exclude_previous or tid != previous_target)
                    and self._target_can_be_selected(player_id, tid, allow_self=allow_self)
                ]
                if not candidates:
                    break
                from engine_runtime_support import forced_random_target
                bounced_target = forced_random_target(self, player_id, candidates)
            bounce_choice = {
                'target_player': bounced_target,
                'target_player_id': bounced_target,
                'target_id': bounced_target,
            }
            self._trigger_card_target_reactions(player_id, card, bounce_choice)
            self.deal_attack_damage(
                bounced_target,
                bounce_amount,
                bounce_hits,
                is_precision=is_precision,
                attacker_id=player_id,
                source_card=card,
            )
            previous_target = bounced_target
        card._bounce_cursor = cursor
        card._bounce_previous_target = previous_target

    def _atomic_crit_multiplier_add(self, player_id, card, params, log, choice, context):
        amount = float(params.get('amount', 0.5) or 0.5)
        temporary = bool(params.get('temporary', False))
        for target_id in self._resolve_targets(player_id, params.get('target', 'target')):
            if not self._valid_player_id(target_id):
                continue
            ps = self.players[target_id]
            key = 'hel_crit_multiplier_turn_bonus' if temporary else 'hel_crit_multiplier_bonus'
            try:
                before = float(ps.custom_vars.get(key, 0) or 0)
            except Exception:
                before = 0.0
            ps.custom_vars[key] = before + amount
            self._hel_sync_crit_multiplier_display(target_id)
            self.log_msg(log or f"{self.pn(target_id)}暴击倍率+{amount:g}×")

    def _def_id_is_magic_pearl(self, def_id: str) -> bool:
        """Match Magic Pearl ids regardless of the id spelling used by a package."""
        normalized = re.sub(r'[^a-z0-9]', '', str(def_id or '').lower())
        return normalized.endswith('magicpearl')

    def _run_ocean_auto_cards_turn_start(self, player_id: int):
        """Turn-start entry point for the auto-play queue.

        The name is historical (the queue started life as an ocean-only
        mechanic) and is kept because callers inside and outside the engine
        patch or forward to it; the queue itself is the generic
        ``auto_play_queue``.
        """
        self._run_auto_play_queue_turn_start(player_id)

    def _run_auto_play_queue_turn_start(self, player_id: int):
        """Play every queued auto-play entry of ``player_id`` for this turn."""
        if not self._valid_player_id(player_id):
            return
        ps = self.players[player_id]
        entries = self._auto_play_queue_entries(ps)
        if not isinstance(entries, list) or not entries:
            return
        for entry in list(entries):
            if not isinstance(entry, dict):
                self._remove_auto_play_entry(entries, entry)
                continue
            if self.game_over or self.phase != 'action':
                break
            if bool(getattr(self, '_turn_boundary_active', False)) and not self._turn_boundary_claim(
                ('ocean_auto_card', int(player_id), id(entry))
            ):
                continue
            entry_def = str(entry.get('def_id') or '')
            entry_exile = bool(entry.get('exile', True))
            entry_each_turn = bool(entry.get('each_turn', True))
            target_id = self._resolve_auto_play_target(player_id, entry)
            if bool(entry.get('require_selectable', True)) and not self._target_can_be_selected(
                player_id,
                target_id,
                allow_self=bool(entry.get('allow_self', False)),
            ):
                if not entry_each_turn:
                    self._remove_auto_play_entry(entries, entry)
                continue
            uses_exiled_card = entry.get('card_instance_id') is not None
            if uses_exiled_card:
                try:
                    instance_id = int(entry.get('card_instance_id', -1))
                except (TypeError, ValueError):
                    instance_id = -1
                auto_card = next(
                    (
                        candidate
                        for candidate in ps.exile
                        if int(getattr(candidate, 'instance_id', -1)) == instance_id
                    ),
                    None,
                )
            else:
                snapshot = entry.get('card')
                if not isinstance(snapshot, dict):
                    snapshot = {'def_id': entry_def}
                auto_card = fresh_card_copy_from_dict(snapshot, entry_def)
                auto_card.swift_value = max(
                    int(getattr(auto_card, 'swift_value', 0) or 0),
                    max(0, int(entry.get('swift_value', 0) or 0)),
                )
                auto_card.magic_swift_value = max(
                    int(getattr(auto_card, 'magic_swift_value', 0) or 0),
                    max(0, int(entry.get('magic_swift_value', 0) or 0)),
                )
            if auto_card is None:
                if not entry_each_turn:
                    self._remove_auto_play_entry(entries, entry)
                continue
            marker = str(entry.get('marker') or self.AUTO_PLAY_QUEUE_MARKER)
            if marker:
                auto_card.instance_flags.add(marker)
            if entry_exile:
                # ``ocean_no_auto`` + the ``exile`` flag send the played copy
                # to the exile pile once the play finishes (legacy machinery),
                # and suppress a second registration from older card data.
                auto_card.instance_flags.add('ocean_no_auto')
                auto_card.instance_flags.add('exile')
            auto_card.disabled_flags.add('rebound')
            can_auto_play, _ = self.can_play_card(player_id, auto_card)
            if not can_auto_play:
                if not entry_each_turn:
                    self._remove_auto_play_entry(entries, entry)
                continue
            if uses_exiled_card:
                ps.exile.remove(auto_card)
            # Move the exact physical card directly to hand so a full hand does
            # not treat the automatic play as an overflow draw.
            ps.hand.append(auto_card)
            auto_choice = {'target_player_id': target_id, 'target_player': target_id, 'target_id': target_id}
            previous_auto_actor = getattr(self, '_allow_out_of_turn_auto_play_for', None)
            previous_auto_choice = getattr(self, '_auto_resolve_choices_for', None)
            previous_auto_cost = getattr(self, '_auto_play_no_cost_for', None)
            self._allow_out_of_turn_auto_play_for = player_id
            self._auto_resolve_choices_for = player_id
            if str(entry.get('cost', 'normal') or 'normal').strip().lower() == 'free':
                self._auto_play_no_cost_for = player_id
            try:
                if len(getattr(self, 'players', []) or []) > 2:
                    result = self.play_card(player_id, auto_card.instance_id, target_id, auto_choice)
                else:
                    result = self.play_card(player_id, auto_card.instance_id, auto_choice)
            except Exception:
                if auto_card in ps.hand:
                    ps.hand.remove(auto_card)
                    if entry_exile:
                        self._put_card_in_exile(player_id, auto_card)
                raise
            finally:
                self._allow_out_of_turn_auto_play_for = previous_auto_actor
                self._auto_resolve_choices_for = previous_auto_choice
                self._auto_play_no_cost_for = previous_auto_cost
            if auto_card in ps.hand and not result.get('needs_response') and not result.get('needs_choice') and not result.get('needs_v2_ui'):
                ps.hand.remove(auto_card)
                if entry_exile:
                    self._put_card_in_exile(player_id, auto_card)
            if not entry_each_turn:
                self._remove_auto_play_entry(entries, entry)
            if not result.get('success') and not result.get('needs_response') and not result.get('needs_choice') and not result.get('needs_v2_ui'):
                continue
            if self.pending_response is not None or self.pending_choice is not None or getattr(self, 'pending_v2_ui', None):
                break

    def _atomic_status_op(self, player_id, card, params, log, choice, context):
        """Round 33 / 批次 AC：``status_op`` 伞（``status_add_named`` /
        ``status_remove_named`` / ``clear_statuses`` / ``settle_status`` 四合一）。

        统一参数 ``op``：``add``（缺省，叠层；``mode:"set"`` 即旧
        ``set_status_named``）、``remove``（减层/清空）、``clear``（preset 名单式
        清状态）、``settle``（DoT 结算）。四段实现体与合并前逐字一致
        （``add`` / ``remove`` 走既有的 ``_apply_status_*_family``）。
        """

        op = str(params.get('op', params.get('action', '')) or '').strip().lower()
        forwarded = dict(params)
        forwarded.pop('op', None)
        forwarded.pop('action', None)
        if op in ('', 'add', 'apply', 'stack'):
            return self._status_add_named_payload(player_id, card, forwarded, log, choice, context)
        if op in ('set',):
            forwarded['mode'] = 'set'
            return self._status_add_named_payload(player_id, card, forwarded, log, choice, context)
        if op in ('remove', 'reduce', 'decay'):
            return self._status_remove_named_payload(player_id, card, forwarded, log, choice, context)
        if op in ('clear', 'purge', 'clear_all'):
            return self._status_op_clear_payload(player_id, card, forwarded, log, choice, context)
        if op in ('settle', 'resolve', 'tick'):
            return self._status_op_settle_payload(player_id, card, forwarded, log, choice, context)
        self._log_mod_runtime_error(
            'status_op', RuntimeError(f'unsupported op: {op}'), player_id, card,
        )

    def _status_add_named_payload(self, player_id, card, params, log, choice, context):
        """Round 31 / 批次 Z：``status_add_named`` 现在用 ``mode`` 区分加/设。

        ``mode`` 缺省 ``add``（层数叠加）；``mode:"set"`` 即旧
        ``set_status_named``（把状态设为 N 层，``stack`` 仍是它的默认值来源）。
        两个名字的参数面完全一致，合并后只多一个 ``mode`` 键。
        """

        mode = str(params.get('mode', 'add') or 'add').strip().lower()
        mode = {'=': 'set', 'set_to': 'set', 'assign': 'set', 'replace': 'set',
                'stack': 'add', '+': 'add', '+=': 'add', 'increase': 'add'}.get(mode, mode)
        op = 'set_status_named' if mode == 'set' else 'status_add_named'
        self._apply_status_add_family(player_id, card, params, log, op=op)

    # Round 30 / 批次 Y：旧写法 ``add_status`` / ``remove_status`` / ``set_status``
    # （Round 15 起是"未写 ``log`` 时默播报层数"的真原子）已随零用量清理删除。
    # 规范写法 ``status_add_named`` / ``status_remove_named`` 现在**只**按步骤
    # 自己写的 ``log`` 决定战报（``log:true`` 就是旧默认那句），因此
    # ``STATUS_LEGACY_ANNOUNCING_OPS`` 也一并消失。
    # Round 31 / 批次 Z：``set_status_named`` 也并进 ``status_add_named(mode:"set")``。

    def _status_family_status_list(self, player_id, card, params):
        raw_statuses = params.get('statuses')
        if isinstance(raw_statuses, (list, tuple)):
            return [
                str(self._step_text_value(player_id, card, item)).strip()
                for item in raw_statuses
                if str(self._step_text_value(player_id, card, item)).strip()
            ]
        return [str(self._step_text_value(player_id, card, params.get('status', ''))).strip()]

    def _apply_status_add_family(self, player_id, card, params, log, *, op):
        """Target / amount resolution shared by the ``add`` and ``set`` spellings."""

        status_list = self._status_family_status_list(player_id, card, params)
        if not any(status_list):
            return
        default_amount = params.get('stack', 1) if op == 'set_status_named' else 1
        amount = self._eval_int(player_id, params.get('amount', default_amount), card, 1)
        for tid in self._resolve_targets(player_id, params.get('target', 'self')):
            for status in status_list:
                self._apply_status_op(
                    player_id, card, params, log, op, tid, status, amount,
                    clear_all=False, context=None,
                )

    def _apply_named_status_step(self, player_id, card, params, log, tid, status: str, amount: int):
        """Backwards-compatible wrapper for the pre-batch-3 entry point."""

        self._apply_status_op(
            player_id, card, params, log, 'status_add_named', tid, status, amount,
            clear_all=False, context=None,
        )

    def _status_attr_field(self, status: str) -> str:
        """Player attribute that stores *status* (union of both historic maps)."""

        return {
            'poison': 'poison', '中毒': 'poison', 'p': 'poison',
            'burn': 'fire', 'fire': 'fire', '灼烧': 'fire', 'f': 'fire',
            'toxic': 'toxic', '淬毒': 'toxic',
            'dodge': 'dodge', '闪避': 'dodge',
            'vulnerable': 'vulnerable',
            'armor': 'armor',
            'equip_protection': 'equipment_protection',
            'equipment_protection': 'equipment_protection',
            '装备摧毁保护': 'equipment_protection', '装备保护': 'equipment_protection',
            'sluggish': 'sluggish', '迟缓': 'sluggish',
            'overload': 'overload', '超载': 'overload',
            'foresight': 'foresight', '预知': 'foresight',
            'fracture': 'fracture', '破损': 'fracture',
            'stagnation': 'stagnation', '滞留': 'stagnation',
            'blind': 'blind', '失明': 'blind',
            'heal_block': 'heal_block', '禁疗': 'heal_block',
            'attack_blocked': 'attack_blocked', '禁攻': 'attack_blocked',
            'attack_only': 'attack_only', '仅攻击': 'attack_only',
            'weakness': 'weakness', '虚弱': 'weakness',
            'bleed': 'bleed', '流血': 'bleed',
            'fragment': 'fragment_stacks', 'fragment_stacks': 'fragment_stacks', '碎片': 'fragment_stacks',
            'stunned': 'skip_turn', 'dizzy': 'skip_turn', 'skip_turn': 'skip_turn', '眩晕': 'skip_turn',
            'untargetable': 'untargetable', '无法选中': 'untargetable',
        }.get(str(status or '').strip(), '')

    def _status_stack_value(self, target_id: int, status_id) -> int:
        """Layers of *status_id* as the engine reads them (immunity suppresses).

        Reading through the engine helpers (frost / nazar / unable-counter alias
        groups included) is what lets both execution paths observe the same
        stack, including for old rooms whose alias keys are still spread out.
        """

        if not self._valid_player_id(target_id):
            return 0
        status_text = str(status_id or '').strip()
        if not status_text:
            return 0
        immune_key = status_text.split(':')[-1] in ('status_immune', 'immune', '状态免疫')
        if immune_key:
            return 1 if self._is_status_immune(target_id) else 0
        if self._is_status_immune(target_id):
            # 状态免疫只压制生效：写入照常，读取按 0 计（两条路径一致）。
            return 0
        if status_text in self._arctic_frost_keys():
            return max(0, int(self._arctic_frost_value(target_id) or 0))
        if self._status_alias_declaration(status_text):
            return max(0, int(self._status_alias_value_for(
                target_id, self._status_alias_declaration(status_text)) or 0))
        if status_text in self._unable_counter_keys():
            return max(0, int(self._unable_counter_value(target_id) or 0))
        attr = self._status_attr_field(status_text)
        if attr:
            # ``attack_blocked`` / ``vulnerable`` / ``装备保护`` 这类属性不在
            # ``_get_status_count`` 的硬编码表里，必须按同一张属性表读。
            return max(0, int(getattr(self.players[target_id], attr, 0) or 0))
        return max(0, int(self._get_status_count(target_id, status_text) or 0))

    def _fire_status_change_events(self, target_id: int, status_id: str, before: int, after: int) -> None:
        """``on_apply`` / ``on_remove`` status events on the 0 <-> positive edges."""

        runner = getattr(self, '_run_v2_status_event', None)
        if not callable(runner):
            return
        if before <= 0 < after:
            runner(target_id, status_id, 'on_apply', {'amount': after - before})
        elif before > 0 and after <= 0:
            runner(target_id, status_id, 'on_remove', {'amount': before})

    def _status_op_log_line(self, op, log_value, source_id, target_id, status, mode,
                            requested, layers, before, after):
        """Battle-log contract of the status family (Round 15 / batch 3).

        ``log: false`` mutes, a string is a data-authored template
        (``{target}`` / ``{source}`` / ``{amount}`` / ``{status}``), and
        ``log: true`` asks for the classic announce line.  Round 30 / 批次 Y
        删掉旧写法之后，未写 ``log`` 一律安静（旧 ``add_status`` /
        ``remove_status`` / ``set_status`` 的"默认播报"要显式写 ``log: true``）。
        """

        applied = int(after) - int(before)
        label = self._status_log_label(status)
        immune_key = str(status).split(':')[-1] in ('status_immune', 'immune', '状态免疫')
        if isinstance(log_value, str):
            if not log_value:
                return None
            if mode in ('remove', 'clear'):
                return self._format_step_log(
                    log_value, target=self.pn(target_id), source=self.pn(source_id),
                    amount=layers, status=label,
                )
            return self._format_step_log(
                log_value, target=self.pn(target_id), amount=requested, status=label,
            )
        if log_value is not True:
            return None
        if immune_key:
            if mode == 'set':
                return f"{self.pn(target_id)}{'获得' if after > 0 else '失去'}状态免疫"
            if applied > 0:
                return f"{self.pn(target_id)}获得状态免疫"
            if applied < 0:
                return f"{self.pn(target_id)}失去状态免疫"
            return None
        if mode == 'set':
            return f"{self.pn(target_id)}的{label}变为{after}层"
        if not applied:
            return None
        return f"{self.pn(target_id)}{'+' if applied > 0 else '-'}{abs(applied)}层{label}"

    def _apply_status_op(self, player_id, card, params, log_value, op, target_id, status, amount,
                         *, clear_all: bool = False, context=None) -> int:
        """Apply / remove / set one named status on one target (shared by both paths).

        Returns the applied delta (``after - before``) as the readers see it.

        Every status step (``status_add_named`` / ``set_status_named`` /
        ``status_remove_named`` / ``clear_statuses``) funnels here, so the
        mechanisms below behave the same whichever name the data uses:

        * alias groups declared by card data (``status_aliases``) + legacy fields;
        * the arctic frost 60-layer cap and its alias group;
        * ``ocean:unable_counter`` (custom key + current-hand sweep);
        * ``status_immune`` (always stored, reads stay suppressed, key group cleared);
        * achievement peaks (``_note_achievement_status_peak``);
        * ``stacking`` (``unique`` / ``duration``) and ``keep_when_zero``;
        * ``on_apply`` / ``on_remove`` status events on the 0 <-> positive edges;
        * the battle-log contract documented on :meth:`_status_op_log_line`.
        """

        if not self._valid_player_id(target_id) or not status:
            return 0
        params = params if isinstance(params, dict) else {}
        if not params.get('bypass_mask'):
            from engine_runtime_support import blocks_special_effect_interference
            if blocks_special_effect_interference(self, target_id):
                return 0
        if self._status_application_blocked(target_id, status):
            return 0
        status_text = str(status).strip()
        if not status_text:
            return 0
        try:
            requested = int(amount or 0)
        except (TypeError, ValueError):
            requested = 0
        if op == 'set_status_named':
            mode = 'set'
        elif op == 'status_remove_named':
            mode = 'clear' if clear_all else 'remove'
        else:
            mode = 'add'
        layers = requested
        if mode == 'remove':
            # Round 30 / 批次 Y：旧写法 ``remove_status``（一贯"至少减 1 层"）已删除，
            # 这里统一按 ``amount`` 精确减少。
            if layers <= 0:
                # ``status_remove_named`` 的 0 层是"清空"（见 _apply_status_remove_family）。
                mode = 'clear'

        ps = self.players[target_id]
        status_key = status_text.split(':')[-1]
        before = self._status_stack_value(target_id, status_text)

        # 霜冻：别名组与 60 层上限由 arctic 助手掌管（默认文案也在那里）。
        if mode == 'add' and status_text in self._arctic_frost_keys():
            template = ''
            if isinstance(log_value, str) and log_value:
                template = self._format_step_log(
                    log_value, target=self.pn(target_id), amount=requested,
                    status=self._status_log_label(status_text),
                )
            self._arctic_add_frost(target_id, layers, template)
            after = self._status_stack_value(target_id, status_text)
            self._fire_status_change_events(target_id, status_text, before, after)
            return after - before

        attr = self._status_attr_field(status_text)
        if attr:
            current = int(getattr(ps, attr, 0) or 0)
            if mode == 'set':
                value = max(0, layers)
            elif mode == 'clear':
                value = 0
            elif mode == 'remove':
                value = max(0, current - layers)
            else:
                value = max(0, current + layers)
            setattr(ps, attr, value)
        elif status_text in self._arctic_frost_keys():
            current = self._arctic_frost_value(target_id)
            if mode == 'set':
                value = max(0, layers)
            elif mode == 'clear':
                value = 0
            elif mode == 'remove':
                value = max(0, current - layers)
            else:
                value = max(0, current + layers)
            self._arctic_set_frost_value(target_id, value)
        elif status_text in self._unable_counter_keys():
            current = self._unable_counter_value(target_id)
            if mode == 'set':
                value = max(0, layers)
            elif mode == 'clear':
                value = 0
            elif mode == 'remove':
                value = max(0, current - layers)
            else:
                value = max(0, current + layers)
            self._set_unable_counter_value(target_id, value)
        elif self._status_alias_declaration(status_text):
            declaration = self._status_alias_declaration(status_text)
            current = self._status_alias_value_for(target_id, declaration)
            if mode == 'set':
                value = max(0, layers)
            elif mode == 'clear':
                value = 0
            elif mode == 'remove':
                value = max(0, current - layers)
            else:
                value = max(0, current + layers)
            self._set_status_alias_value_for(target_id, declaration, value)
        elif status_key in ('status_immune', 'immune', '状态免疫'):
            ps.custom_statuses = getattr(ps, 'custom_statuses', {})
            for key in ('status_immune', 'immune', '状态免疫'):
                ps.custom_statuses.pop(key, None)
            if mode in ('add', 'set') and layers > 0:
                ps.custom_statuses['status_immune'] = 1
            elif mode == 'remove' and before - layers > 0:
                ps.custom_statuses['status_immune'] = 1
        else:
            definition = self._get_v2_status_def(status_text)
            definition = definition if isinstance(definition, dict) else {}
            stacking = str(definition.get('stacking') or 'stack')
            ps.custom_statuses = getattr(ps, 'custom_statuses', {})
            current = int(ps.custom_statuses.get(status_text, 0) or 0)
            if mode == 'set':
                value = 1 if stacking == 'unique' and layers > 0 else max(0, layers)
            elif mode == 'clear':
                value = 0
            elif mode == 'remove':
                value = max(0, current - layers)
            elif stacking == 'unique':
                value = 1 if layers > 0 else max(0, current)
            elif stacking == 'duration':
                value = max(current, max(0, layers))
            else:
                value = max(0, current + layers)
            if value <= 0:
                keep_zero = bool(
                    definition.get('keep_when_zero') or definition.get('keep_zero')
                    or self._status_keep_when_zero(status_text)
                )
                if keep_zero:
                    ps.custom_statuses[status_text] = 0
                else:
                    ps.custom_statuses.pop(status_text, None)
            else:
                ps.custom_statuses[status_text] = value

        self._normalize_status_value(ps, status_text)
        self._note_achievement_status_peak(target_id)
        if status_text in self._unable_counter_keys():
            self._apply_unable_counter_to_current_hand(target_id)
        after = self._status_stack_value(target_id, status_text)
        self._fire_status_change_events(target_id, status_text, before, after)
        if mode != 'clear':
            line = self._status_op_log_line(
                op, log_value, player_id, target_id, status_text, mode,
                requested, layers, before, after,
            )
            if line:
                self.log_msg(line)
        return after - before

    def _status_remove_named_payload(self, player_id, card, params, log, choice, context):
        # Round 33 / 批次 AC：``status_op(op:"remove")`` 的实现体。
        self._apply_status_remove_family(player_id, card, params, log, op='status_remove_named')

    def _apply_status_remove_family(self, player_id, card, params, log, *, op):
        """Target / amount resolution of the ``set_status_named`` / remove family.

        ``status_remove_named`` without an explicit ``amount`` keeps its
        historical "clear this status" behaviour; every other spelling removes
        that many layers.  Round 30 / 批次 Y 删掉了 ``remove_status``（"至少减
        1 层"的旧默认），要那个语义就显式写 ``amount: 1``。
        """

        status = str(params.get('status', '')).strip()
        raw_amount = params.get('amount', params.get('layers'))
        reduce_amount = 0
        if raw_amount is not None:
            try:
                reduce_amount = max(0, int(self._eval_int(player_id, raw_amount, card, 0) or 0))
            except Exception:
                reduce_amount = 0
        # Historical quirk kept on purpose: ``status_remove_named`` has no
        # "remove zero layers" mode - without an amount (or with ``0``) it clears
        # the status, which is what the pre-batch-3 atom did.
        clear_all = op == 'status_remove_named' and reduce_amount <= 0
        for tid in self._resolve_targets(player_id, params.get('target', 'self')):
            self._apply_status_op(
                player_id, card, params, log, op, tid, status, reduce_amount,
                clear_all=clear_all, context=None,
            )

    def _remove_named_status_layers(self, target_id: int, status: str, amount: int) -> None:
        """Reduce one named status by *amount* layers (never below zero)."""
        if not self._valid_player_id(target_id) or amount <= 0 or not status:
            return
        ps = self.players[target_id]
        attr = {
            'poison': 'poison', '中毒': 'poison',
            'burn': 'fire', 'fire': 'fire', '灼烧': 'fire',
            'toxic': 'toxic', '淬毒': 'toxic',
            'dodge': 'dodge', '闪避': 'dodge',
            'sluggish': 'sluggish', '迟缓': 'sluggish',
            'overload': 'overload', '超载': 'overload',
            'foresight': 'foresight', '预知': 'foresight',
            'fracture': 'fracture', '破损': 'fracture',
            'stagnation': 'stagnation', '滞留': 'stagnation',
            'blind': 'blind', '失明': 'blind',
            'heal_block': 'heal_block', '禁疗': 'heal_block',
            'weakness': 'weakness', '虚弱': 'weakness',
            'bleed': 'bleed', '流血': 'bleed',
            'fragment': 'fragment_stacks', 'fragment_stacks': 'fragment_stacks', '碎片': 'fragment_stacks',
            'stunned': 'skip_turn', 'dizzy': 'skip_turn', 'skip_turn': 'skip_turn', '眩晕': 'skip_turn',
        }.get(status)
        if attr is not None and hasattr(ps, attr):
            setattr(ps, attr, max(0, int(getattr(ps, attr, 0) or 0) - amount))
            return
        getter = getattr(self, '_custom_status_value', None)
        setter = getattr(self, '_set_custom_status_value', None)
        if callable(getter) and callable(setter):
            try:
                current = max(0, int(getter(target_id, status) or 0))
                setter(target_id, status, max(0, current - amount))
                return
            except Exception:
                pass
        ps.custom_statuses = getattr(ps, 'custom_statuses', {})
        if status in ps.custom_statuses:
            ps.custom_statuses[status] = max(0, int(ps.custom_statuses.get(status, 0) or 0) - amount)

    def _sync_custom_var_alias(self, ps, name: str):
        try:
            value = int(self._scalar_value(ps.custom_vars.get(name, 0), 0))
        except Exception:
            value = 0
        if name == '\u4e09\u89d2\u5f62\u5c42\u6570':
            ps.triangle_stacks = max(0, value)
        elif name == '\u5496\u5561\u9996\u6b21\u4f7f\u7528':
            ps.coffee_first_use = bool(value)

    def _atomic_player_var_change(self, player_id, card, params, log, choice, context):
        """Round 29 / 批次 X：玩家自定义变量的五个同形原子合并成一条。

        覆盖 ``var_set`` / ``var_add`` / ``var_sub`` / ``var_mul`` / ``var_div``：
        ``mode`` 选 ``set`` / ``add`` / ``sub`` / ``mul`` / ``div``（也认
        ``assign`` / ``=`` / ``+=`` / ``-=`` / ``*=`` / ``/=`` 这些符号写法）。
        五段实现逐条搬到这里，因此默认值与边界都保持原样：

        * ``set``：名字走 ``_step_text_value``（可写取值表达式），值走
          ``_eval_var_assignment_value``（赋值口径，可写表达式）；
        * ``add`` / ``sub``：值走 ``_eval_int``，默认 0；
        * ``mul`` / ``div``：值走 ``_eval_int``，默认 1；
        * ``div`` 除数为 0 时保持原值不变（旧 ``var_div`` 的保护）。

        与 ``set_var`` / ``add_var``（运行时临时变量）的区别见《引擎原子与数据步骤
        清单》§27：这三个名字写的是**玩家变量**（``custom_vars``），不是步骤临时变量。
        """
        mode = str(params.get('mode', params.get('op_mode', 'set')) or 'set').strip().lower()
        mode = {
            '=': 'set', 'assign': 'set', 'set_to': 'set', 'write': 'set',
            '+': 'add', '+=': 'add',
            '-': 'sub', '-=': 'sub',
            '*': 'mul', '*=': 'mul',
            '/': 'div', '/=': 'div',
        }.get(mode, mode)
        if mode not in ('set', 'add', 'sub', 'mul', 'div'):
            return
        for target_ref in self._var_target_refs(player_id, params.get('target', 'self')):
            store = self._var_store_for_target(player_id, target_ref)
            if mode == 'set':
                name = str(self._step_text_value(
                    player_id, card, params.get('name', params.get('var', 'var')),
                ))
            else:
                name = str(params.get('name', params.get('var', 'var')))
            with self._read_status_var_for_mutation(target_ref, name):
                if mode == 'set':
                    value = self._eval_var_assignment_value(player_id, params.get('value', 0), card)
                else:
                    default = 1 if mode in ('mul', 'div') else 0
                    value = self._eval_int(player_id, params.get('value', default), card, default)
            if mode == 'set':
                store[name] = value
            else:
                current = int(self._scalar_value(store.get(name, 0), 0))
                if mode == 'add':
                    store[name] = current + int(value)
                elif mode == 'sub':
                    store[name] = current - int(value)
                elif mode == 'mul':
                    store[name] = current * int(value)
                else:
                    divisor = int(value)
                    store[name] = current if divisor == 0 else current // divisor
            if isinstance(target_ref, int):
                self._sync_custom_var_alias(self.players[target_ref], name)

    # Round 31 / 批次 Z：``var_set`` 兼容垫片已删除（``player_var_change(mode:"set")``
    # 是唯一实现；Round 30 已把 ``countdown_var`` 的内部调用改到规范名）。

    def _atomic_list_modify(self, player_id, card, params, log, choice, context):
        """Round 32 / 批次 AA：``list_set`` / ``list_append`` / ``list_insert`` /
        ``list_delete`` / ``list_clear`` 五合一。

        参数：``list`` 是**列表变量名**（旧的 ``name``，默认 ``"list"``），
        ``mode`` 选 ``set`` / ``append`` / ``insert`` / ``delete`` / ``clear``
        （也接受 ``action`` / ``list_op``，老式 ``{"type":...,"params":{...}}``
        编码里还能直接写 ``op``），``index`` 是 insert/delete 的 1 基下标，
        ``value`` 是写入值（append/insert 的单元素，set 的整张列表）。

        五段旧实现逐条保留：非列表的旧值先包成单元素列表（``None`` 视作空），
        insert 的下标夹在 ``[0, len]``，delete 越界是空操作，set 逐项
        ``_serializable_list_item`` 归一。
        """

        action = str(
            params.get('mode') or params.get('list_op') or params.get('action')
            or params.get('op') or 'append'
        ).strip().lower()
        raw_name = params.get('list')
        if isinstance(raw_name, str):
            name = raw_name
            value_expr = params.get('value', params.get('item'))
        else:
            name = str(params.get('name', 'list'))
            value_expr = params.get('value', params.get('item', raw_name))
        for target_ref in self._var_target_refs(player_id, params.get('target', 'self')):
            store = self._var_store_for_target(player_id, target_ref)
            if action in ('set', 'list_set'):
                store[name] = [
                    self._serializable_list_item(v)
                    for v in self._eval_list(player_id, value_expr if value_expr is not None else [], card)
                ]
                continue
            if action in ('clear', 'list_clear'):
                store[name] = []
                continue
            current = store.get(name, [])
            if not isinstance(current, list):
                current = [] if current is None else [current]
            if action in ('append', 'list_append', 'push'):
                current.append(self._serializable_list_item(
                    self._eval_raw_item(player_id, value_expr if value_expr is not None else 0, card)
                ))
            elif action in ('insert', 'list_insert'):
                index = max(0, min(len(current), self._eval_int(player_id, params.get('index', 1), card, 1) - 1))
                current.insert(index, self._serializable_list_item(
                    self._eval_raw_item(player_id, value_expr if value_expr is not None else 0, card)
                ))
            elif action in ('delete', 'remove', 'list_delete'):
                index = self._eval_int(player_id, params.get('index', 1), card, 1) - 1
                if 0 <= index < len(current):
                    current.pop(index)
            store[name] = current

    # Round 32 / 批次 AA：``for_each_list`` 已并入
    # ``for_each(source: <列表表达式>)``（``_engine_loop_resolver`` 认得
    # ``list_var``/``zone_list`` 这些引擎列表词表，默认变量名同样是 ``item``），
    # ``for_each_selected_card`` 并入 ``for_each(bind:"selected_card")``。

    def _equipment_matches_loop_filter(self, player_id, eq, params, card):
        loop_filter = str(params.get('filter', 'all') or 'all')
        if loop_filter in ('all', 'any'):
            return True
        if loop_filter in ('destroyable', 'can_destroy'):
            return 'indestructible' not in eq.card_instance.flags
        if loop_filter in ('indestructible', 'cannot_destroy'):
            return 'indestructible' in eq.card_instance.flags
        if loop_filter in ('named', 'card_id'):
            expected = ''
            selector = params.get('card')
            if selector is not None:
                expected = self._resolve_card_id_ref(player_id, selector, card)
            expected = expected or str(params.get('card_id', '') or '')
            return bool(expected) and eq.def_id == expected
        if loop_filter in ('current_target', 'effect_target'):
            target_id = self._resolve_target(player_id, params.get('effect_target', params.get('target', 'self')))
            return getattr(eq, 'effect_target', getattr(eq, 'owner', -1)) == target_id
        return True

    def _equipment_op_each_payload(self, player_id, card, params, log, choice, context):
        # Round 33 / 批次 AC：``equipment_op(mode:"each")`` 的实现体（旧
        # ``for_each_equipment``：逐件装备跑 ``body`` 子步骤）。
        body = params.get('body', []) or []
        targets = self._resolve_targets(player_id, params.get('target', 'self'))
        previous_selected = (context or {}).get('selected_equipment_instance_id') if isinstance(context, dict) else None
        loop_items = []
        for target_id in targets:
            if not (0 <= target_id < len(self.players)):
                continue
            for eq in list(self.players[target_id].equipment):
                if self._equipment_matches_loop_filter(player_id, eq, params, card):
                    loop_items.append((target_id, eq))
        try:
            for index, (owner_id, eq) in enumerate(loop_items, start=1):
                loop_context = {
                    **(context or {}),
                    'selected_equipment_instance_id': eq.card_instance.instance_id,
                    'selected_equipment_owner_id': owner_id,
                    'equipment_index': index,
                }
                try:
                    self._run_effect_list(player_id, card, body, choice, loop_context)
                except ModLoopContinue:
                    continue
                except ModLoopBreak:
                    break
        finally:
            if isinstance(context, dict) and previous_selected is not None:
                context['selected_equipment_instance_id'] = previous_selected

    def use_trigger(self, player_id: int, equipment_instance_id: int, target_player_id: int = -1) -> dict:
        if self.current_player != player_id:
            return {'success': False, 'error': '不是你的回合'}
        ps = self.players[player_id]
        eq = ps.find_equipment(equipment_instance_id)
        if eq is None:
            return {'success': False, 'error': '装备不存在'}
        if not self._equipment_runtime_active(eq):
            return {'success': False, 'error': '装备处于尘封状态'}
        has_mod_trigger = self._has_card_event(eq.card_def, 'equipment_trigger')
        if eq.card_def.trigger_cost_e < 0 and not has_mod_trigger:
            return {'success': False, 'error': '该装备没有触发效果'}
        required_turns = card_trigger_ready_turns(eq.card_def)
        if eq.turns_equipped < required_turns:
            return {'success': False, 'error': '装备需要装备一回合后才能触发'}
        trigger_cost = max(0, int(eq.card_def.trigger_cost_e or 0))
        trigger_cost_m = max(0, int(getattr(eq.card_def, 'trigger_cost_m', 0) or eq.card_def.v2_resource.get('trigger_cost_m', 0) or 0))
        if trigger_cost > ps.elixir:
            return {'success': False, 'error': '能量不足'}
        if trigger_cost_m > ps.magic:
            return {'success': False, 'error': '魔力不足'}
        max_uses = self._equipment_trigger_max_uses(eq)
        if max_uses > 0 and int(getattr(eq, 'uses_this_turn', 0)) >= max_uses:
            return {'success': False, 'error': f'该装备本回合最多触发{max_uses}次'}
        uses_effect_target = self._equipment_trigger_uses_effect_target(eq.card_def)
        if uses_effect_target:
            target_id = self._equipment_effect_target_id(eq, player_id)
        else:
            try:
                target_id = int(target_player_id)
            except Exception:
                target_id = -1
            if not (0 <= target_id < len(self.players)):
                target_id = 1 - player_id
        fixed_target_available = (
            self._valid_player_id(target_id)
            and int(getattr(self.players[target_id], 'health', 0) or 0) > 0
        )
        if uses_effect_target and not fixed_target_available:
            return {'success': False, 'error': '没有可选中的玩家'}
        if not uses_effect_target and not self._target_can_be_selected(player_id, target_id, allow_self=True):
            return {'success': False, 'error': '没有可选中的玩家'}
        if self._equipment_trigger_forbids_self_target(eq.card_def) and target_id == player_id:
            return {'success': False, 'error': '不能选择自己作为目标'}
        self._spend_resource(player_id, 'elixir', trigger_cost, eq.card_instance)
        self._spend_resource(player_id, 'magic', trigger_cost_m, eq.card_instance)
        eq.uses_this_turn = int(getattr(eq, 'uses_this_turn', 0)) + 1
        self._log_equipment_trigger(player_id, eq)
        choice = {'target_player': target_id, 'target_player_id': target_id, 'target_id': target_id}
        if has_mod_trigger and self._run_card_event(player_id, eq.card_instance, 'equipment_trigger', choice,
                                                    {'source_id': player_id, 'target_id': target_id}):
            self._dispatch_card_event('equipment_triggered', player_id, eq.card_instance,
                                      target_id=target_id, equipment=eq, equipment_owner_id=player_id)
            self._check_game_over()
            return {'success': True, 'target_player_id': target_id}
        opp_id = target_id
        self._dispatch_card_event('equipment_triggered', player_id, eq.card_instance,
                                  target_id=opp_id, equipment=eq, equipment_owner_id=player_id)
        self._check_game_over()
        return {'success': True, 'target_player_id': target_id}
